/* ---- ABI v84: record-0 StatHUD tail WALK-ACTIVE lane shared constants ---- */

/** Per-player pack field names in layout/flattened order (16 u32 = 64 B).
 *  Ptr (+0) is the PLAYER POINTER VALUE (host resolves *(u32*)(begin+4*i))
 *  — the entry token the slot get-or-insert matches and stores. */
const HUD_STAT_WALK_PLAYER_FIELDS = [
  "Ptr", "PredA", "F2c", "F3bc", "F13c0", "F172", "OtherPtr", "Other161c",
  "F161c", "F328", "F1568", "F1460", "F1470", "F1480", "F1464", "F156c",
];

/** Tween k-slots: k=0..7 tweened (mask 0xfffffeff), k=8 NEVER tweened at the
 *  walk site (mask bit 0x100 clear) but its timer still counts down, k=9
 *  tweened from Game+0x1adb4. Order the PE dispatches them in. */
const HUD_STAT_WALK_TWEEN_K_ORDER = [0, 1, 2, 3, 4, 5, 6, 7, 9];

function f32BitsOf(value) {
  const u = new Uint32Array(1);
  new Float32Array(u.buffer)[0] = Math.fround(value);
  return u[0] >>> 0;
}

function f32Of(bits) {
  const u = new Uint32Array(1);
  u[0] = bits >>> 0;
  return new Float32Array(u.buffer)[0];
}

/** Runtime-input key for player pack field `field` of player i. */
function hudStatPlayerKey(i, field) {
  return `hudStatPlayer${i}${field}`;
}

/** Runtime-input key for tween slot (g,k) field `field` (Current/Prev/
 *  Threshold/Timer). */
function hudStatSlotKey(g, k, field) {
  return `hudStatSlot${g}${k}${field}`;
}

/** Build the record-0 walk runtime inputs. Defaults: gate open, count 1
 *  (begin 0x1000, end 0x1004), container EMPTY (predA skipped), owner 1,
 *  small probes (k6/k7/k9 targets 1.0), all 20 slot states seeded with
 *  {current 1.0, prev 2.0, threshold 0.5, timer 0}. */
function walkRuntimeInputs(overrides = {}, players = []) {
  const rt = {
    managerStatFlag: 1,
    hudStatWalkBlobReady: 1,
    hudStatPlayerListBegin: 0x1000,
    hudStatPlayerListEnd: 0x1004,
    hudStatOwnerByte: 1,
    hudStatContainerBegin: 0x2000,
    hudStatContainerEnd: 0x2000,
    /* The runtime ABI carries these as raw f32 BITS (u32 fields in the
       layout + C++ struct; the PE reads entry+0x1568 etc. via movss). */
    hudStatWalkProbe1: f32BitsOf(0.01),
    hudStatWalkProbe2: 1,
    hudStatWalkProbe3: f32BitsOf(1.0),
    hudStatGame1adb4: f32BitsOf(0.42),
    hudStatSlotPtr0: 0,
    hudStatSlotPtr1: 0,
  };
  for (let g = 0; g < 2; g += 1) {
    for (let k = 0; k < 10; k += 1) {
      rt[hudStatSlotKey(g, k, "Current")] = 1.0;
      rt[hudStatSlotKey(g, k, "Prev")] = 2.0;
      rt[hudStatSlotKey(g, k, "Threshold")] = 0.5;
      rt[hudStatSlotKey(g, k, "Timer")] = 0;
    }
  }
  for (const [i, pack] of players.entries()) {
    for (const field of HUD_STAT_WALK_PLAYER_FIELDS) {
      if (field in pack) rt[hudStatPlayerKey(i, field)] = pack[field];
    }
  }
  return { ...rt, ...overrides };
}

/** A pack that passes every slot_get_or_insert gate (container empty, so
 *  predA is skipped; f172=0 so predB is false). Targets are all 1.0 except
 *  k9 = game1adb4*100 = 42 in the default walks. Ptr is the entry token. */
function walkPassPack(overrides = {}) {
  return {
    Ptr: 0x1000, PredA: 1, F2c: 0, F3bc: 0, F13c0: 0x1d, F172: 0, OtherPtr: 0,
    Other161c: 0, F161c: 0, F328: 0,
    /* f32 fields travel as raw bits (u32 ABI): 1.0 / 29.0 / 1.0 / 40.0 /
       1.0 / 1.0. */
    F1568: f32BitsOf(1.0), F1460: f32BitsOf(29.0), F1470: f32BitsOf(1.0),
    F1480: f32BitsOf(40.0), F1464: f32BitsOf(1.0), F156c: f32BitsOf(1.0),
    ...overrides,
  };
}

/** The first-call scratch pre-seed (host seeds owner/ptrs/slot states from
 *  the runtime inputs; delta = 0). Slots are a FLAT 20-entry array indexed
 *  g*10+k (2 rows x 10 k-slots), mirroring the C++ 83-word scratch. */
function walkSeedScratch(rt) {
  const slots = [];
  for (let g = 0; g < 2; g += 1) {
    for (let k = 0; k < 10; k += 1) {
      slots.push({
        current: Math.fround(rt[hudStatSlotKey(g, k, "Current")] ?? 0),
        delta: 0,
        prev: Math.fround(rt[hudStatSlotKey(g, k, "Prev")] ?? 0),
        threshold: Math.fround(rt[hudStatSlotKey(g, k, "Threshold")] ?? 0),
        timer: ((rt[hudStatSlotKey(g, k, "Timer")] ?? 0) | 0),
      });
    }
  }
  return {
    ownerByte: (rt.hudStatOwnerByte ?? 0) !== 0 ? 1 : 0,
    slotPtr0: (rt.hudStatSlotPtr0 ?? 0) >>> 0,
    slotPtr1: (rt.hudStatSlotPtr1 ?? 0) >>> 0,
    slots,
  };
}

/** Slot index in the flat scratch array for row g, k-slot k. */
function slotIdx(g, k) {
  return g * 10 + k;
}

/** Run the walk lane oracle on a first-call pre-seeded scratch. */
function walkRun(rt, stateOverrides = {}) {
  return hudStatWalkRun(
    walkSeedScratch(rt),
    rt,
    { frameCounter264f8: 0, ...stateOverrides },
  );
}

/** The 9 tween targets for row g's player pack (PE mask table; the model
 *  applies each tween to its OWN k-slot, never chained). */
function walkTweenTargets(rt, pack) {
  const f = Math.fround;
  /* Probes and pack stats travel as raw f32 BITS (u32 ABI) — read them
     back through f32Of, exactly like the C++ __builtin_bit_cast reads. */
  const probe1 = f32Of((rt.hudStatWalkProbe1 ?? 0) >>> 0);
  let clamped = f(probe1);
  if (clamped !== clamped) clamped = 0.0; /* maxss(probe1, 0.0): NaN -> 0.0 */
  if (clamped > 1.0) clamped = 1.0;       /* minss(x, 1.0) */
  if (clamped < 0.0) clamped = 0.0;       /* maxss(x, 0.0) */
  if (!hudStatRecomputeProbe2Live(rt.hudStatWalkProbe2 ?? 0)) clamped = 0.0; /* xorps */
  const probe3 = f32Of((rt.hudStatWalkProbe3 ?? 0) >>> 0);
  const owner = (rt.hudStatOwnerByte ?? 0) !== 0 ? 1 : 0;
  const t6 = owner
    ? f(clamped * 100.0)
    : f(f(f(1.0 - probe3) * clamped) * 100.0);
  const t7 = f(f(probe3 * clamped) * 100.0);
  const t9 = f(f32Of((rt.hudStatGame1adb4 ?? 0) >>> 0) * 100.0);
  return {
    0: f32Of((pack.F1568 ?? 0) >>> 0),
    1: f(30.0 / f(f32Of((pack.F1460 ?? 0) >>> 0) + 1.0)),
    2: f32Of((pack.F1470 ?? 0) >>> 0),
    3: f(f32Of((pack.F1480 ?? 0) >>> 0) / 40.0),
    4: f32Of((pack.F1464 ?? 0) >>> 0),
    5: f32Of((pack.F156c ?? 0) >>> 0),
    6: t6,
    7: t7,
    9: t9,
  };
}

/** Apply the tween + the post-tween countdown tick to slot state `slot`
 *  with the PE's tween law (via the shared playerhud helper) and the v83
 *  countdown law (v > 0 decrements exactly 1, signed). */
function walkSlotExpectation(slot, target, flag) {
  const tweened = playerHudStatBarTween(
    {
      currentBits: f32BitsOf(slot.current),
      deltaBits: f32BitsOf(slot.delta),
      prevBits: f32BitsOf(slot.prev),
      thresholdBits: f32BitsOf(slot.threshold),
      timer: slot.timer | 0,
    },
    f32BitsOf(target),
    flag,
  );
  const timer = (tweened.timer | 0) > 0 ? (tweened.timer | 0) - 1 : tweened.timer | 0;
  return {
    current: f32Of(tweened.currentBits),
    delta: f32Of(tweened.deltaBits),
    prev: f32Of(tweened.prevBits),
    threshold: slot.threshold,
    timer,
  };
}

test("recovered ABI is pinned at v96 (record idx 48 0x008607a0 set-arm arg-prep) with explicit struct sizes", () => {
  assert.equal(ABI_VERSION, 99);
  /* v79: record 2 (VA 0x006fb414..0x006fb474 + advance 0x00414a80) moved to
     resolvedBoundaries; state 520 -> 524 (globalTree4aba0Result byte at
     Game+0x4aba0), runtime 3748 -> 4532 (blob gate/count/begin/end + 32 x
     24-byte node packs {addr,next,prev,child,f0d,f18}), events unchanged. */
  /* v71 added the FUN_004257b0 blob to runtime inputs (2392 → 3172: the F4
     pre/post pointer pairs + capacity, the id-vector and container bounds,
     the stale byte channel, 9 per-player packs, 4 per-element packs and the
     3 list triples) and the pure Pass A/B accounting to events (436 → 464).
     v72 adds exactly four shell-gate words (3172 → 3188) and NOTHING else:
     state, constants and events must NOT move — the shell drop reuses the
     existing opaque_frame_effect_6fd7c0_shell counter.
     v73 adds NO input at all: the blue-room probe's `direction` is the frozen
     site constant -1 (PE 0x006fb9e0 / 0x008041f4, both `6a ff`), and giving
     it a runtime input would invent a degree of freedom the PE does not have.
     All four sizes are UNCHANGED from v72.
     v74 adds exactly four rewind-gate words (3188 → 3204) and NOTHING else:
     state, constants and events must NOT move — the further-narrowed drop
     reuses the existing opaque_frame_effect_6fd7c0_shell counter, and
     FUN_00705ee0's argument is the frozen -1 of PE 0x006fdb4d `6a ff`.
     v75 adds exactly two engine-prefix latch words (3204 -> 3212) and NOTHING
     else: state, constants and events must NOT move - the record-22 drop
     reuses the existing opaque_room_transition_engine_prefix counter.
     v76 adds exactly two timer-MT wire words (3212 -> 3220) and ONE event
     (464 -> 468, the in-module draw's post-state index); state and constants
     must NOT move. The 0x0098de58 interior already carried the v70 plan, so
     the boundary removal at v76 is the draw, not the floats.
     v86: HUD v5 try_pure wire for 0x0092f1c0. Runtime 6696 -> 6708
     (ready/mode/counter), events 480 -> 484 (counterOut).
     v87: HUD v5 try_pure wire for 0x008318a0. Runtime 6708 -> 6716
     (ready/mode). Events unchanged (484).
     v88: SFX sound-group walk split for 0x0092e300. Runtime 6716 -> 6720
     (soundGroupWalkReady). Events 484 -> 500 (slot3c/stores/pendingMask/applied).
     v89: 0x008ef990 state==2 arm translated pure (mode24ed8 -= 1 wrap +
     state clear when pre<=0, PE 0x8efdec..0x8efe04). No layout/event change.
     v90: 4212c0 flag_111 409030-pair gate (PE 0x421300..0x421316 + the B-sub
     root at Game+0x1d2ec). Runtime 6720 -> 6732 (pairReady / field5c /
     flag6c). Events unchanged (500). Code only; no struct realloc.
     v91: 4212c0 secondary==3 probe arm (40add0 pure-false). Runtime 6732 ->
     6756 (probeReady/probeResolved/add0Field4/add0ListCount/add0MatchIndex/
     add0Bitfield18). Events unchanged (500).
     v92: FUN_0098dba0 empty-vector walk arm blob gate. Runtime 6756 -> 6768
     (walkReady/walkBegin/walkEnd). Events 500 -> 504 (walkEmptySkip). The
     empty arm's walk loop is a proof-complete pure skip (PE 0x98dbe1
     test/jne + 0x98dc11 test/je); the fatal log 0xa112c0 stays host.
     v93: record 9 iterate-arm JOIN (0x8efc92..0x8efce9) blob-gated pure
     decision. Runtime 6768 -> 6800 (joinReady/joinProbe/joinIdx8 + the RTE
     956780 gate operands game/nodeBd/nodeF10/nodePtr/sentinel). Events
     504 -> 508 (joinPure). The JOIN tail is proven pure: idx8==probe-0xe
     -> NO-SFX exit (zero calls), or the RTE 956780 gate closed -> prep
     no-op and Play 0x92dc30 is the sole residual host call.
     v94: record idx 1 (0x0092e300) walk pending-mask law action-gated:
     the mask loop carries the SAME sfxStopAllGroupAction gate as the walk
     (PE 0x92e340 BYTE enabled / 0x92e352 UNSIGNED count precede every
     [e+0x29] store); disabled/empty groups set NO mask bits on their
     firstVoice slots even when pending09 is non-zero. No layout change.
     v94 (R3 log-split, record idx 10): FUN_0040add0 fatal log
     'AnimationData is NULL\n' (PE 0x40adde..0x40adee push 0xb1a504;
     push 0x10; call 0xa112c0; add esp,8) becomes a TYPED HOST EVENT
     (frameOpaque4212c0Add0LogNeeded). Events 508 -> 512. The log is NOT
     a return — the post-log probe flow (miss PE 0x40adfb/0x40adfd, bit
     0x40ae4e..0x40ae6a, false-arm clear 0x4213de..0x4213ea) runs on BOTH
     field_4 arms, so the miss law (probe_pure_false) applies without the
     old field_4!=0 gate. Split laws: 4212c0_add0_log_needed /
     probe_pure_false. No runtime input change.
     v95 (record idx 48 0x008607a0 set-arm arg-prep): the LuaEngine frame-
     unref SET arm (flag byte bit 1 set, PE 0x008607e7 LOW-BYTE test)
     publishes the lua_pcallk call-ARG laws as the typed-event arg-prep:
     LUA_REGISTRYINDEX 0xfff0b9d8 (0x860803/0x872996/0x8729e4), nargs 2 /
     nresults 1 (0x8729c8/0x8729c6), pcallk context errfunc/ctx/k == 0
     (0x8729c0..c4), pushed args 1 / 0xffffffff (0x8607d1/0x8607d8).
     Events 512 -> 536 (six u32 at 512/516/520/524/528/532). The pcallk
     STAYS typed-host: registry[fn_key] is mod bytecode (fn_key = P[4],
     P=[engine+0x10], host-time); 0xfff0b9d8 is REGISTRYINDEX, not the
     fn key. ready==0 (monolith) and the v57-dropped clear arm leave the
     prep words 0. No runtime input change. */
  assert.deepEqual(ABI_SIZES, { state: 524, constants: 32, runtimeInputs: 23696, events: 1260 });
  assert.equal(GAME_OBJECT_MIN_SIZE, 0x68d70);
  /* PE 0x00705f09 reads the third guard at Game+0x68d70, i.e. exactly ONE PAST
     the captured buffer. That coincidence is why the three guards are runtime
     inputs and not sparse state, so pin it rather than leave it to a comment. */
  assert.equal(RUNTIME_INPUTS_LAYOUT.frameEffectRewindGuard68d70.offset, 3200);
  assert.ok(
    !Object.keys(STATE_LAYOUT).some((n) => /rewindGuard/i.test(n)),
    "the guards must not become sparse state — 0x68d70 is outside the buffer",
  );
  /* v75: the latch is read at PE 0x0082ee9e, i.e. AFTER the 0x0082ee96 log
     call, so it must stay a runtime input the host re-supplies rather than a
     sparse field folded from the tick's opening capture. */
  assert.equal(RUNTIME_INPUTS_LAYOUT.engineAnm2LatchReady.offset, 3204);
  assert.equal(RUNTIME_INPUTS_LAYOUT.engineAnm2Latch.offset, 3208);
  /* v76: the timer-interior MT capture. mti is SIGNED i32 (the cold 625 seed
     path needs full int32 range); the index-out event is the new mti the
     host must apply to 0x00C34F04 per the frozen Room contract. */
  assert.equal(RUNTIME_INPUTS_LAYOUT.frameOpaque98dba0TimerMtReady.offset, 3212);
  assert.equal(RUNTIME_INPUTS_LAYOUT.frameOpaque98dba0TimerMtiIn.offset, 3216);
  assert.equal(EVENTS_LAYOUT.frameOpaque98dba0TimerMtIndexOut.offset, 464);
  assert.equal(EVENTS_LAYOUT.frameOpaque98dba0TimerMtIndexOut.type, "i32");
  assert.ok(
    !Object.keys(STATE_LAYOUT).some((n) => /engineAnm2Latch/i.test(n)),
    "the latch must not become sparse state — the PE reads it after a call",
  );
});

/* ---- ABI v67 Room capture contract shape ---- */

test("Room capture contract covers exactly the state fields without a buffer home", () => {
  const stateOnly = Object.keys(STATE_LAYOUT).filter((name) => !(name in BINARY_LAYOUT));
  /* The contract must account for every such field — one entry each, no
     extras — so a new STATE_LAYOUT field without a BINARY_LAYOUT home cannot
     silently reopen the stale-capture lane. */
  assert.deepEqual(
    Object.keys(HOST_OWNED_STATE_CONTRACT).sort(),
    stateOnly.sort(),
    "contract keys must be exactly STATE_LAYOUT minus BINARY_LAYOUT",
  );
  assert.equal(Object.keys(HOST_OWNED_STATE_CONTRACT).length, 36);
  /* Overlay set = contract minus the buffer-reclassified entry. */
  assert.equal(HOST_OWNED_STATE_FIELDS.length, 35);
  assert.ok(!HOST_OWNED_STATE_FIELDS.includes("rankDisplayClear3b0Out"));
  for (const [name, spec] of Object.entries(HOST_OWNED_STATE_CONTRACT)) {
    assert.ok(typeof spec.address === "string" && spec.address.length > 0, `${name} address`);
    assert.ok([1, 2, 4].includes(spec.bytes), `${name} bytes`);
    assert.ok(["i32", "u32", "f32", "u8"].includes(spec.type), `${name} wire type`);
    assert.ok(["inout", "out", "buffer"].includes(spec.direction), `${name} direction`);
    assert.ok(typeof spec.recapture === "string" && spec.recapture.length > 0, `${name} recapture`);
    assert.equal(spec.type, STATE_LAYOUT[name].type, `${name} wire type must match STATE_LAYOUT`);
    assert.ok(Object.isFrozen(spec), `${name} entry must be frozen`);
  }
  assert.ok(Object.isFrozen(HOST_OWNED_STATE_CONTRACT));
  assert.ok(Object.isFrozen(HOST_OWNED_STATE_FIELDS));
  /* Output lanes are exactly the two documented ones. */
  assert.deepEqual(
    Object.keys(HOST_OWNED_STATE_CONTRACT).filter((n) => HOST_OWNED_STATE_CONTRACT[n].direction === "out").sort(),
    ["rankDisplayTailOut", "roomDescShortAe"],
  );
  /* The gate carrier's exact PE location, per the recovered evidence. */
  assert.equal(HOST_OWNED_STATE_CONTRACT.roomDescFlags44.address, "*(Room+0x4)+0x44");
  assert.equal(HOST_OWNED_STATE_CONTRACT.roomDescClearCount4a.bytes, 2);
  assert.equal(HOST_OWNED_STATE_CONTRACT.roomType8.address, "Room+0x8");
  assert.equal(HOST_OWNED_STATE_CONTRACT.roomClearDelay11ec.address, "Room+0x11ec");
});

test("rankDisplayClear3b0Out is buffer-reclassified through the alias map", () => {
  assert.equal(HOST_OWNED_STATE_CONTRACT.rankDisplayClear3b0Out.direction, "buffer");
  assert.deepEqual(STATE_TO_BINARY_ALIASES, { rankDisplayClear3b0Out: "rankDisplayByte3b0" });
  /* Every alias source is a state field WITHOUT its own BINARY_LAYOUT key
     (otherwise writeStruct would double-write one offset), and every alias
     target is a real buffer home. */
  for (const [stateName, binaryName] of Object.entries(STATE_TO_BINARY_ALIASES)) {
    assert.ok(stateName in STATE_LAYOUT, `${stateName} must be a STATE_LAYOUT key`);
    assert.ok(!(stateName in BINARY_LAYOUT), `${stateName} must not also be a BINARY_LAYOUT key`);
    assert.ok(binaryName in BINARY_LAYOUT, `${binaryName} must be a BINARY_LAYOUT key`);
  }
  assert.equal(BINARY_LAYOUT[STATE_TO_BINARY_ALIASES.rankDisplayClear3b0Out].offset, 0x1da00);
});

test("overlayHostOwnedState honours callers on inout lanes and pins output lanes", () => {
  const captured = Object.fromEntries(Object.keys(STATE_LAYOUT).map((n) => [n, 0]));
  captured.shortTimer = 42; // binary-homed: overlay must not touch it
  captured.roomDescShortAe = 7; // out lane: overlay must pin 0
  captured.rankDisplayTailOut = 3; // out lane: overlay must pin 0
  const out = overlayHostOwnedState(captured, {
    roomDescFlags44: 9,
    roomWaterAmount7240: 0.1, // f32 lane must round to float32
    roomDescShortAe: 11, // caller CANNOT drive an out lane
    rankDisplayTailOut: 1, // caller CANNOT drive an out lane
    shortTimer: 999, // binary-homed keys are ignored by the overlay
  });
  assert.equal(out.roomDescFlags44, 9);
  assert.equal(out.roomWaterAmount7240, Math.fround(0.1));
  assert.equal(out.roomDescShortAe, 0);
  assert.equal(out.rankDisplayTailOut, 0);
  assert.equal(out.shortTimer, 42);
  assert.equal(out.roomAlive12c0, 0, "absent inout fields take the contract default 0");
  /* No hostState at all = the deterministic empty-Room default on every lane. */
  const bare = overlayHostOwnedState({ ...captured, roomTimer722c: 77 }, null);
  assert.equal(bare.roomTimer722c, 0);
});

test("the C++ capture assigns every host-owned member (v67 contract)", () => {
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const captureBody = source.slice(
    source.indexOf("int32_t isaac_game_update_slice_capture("),
    source.indexOf("int32_t isaac_game_update_slice_apply("),
  );
  /* Static shape only — the behavioural discriminator is the poisoned-scratch
     capture assert in verify-game-update-slice.mjs and the fresh-vs-warm
     session tests in decomp-frame-path.test.js. */
  const expected = {
    roomDescFlags44: "room_desc_flags_44",
    roomDescClearCount4a: "room_desc_clear_count_4a",
    roomDescShortAe: "room_desc_short_ae",
    rankDisplayTailOut: "rank_display_tail_out",
    roomClearDelay11ec: "room_clear_delay_11ec",
    roomCollectibleTimer7764: "room_collectible_timer_7764",
    roomAmbientFlag745c: "room_ambient_flag_745c",
  };
  for (const member of Object.values(expected)) {
    assert.match(
      captureBody,
      new RegExp(`state->${member} = 0`),
      `capture must pin state->${member} deterministically`,
    );
  }
});

