test("ABI v107 (wave-29 merge): mid-restock typed drop + the 36 rebound lanes land in JSON/mirrors", () => {
  /* §2 of the wave-29 merge: the record idx 39 mid-restock seed==0 fatal
     becomes the typed event midRestockSeedZeroDrop @984 (events 984 -> 988)
     in all three mirrors; the 18 phone-home probe lanes REBIND to
     6800..6868, the 92f1c0 receiver pair sits at 6872/6876, the 4212c0 A/B
     pack at 7656..7688 and the tcsStats vector at 7960..7984 (was stale
     7108..7176 / 6872..6904 / 8356..8380). */
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  /* Typed drop event: JSON row + layout + cpp field + module write. */
  const ev = spec.events.find((e) => e.name === "midRestockSeedZeroDrop");
  assert.ok(ev, "spec records midRestockSeedZeroDrop");
  assert.equal(ev.offset, 984, "event offset 984 (next-free after 980)");
  assert.equal(ev.bytes, 4, "event bytes");
  assert.match(ev.abiV107 || "", /mid-restock|seed|984/i, "abiV107 note");
  assert.equal(EVENTS_LAYOUT.midRestockSeedZeroDrop.offset, 984, "model layout @984");
  assert.ok(header.includes("uint32_t mid_restock_seed_zero_drop;"), "header field");
  assert.ok(source.includes("events->mid_restock_seed_zero_drop ="), "cpp write");
  assert.ok(source.includes("static_assert(sizeof(IsaacGameUpdateSliceEvents) == 1260"),
    "cpp sizeof pin 996 (v119 +1 tail slot)");
  assert.equal(ABI_SIZES.events, 1260, "events size 996");
  /* Wave-30 merge: record idx 39 REMOVED — the boundary row moved to
     resolvedBoundaries (46 -> 45; 4th removal since v79); the residual
     coarse counter @220 + typed drop @984 stay committed. */
  const rec39 = spec.resolvedBoundaries.find((b) => b.name === "opaqueRoomUpdateTailMidRestock");
  assert.ok(rec39, "record idx 39 rides resolvedBoundaries (REMOVED at ABI v108)");
  assert.equal(rec39.targetVa, "0x00805408");
  assert.match(rec39.operation, /REMOVED at ABI v108/);
  assert.match(rec39.abiV108 || "", /idx 39|46->45|desc pack/i, "idx39 abiV108 key");
  assert.match(rec39.evidence || "", /desc|seed58|all-or-nothing|MONOLITHIC|full-capture/i);
  assert.ok(!spec.opaqueBoundaries.some((b) => b.idx === 39),
    "record idx 39 is GONE from opaqueBoundaries (46 -> 45)");
  assert.equal(spec.opaqueBoundaries.length, 24,
    "count 26 -> 25 (record idx 27 roomTriggerClearAudio REMOVED at ABI v138, update-v138-audio-alt-tail-pack); count 27 -> 26 (record idx 26 roomTriggerClearAudioNonGreed REMOVED at ABI v136, update-v136-audio-head-pack); count 32 -> 31 (record idx 45 REMOVED at v128, 18th removal since v79); count 33 -> 32 (record idx 38 REMOVED at v127, 17th removal since v79); count 34 -> 33 (record idx 40 REMOVED at v126, 16th removal since v79); count 35 -> 34 (record idx 25 REMOVED at v125, 15th removal since v79); count 36 -> 35 (record idx 46 REMOVED at v124, 14th removal since v79); count 37 -> 36 (record idx 19 REMOVED at v122); count 38 -> 37 (record idx 47 REMOVED at v121); count 39 -> 38 (record idx 41 REMOVED at v120); count 44 -> 43 (record idx 16 REMOVED at v110, 6th removal since v79); count 45 -> 44 (record idx 12 REMOVED at v109, 5th removal since v79); count 46 -> 45 (record idx 39 REMOVED at v108, 4th removal since v79)");
  /* The 36 rebound lanes at the module offsets (compiled-struct truth). */
  const rows = new Map(spec.runtimeInputs.map((r) => [r.name, r]));
  for (const [name, off] of [
    ["frameOpaque98dba0956110Ready", 6800],
    ["frameOpaque98dba0956110VtableResult7", 6864],
    ["frameOpaque98dba0956110GeneralResult", 6868],
    ["opaque0092f1c0Limit", 6872],
    ["opaque0092f1c0Field14", 6876],
    ["frameOpaque4212c0AbPackReady", 7656],
    ["frameOpaque4212c0BLoopFlag", 7688],
    ["tcsStatsVecReady", 7960],
    ["tcsStatsGameByte8", 7984],
  ]) {
    const row = rows.get(name);
    assert.ok(row, `spec records ${name}`);
    assert.equal(row.offset, off, `${name} offset`);
    assert.equal(RUNTIME_INPUTS_LAYOUT[name].offset, off, `layout ${name} offset`);
  }
  /* The obsolete capture rows are dropped and the name-blob size fixed. */
  assert.ok(!rows.has("state24ecc8ef990ListenerIds"), "ListenerIds dropped");
  assert.ok(!rows.has("state24ecc8ef990ListenerBits"), "ListenerBits dropped");
  const lyr = rows.get("engineAnm2LayerNames");
  assert.ok(lyr, "engineAnm2LayerNames row stays");
  assert.equal(lyr.bytes, 256, "layer names bytes 256");
  assert.equal(RUNTIME_INPUTS_LAYOUT.engineAnm2LayerNames.size, 256, "layout size 256");
  /* The module reads them at the rebound offsets (load-constant truth). */
  assert.match(header, /frame_opaque_98dba0_956110_ready/);
  assert.match(header, /frame_opaque_4212c0_ab_pack_ready/);
  assert.match(header, /tcs_stats_vec_ready/);
});

/* Wave-31 merge: record idx 12 REMOVED — the boundary row moved to
   resolvedBoundaries (45 -> 44; 5th removal since v79); the residual
   coarse counters @104/108/112/116 + typed seam events @912/916 +
   typed pack trio @968/972/976 stay committed. */
test("ABI v109 (wave-31 merge): record idx 12 rides resolvedBoundaries — JSON rows, event slots, pack lanes and the count all pin the removal", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  const rec12 = spec.resolvedBoundaries.find((b) => b.targetVa === "0x006fd7c0");
  assert.ok(rec12, "record idx 12 rides resolvedBoundaries (REMOVED at ABI v109)");
  assert.equal(rec12.name, "opaqueCall006fd7c0");
  assert.match(rec12.operation, /REMOVED at ABI v109/);
  assert.match(rec12.evidence || "", /full-capture|update-v108-record12-arms|shot|W30-S4/i,
    "idx12 evidence names the W30-S4 audit");
  assert.match(rec12.abiV109 || "", /idx 12|45->44/i, "idx12 abiV109 key");
  assert.ok(!spec.opaqueBoundaries.some((b) => b.idx === 12),
    "record idx 12 is GONE from opaqueBoundaries (45 -> 44)");
  assert.equal(spec.opaqueBoundaries.length, 24,
    "count 26 -> 25 (record idx 27 roomTriggerClearAudio REMOVED at ABI v138, update-v138-audio-alt-tail-pack); count 27 -> 26 (record idx 26 roomTriggerClearAudioNonGreed REMOVED at ABI v136, update-v136-audio-head-pack); count 32 -> 31 (record idx 45 REMOVED at v128, 18th removal since v79); count 33 -> 32 (record idx 38 REMOVED at v127, 17th removal since v79); count 34 -> 33 (record idx 40 REMOVED at v126, 16th removal since v79); count 35 -> 34 (record idx 25 REMOVED at v125, 15th removal since v79); count 36 -> 35 (record idx 46 REMOVED at v124, 14th removal since v79); count 37 -> 36 (record idx 19 REMOVED at v122); count 38 -> 37 (record idx 47 REMOVED at v121); count 39 -> 38 (record idx 41 REMOVED at v120); count 44 -> 43 (record idx 16 REMOVED at v110, 6th removal since v79); count 45 -> 44 (record idx 12 REMOVED at v109, 5th removal since v79)");
  /* Event slots UNCHANGED: the Mode4Sfx counter @108 (row 19), the shell
     @112 (row 20) and the engine prefix @116 (row 21 REMOVED, counter
     stays) all remain — no bare 6fd7c0 slot exists. */
  const ev = new Map(spec.events.map((e) => [e.offset, e.name]));
  assert.equal(ev.get(108), "opaqueCall006fd7c0Mode4Sfx", "slot @108 row 19 STAYS");
  assert.equal(ev.get(112), "opaqueFrameEffect6fd7c0Shell", "slot @112 row 20 STAYS");
  assert.equal(ev.get(116), "opaqueRoomTransitionEnginePrefix", "slot @116 row 21 counter STAYS");
  /* Pack lanes UNCHANGED @14292..14324 (the transition pack stays live
     behind the two-voucher gate). */
  const rt = new Map(spec.runtimeInputs.map((r) => [r.name, r.offset]));
  for (const [name, off] of [
    ["transition6fd7c0Game0", 14292], ["transition6fd7c0AltPathProbe", 14296],
    ["transition6fd7c0RouteProbe", 14300], ["transition6fd7c0PlayerLoopProbe", 14304],
    ["transition6fd7c0RoomType8", 14308], ["transition6fd7c0RoomSubroomFlag44", 14312],
    ["transition6fd7c0BlueRoomProbe", 14316], ["transition6fd7c0EnginePredProbe", 14320],
    ["transition6fd7c0Ready", 14324],
  ]) {
    assert.equal(rt.get(name), off, `${name} straddles the pack block`);
  }
  assert.equal(RUNTIME_INPUTS_LAYOUT.transition6fd7c0Ready.offset, 14324, "layout pack tail");
  assert.equal(RUNTIME_INPUTS_LAYOUT.opaqueCall006fd7c0Ready.offset, 13732, "layout ready voucher");
});

/* Wave-31 merge: record idx 16 REMOVED — the boundary row moved to
   resolvedBoundaries (44 -> 43; 6th removal since v79); the residual
   coarse counter opaqueRoomUpdatePrefixB8 @148 + the B8 capture lanes
   (roomB8BlobReady @204 / roomGridCells @200, k-blob scratch exports)
   stay committed — the counter is the observation channel for the
   capture-absence mono residual, not a removable lane. */
test("ABI v110 (wave-31 merge): record idx 16 rides resolvedBoundaries — JSON rows, event slot @148, capture lanes and the count all pin the removal", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  const rec16 = spec.resolvedBoundaries.find((b) => b.targetVa === "span" && b.name === "opaqueRoomUpdatePrefixB8");
  assert.ok(rec16, "record idx 16 rides resolvedBoundaries (REMOVED at ABI v110)");
  assert.equal(rec16.name, "opaqueRoomUpdatePrefixB8");
  assert.match(rec16.operation, /REMOVED at ABI v110/);
  assert.match(rec16.evidence || "", /full-capture|dt-b8|update-v109-record16-eval/i,
    "idx16 evidence names the record-16 eval theorem arms");
  assert.match(rec16.abiV110 || "", /idx 16|45->44|43/i, "idx16 abiV110 key");
  assert.ok(!spec.opaqueBoundaries.some((b) => b.idx === 16),
    "record idx 16 is GONE from opaqueBoundaries (44 -> 43)");
  assert.equal(spec.opaqueBoundaries.length, 24,
    "count 26 -> 25 (record idx 27 roomTriggerClearAudio REMOVED at ABI v138, update-v138-audio-alt-tail-pack); count 27 -> 26 (record idx 26 roomTriggerClearAudioNonGreed REMOVED at ABI v136, update-v136-audio-head-pack); count 32 -> 31 (record idx 45 REMOVED at v128, 18th removal since v79); count 33 -> 32 (record idx 38 REMOVED at v127, 17th removal since v79); count 34 -> 33 (record idx 40 REMOVED at v126, 16th removal since v79); count 35 -> 34 (record idx 25 REMOVED at v125, 15th removal since v79); count 36 -> 35 (record idx 46 REMOVED at v124, 14th removal since v79); count 37 -> 36 (record idx 19 REMOVED at v122); count 38 -> 37 (record idx 47 REMOVED at v121); count 39 -> 38 (record idx 41 REMOVED at v120); count 44 -> 43 (record idx 16 REMOVED at v110, 6th removal since v79)");
  /* Event slot UNCHANGED: the coarse counter @148 STAYS in the events ABI
     (fires on every capture-absence gate-miss residual byte-for-byte). */
  const ev = new Map(spec.events.map((e) => [e.offset, e.name]));
  assert.equal(ev.get(148), "opaqueRoomUpdatePrefixB8", "slot @148 counter STAYS");
  /* Capture lanes UNCHANGED: ready @204 / cells @200 / the k-blob scratch
     exports stay committed (captureUpdateB8 all-or-nothing grid record). */
  const rt = new Map(spec.runtimeInputs.map((r) => [r.name, r.offset]));
  assert.equal(rt.get("roomB8BlobReady"), 204, "roomB8BlobReady @204");
  assert.equal(rt.get("roomGridCells"), 200, "roomGridCells @200");
  assert.equal(RUNTIME_INPUTS_LAYOUT.roomB8BlobReady.offset, 204, "layout ready @204");
  assert.equal(EVENTS_LAYOUT.opaqueRoomUpdatePrefixB8.offset, 148, "layout counter @148");
});

