test("ABI v86: the 92f1c0 gate is a FULL-WORD dispatch, not a low-byte test", () => {
  /* PE 0x92f1f0..0x92f1fc: mov eax,[ebx]; dec eax; cmp eax,3; ja 0x92ff60 —
     the switch index is (uint32)(mode-1) > 3 compared on the FULL dword.
     Modes whose LOW byte is 1..4 but that carry high bits (0x101, 0x104,
     0x1000004, 0x20000001, 0x1ff0002) must fall to the pure tail, exactly
     like mode 0x100 / 0xffffffff. A byte-narrowed translation (compare
     (mode&0xff)-1) would wrongly classify these as host cases 1..4.
     Independent PE-truth: same dec/cmp/ja shape drives every case body. */
  for (const mode of [0x101, 0x104, 0x1000004, 0x20000001, 0x1ff0002]) {
    assert.equal(opaque0092f1c0NeedsHost({ ready: 1, mode }), false,
      `mode=${mode} (low byte ${mode & 0xff}) must be pure`);
    const out = step({ gate1ba78: 1, status22ed4: 0, status22edc: 0 }, {
      opaque0092f1c0Ready: 1,
      opaque0092f1c0Mode: mode,
      opaque0092f1c0Counter: 7,
    });
    assert.equal(out.events.opaqueCall0092f1c0, 0, `mode=${mode} host`);
    assert.equal(out.events.continuationKind,
      UPDATE_CONTINUATION.RETURN_AFTER_GATE_1BA78, `mode=${mode} cont`);
    assert.equal(out.events.opaque0092f1c0CounterOut, 8, `mode=${mode} inc`);
    assert.equal(out.state.status22ed4, 0, `mode=${mode} no tail store`);
    assert.equal(out.state.status22edc, 0);
  }
  /* Control: the SAME low byte with no high bits IS a host case — the gate
     cannot be reading the low byte alone. */
  for (const mode of [1, 2, 4]) {
    assert.equal(opaque0092f1c0NeedsHost({ ready: 1, mode }), true,
      `mode=${mode} bare low byte still hosts`);
  }
});

test("ABI v87: the 8318a0 gate is a FULL-WORD dispatch, not a low-byte test", () => {
  /* Same shared law (hudGate92f1c0TryPure): full-word (mode-1) > 3. */
  for (const mode of [0x101, 0x104, 0x1000004, 0x1ff0002]) {
    assert.equal(opaque008318a0NeedsHost({ ready: 1, mode }), false,
      `mode=${mode} (low byte ${mode & 0xff}) must be pure`);
    const out = step({ gate1b83c: 1 }, {
      opaque008318a0Ready: 1,
      opaque008318a0Mode: mode,
    });
    assert.equal(out.events.opaqueCall008318a0, 0, `mode=${mode} 8318a0`);
    assert.equal(out.events.opaqueCall0098dba0PlayerWalk, 1, `mode=${mode} walk`);
    assert.equal(out.events.continuationKind,
      UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK, `mode=${mode} cont`);
  }
  for (const mode of [1, 2, 4]) {
    assert.equal(opaque008318a0NeedsHost({ ready: 1, mode }), true,
      `mode=${mode} bare low byte still hosts`);
  }
});

test("ABI v86: try_pure tail stores Game+0x22ed4/0x22edc when recaptured mode is 2 or 3", () => {
  /* Drop path never ran a case body, so modeAfterBody === mode.
     Modes 2/3 are HOST at the head, so this only models the tail helper
     itself (HUD v5 BY REFERENCE) — the step path cannot reach tail
     stores on a drop. Pin the helper so a re-derive cannot invert it. */
  const two = opaque0092f1c0ApplyTail({ mode: 2, counter: 9 });
  assert.equal(two.counterOut, 10);
  assert.equal(two.tailStoresNeeded, true);
  const three = opaque0092f1c0ApplyTail({ mode: 3, counter: -1 });
  assert.equal(three.counterOut, 0);
  assert.equal(three.tailStoresNeeded, true);
  const zero = opaque0092f1c0ApplyTail({ mode: 0, counter: 0x7fffffff });
  assert.equal(zero.counterOut, -2147483648, "32-bit wrap");
  assert.equal(zero.tailStoresNeeded, false);
});

