/* ===== ABI v96: 0x008318a0 modes 1/2/4 decision laws (wave-20 S2 close) ====
   Evidence: disasm-8318a0-full.txt (extent 0x8318a0..0x8327bb, int3 pad
   0x8327dc, next fn 0x8327e0). Exports-only; ABI 95; layouts frozen. The
   SFX-manager base 0xc798e0 is .data BSS (file-backed .data ends 0xc61800)
   — OUTSIDE BINARY_LAYOUT: plan globals are ABI-96 lane requests. */

test("ABI v96: 8318a0 mode-1 SFX-manager block entry gate (0x831c64..0x831e31)", () => {
  /* (candidate_found!=0 || type==0x15) && type!=0x13 && !(0xb/0x10 &&
     field_14==0x18304). FULL-DWORD type/field_14 compares. */
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 0x15, 0), 1, "candidate||0x15");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(0, 0x15, 0), 1, "type 0x15 always");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 0x13, 0), 0, "0x13 = handoff block");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 0xb, 0x18304), 0, "0xb + room18304 clear arm");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 0xb, 0x18305), 1, "0xb + other room");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 0x10, 0x18304), 0, "0x10 + room18304 clear arm");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 5, 0), 1, "plain type");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(0, 5, 0), 0, "no candidate, not 0x15");
  /* FULL-DWORD: 0x10000013 != 0x13, 0x1000000b != 0xb. */
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 0x10000013, 0), 1, "wide 0x13");
  assert.equal(gameUpdateSlice8318a0Mode1ManagerBlockGate(1, 0x1000000b, 0x18304), 1, "wide 0xb");
});

