test("ABI v96: 8318a0 mode-1 SFX-manager 9-store typed plan (0x831e6d..0x831f2f)", () => {
  assert.equal(GAME_UPDATE_SLICE_8318A0_SFX_MANAGER_STORES, 9);
  let p = gameUpdateSlice8318a0SfxManagerStorePlan(0, 0, 0, 0x12345678);
  assert.equal(p.length, 9, "nine stores in program order");
  /* v99 fold correction (update-v99-record4-fold §2c): row0 is the byte
     store at queue node+4 (0x831e5a lea edx,[esi+4]) -> mgrOff 0x4;
     row7 0xc79790 = mgr-0x150 -> 0xfffffeb0; row8 0xc7978c = mgr-0x154
     -> 0xfffffeac. */
  assert.deepEqual(p[0], { mgrOff: 0x4, size: 1, value: 0, element: 1 }, "bit5 clear -> 0 (node+4 byte)");
  assert.deepEqual(p[1], { mgrOff: 0x0, size: 4, value: 0x12345678, element: 1 }, "[esi]=79948");
  assert.deepEqual(p[2], { mgrOff: 0x20, size: 4, value: 0, element: 0 }, "+0x20 = 0");
  assert.deepEqual(p[3], { mgrOff: 0x24, size: 4, value: 6, element: 0 }, "bit4 clear -> 6 (cmove)");
  assert.deepEqual(p[4], { mgrOff: 0x28, size: 4, value: 7, element: 0 });
  assert.deepEqual(p[5], { mgrOff: 0x2c, size: 4, value: 1, element: 0 });
  assert.deepEqual(p[6], { mgrOff: 0x30, size: 4, value: 7, element: 0 });
  assert.deepEqual(p[7], { mgrOff: 0xfffffeb0, size: 4, value: 0xffffffff, element: 0 }, "79790-1 wraps (mgr-0x150)");
  assert.deepEqual(p[8], { mgrOff: 0xfffffeac, size: 4, value: 0, element: 0 }, "new==0 -> 0 (mgr-0x154)");
  p = gameUpdateSlice8318a0SfxManagerStorePlan(0x24, 5, 0x1234, 0);
  assert.equal(p[0].value, 1, "bit5 set (0x20) -> 1");
  assert.equal(p[3].value, 1, "bit4 set (0x4) -> 1");
  assert.equal(p[7].value, 4, "79790-1");
  assert.equal(p[8].value, 0x1234, "new!=0 keeps 7978c");
  p = gameUpdateSlice8318a0SfxManagerStorePlan(0x100, 0, 0, 0);
  assert.equal(p[0].value, 0, "0x100 bit5 clear");
  assert.equal(p[3].value, 6, "0x100 bit4 clear -> 6 (wide source, not low byte)");
});

