test("ABI v118: 8318a0 leftover laws are in source/build/JSON (ABI 99, idx 4 STAYS)", () => {
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const build = readFileSync(join(root, "scripts", "decomp", "build-game-update-slice.mjs"), "utf8");
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  const names = [
    "8318a0_pickup_latch",
    "8318a0_mode1_score_block_gate",
    "8318a0_mode1_type13_pickup_gate",
    "8318a0_mode1_type13_b64_exit",
    "8318a0_mode1_4ce0f0_esi_remap",
    "8318a0_mode3_membership_hit",
    "8318a0_mode3_flag_2000000_skip",
    "8318a0_mode3_type3_string_gate",
    "8318a0_mode3_miss_arm",
    "8318a0_mode3_true_arm",
    "8318a0_mode3_anim_arg",
    "8318a0_mode3_anim_live",
    "8318a0_mode3_walk_410_cond",
    "8318a0_mode3_host_va_7ab380",
    "8318a0_mode3_host_va_7ab550",
  ];
  for (const name of names) {
    assert.ok(source.includes(`isaac_game_update_slice_${name}`), `cpp ${name}`);
    assert.ok(header.includes(`isaac_game_update_slice_${name}`), `header ${name}`);
    assert.ok(build.includes(`_isaac_game_update_slice_${name}`), `build ${name}`);
    assert.ok(spec.translatedHelpers.some((t) => t.name === `isaac_game_update_slice_${name}`),
      `json helper ${name}`);
  }
  assert.equal(spec.abiVersion, 99);
  const rec = spec.opaqueBoundaries.find((b) => b.targetVa === "0x008318a0");
  assert.ok(rec, "idx 4 stays");
  assert.match(rec.abiV118 || "", /pickup_latch|0x3c5/i);
  assert.equal(spec.opaqueBoundaries.length, 24);
  const lawBlock = header.slice(header.indexOf("8318a0_pickup_latch"));
  assert.ok(!/uint8_t [a-z_0-9]+[,)]/.test(lawBlock), "no uint8_t scalar params");
});

test("ABI v118: shipped Wasm exposes 8318a0 leftover laws (skip if stale)", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run the coordinator merge build first — this probe needs the module");
    return;
  }
  const wasm = new WebAssembly.Module(readFileSync(slicePath));
  const inst = new WebAssembly.Instance(wasm, {});
  const pick = (n) => inst.exports[n] ?? inst.exports[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (pre-merge); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const latch = pick("isaac_game_update_slice_8318a0_pickup_latch");
  const score = pick("isaac_game_update_slice_8318a0_mode1_score_block_gate");
  const mem = pick("isaac_game_update_slice_8318a0_mode3_membership_hit");
  if (typeof latch !== "function" || typeof score !== "function" || typeof mem !== "function") {
    t.skip("module predates the leftover exports");
    return;
  }
  assert.equal(latch(0x1000, 0x3c5, 0xa) | 0, 1);
  assert.equal(latch(0x1000, 0x103c5, 0xa) | 0, 0);
  assert.equal(score(0x13, 1, 1, 0xffffffff) | 0, 0, "SIGNED score");
  assert.equal(mem(0x100) | 0, 0, "BYTE membership");
  assert.equal(pick("isaac_game_update_slice_8318a0_mode3_host_va_7ab380")() >>> 0, 0x007ab380);
});


