/* ===== ABI v96 (wave-23, update-v98-record4-wire): the mode-1
   sfx_manager_store_plan emission LIVE on the pure arm ==================
   The gate_1b83c wire (cpp + model mirror) consumes the committed pack
   (runtime 13736..14152; NOTES update-v98-record4-wire §4) and +1s the
   typed event opaque_008318a0_sfx_manager_stores @932 exactly when the
   mode-1 manager block 0x831e31 runs: candidate_found = [ebp-0x41]
   (set 1 @0x83191c; cleared @0x831ae4 iff a live span entry has
   b173==0 && (b1398||b139a) && (ptr7c==0 || byte34==0) && w3fc!=4 —
   FULL-DWORD w3fc; entries with b173!=0 or ptr7c!=0&&byte34!=0 exit
   0x831aff before the score block) then mode1_manager_block_gate
   (PE 0x831c64 cmp byte [ebp-0x41],0 / jne 0x831c75, FULL-DWORD
   type/field_14). Coarse opaque_call_008318a0 STAYS (record-12 seam
   precedent); every gate miss is byte-for-byte inert. Pack rows are the
   span slots in order (count = (end-begin)>>2, cap 8); null-slot rows
   MUST be all-zero. */

const PACK8 = [0, 0, 0, 0, 0, 0, 0, 0];

function packRt(overrides = {}) {
  return {
    opaque008318a0Ready: 1,
    opaque008318a0Mode: 1,
    opaque8318a0PlayerEntryReady: 1,
    opaque8318a0PlayerEntryCount: 0,
    opaque8318a0PlayerEntryB173: [...PACK8],
    opaque8318a0PlayerEntryB1398: [...PACK8],
    opaque8318a0PlayerEntryB139a: [...PACK8],
    opaque8318a0PlayerEntryB171: [...PACK8],
    opaque8318a0PlayerEntryW410: [...PACK8],
    opaque8318a0PlayerEntryW3fc: [...PACK8],
    opaque8318a0PlayerEntryPtr7c: [...PACK8],
    opaque8318a0PlayerEntryB34: [...PACK8],
    opaque8318a0PlayerEntryB88: [...PACK8],
    opaque8318a0PlayerEntryW1600: [...PACK8],
    opaque8318a0PlayerEntryW418: [...PACK8],
    opaque8318a0PlayerEntryW16c: [...PACK8],
    ...overrides,
  };
}

function seamStep(rt, stateOverrides = {}) {
  return step({ gate1b83c: 1, ...stateOverrides }, rt);
}

test("ABI v96 (wave-23): 8318a0 mode-1 store-plan seam fires on the empty walk (candidate flag stays 1)", () => {
  /* count==0 -> the walk never runs -> [ebp-0x41] stays 1 (0x83191c) ->
     candidate_found=1 -> manager gate opens for any non-0x13/0xb/0x10
     type. The coarse 8318a0 host edge STAYS (record-12 precedent). */
  for (const type of [5, 0x15, 0x3c5]) {
    const out = seamStep(packRt(), { engineField1c: type, engineField14: 0 });
    assert.equal(out.events.opaque008318a0SfxManagerStores, 1,
      `type ${type} empty walk -> typed event fires`);
    assert.equal(out.events.opaqueCall008318a0, 1, "coarse edge stays");
    assert.equal(out.events.opaqueCall0098dba0PlayerWalk, 1, "walk edge stays");
  }
});

test("ABI v96 (wave-23): candidate_found clears on the scored entry (0x831ae4) and 0x15 re-opens", () => {
  /* Entry: b173==0 && b1398 set && ptr7c==0 && w3fc=0x42 -> the score
     block runs -> flag cleared -> candidate_found=0. Type 0x15 passes the
     gate anyway; type 5 closes it. */
  const scored = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  const fired = seamStep(scored, { engineField1c: 0x15, engineField14: 0 });
  assert.equal(fired.events.opaque008318a0SfxManagerStores, 1, "0x15 fires with cleared candidate");
  const closed = seamStep(scored, { engineField1c: 5, engineField14: 0 });
  assert.equal(closed.events.opaque008318a0SfxManagerStores, 0, "plain type + cleared candidate -> no event");
});

test("ABI v96 (wave-23): the per-entry score gates are exact (b173 / ptr7c+byte34 / w3fc==4 / wide bytes)", () => {
  /* b173 != 0 -> 0x8319c9 vcall path exits at 0x831aff: never scores. */
  const b173Set = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB173: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(b173Set, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 1,
    "b173 set -> no clear -> fires");
  /* ptr7c != 0 && byte34 != 0 -> 0x8319f0 block exits at 0x831aff: no clear. */
  const ptrGate = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryPtr7c: [0x1000, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryB34: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(ptrGate, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 1,
    "ptr+0x34 set -> no clear -> fires");
  /* Same but byte34==0 -> the 0x831a19 lane -> scores -> clears. */
  const ptrGateOpen = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryPtr7c: [0x1000, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryB34: [0, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(ptrGateOpen, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 0,
    "byte34 clear -> scores -> no event");
  /* w3fc==4 -> 0x831af8 [edi+0x171]=0 store, flag untouched. */
  const w3fc4 = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [4, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(w3fc4, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 1,
    "w3fc==4 -> no clear -> fires");
  /* Wide byte rows: b1398=0x100 is CLEAR as a byte (cmp byte 0x831a95). */
  const wide = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [0x100, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(wide, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 1,
    "0x100 low byte clear -> no clear -> fires");
  /* w3fc FULL-DWORD: 0x1000004 must NOT equal 4. */
  const w3fcWide = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x1000004, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(w3fcWide, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 0,
    "w3fc 0x1000004 != 4 FULL-DWORD -> clears");
  /* Null-slot zero rows (span slot without an entry) are no-ops. */
  const nullSlot = packRt({
    opaque8318a0PlayerEntryCount: 2,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(nullSlot, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 0,
    "row 0 scores; all-zero row 1 is a null-slot no-op");
});

test("ABI v96 (wave-23): store-plan seam gate misses are byte-for-byte inert", () => {
  /* Block closed by type: 0x13 (handoff 0x831c78) / 0xb+0x18304 /
     0x10+0x18304 (reset arm 0x831d76..0x831db4). */
  const miss = seamStep(packRt(), { engineField1c: 0x13, engineField14: 0 });
  assert.equal(miss.events.opaque008318a0SfxManagerStores, 0, "0x13 handoff -> no event");
  assert.equal(miss.events.opaqueCall008318a0, 1, "coarse edge unchanged");
  const resetB = seamStep(packRt(), { engineField1c: 0xb, engineField14: 0x18304 });
  assert.equal(resetB.events.opaque008318a0SfxManagerStores, 0, "0xb + room18304 reset -> no event");
  const reset10 = seamStep(packRt(), { engineField1c: 0x10, engineField14: 0x18304 });
  assert.equal(reset10.events.opaque008318a0SfxManagerStores, 0, "0x10 + room18304 reset -> no event");
  const wideB = seamStep(packRt(), { engineField1c: 0x1000000b, engineField14: 0x18304 });
  assert.equal(wideB.events.opaque008318a0SfxManagerStores, 1, "wide 0x1000000b FULL-DWORD opens");

  /* Capture misses: ready=0 / mode!=1 / pack_ready=0 / count>cap. */
  const noReady = seamStep(packRt({ opaque008318a0Ready: 0 }), { engineField1c: 5 });
  assert.equal(noReady.events.opaque008318a0SfxManagerStores, 0, "ready=0 -> inert");
  const mode4 = seamStep(packRt({ opaque008318a0Mode: 4 }), { engineField1c: 5 });
  assert.equal(mode4.events.opaque008318a0SfxManagerStores, 0, "mode 4 -> inert");
  const noPack = seamStep(packRt({ opaque8318a0PlayerEntryReady: 0 }), { engineField1c: 5 });
  assert.equal(noPack.events.opaque008318a0SfxManagerStores, 0, "pack not ready -> inert");
  const overCap = seamStep(packRt({ opaque8318a0PlayerEntryCount: 9 }), { engineField1c: 5 });
  assert.equal(overCap.events.opaque008318a0SfxManagerStores, 0, "count > cap 8 -> inert");
  const cap8 = seamStep(packRt({ opaque8318a0PlayerEntryCount: 8 }), { engineField1c: 5 });
  assert.equal(cap8.events.opaque008318a0SfxManagerStores, 1, "count == cap 8 -> fires");

  /* The LIVE seam's ONLY net effect is the +1 typed event: a no-pack run
     and a pack-gated-closed run are event-identical (record-12 withoutTyped
     equality pattern). */
  const withoutSeam = step({ gate1b83c: 1, engineField1c: 0x13, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1 });
  const withSeamClosed = seamStep(packRt(), { engineField1c: 0x13, engineField14: 0 });
  const strip = (ev) => {
    const out = { ...ev };
    delete out.opaque008318a0SfxManagerStores;
    return out;
  };
  assert.deepEqual(strip(withSeamClosed.events), strip(withoutSeam.events),
    "gate-closed pack run == no-pack run (residual byte-for-byte)");
  assert.deepEqual(withSeamClosed.state, withoutSeam.state, "state byte-for-byte equal");
});

