/* ===== ABI v99 (wave-23 fold, update-v99-record4-fold): the mode-1 walk
   store fold ==============================================================
   Transcribed per-player entry writes (walk 0x8319b2..0x831b0d + manager
   block 0x831c64..0x831e31) -> three NEW byte-gate u32 laws + the
   type-0-zero-arm correction of the v98 candidate_found derivation + the
   store-plan row offset corrections (row0 node+4; row7 mgr-0x150;
   row8 mgr-0x154). Evidence: update-v99-record4-fold NOTES §2/§4. */

test("ABI v99 (fold): walk-entry zero-arm law (0x831a19..0x831a59) — type==0 zeroes 0x1398/0x139a on the score block", () => {
  /* PE 0x831a19 cmp dword [ebx+0x1c],0 (FULL-DWORD type) then 4 byte-zero
     stores (0x831a1f/0x831a26/0x831a53/0x831a59). Guard = score-block
     reach: b173 byte clear && byte (1398|139a) != 0 && (ptr7c==0 ||
     byte34==0). */
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0, 0, 1, 0, 0, 0), 1, "type0 1398 set");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0, 0, 0, 1, 0, 0), 1, "type0 139a set");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0, 0, 1, 0, 0x1000, 0), 1, "ptr set, byte34 clear");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(5, 0, 1, 0, 0, 0), 0, "type 5 -> no zero arm");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0x100, 0, 1, 0, 0, 0), 0, "wide type 0x100 FULL-DWORD");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0, 1, 1, 0, 0, 0), 0, "b173 set -> 0x8319c9 vcall exit");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0, 0, 0x100, 0, 0, 0), 0, "0x1398 0x100 byte clear -> candidate block");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0, 0, 1, 0, 0x1000, 1), 0, "ptr7c && byte34 set -> 0x8319f0 exit");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntryZeroArm(0, 0, 0, 0, 0, 0), 0, "no bytes -> candidate block");
});

test("ABI v99 (fold): walk-entry 0x171 zero law (0x831a95..0x831af8) — zero-arm || FULL-DWORD w3fc==4", () => {
  /* [e+0x171]=0 fires on the score path iff post-write bytes both zero
     (type==0 zero arm) || w3fc==4 (0x831aa7 cmp dword [edi+0x3fc],4). */
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(0, 0, 1, 0, 0, 0, 0x42), 1, "type0 zero arm");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(5, 0, 1, 0, 0, 0, 4), 1, "w3fc==4");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(5, 0, 0, 1, 0, 0, 4), 1, "139a-only + w3fc==4");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(5, 0, 1, 0, 0, 0, 0x42), 0, "scored, w3fc!=4 -> score block");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(5, 0, 1, 0, 0, 0, 0x1000004), 0, "w3fc FULL-DWORD 0x1000004 != 4");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(5, 1, 1, 0, 0, 0, 4), 0, "b173 set -> no 171 write");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(0, 0, 0x100, 0, 0, 0, 5), 0, "0x100 byte clear -> candidate block");
  assert.equal(gameUpdateSlice8318a0Mode1WalkEntry171Zero(0, 0, 1, 0, 0x1000, 1, 4), 0, "ptr+byte34 set -> no write");
});

test("ABI v99 (fold): reset-arm whole-span clear-writes law (0x831d6c..0x831db4)", () => {
  /* 0xb/0x10 FULL-DWORD && field_14 == 0x18304 (mode1_manager_block_gate
     reset arm BY REFERENCE) -> EVERY non-null slot gets byte 0x171=0 +
     byte 0x410=1 (constant writes, 0x831d9b/0x831da2). */
  assert.equal(gameUpdateSlice8318a0Mode1ResetSpanClearWrites(0xb, 0x18304), 1, "0xb + room");
  assert.equal(gameUpdateSlice8318a0Mode1ResetSpanClearWrites(0x10, 0x18304), 1, "0x10 + room");
  assert.equal(gameUpdateSlice8318a0Mode1ResetSpanClearWrites(0xb, 0x18305), 0, "other room");
  assert.equal(gameUpdateSlice8318a0Mode1ResetSpanClearWrites(5, 0x18304), 0, "plain type");
  assert.equal(gameUpdateSlice8318a0Mode1ResetSpanClearWrites(0x1000000b, 0x18304), 0, "wide 0xb FULL-DWORD");
});

test("ABI v99 (fold): the type-0 zero-arm makes the store-plan seam FIRE on scored entries", () => {
  /* Machine: type==0 -> 0x1398/0x139a zeroed -> 0x831a95 falls to
     0x831af8 -> [ebp-0x41] is NEVER cleared -> manager gate opens ->
     the block (and the typed event) runs. The v98 wire cleared the flag
     here (missing type term) — the fold fixes the divergence. */
  const scored = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(scored, { engineField1c: 0 }).events.opaque008318a0SfxManagerStores, 1,
    "type 0 + scored entry -> zero arm -> flag stays 1 -> FIRES");
  assert.equal(seamStep(scored, { engineField1c: 5 }).events.opaque008318a0SfxManagerStores, 0,
    "type 5 + scored entry -> flag clears -> closed (unchanged)");
  /* w3fc==4 with type 0: 0x831af8 exit either way -> fires. */
  const w3fc4 = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [4, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(w3fc4, { engineField1c: 0 }).events.opaque008318a0SfxManagerStores, 1,
    "type 0 + w3fc==4 -> fires");
  /* ptr7c&&byte34 set -> 0x8319f0 exit, no clear -> fires under type 0. */
  const ptrGate = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryPtr7c: [0x1000, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryB34: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(ptrGate, { engineField1c: 0 }).events.opaque008318a0SfxManagerStores, 1,
    "type 0 + ptr/0x34 set -> fires");
  /* Wide type: 0x1000000 != 0 -> the clear path is live again. */
  const wideType = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  assert.equal(seamStep(wideType, { engineField1c: 0x1000000 }).events.opaque008318a0SfxManagerStores, 0,
    "wide type 0x1000000 FULL-DWORD != 0 -> clears -> closed");
  /* The seam's ONLY net effect stays the +1 typed event (v98 pattern). */
  const withSeam = seamStep(scored, { engineField1c: 0 });
  const withoutSeam = step({ gate1b83c: 1, engineField1c: 0, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1 });
  const strip = (ev) => {
    const out = { ...ev };
    /* ABI v142: the rt_band_pop composite lanes ride the SAME firing
       condition as @932 — strip them with it for the byte-for-byte pin. */
    delete out.opaque008318a0RtBandPopFired;
    delete out.opaque008318a0RtBandPopDepthAfter;
    delete out.opaque008318a0RtBandPopLatchAfter;
    delete out.opaque008318a0RtBandPopParamsPack;
    delete out.opaque008318a0SfxManagerStores;
    return out;
  };
  assert.deepEqual(strip(withSeam.events), strip(withoutSeam.events),
    "type-0 fired pack run == no-pack run outside the typed event");
  assert.deepEqual(withSeam.state, withoutSeam.state, "state byte-for-byte equal");
});

test("ABI v99 (fold): store-plan row corrections + source pins (JSON delta staged in NOTES)", () => {
  /* Row encodings: row0 = queue node+4 byte; row7 = mgr-0x150;
     row8 = mgr-0x154 (PE 0x831e5a/0x831f1b/0x831f2f; NOTES §2c).
     The JSON abiV98 + translatedHelpers delta is STAGED in NOTES
     update-v99-record4-fold §json-delta (single-writer freeze: S1 owns
     decomp/game-update-slice.json this wave; the wave-24 merge commits it
     — the coordinator directive 2026-08-18). */
  const p = gameUpdateSlice8318a0SfxManagerStorePlan(0x24, 5, 0x1234, 0);
  assert.equal(p[0].mgrOff, 0x4, "node+4 byte row");
  assert.equal(p[7].mgrOff, 0xfffffeb0, "0xc79790 = mgr-0x150");
  assert.equal(p[8].mgrOff, 0xfffffeac, "0xc7978c = mgr-0x154");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  assert.match(source, /mode1_walk_entry_zero_arm/);
  assert.match(source, /mode1_walk_entry_171_zero/);
  assert.match(source, /mode1_reset_span_clear_writes/);
  assert.match(source, /\{0x4u, 1u,/);
  assert.match(source, /0xfffffeb0u/);
  assert.match(source, /0xfffffeacu/);
  const model = readFileSync(join(root, "scripts", "decomp", "game-update-model.mjs"), "utf8");
  assert.match(model, /gameUpdateSlice8318a0Mode1WalkEntryZeroArm/);
  assert.match(model, /mgrOff: 0x4, size: 1/);
  assert.match(model, /mgrOff: 0xfffffeb0/);
  assert.match(model, /mgrOff: 0xfffffeac/);
  /* JSON: current tree keeps abiV97 (the wave-23 evidence); the abiV98
     record key + 3 helper rows land at the wave-24 merge (§json-delta). */
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const rec = spec.opaqueBoundaries.find((b) => b.targetVa === "0x008318a0");
  assert.ok(rec, "record stays in opaqueBoundaries");
  assert.match(rec.abiV97 || "", /sfx_manager_store_plan emission LIVE/i);
});

/* ===== ABI v102 (wave-26, update-v102-record4-apply): the store-plan
   APPLICATION arm =========================================================
   When the mode-1 manager-block gate opens (the @932 event fires) the
   module now EMITS the typed per-row apply plan into the step scratch
   (IsaacGameUpdateSlice8318a0SfxManagerStoreApplyPlan: store_mask 0x1ff
   = the 9 block sites 0x831e31..0x831f34 + the 9 v96 plan-law rows over
   the captured globals @13736..13748) — the typed-host-call contract the
   native-update-bridge §5 consumer applies to the SFX-manager BSS
   (element=1 rows -> the residual 0x684f30() node, row 0's PE guard
   @0x831e5d node+4 != 0 host-applied; element=0 -> the 0xc798e0 BSS).
   Gate misses leave the scratch all-zero (residual byte-for-byte).
   Evidence: update-v102-record4-apply NOTES §1/§3/§5. */

test("ABI v102 (apply): the apply law emits mask 0x1ff + the 9 plan rows (pack-discriminating)", () => {
  /* The mask is the module's application decision: the block's 9 sites. */
  assert.equal(GAME_UPDATE_SLICE_8318A0_SFX_MANAGER_STORE_MASK, 0x1ff);
  const p = gameUpdateSlice8318a0SfxManagerStoreApplyPlan(0x24, 5, 0x1234, 7);
  assert.equal(p.storeMask, 0x1ff, "mask 0x1ff (all 9 block sites)");
  assert.equal(p.rows.length, 9, "nine rows in program order");
  assert.deepEqual(p.rows, gameUpdateSlice8318a0SfxManagerStorePlan(0x24, 5, 0x1234, 7),
    "rows == the v96 plan law rows");
  /* Discriminating packs: different captured globals -> DIFFERENT rows'
     applications (row0 bit5, row3 cmove, row7/8 wrap, row1 passthrough). */
  const a = gameUpdateSlice8318a0SfxManagerStoreApplyPlan(0, 0, 0, 0x12345678);
  assert.equal(a.rows[0].value, 0, "bit5 clear -> row0 0");
  assert.equal(a.rows[3].value, 6, "byte&4 clear -> row3 6");
  assert.equal(a.rows[7].value, 0xffffffff, "79790 0 -> row7 32-bit wrap -1");
  assert.equal(a.rows[8].value, 0, "new==0 -> row8 0");
  assert.equal(a.rows[1].value, 0x12345678, "row1 = 79948 passthrough");
  const b = gameUpdateSlice8318a0SfxManagerStoreApplyPlan(0x24, 1, 0x99, 7);
  assert.equal(b.rows[0].value, 1, "bit5 set -> row0 1");
  assert.equal(b.rows[3].value, 1, "byte&4 set -> row3 1");
  assert.equal(b.rows[7].value, 0, "79790 1 -> row7 0");
  assert.equal(b.rows[8].value, 0, "new==0 -> row8 0 (cmove)");
  const c = gameUpdateSlice8318a0SfxManagerStoreApplyPlan(0x100, 2, 0x99, 7);
  assert.equal(c.rows[0].value, 0, "wide 0x100 bit5 clear (DWORD >>5)");
  assert.equal(c.rows[3].value, 6, "wide 0x100 byte&4 clear -> 6");
  assert.equal(c.rows[7].value, 1, "79790 2 -> row7 1");
  assert.equal(c.rows[8].value, 0x99, "new!=0 -> row8 keeps 7978c");
});

test("ABI v102 (apply): the seam oracle emits the plan iff the manager gate opens", () => {
  /* Empty walk + type 5: candidate_found stays 1 -> gate opens -> plan. */
  let plan = opaque8318a0SfxManagerStoreApplyPlan(
    { engineField1c: 5, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1,
      opaque8318a0PlayerEntryReady: 1, opaque8318a0PlayerEntryCount: 0,
      opaque8318a0SfxGlobal798e4: 0x24, opaque8318a0SfxGlobal79790: 5,
      opaque8318a0SfxGlobal7978c: 0x1234, opaque8318a0SfxGlobal79948: 7 },
  );
  assert.ok(plan, "empty walk type 5 -> plan emitted");
  assert.equal(plan.storeMask, 0x1ff, "mask 0x1ff on fire");
  assert.equal(plan.rows[0].value, 1, "row0 from captured 0x24");
  assert.equal(plan.rows[3].value, 1, "row3 from captured 0x24");
  assert.equal(plan.rows[7].value, 4, "row7 79790-1");
  assert.equal(plan.rows[8].value, 0x1234, "row8 keeps 7978c");
  assert.deepEqual(plan.rows,
    gameUpdateSlice8318a0SfxManagerStorePlan(0x24, 5, 0x1234, 7),
    "oracle rows == law rows over the captured globals");
  /* Type 0 + scored entry (v99 zero-arm): flag never clears -> fires. */
  plan = opaque8318a0SfxManagerStoreApplyPlan(
    { engineField1c: 0, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1,
      opaque8318a0PlayerEntryReady: 1, opaque8318a0PlayerEntryCount: 1,
      opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
      opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
      opaque8318a0SfxGlobal798e4: 0, opaque8318a0SfxGlobal79790: 0,
      opaque8318a0SfxGlobal7978c: 0, opaque8318a0SfxGlobal79948: 0 },
  );
  assert.ok(plan, "type 0 + scored -> zero arm -> plan emitted");
  assert.equal(plan.rows[3].value, 6, "captured 0 -> row3 6");
  assert.equal(plan.rows[7].value, 0xffffffff, "captured 0 -> row7 wrap");
  /* 0x15 re-opens with a cleared candidate. */
  plan = opaque8318a0SfxManagerStoreApplyPlan(
    { engineField1c: 0x15, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1,
      opaque8318a0PlayerEntryReady: 1, opaque8318a0PlayerEntryCount: 1,
      opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
      opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0] },
  );
  assert.ok(plan, "0x15 fires with cleared candidate");
});

test("ABI v102 (apply): gate misses emit NOTHING (oracle null — residual byte-for-byte)", () => {
  const rt = {
    opaque008318a0Ready: 1, opaque008318a0Mode: 1,
    opaque8318a0PlayerEntryReady: 1, opaque8318a0PlayerEntryCount: 0,
    opaque8318a0SfxGlobal798e4: 0x24, opaque8318a0SfxGlobal79790: 5,
    opaque8318a0SfxGlobal7978c: 0x1234, opaque8318a0SfxGlobal79948: 7,
  };
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 0x13 }, rt), null,
    "0x13 handoff -> no plan");
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 0xb, engineField14: 0x18304 }, rt), null,
    "0xb + 0x18304 reset -> no plan");
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 0x10, engineField14: 0x18304 }, rt), null,
    "0x10 + 0x18304 reset -> no plan");
  const scored = {
    ...rt,
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  };
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 5 }, scored), null,
    "scored + plain type -> flag clears -> no plan");
  /* Capture/mode misses. */
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 5 },
    { ...rt, opaque008318a0Ready: 0 }), null, "ready=0 -> inert");
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 5 },
    { ...rt, opaque008318a0Mode: 4 }), null, "mode 4 -> inert");
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 5 },
    { ...rt, opaque8318a0PlayerEntryReady: 0 }), null, "pack not ready -> inert");
  assert.equal(opaque8318a0SfxManagerStoreApplyPlan({ engineField1c: 5 },
    { ...rt, opaque8318a0PlayerEntryCount: 9 }), null, "count > cap 8 -> inert");
  /* The seam's ONLY net effect on a fire stays the +1 event (the plan
     scratch is a step channel): fired pack run == no-pack run outside
     @932, state byte-for-byte (v98 pattern). */
  const fired = seamStep(packRt({
    opaque8318a0SfxGlobal798e4: 0x24, opaque8318a0SfxGlobal79790: 5,
    opaque8318a0SfxGlobal7978c: 0x1234, opaque8318a0SfxGlobal79948: 7,
  }), { engineField1c: 5, engineField14: 0 });
  assert.equal(fired.events.opaque008318a0SfxManagerStores, 1, "@932 fires");
  const withoutSeam = step({ gate1b83c: 1, engineField1c: 5, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1 });
  const strip = (ev) => {
    const out = { ...ev };
    /* ABI v142: the composite lanes ride the same firing condition. */
    delete out.opaque008318a0RtBandPopFired;
    delete out.opaque008318a0RtBandPopDepthAfter;
    delete out.opaque008318a0RtBandPopLatchAfter;
    delete out.opaque008318a0RtBandPopParamsPack;
    delete out.opaque008318a0SfxManagerStores;
    return out;
  };
  assert.deepEqual(strip(fired.events), strip(withoutSeam.events),
    "fired pack run == no-pack run outside the typed event");
  assert.deepEqual(fired.state, withoutSeam.state, "state byte-for-byte equal");
  /* And the oracle agrees on the same fired shape (discriminating pack). */
  const oraclePlan = opaque8318a0SfxManagerStoreApplyPlan(
    { engineField1c: 5, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1,
      opaque8318a0PlayerEntryReady: 1, opaque8318a0PlayerEntryCount: 0,
      opaque8318a0SfxGlobal798e4: 0x24, opaque8318a0SfxGlobal79790: 5,
      opaque8318a0SfxGlobal7978c: 0x1234, opaque8318a0SfxGlobal79948: 7 },
  );
  assert.ok(oraclePlan, "oracle fires on the same shape");
  assert.equal(oraclePlan.rows[7].value, 4, "row7 value on the fired shape");
});

