/* ===== ABI v142 (update-v142-rt-band-pop, record idx4): the typed
   rt_band_pop composite carrier ===========================================
   Extends the standing v97/v102 pair (BY REFERENCE — nothing re-derived):
   on capture-live firing ticks the two STATEFUL 0xc798e0-band deltas
   (0xc79790 depth decrement, 0xc7978c empty-latch clear) retire onto the
   four event lanes @1244..1256 and the five constant param stores
   (0xc79900..0xc79910) fold PURELY; the four opaque thiscall leaves on
   *0xc798e0 stay host actions. Theorem arms in BOTH mirrors:
   capture-live retires vs absent keeps byte-for-byte.
   Evidence: contracts-idx4-engine-band NOTES §1/§3/§4/§5. */

test("ABI v142 (rt_band_pop): the pure law mirrors the PE deltas over the captured globals", () => {
  assert.equal(GAME_UPDATE_SLICE_8318A0_RT_BAND_POP_PARAMS, 5);
  /* Depth decrement is a plain 32-bit wrap sub AFTER the log-check join. */
  let pop = gameUpdateSlice8318a0RtBandPop(0x24, 3, 0xabcdef01);
  assert.equal(pop.depthAfter, 2, "depth pre-1");
  assert.equal(pop.latchAfter, 0xabcdef01, "new depth != 0 -> latch keeps");
  assert.deepEqual(pop.params, [0, 1, 7, 1, 7], "e4&4 set -> sel 1");
  pop = gameUpdateSlice8318a0RtBandPop(0x20, 1, 0x12345678);
  assert.equal(pop.depthAfter, 0, "underflow arm: 1-1 == 0");
  assert.equal(pop.latchAfter, 0, "cmove: new depth 0 -> latch CLEARS");
  assert.equal(pop.params[1], 6, "byte[e4]&4 clear -> sel 6");
  /* Width split pinned at v96 stays honored: BYTE &4 vs DWORD >>5. */
  assert.equal(gameUpdateSlice8318a0RtBandPop(0x100, 9, 1).params[1], 6,
    "wide 0x100: bit2 of the LOW BYTE clear -> 6 (DWORD >>5 would see bit set only for +4)");
  assert.equal(gameUpdateSlice8318a0RtBandPop(0, 0, 0).depthAfter, 0xffffffff,
    "pre 0 wraps to 0xffffffff (the sub is unconditional on the block path)");
  /* Params pack: five 4-bit fields, p0|p1<<4|p2<<8|p3<<12|p4<<16. */
  assert.equal(gameUpdateSlice8318a0RtBandPopParamsPack([0, 1, 7, 1, 7]), 0x71710);
  assert.equal(gameUpdateSlice8318a0RtBandPopParamsPack([0, 6, 7, 1, 7]), 0x71760);
});

test("ABI v142 (rt_band_pop): seam oracle fires iff the manager gate opens (same condition as the v102 plan)", () => {
  const rt = {
    opaque008318a0Ready: 1, opaque008318a0Mode: 1,
    opaque8318a0PlayerEntryReady: 1, opaque8318a0PlayerEntryCount: 0,
    opaque8318a0SfxGlobal798e4: 0x24, opaque8318a0SfxGlobal79790: 3,
    opaque8318a0SfxGlobal7978c: 0xabcdef01, opaque8318a0SfxGlobal79948: 0xcafe,
  };
  const carrier = opaque8318a0RtBandPopCarrier({ engineField1c: 0x15, engineField14: 0 }, rt);
  assert.ok(carrier, "capture-live firing tick -> carrier publishes");
  assert.equal(carrier.depthAfter, 2);
  assert.equal(carrier.latchAfter, 0xabcdef01);
  assert.equal(carrier.paramsPack, 0x71710);
  /* Absence arms: every gate miss -> null (lanes stay 0 downstream). */
  assert.equal(opaque8318a0RtBandPopCarrier({ engineField1c: 0x15 },
    { ...rt, opaque008318a0Ready: 0 }), null, "ready=0 keeps");
  assert.equal(opaque8318a0RtBandPopCarrier({ engineField1c: 0x15 },
    { ...rt, opaque008318a0Mode: 2 }), null, "mode != 1 keeps");
  assert.equal(opaque8318a0RtBandPopCarrier({ engineField1c: 0x15 },
    { ...rt, opaque8318a0PlayerEntryReady: 0 }), null, "pack not ready keeps");
  assert.equal(opaque8318a0RtBandPopCarrier({ engineField1c: 0x13 }, rt), null,
    "0x13 handoff keeps");
  assert.equal(
    opaque8318a0RtBandPopCarrier({ engineField1c: 0xb, engineField14: 0x18304 }, rt),
    null, "reset arm keeps");
});

test("ABI v142 (rt_band_pop): step wires the lanes on capture-live and keeps byte-for-byte on absence", () => {
  const pack = packRt({
    opaque8318a0SfxGlobal798e4: 0x24, opaque8318a0SfxGlobal79790: 3,
    opaque8318a0SfxGlobal7978c: 0xabcdef01, opaque8318a0SfxGlobal79948: 0xcafe,
  });
  /* CAPTURE-LIVE RETIRE arm: lanes publish, @932 still fires as shipped. */
  const fired = seamStep(pack, { engineField1c: 0x15, engineField14: 0 });
  assert.equal(fired.events.opaque008318a0RtBandPopFired, 1);
  assert.equal(fired.events.opaque008318a0RtBandPopDepthAfter, 2, "mutation: depth moved");
  assert.equal(fired.events.opaque008318a0RtBandPopLatchAfter, 0xabcdef01, "latch kept");
  assert.equal(fired.events.opaque008318a0RtBandPopParamsPack, 0x71710);
  assert.equal(fired.events.opaque008318a0SfxManagerStores, 1, "@932 unchanged");
  /* Underflow arm: pre==1 -> post 0 -> the latch CLEARS. */
  const under = seamStep(packRt({
    opaque8318a0SfxGlobal798e4: 0x20, opaque8318a0SfxGlobal79790: 1,
    opaque8318a0SfxGlobal7978c: 0x12345678,
  }), { engineField1c: 0x15, engineField14: 0 });
  assert.equal(under.events.opaque008318a0RtBandPopDepthAfter, 0);
  assert.equal(under.events.opaque008318a0RtBandPopLatchAfter, 0, "empty-latch clear applied");
  assert.equal(under.events.opaque008318a0RtBandPopParamsPack, 0x71760, "sel 6 packed");
  /* ABSENT KEEPS arm: no pack -> all four lanes stay 0, residual inert. */
  const absent = step({ gate1b83c: 1, engineField1c: 0x15, engineField14: 0 },
    { opaque008318a0Ready: 1, opaque008318a0Mode: 1 });
  for (const lane of ["opaque008318a0RtBandPopFired", "opaque008318a0RtBandPopDepthAfter",
    "opaque008318a0RtBandPopLatchAfter", "opaque008318a0RtBandPopParamsPack"]) {
    assert.equal(absent.events[lane] | 0, 0, `${lane} stays 0 without capture`);
  }
  /* Gate miss with the pack live (scored entry + plain type) also keeps. */
  const scored = packRt({
    opaque8318a0PlayerEntryCount: 1,
    opaque8318a0PlayerEntryB1398: [1, 0, 0, 0, 0, 0, 0, 0],
    opaque8318a0PlayerEntryW3fc: [0x42, 0, 0, 0, 0, 0, 0, 0],
  });
  const missed = seamStep(scored, { engineField1c: 5, engineField14: 0 });
  assert.equal(missed.events.opaque008318a0RtBandPopFired | 0, 0, "gate closed -> keeps");
});

