/* ================= ABI v92: 98dba0 empty-vector walk arm (blob gate) =====
   PE (disasm-98dba0-walk.txt):
     0x0098dbd2  mov edx,[eax+0x1baac]   ; player vector END
     0x0098dbd8  sub edx,[eax+0x1baa8]   ; END-BEGIN (32-bit wrap)
     0x0098dbde  sar edx,2               ; count = (end-begin) SAR 2, FULL dword
     0x0098dbe1  test edx,edx
     0x0098dbe3  jne  0x0098dbf4         ; count != 0 -> skip fatal
     0x0098dbec  call 0xa112c0           ; "There are no players!" fatal (HOST)
     0x0098dc11  test eax,eax            ; count re-derived
     0x0098dc13  je   0x0098de4a         ; count==0 -> SKIP the whole walk loop
   count==0 is a PROOF-COMPLETE pure skip: [0x0098dbf4, 0x0098de4a) has zero
   stores and zero calls (the mid-loop re-check fatal 0x0098dc30 is only
   reachable when the vector empties between iterations — impossible when the
   loop never runs), and the 0x0098de34 `test bl,bl / je` counter step no-ops
   (bl==0). The ONLY host content left on the walk residual is the fatal log.
   Any nonzero SAR count — including NEGATIVE diffs (end<begin) and wrapped
   diffs — keeps the walk body host. ready=0 keeps the pre-v92 always-host
   walk with no proof event. */

test("ABI v92: walk_vector_count is the FULL-dword SAR, not unsigned or byte-narrow", () => {
  /* Independent PE-truth: count = SAR32(end-begin, 2) transcribed from
     0x0098dbd2..0x0098dbde. Negative/wrapped diffs give NEGATIVE counts
     (nonzero -> walk arm); sub-vector diffs 1..3 give 0 (-> empty arm). */
  const cases = [
    [0x1000, 0x1000, 0],
    [0x1000, 0x1001, 0],
    [0x1000, 0x1003, 0],
    [0x1000, 0x1004, 1],
    [0x1000, 0x101c, 7],
    [0x1000, 0xffc, -1],
    [0x1000, 0xffe, -1],
    [0xffffffe0, 0, 8],
    [0, 0xfffffffc, -1],
    [0x80000000, 0x80000004, 1],
    [0x80000004, 0x80000000, -1],
    [0, 0x100, 0x40],
    [0, 0x101, 0x40],
  ];
  for (const [b, e, want] of cases) {
    assert.equal(gameUpdateSlice98dba0WalkVectorCount(b, e), want,
      `vector_count(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
});

test("ABI v92: pure_skip gate classifies empty vs walk arms (fatal stays host)", () => {
  /* PE-truth: the fatal (0x98dbe3 jne skip) and the skip (0x98dc13 je timer)
     both hinge on the SAR count being exactly 0. */
  const empty = [
    [0x1000, 0x1000], [0x1000, 0x1001], [0x1000, 0x1003],
    [0x12345678, 0x12345678], [0, 0],
  ];
  for (const [b, e] of empty) {
    assert.equal(gameUpdateSlice98dba0WalkPureSkip(b, e), 1,
      `pure_skip(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
  const walk = [
    [0x1000, 0x1004], [0x1000, 0x101c], [0x1000, 0xffc],
    [0xffffffe0, 0], [0, 0x100], [0, 0x101], [0x80000000, 0x80000004],
  ];
  for (const [b, e] of walk) {
    assert.equal(gameUpdateSlice98dba0WalkPureSkip(b, e), 0,
      `pure_skip(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
});

test("ABI v92: gate-1b83c walk emit publishes the pure-skip proof ONLY on empty spans", () => {
  const rt = (begin, end) => ({
    frameOpaque98dba0WalkReady: 1,
    frameOpaque98dba0WalkBegin: begin,
    frameOpaque98dba0WalkEnd: end,
  });
  const empty = step({ gate1b83c: 1 }, rt(0x1000, 0x1000));
  assert.equal(empty.events.opaqueCall0098dba0PlayerWalk, 1,
    "the fatal log keeps the walk host edge");
  assert.equal(empty.events.frameOpaque98dba0WalkEmptySkip, 1,
    "empty span publishes the pure-skip proof");
  assert.equal(empty.events.continuationKind,
    UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK);
  /* Sub-vector diff 1..3 is ALSO count==0 in the PE (SAR floor). */
  const sub = step({ gate1b83c: 1 }, rt(0x1000, 0x1003));
  assert.equal(sub.events.frameOpaque98dba0WalkEmptySkip, 1, "diff 3 -> SAR 0 -> empty arm");
  /* One player: walk arm, no proof. */
  const one = step({ gate1b83c: 1 }, rt(0x1000, 0x1004));
  assert.equal(one.events.opaqueCall0098dba0PlayerWalk, 1);
  assert.equal(one.events.frameOpaque98dba0WalkEmptySkip || 0, 0, "walk arm is not a skip");
  /* Negative wrapped span: WALK arm (test edx,edx sees -1). */
  const neg = step({ gate1b83c: 1 }, rt(0x1000, 0xffc));
  assert.equal(neg.events.frameOpaque98dba0WalkEmptySkip || 0, 0, "negative count walks");
  /* High-byte span: WALK arm — a byte-narrow count mutant would misread 0x100
     as empty (the 0x100/0x101 drives). */
  const wide = step({ gate1b83c: 1 }, rt(0, 0x101));
  assert.equal(wide.events.frameOpaque98dba0WalkEmptySkip || 0, 0, "0x101 count 0x40 walks");
});

test("ABI v92: ready=0 keeps the pre-v92 always-host walk with no proof event", () => {
  const out = step({ gate1b83c: 1 }, {
    frameOpaque98dba0WalkReady: 0,
    frameOpaque98dba0WalkBegin: 0x1000,
    frameOpaque98dba0WalkEnd: 0x1000,
  });
  assert.equal(out.events.opaqueCall0098dba0PlayerWalk, 1);
  assert.equal(out.events.frameOpaque98dba0WalkEmptySkip || 0, 0,
    "ready=0 must not publish the proof");
});

test("ABI v92: frame-aux walk emit applies the SAME gate", () => {
  /* The frame-aux 98dba0 emit lives in continueAfterMenuUpdate (menu branch
     not entered; state24ecc 0 so the record-9 gate falls through). */
  const walkAux = (begin, end) => {
    const base = state({ menuState23a74: 0, state24ecc: 0 });
    const events = { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_MENU_UPDATE };
    return resumeGameUpdateMenuUpdate(base, {
      globalRangeByteLength: 1, /* bypass the state24ecc gate */
      frameOpaque98dba0WalkReady: 1,
      frameOpaque98dba0WalkBegin: begin,
      frameOpaque98dba0WalkEnd: end,
    }, events);
  };
  const empty = walkAux(0x1000, 0x1000);
  assert.equal(empty.events.opaqueCall0098dba0PlayerWalk, 1);
  assert.equal(empty.events.frameOpaque98dba0WalkEmptySkip, 1, "frame-aux empty arm proves skip");
  assert.equal(empty.events.continuationKind,
    UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK);
  const one = walkAux(0x1000, 0x1004);
  assert.equal(one.events.frameOpaque98dba0WalkEmptySkip || 0, 0, "frame-aux walk arm");
});

