  assert.match(source, /static_assert\(offsetof\(IsaacGameUpdateSliceEvents, frame_opaque_98dba0_walk_empty_skip\) == 500/);
  assert.match(source, /static_assert\(offsetof\(IsaacGameUpdateSliceEvents, opaque_call_008607a0_args_arg2\) == 532/);
