test("ABI v92: the shipped Wasm agrees with the oracle on BOTH new exports", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  const vc = pick("isaac_game_update_slice_98dba0_walk_vector_count");
  const ps = pick("isaac_game_update_slice_98dba0_walk_pure_skip");
  assert.equal(typeof vc, "function", "walk_vector_count missing from the module");
  assert.equal(typeof ps, "function", "walk_pure_skip missing from the module");
  /* Values cross UNMASKED — the MODULE must narrow, never the harness. */
  for (const [b, e] of [
    [0x1000, 0x1000], [0x1000, 0x1003], [0x1000, 0x1004],
    [0x1000, 0xffc], [0, 0x101], [0xffffffe0, 0], [0x80000004, 0x80000000],
  ]) {
    assert.equal(vc(b, e) | 0, gameUpdateSlice98dba0WalkVectorCount(b, e),
      `wasm vector_count(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
    assert.equal(ps(b, e) | 0, gameUpdateSlice98dba0WalkPureSkip(b, e),
      `wasm pure_skip(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
});

/* ================= ABI v95: record idx 2 (0x009b6840 MenuGateUpdate) body
   pure laws == PE (census update-v95-menu-update-census/NOTES.md, full body
   0x9b6840..0x9b7180):
     A2 0x9b6905 cmp dword [Game+0x22ed4],2 / 0x9b690c je skip; stores 1/2
     A1 0x9b6895..0x9b68a1 FULL-DWORD manager container begin==end -> probe
     A1 0x9b68c7 cmp [count],0 / jbe skip (UNSIGNED)
     A1 0x9b68d9 cmp dword [e+0x28],5 / 0x9b68df cmp dword [e+0x2c],0x64
     A8 0x9b712a cmp esi,1 / cmovne 0x249|0x135 / 0x9b713a cmp byte,0 / je exit
     A4 0x9b6a02 cmp [anim+0x80],req / jg (SIGNED)
     A4 0x9b6a32..0x9b6a3d test/je + test/js + cmp/jl (SIGNED) */

test("ABI v95: 9b6840 mode_latch_needed is a FULL-DWORD !=2 store gate", () => {
  /* PE 0x9b6905 cmp dword ptr [eax+0x22ed4],2 / 0x9b690c je skip — full 32-bit
     compare. 0x102 has low byte 2 but the DWORD is 0x102: it must LATCH
     (a low-byte read would skip). 0xffffffff latches. Only exact 2 skips. */
  for (const v of [0, 1, 3, 0x100, 0x102, 0x1ff, 0x7fffffff, 0x80000000, 0xffffffff]) {
    assert.equal(gameUpdateSlice9b6840ModeLatchNeeded(v), 1,
      `mode_latch(0x${(v >>> 0).toString(16)}) must latch`);
  }
  assert.equal(gameUpdateSlice9b6840ModeLatchNeeded(2), 0, "exact 2 skips");
  assert.equal(gameUpdateSlice9b6840ModeLatchNeeded(0x2), 0);
});

test("ABI v95: 9b6840 fco_probe_needed runs the probe arm ONLY on an empty manager container", () => {
  /* PE 0x9b6895 mov eax,[ecx+0x4b3d8] / 0x9b689b cmp eax,[ecx+0x4b3dc] /
     0x9b68a1 jne skip: any NON-empty span jumps past probe+walk (pure skip).
     FULL-DWORD equality. */
  assert.equal(gameUpdateSlice9b6840FcoProbeNeeded(0, 0), 1, "empty -> probe");
  assert.equal(gameUpdateSlice9b6840FcoProbeNeeded(0x1000, 0x1000), 1);
  assert.equal(gameUpdateSlice9b6840FcoProbeNeeded(0xffffffff, 0xffffffff), 1);
  assert.equal(gameUpdateSlice9b6840FcoProbeNeeded(0x1000, 0x1004), 0, "one entry -> skip");
  assert.equal(gameUpdateSlice9b6840FcoProbeNeeded(0, 0x100), 0);
  assert.equal(gameUpdateSlice9b6840FcoProbeNeeded(0x100, 0), 0);
});

test("ABI v95: 9b6840 walk_count_needed is UNSIGNED !=0", () => {
  /* PE 0x9b68c7 cmp [ebx+0x1264], esi(0) / 0x9b68cd jbe skip. UNSIGNED:
     0xffffffff is a huge positive count and walks; 0 skips. */
  for (const c of [1, 0x100, 0x7fffffff, 0x80000000, 0xffffffff]) {
    assert.equal(gameUpdateSlice9b6840WalkCountNeeded(c), 1,
      `count 0x${(c >>> 0).toString(16)} walks`);
  }
  assert.equal(gameUpdateSlice9b6840WalkCountNeeded(0), 0, "zero count skips");
});

test("ABI v95: 9b6840 walk_entry_needed uses FULL-DWORD 5 && 0x64", () => {
  /* PE 0x9b68d9 cmp dword [ecx+0x28],5 / jne; 0x9b68df cmp dword [ecx+0x2c],
     0x64 / jne. 0x105/0x164 must NOT match (a byte test would). */
  assert.equal(gameUpdateSlice9b6840WalkEntryNeeded(5, 0x64), 1, "type 5 variant 0x64");
  assert.equal(gameUpdateSlice9b6840WalkEntryNeeded(5, 0x100 | 0x64), 0, "variant high bits");
  assert.equal(gameUpdateSlice9b6840WalkEntryNeeded(0x100 | 5, 0x64), 0, "type high bits");
  assert.equal(gameUpdateSlice9b6840WalkEntryNeeded(4, 0x64), 0);
  assert.equal(gameUpdateSlice9b6840WalkEntryNeeded(5, 0x63), 0);
  assert.equal(gameUpdateSlice9b6840WalkEntryNeeded(0xffffffff, 0x64), 0);
});

test("ABI v95: 9b6840 tail_render_needed selects byte by FULL-DWORD mode==1, LOW-BYTE test", () => {
  /* PE 0x9b712a cmp esi,1 / 0x9b712d mov eax,0x249 / 0x9b7132 mov ecx,0x135 /
     0x9b7137 cmovne eax,ecx / 0x9b713a cmp byte ptr [eax+edi],0 / je exit.
     mode==1 -> 0x249 byte else 0x135 byte; the byte is LOW-BYTE tested.
     0x101 mode is NOT 1 -> the 0x135 byte decides; byte 0x100 = low 0. */
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(1, 1, 0), 1, "mode 1, byte249 nonzero");
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(1, 0, 1), 0, "mode 1 uses byte249");
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(1, 0x100, 0), 0, "byte249 low byte 0");
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(2, 0, 1), 1, "mode 2 uses byte135");
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(2, 1, 0), 0);
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(0x101, 0, 1), 1, "WIDE mode !=1 -> byte135");
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(0x101, 1, 0), 0);
  assert.equal(gameUpdateSlice9b6840TailRenderNeeded(0xffffffff, 0, 0x100), 0, "byte135 low 0");
});

test("ABI v95: 9b6840 anim_layer_ok is SIGNED jg", () => {
  /* PE 0x9b6a02 cmp [anim+0x80],req / jg ok: 0xffffffff max is NEGATIVE and
     must log 'LayerId out of bounds\n' (not pass). */
  assert.equal(gameUpdateSlice9b6840AnimLayerOk(3, 2), 1, "max 3 > 2");
  assert.equal(gameUpdateSlice9b6840AnimLayerOk(2, 2), 0, "equal does not pass (jg)");
  assert.equal(gameUpdateSlice9b6840AnimLayerOk(1, 2), 0);
  assert.equal(gameUpdateSlice9b6840AnimLayerOk(0xffffffff, 2), 0, "negative max logs");
  assert.equal(gameUpdateSlice9b6840AnimLayerOk(0x80000000, 2), 0);
  assert.equal(gameUpdateSlice9b6840AnimLayerOk(0x7fffffff, 2), 1);
});

test("ABI v95: 9b6840 anim_id_ok is SIGNED id range (js/jl)", () => {
  /* PE 0x9b6a32 test eax,eax / je fatal; 0x9b6a36 test ebx,ebx / js fatal;
     0x9b6a3a cmp ebx,[anim+0x1c] / jl ok. 0xffffffff id is negative -> fail;
     id==count fails; id<count passes. */
  assert.equal(gameUpdateSlice9b6840AnimIdOk(1, 0, 8), 1);
  assert.equal(gameUpdateSlice9b6840AnimIdOk(1, 7, 8), 1);
  assert.equal(gameUpdateSlice9b6840AnimIdOk(1, 8, 8), 0, "id == count fails");
  assert.equal(gameUpdateSlice9b6840AnimIdOk(1, 0xffffffff, 8), 0, "negative id fails");
  assert.equal(gameUpdateSlice9b6840AnimIdOk(1, 0x80000000, 8), 0);
  assert.equal(gameUpdateSlice9b6840AnimIdOk(0, 0, 8), 0, "null anim fails");
});

test("ABI v95: 9b6840 emit sites mirror the mode-latch store law", () => {
  /* The A2 latch (PE 0x9b6905..0x9b6918) runs on EVERY non-early-out body
     path AFTER 0x425130 (which does not touch Game+0x22ed4/0x22edc). When a
     site fires opaque_call_009b6840, the slice must apply status 1/2 iff
     status22ed4 != 2 — WIDE status 0x102 latches, 2 does not. */
  const base = { menuState23a74: 1, gate1b83c: 0, predicate1ba74: 0 };
  const out = step({ ...base, gate1d520: 1, status22ed4: 0 });
  assert.equal(out.events.opaqueCall009b6840, 1, "host fires for open menu (gate-1d520 site)");
  assert.equal(out.state.status22ed4, 1, "latch stores 1");
  assert.equal(out.state.status22edc, 2, "latch stores 2");
  const wide = step({ ...base, gate1d520: 1, status22ed4: 0x102 });
  assert.equal(wide.events.opaqueCall009b6840, 1);
  assert.equal(wide.state.status22ed4, 1, "WIDE 0x102 latches (full-dword)");
  assert.equal(wide.state.status22edc, 2);
  const already = step({ ...base, gate1d520: 1, status22ed4: 2, status22edc: 2 });
  assert.equal(already.state.status22ed4, 2, "status==2 stays");
  assert.equal(already.state.status22edc, 2);
  const closed = step({ ...base, gate1d520: 1, menuState23a74: 0, status22ed4: 0 });
  assert.equal(closed.events.opaqueCall009b6840 || 0, 0, "closed menu no host");
  assert.equal(closed.state.status22ed4, 0, "closed menu no latch");
  /* Menu-open resume site (continueAfterMenuOpen, menu branch). */
  const rt = { globalRangeByteLength: 1, frameOpaque98dba0WalkReady: 0 };
  const events = { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_MENU_OPEN };
  const mu = resumeGameUpdateMenuOpen(
    { ...base, status22ed4: 0 }, rt, events);
  assert.equal(mu.events.opaqueCall009b6840, 1, "menu-open resume site fires");
  assert.equal(mu.state.status22ed4, 1, "menu-open resume applies the latch");
  assert.equal(mu.state.status22edc, 2);
  const muClosed = resumeGameUpdateMenuOpen(
    { ...base, menuState23a74: 0, status22ed4: 0 },
    rt, { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_MENU_OPEN });
  assert.equal(muClosed.events.opaqueCall009b6840 || 0, 0, "closed menu skip at resume");
  assert.equal(muClosed.state.status22ed4, 0, "closed menu no latch at resume");
});

