test("ABI v93: the shipped Wasm agrees with the oracle on BOTH new exports", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  const skip = pick("isaac_game_update_slice_8ef990_join_skip");
  const closed = pick("isaac_game_update_slice_8ef990_join_956780_closed");
  assert.equal(typeof skip, "function", "join_skip missing from the module");
  assert.equal(typeof closed, "function", "join_956780_closed missing from the module");
  /* Values cross UNMASKED — the MODULE must narrow, never the harness. */
  for (const [p, idx8] of [
    [0x11a, 0x11a], [0x11a, 0x11b], [0, 0], [0, 1],
    [0xffffffff, 0xffffffff], [0xffffffff, 0xfffffffe],
    [0x7fffffff, 0x80000000], [0x100, 0x1000],
  ]) {
    assert.equal(skip(p, idx8) | 0, gameUpdateSlice8ef990JoinSkip(p, idx8),
      `wasm join_skip(0x${(p >>> 0).toString(16)}, 0x${(idx8 >>> 0).toString(16)})`);
  }
  for (const [g, bd, f10, np, sn] of [
    [0xc71678, 0x0, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x100, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x1ff, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x0, 0xffffffff, 0x1234, 0x9999],
    [0xc71678, 0xffffffff, 0x0, 0x1234, 0x9999],
    [0x0, 0x0, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x8, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x0, 0x1234, 0x1234],
  ]) {
    assert.equal(closed(g, bd, f10, np, sn) | 0,
      gameUpdateSlice8ef990Join956780Closed(g, bd, f10, np, sn),
      `wasm join_956780_closed(0x${(g >>> 0).toString(16)},0x${(bd >>> 0).toString(16)},` +
      `0x${(f10 >>> 0).toString(16)},0x${(np >>> 0).toString(16)},0x${(sn >>> 0).toString(16)})`);
  }
});

/* ================= ABI v96 (wave update-v96-record9-tailalaws, record idx 9):
   TAIL-A seam laws 0x8efcea..0x8efdd1 ===========================
   PE (disasm-8efcea-taila-full.txt, stitched from cpu-dump/{008ef990,
   008efc90,008efcf4,008efe04}.txt):
     0x008efcf4  mov  eax,[M+0x4b3d8]      ; MP-slot vector begin (M=[0xc7169c])
     0x008efcfa  cmp  eax,[M+0x4b3dc]      ; slot end
     0x008efd00  je   0x008efd3e           ; D1: EMPTY -> ARM B; else ARM A
     0x008efd97  mov  dword ptr [esp+0x10],0x36 ; TAIL-A fallback id 0x36
     0x008efd9f  call 0x00956780           ; RTE gate closed -> no-op (id stays)
     0x008efdcc  call 0x0092dc30           ; SFXManager::Play (sole residual host)
     0x008efdd1  mov  dword ptr [edi],2           ; ==== ELSE-RESET triple ====
     0x008efdd7  mov  dword ptr [edi+0xc],8       ; mode24ed8 = 8
     0x008efdde  mov  dword ptr [edi+4],0xffffffff ; value24ed0 = -1
   The roll select lives in FUN_00956780 itself (cpu-dump/00956780.txt):
     0x00956806  mov  dword ptr [edi],0x25   ; seed id 0x25 (37)
     0x00956850  mov  eax,0xcccccccd         ; magic-mul mod-20
     0x00956859  mul  esi                    ; (0x95685b stores the seed [0xc5d2b0])
     0x00956861  shr  edx,4                  ; edx = seed/20 (exact iff %20==0)
     0x0095686c  jne  0x956874               ; remainder != 0 -> keep 0x25
     0x0095686e  mov  dword ptr [edi],0x12d  ; remainder == 0 -> 0x12d (301)
   ABI stays 95; no runtime lanes, no events (layouts frozen). */

test("ABI v96 (record 9 TAIL-A): slot_empty is FULL-dword begin==end (0x8efcf4..0x8efd00)", () => {
  /* PE-truth: 0x8efcf4 mov eax,[M+0x4b3d8] / 0x8efcfa cmp eax,[M+0x4b3dc] /
     0x8efd00 je 0x8efd3e — the MP slot is EMPTY iff begin == end (FULL
     32-bit equality, the room-5/sfx-family canonical empty test). WIDE
     0x100/0xffffffff pairs compare EQUAL (a byte-narrow mutant would read
     the low bytes only). */
  const empty = [
    [0, 0], [1, 1], [0xffffffff, 0xffffffff],
    [0x100, 0x100], [0x7fffffff, 0x7fffffff], [0x80000000, 0x80000000],
  ];
  for (const [b, e] of empty) {
    assert.equal(gameUpdateSlice8ef990TailaSlotEmpty(b, e), 1,
      `slot_empty(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
  const nonEmpty = [
    [0, 1], [1, 0], [0xffffffff, 0xfffffffe],
    [0x100, 0x1ff], [0x100, 0x101], [0x7fffffff, 0x80000000],
    /* equal LOW bytes, unequal FULL dword — a byte-narrow mutant returns 1 */
    [0x100, 0x200], [0x1234, 0x1334],
  ];
  for (const [b, e] of nonEmpty) {
    assert.equal(gameUpdateSlice8ef990TailaSlotEmpty(b, e), 0,
      `slot_empty(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
});

test("ABI v96 (record 9 TAIL-A): else_reset stores the constant triple 2/8/0xffffffff", () => {
  /* PE 0x8efdd1..0x8efde4: [edi]=2 / [edi+0xc]=8 / [edi+4]=0xffffffff.
     Path-agnostic — find-fail 0x8ef9d8, count==0 0x8ef9e0 and the TAIL-A
     fallthrough all write the SAME triple (the "path tag" is a host event,
     not a store difference). */
  assert.equal(gameUpdateSlice8ef990ElseResetState(), 2);
  assert.equal(gameUpdateSlice8ef990ElseResetMode(), 8);
  assert.equal(gameUpdateSlice8ef990ElseResetValue(), 0xffffffff);
});

test("ABI v96 (record 9 TAIL-A): taila_956780_closed is the site-pinned re-export of the v93 join law", () => {
  /* Site 0x8efd9f, same 0x4288a0 gate shape as the JOIN (0x8efcb1): the
     re-export must agree with gameUpdateSlice8ef990Join956780Closed on
     EVERY drive (closed -> prep no-op, id stays 0x36; open -> host remap). */
  const closed = [
    [0x0, 0x0, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x1, 0x0, 0x1234, 0x9999],
    [0xc71678, 0xff, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x1ff, 0x0, 0x1234, 0x9999],
    [0xc71678, 0xffffffff, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x8, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x100, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x0, 0x1234, 0x1234],
  ];
  const open = [
    [0xc71678, 0x0, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x100, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x7, 0x1234, 0x9999],
    [0xc71678, 0x0, 0xffffffff, 0x1234, 0x9999],
    [0x1, 0x0, 0x0, 0x0, 0x1],
  ];
  for (const [g, bd, f10, np, sn] of closed) {
    assert.equal(gameUpdateSlice8ef990Taila956780Closed(g, bd, f10, np, sn), 1,
      `taila_closed(0x${(g >>> 0).toString(16)},0x${(bd >>> 0).toString(16)},` +
      `0x${(f10 >>> 0).toString(16)},0x${(np >>> 0).toString(16)},0x${(sn >>> 0).toString(16)})`);
  }
  for (const [g, bd, f10, np, sn] of open) {
    assert.equal(gameUpdateSlice8ef990Taila956780Closed(g, bd, f10, np, sn), 0,
      `taila_closed(0x${(g >>> 0).toString(16)},0x${(bd >>> 0).toString(16)},` +
      `0x${(f10 >>> 0).toString(16)},0x${(np >>> 0).toString(16)},0x${(sn >>> 0).toString(16)})`);
  }
  for (const row of [...closed, ...open]) {
    assert.equal(gameUpdateSlice8ef990Taila956780Closed(...row),
      gameUpdateSlice8ef990Join956780Closed(...row),
      `re-export equals the v93 JOIN law on (0x${row.map((x) => (x >>> 0).toString(16)).join(",")})`);
  }
});

test("ABI v96 (record 9 TAIL-A): taila_sfx_id rolls 0x12d iff roll % 20 == 0", () => {
  /* PE 0x956806 seeds 0x25; the magic-mul mod-20 zero test 0x956850..0x95686c
     (0xcccccccd high word shr edx,4 — exact iff roll % 20 == 0, UNSIGNED)
     overwrites with 0x12d at 0x95686e. The modulo is pure arithmetic and
     computed IN-MODULE (sfx-family rare_hit precedent); only the xorshift
     RNG chain stays host. WIDE drives: 0x7fffffff % 20 == 7, 0x80000000
     % 20 == 8, 0xffffffff % 20 == 15 — none zero; 0xfffffff0 % 20 == 0. */
  for (const r of [0, 20, 100, 0x140, 0xfffffff0]) {
    assert.equal(gameUpdateSlice8ef990TailaSfxId(r), 0x12d,
      `roll 0x${(r >>> 0).toString(16)} (%20==0) -> 0x12d (301)`);
  }
  for (const r of [1, 10, 19, 0x7fffffff, 0x80000000, 0xffffffff]) {
    assert.equal(gameUpdateSlice8ef990TailaSfxId(r), 0x25,
      `roll 0x${(r >>> 0).toString(16)} -> 0x25 (37)`);
  }
});

