test("ABI v96 (record 9 TAIL-A): the shipped Wasm agrees with the oracle on the four TAIL-A laws", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (pre-v96); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const slot = pick("isaac_game_update_slice_8ef990_taila_slot_empty");
  if (typeof slot !== "function") {
    t.skip("the shipped module is stale (pre-v96 TAIL-A); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const st = pick("isaac_game_update_slice_8ef990_else_reset_state");
  const mo = pick("isaac_game_update_slice_8ef990_else_reset_mode");
  const va = pick("isaac_game_update_slice_8ef990_else_reset_value");
  const closed = pick("isaac_game_update_slice_8ef990_taila_956780_closed");
  const sfx = pick("isaac_game_update_slice_8ef990_taila_sfx_id");
  for (const [b, e] of [
    [0, 0], [0, 1], [1, 0], [0xffffffff, 0xffffffff],
    [0xffffffff, 0xfffffffe], [0x100, 0x100], [0x100, 0x1ff],
    [0x100, 0x200],
  ]) {
    assert.equal(slot(b, e) | 0, gameUpdateSlice8ef990TailaSlotEmpty(b, e),
      `wasm taila_slot_empty(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
  assert.equal(st() | 0, gameUpdateSlice8ef990ElseResetState() | 0, "wasm else_reset_state");
  assert.equal(mo() | 0, gameUpdateSlice8ef990ElseResetMode() | 0, "wasm else_reset_mode");
  assert.equal(va() | 0, gameUpdateSlice8ef990ElseResetValue() | 0, "wasm else_reset_value");
  for (const [g, bd, f10, np, sn] of [
    [0xc71678, 0x0, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x100, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x1ff, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x0, 0xffffffff, 0x1234, 0x9999],
    [0x0, 0x0, 0x0, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x8, 0x1234, 0x9999],
    [0xc71678, 0x0, 0x0, 0x1234, 0x1234],
  ]) {
    assert.equal(closed(g, bd, f10, np, sn) | 0,
      gameUpdateSlice8ef990Taila956780Closed(g, bd, f10, np, sn),
      `wasm taila_956780_closed(0x${(g >>> 0).toString(16)},0x${(bd >>> 0).toString(16)},` +
      `0x${(f10 >>> 0).toString(16)},0x${(np >>> 0).toString(16)},0x${(sn >>> 0).toString(16)})`);
  }
  for (const r of [0, 20, 100, 1, 10, 19, 0xffffffff]) {
    assert.equal(sfx(r) | 0, gameUpdateSlice8ef990TailaSfxId(r),
      `wasm taila_sfx_id(0x${(r >>> 0).toString(16)})`);
  }
});

/* ================= ABI v90: 4212c0 flag_111 409030-pair gate ==============
   PE 0x00421300..0x00421316: `cmp byte [esi+0x111],0; lea edi,[esi+0x38];
   call 0x409030; lea ecx,[esi+0x58]; call 0x409030`. Each 409030 is a pure
   no-op (`mov edi,[esi+4]; test edi,edi; je 0x4090eb; cmp byte [esi+0x14],0;
   je 0x4090eb` — straight to the store-free epilogue) when field4==0 or
   flag14 low byte==0. A's fields are the captured +0x3c/+0x4c (field3c /
   flag4c); B's are +0x5c/+0x6c (field5c / flag6c), read through the runtime
   blob along with pairReady (ready=0 keeps the pre-v90 always-host).
   Both gates no-op -> the pair folds to nothing and the secondary==3 arm
   (0x0042131b) still applies; one live gate -> host the whole arm. */

function frameAux4212c0(overrides = {}, runtime = {}) {
  const base = state({
    frameOpaque4212c0Mode: 0,
    frameOpaque4212c0Secondary: 0,
    frameOpaque4212c0Field3c: 0,
    frameOpaque4212c0Flag4c: 0,
    frameOpaque4212c0Flag111: 0,
    ...overrides,
  });
  const events = {
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK,
    frameOpaque98dba0Site: 1 /* FRAME_AUX */,
  };
  return resumeGameUpdate98dba0PlayerWalk(base, runtime, events);
}

test("ABI v90: pairReady=0 keeps the pre-v90 always-host at 0x004212c0", () => {
  const out = frameAux4212c0(
    { frameOpaque4212c0Mode: 2, frameOpaque4212c0Flag111: 1 },
    { frameOpaque4212c0PairReady: 0, frameOpaque4212c0Field5c: 1, frameOpaque4212c0Flag6c: 1 },
  );
  assert.equal(out.events.opaqueCall004212c0, 1);
  assert.equal(out.events.continuationKind, UPDATE_CONTINUATION.RESUME_AFTER_FRAME_AUX_UPDATES);
});

test("ABI v90: flag_111 set + BOTH 409030 gates no-op folds to pure (secondary arm applies)", () => {
  /* A no-op via flag4c low byte 0; B no-op via field5c 0. mode==1 clear
     still applies before the pair (PE 0x4212d4..0x4212fa). */
  const out = frameAux4212c0(
    {
      frameOpaque4212c0Mode: 1,
      frameOpaque4212c0Field3c: 7,
      frameOpaque4212c0Flag4c: 0x100, /* low byte 0 -> A no-op */
      frameOpaque4212c0Flag111: 1,
    },
    { frameOpaque4212c0PairReady: 1, frameOpaque4212c0Field5c: 0, frameOpaque4212c0Flag6c: 1 },
  );
  assert.equal(out.events.opaqueCall004212c0, 0);
  assert.equal(out.state.frameOpaque4212c0Mode, 0, "mode==1 clear runs before the pair");
});

test("ABI v90: one live 409030 keeps host (defect class 1: subobject stores)", () => {
  /* A live (field3c 7, flag4c low 1). B no-op. Host must stay — the live
     409030 stores into the A subobject and state apply must not fold it. */
  for (const [field5c, flag6c] of [[1, 1], [1, 0], [0, 1], [0x100, 0x1ff]]) {
    const out = frameAux4212c0(
      {
        frameOpaque4212c0Mode: 2,
        frameOpaque4212c0Field3c: 7,
        frameOpaque4212c0Flag4c: 1,
        frameOpaque4212c0Flag111: 1,
      },
      { frameOpaque4212c0PairReady: 1, frameOpaque4212c0Field5c: field5c, frameOpaque4212c0Flag6c: flag6c },
    );
    assert.equal(out.events.opaqueCall004212c0, 1, `f5c=${field5c} f6c=${flag6c}`);
  }
});

test("ABI v90: B gate alone live keeps host; wide flag6c 0x100 is low-byte", () => {
  /* B live (field5c 1, flag6c low 1). A no-op (field3c 0). */
  const live = frameAux4212c0(
    { frameOpaque4212c0Mode: 2, frameOpaque4212c0Field3c: 0, frameOpaque4212c0Flag111: 1 },
    { frameOpaque4212c0PairReady: 1, frameOpaque4212c0Field5c: 1, frameOpaque4212c0Flag6c: 1 },
  );
  assert.equal(live.events.opaqueCall004212c0, 1);
  /* B flag6c low byte 0 (wide 0x100) + field5c 0 on BOTH sides of the gate
     -> pure fold. The byte test is never pre-masked on the Wasm side. */
  const pure = frameAux4212c0(
    { frameOpaque4212c0Mode: 2, frameOpaque4212c0Field3c: 0, frameOpaque4212c0Flag111: 1 },
    { frameOpaque4212c0PairReady: 1, frameOpaque4212c0Field5c: 0, frameOpaque4212c0Flag6c: 0x100 },
  );
  assert.equal(pure.events.opaqueCall004212c0, 0, "flag6c 0x100 low byte is 0");
  const wideA = frameAux4212c0(
    { frameOpaque4212c0Mode: 2, frameOpaque4212c0Field3c: 0x100, frameOpaque4212c0Flag111: 1 },
    { frameOpaque4212c0PairReady: 1, frameOpaque4212c0Field5c: 0, frameOpaque4212c0Flag6c: 1 },
  );
  assert.equal(wideA.events.opaqueCall004212c0, 0, "field3c 0x100 is a full-dword no-op gate");
});

