test("ABI v94: the shipped Wasm agrees with the oracle on BOTH new exports", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  assert.equal(pick("isaac_game_update_slice_events_size")(), ABI_SIZES.events);
  const ln = pick("isaac_game_update_slice_4212c0_add0_log_needed");
  const pf = pick("isaac_game_update_slice_4212c0_add0_probe_pure_false");
  assert.equal(typeof ln, "function", "add0_log_needed missing from the module");
  assert.equal(typeof pf, "function", "add0_probe_pure_false missing from the module");
  /* Bytes cross UNMASKED: the MODULE must narrow, never the harness. */
  const fields = [0, 1, 0xff, 0x100, 0x1ff, 0x7fffffff, 0x80000000, 0xffffffff];
  for (const f of fields) {
    assert.equal(ln(f) | 0, gameUpdateSlice4212c0Add0LogNeeded(f),
      `wasm log_needed(0x${(f >>> 0).toString(16)})`);
  }
  const counts = [0, 1, 0xff, 0x100, 0x1ff, 0x7fffffff, 0x80000000, 0xffffffff];
  for (const c of counts) {
    assert.equal(pf(c) | 0, gameUpdateSlice4212c0Add0ProbePureFalse(c),
      `wasm probe_pure_false(0x${(c >>> 0).toString(16)})`);
  }
});

/* ============ ABI v95: B13 H5 824a70 per-loop CREATE arm (record idx 34) ===
   PE-truth (transcribed from ambient-always-host/FUN_00824a70-full.txt,
   branch-by-branch):
   loop count 0x00824b60..0x00824ba3 — `test ecx,ecx` on age (age =
   Room[0]==0 ? -1 : Game+0x264f8 - Room+0x11f0); `sete al`; `lea
   eax,[eax*4+1]`: age==0 -> FIVE loop iterations, else ONE (the %210
   cadence lives in the separate needs_host gate).
   CREATE arm 0x00824c97..0x00824cc2: R3 = genrand (push eax @0x824ca4);
   push 0 / push 0 @0x824ca2/0x824ca5/0x824ca7; push 0x8a (variant
   @0x824cb3); push 0x3e8 (type @0x824cb8); call 0x6fe410; then
   push 0xb1bc54 (anm-data for A1 0x40a5d0 @0x824cc2). GetLayer layer
   index = push 0 @0x824e55 (L0 layer 0).
   R4 genrand decision 0x00824cd8 `test edi,edi` ([anm2+0x30] anim_count)
   / 0x00824cda `je` skip: FULL-DWORD — 0x100 / 0xffffffff still draw.
   The entity create 0x6fe410 (and ANM2 helpers 0x40bcd0/0x40a5d0/
   0x408e00, GetLayer 0x40b220, entity vcall [e+0xc]) STAYS TYPED HOST;
   the per-loop argument plan is typed in-module (create_args_plan) and
   the create event becomes ambient_824a70_create_typed (plan count) +
   the create-args scratch (7 u32 per loop).
   Mutation legend (each flipped line fails THIS group, then restored
   sha256-byte-identical — NOTES.md update-v95-824a70-create-typed):
   - loop-count law inverted (age!=0 ? 5 : 1): T1 dies on age 0/1.
   - plan type 0x3e8 -> 0x3e9: T2 dies.
   - r4_needed inverted: T3 dies on WIDE anim_count.
   - wiring seed slot i*7+2 (R2) instead of i*7+3 (R3): T5 step test's
     plan-count still passes but the verifier scratch oracle dies. */

function ambientH5HeadRuntime(overrides = {}) {
  return {
    h5BodyBlobReady: 1,
    genrandMtReady: 1,
    genrandIndexIn: 0,
    genrandModeFlag: 0,
    ambientRoomActive: 1,
    ambientRoomEntry11f0: 0,
    ambientRoomF14: 100,
    ambientRoomF18: 200,
    ambientRoomF1c: 300,
    ambientRoomF20: 400,
    ...overrides,
  };
}

/** Run the room-update-CLEAR resume with the ambient H5 inputs shaped so the
 *  H5 fragment fires (mode==0x2c forces needs_host in the v17 gate). The
 *  ambient suite lives in the CLEAR resume (it then hands off to the head). */
function ambientH5Head(stateOverrides = {}, runtimeOverrides = {}) {
  const base = step({});
  const shaped = { ...base.state, mode26584: 0x2c, ...stateOverrides };
  const ev = {
    ...base.events,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_CLEAR,
  };
  const out = resumeGameUpdateRoomUpdateClear(shaped, ambientH5HeadRuntime(runtimeOverrides), ev);
  assert.ok(out, "clear resume returned a result");
  return out;
}

