test("ABI v99: JSON evidence — name-matched opaqueCall004212c0 REMOVED (count 48 -> 47; abiV99 rides resolvedBoundaries)", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const rec = spec.resolvedBoundaries.find((b) => b.name === "opaqueCall004212c0");
  assert.ok(rec, "record found by NAME in resolvedBoundaries (never index-match)");
  assert.equal(rec.targetVa, "0x004212c0");
  assert.match(rec.operation, /REMOVED at ABI v99/);
  assert.match(rec.evidence || rec.abiV99 || "", /0x421343|0x4213cd|interior|prefix_plan|capture-absence/i);
  assert.match(rec.evidence || "", /92e430|6fd7c0|8318a0|volume|se_14|call_8318a0_drop/i);
  assert.match(rec.abiV99 || "", /resolvedBoundaries|48 -> 47|bridge unit|idx 1/i);
  assert.ok(!spec.opaqueBoundaries.some((b) => b.targetVa === "0x004212c0"),
    "the record is GONE from opaqueBoundaries");
  assert.equal(spec.opaqueBoundaries.length, 24,
    "count 26 -> 25 (record idx 27 roomTriggerClearAudio REMOVED at ABI v138, update-v138-audio-alt-tail-pack); count 27 -> 26 (record idx 26 roomTriggerClearAudioNonGreed REMOVED at ABI v136, update-v136-audio-head-pack); count 32 -> 31 (record idx 45 REMOVED at v128, 18th removal since v79); count 33 -> 32 (record idx 38 REMOVED at v127, 17th removal since v79); count 34 -> 33 (record idx 40 REMOVED at v126, 16th removal since v79); count 35 -> 34 (record idx 25 REMOVED at v125, 15th removal since v79); count 36 -> 35 (record idx 46 REMOVED at v124, 14th removal since v79); count 37 -> 36 (record idx 19 REMOVED at v122, 13th removal since v79); count 38 -> 37 (record idx 47 REMOVED at v121, 12th removal since v79); count 39 -> 38 (record idx 41 REMOVED at v120, 11th removal since v79); count 41 -> 39 (records idx 24 + idx 33 REMOVED at v119); count 42 -> 41 (record idx 23 REMOVED at v115); count 43 -> 42 (record idx 42 REMOVED at v114); count 44 -> 43 (record idx 16 REMOVED at v110); count 45 -> 44 (record idx 12 REMOVED at v109); count 46 -> 45 (record idx 39 REMOVED at v108); count 47 -> 46 (record idx 1 REMOVED at v100); count 48 -> 47 (record idx 10 REMOVED at v99); count 49 -> 48 (record 22 REMOVED at v98)");
  /* The v98 seam's typed event + capture lanes stay COMMITTED (the removal
     is census/bookkeeping — the residual counter + ABI rows are kept). */
  const evNames = spec.events.map((e) => e.name);
  assert.ok(evNames.includes("frame_opaque_4212c0_true_probe_interior"),
    "typed event @936 stays COMMITTED after the removal");
  assert.ok(evNames.includes("frameOpaque4212c0Add0LogNeeded"),
    "typed platform log @508 stays COMMITTED");
  const riNames = spec.runtimeInputs.map((r) => r.name);
  assert.ok(riNames.includes("frame_opaque_4212c0_true_probe_ready") &&
    riNames.includes("frame_opaque_4212c0_true_probe_volume_bits"),
    "true-probe blob lanes stay COMMITTED (runtime 14152..14200)");
  const evRow = spec.events.find((e) => e.name === "frame_opaque_4212c0_true_probe_interior");
  assert.equal(evRow?.offset, 936, "@936 offset pinned");
});

