  assert.ok(!spec.opaqueBoundaries.some((b) => b.idx === 40),
    "record idx 40 is GONE from opaqueBoundaries (34 -> 33)");
  /* Event slots: the retired coarse counter @224 STAYS in the events ABI
     (NEVER fires); the NEW armed carrier @996 is committed. */
  const ev = new Map(spec.events.map((e) => [e.offset, e.name]));
  assert.equal(ev.get(224), "opaqueRoomUpdateTailMid7230Spawn", "slot @224 counter STAYS");
  assert.equal(EVENTS_LAYOUT.opaqueRoomUpdateTailMid7230Spawn.offset, 224, "layout counter @224");
