test("ABI v95 STOP fold: the per-iteration bound re-read (PE 0x92e2e6 unsigned jb) bounds the walk per sample", () => {
  /* PE 0x92e2e2..0x92e2ec: inc ebx / add esi,0x38 / cmp ebx,[edi+0x190] /
     jb — the bound is RE-READ every iteration through the pointer pinned at
     0x92e267. voice 1's reload 0 stops the loop; voice 2 is never visited. */
  const voices = [
    stopFoldVoice({ channelNull: 1, voicesReloaded: 2 }),
    stopFoldVoice({ channelNull: 1, voicesReloaded: 0 }),
    stopFoldVoice({ channelNull: 1, voicesReloaded: 3 }),
  ];
  const fold = sfxStopFold({
    foldReady: 1, ready: 1, span: 509 * 0x1b8 + 4, voices190: 3, enabled198: 1,
    voiceCount: 3, voices,
  });
  assert.equal(fold.applied, 1);
  assert.equal(fold.voicesVisited, 2, "voice 1's reload 0 stops the loop");
  assert.equal(fold.stores, 2, "one sentinel store per visited voice (0x92e2a0)");
  const rt = stopFoldRuntime({ sfxStopVoices190: 3, sfxStopVoiceCount: 3, sfxStopVoices: voices });
  const out = stopFoldRun(rt);
  assert.equal(out.foldApplied, 1);
  assert.equal(out.stores, 2);
  assert.equal(out.pendingMask, 0);
});

test("ABI v95 STOP fold divergence pin: the STOP pack carries NO +0x08 loop-byte (record-1 divergence #3)", () => {
  /* 0x92e300 substitutes the wrapper's +0x08 loop byte ([voice+0x28], PE
     0x92e3a2 mov cl,[esi+eax+0x28], LOW-BYTE test cl,cl at 0x92e3b3) on its
     null-channel third read; 0x92e230 NEVER reads +0x28 — every per-voice
     gate byte is +0x29 (0x92e2ae cmp byte [esi],0; 0x92e2cf cmp byte
     [esi],al). A merged fold would consult loop_08/query_44; the STOP
     pack must not carry them. */
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  assert.ok(header.includes("IsaacGameUpdateSliceSfxStopVoicePack"), "STOP voice pack struct exists");
  const start = header.indexOf("typedef struct IsaacGameUpdateSliceSfxStopVoicePack");
  const pack = header.slice(start, header.indexOf("} IsaacGameUpdateSliceSfxStopVoicePack;", start));
  assert.ok(!/loop_08|query_44|channel_null_third|channel_null_fourth/.test(pack),
    "the STOP pack is the 6-field sibling, no record-1 third-stage fields");
  const fold = sfxStopFold({
    foldReady: 1, ready: 1, span: 509 * 0x1b8 + 4, voices190: 1, enabled198: 1,
    voiceCount: 1, voices: [stopFoldVoice()],
  });
  assert.equal(fold.probeCalls, 1, "pending 0: second probe only");
  assert.equal(fold.stopCalls, 0);
  assert.equal(fold.stores, 1);
});

