test("ABI v95: quiet arm (maxVol 0 via ineligible pack) + not-playing is a PURE SKIP through the wire", () => {
  /* PE PM2 eligibility (0x009bb70f..0x009bb72d): raw<=0, flags&0x40, or
     dead!=0 SKIP the contribution -> maxVol stays 0 (xorps xmm1) -> comiss
     0.01f vs 0 -> CF=0 -> QUIET arm; probe 0x92e560 == 0 -> 0x9bb795 je.
     No host of any kind (the loud arm would be PLAY/UDPATE). */
  const out = heartbeatResumeDelta({}, {
    pmIntensityPlayerCount: 1, pmIntensityBlobReady: 1, pmIntensityRaw0: 20,
    pmIntensityFlags0: 0x40, pmIntensityDead0: 0, pmIntensitySfxPlaying: 0,
  });
  assert.deepEqual(out, { heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 0, playDevice: 0 },
    "quiet maxVol 0 + probe 0 -> whole-arm pure skip");
  /* Same pack but PLAYING: quiet arm -> STOP lane. MISS gate -> dropped. */
  const playing = heartbeatResumeDelta({}, {
    pmIntensityPlayerCount: 1, pmIntensityBlobReady: 1, pmIntensityRaw0: 20,
    pmIntensityFlags0: 0x40, pmIntensityDead0: 0, pmIntensitySfxPlaying: 1,
    sfxStopReady: 1, sfxStopSpan: 0, sfxStopVoices190: 1, sfxStopEnabled198: 1,
  });
  assert.deepEqual(playing, { heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 0, playDevice: 0 },
    "quiet maxVol 0 + playing + MISS -> stop fold no-op, no heartbeat");
});

test("ABI v95: WIDE count 0x100 with blob=0 keeps the NON-EMPTY MONOLITHIC fallback", () => {
  /* A low-byte count test would treat 0x100 as empty and pure-skip; the PE
     count is (end-begin) SAR 2 FULL-DWORD, so 0x100 is non-empty -> blob=0
     -> MONOLITHIC heartbeat host. */
  const out = heartbeatResumeDelta({}, {
    pmIntensityPlayerCount: 0x100, pmIntensityBlobReady: 0, pmIntensitySfxPlaying: 0,
  });
  assert.deepEqual(out, { heartbeat: 1, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 0, playDevice: 0 });
  /* The loud arm still reaches UPDATE on the pack path (unchanged v44 wire). */
  const loud = heartbeatResumeDelta({}, {
    pmIntensityPlayerCount: 1, pmIntensityBlobReady: 1, pmIntensityRaw0: 20,
    pmIntensityFlags0: 0, pmIntensityDead0: 0, pmIntensitySfxPlaying: 1,
    sfxStopReady: 1, sfxStopSpan: 0, sfxStopVoices190: 1, sfxStopEnabled198: 1,
  });
  assert.deepEqual(loud, { heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 0, playDevice: 0 },
    "loud+playing + MISS -> volume/pitch folds are proof-complete no-ops");
});

/* ---------- ABI v95: record idx 46 — PLAY lane typed host leaves ----------
   The RESIDUAL_PLAY lane consumes the SFX family Play gate BY REFERENCE
   (isaac_sfx_play_gate / sfxPlayGate — the exact 0x0092dc30 first three
   tests) and splits the monolithic residual into three named host leaves:
   NO_SAMPLES warn-log, PRELOAD Load+log+counter+continuation, LIVE device
   body. MISS drops; ready=0 keeps the monolithic counter. */

function playLaneDelta(runtime = {}) {
  return heartbeatResumeDelta({}, {
    pmIntensityPlayerCount: 1, pmIntensityBlobReady: 1,
    pmIntensityRaw0: 20, pmIntensityFlags0: 0, pmIntensityDead0: 0,
    pmIntensitySfxPlaying: 0,
    ...runtime,
  });
}

test("ABI v95: PLAY lane MISS drops everything (side-effect-free, PE 0x92dc73/0x92dc96)", () => {
  /* id 0x1fc >= count (span 0): the PE returns before any side effect. */
  const out = playLaneDelta({
    sfxStopReady: 1, sfxStopSpan: 0, sfxStopVoices190: 1, sfxStopEnabled198: 1,
  });
  assert.deepEqual(out, {
    heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 0, playDevice: 0,
  });
  /* A NEGATIVE id can never reach the wire (0x1fc is fixed); the WIDE
     count keeps the signed jge semantics: span with count == 0x1fc is
     MISS (id >= count), count == 0x1fd is LIVE. */
  const at = playLaneDelta({
    sfxStopReady: 1, sfxStopSpan: 0x1fc * 0x1b8, sfxStopVoices190: 1,
    sfxStopEnabled198: 1,
  });
  assert.equal(at.playDevice, 0, "count == id is MISS (signed jge)");
  const live = playLaneDelta({
    sfxStopReady: 1, sfxStopSpan: (0x1fc + 1) * 0x1b8, sfxStopVoices190: 1,
    sfxStopEnabled198: 1,
  });
  assert.deepEqual(live, {
    heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 0, playDevice: 1,
  });
});

test("ABI v95: PLAY lane NO_SAMPLES -> the warn-log leaf ONLY (PE 0x92dcb5 + ret 0x92dcce)", () => {
  const out = playLaneDelta({
    sfxStopReady: 1, sfxStopSpan: (0x1fc + 1) * 0x1b8, sfxStopVoices190: 0,
    sfxStopEnabled198: 1,
  });
  assert.deepEqual(out, {
    heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 1, playPreload: 0, playDevice: 0,
  });
  /* WIDE voices: the count test is UNSIGNED full dword — 0x100 is NOT 0. */
  const wide = playLaneDelta({
    sfxStopReady: 1, sfxStopSpan: (0x1fc + 1) * 0x1b8, sfxStopVoices190: 0x100,
    sfxStopEnabled198: 1,
  });
  assert.equal(wide.playNoSamples, 0, "0x100 voices is NOT the no-samples arm (unsigned full dword)");
  assert.equal(wide.playDevice, 1, "0x100 voices -> LIVE device leaf");
});

test("ABI v95: PLAY lane PRELOAD -> the Load leaf + continuation edge (v68 pin)", () => {
  /* enabled low byte 0: SoundEffect::Load + "not preloaded" + counter++,
     then the body CONTINUES — one typed preload host leaf (the window/
     voice inputs are not captured; the whole edge stays typed-host). */
  const out = playLaneDelta({
    sfxStopReady: 1, sfxStopSpan: (0x1fc + 1) * 0x1b8, sfxStopVoices190: 2,
    sfxStopEnabled198: 0,
  });
  assert.deepEqual(out, {
    heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 1, playDevice: 0,
  });
  /* WIDE enabled 0x100: LOW-BYTE test -> still PRELOAD. */
  const wide = playLaneDelta({
    sfxStopReady: 1, sfxStopSpan: (0x1fc + 1) * 0x1b8, sfxStopVoices190: 2,
    sfxStopEnabled198: 0x100,
  });
  assert.deepEqual(wide, {
    heartbeat: 0, stop: 0, update: 0, play: 0,
    playNoSamples: 0, playPreload: 1, playDevice: 0,
  }, "enabled 0x100 has a ZERO low byte -> preload (low-byte cmp byte [entry+0x198])");
});

