test("ABI v95: the shipped Wasm agrees with the oracle on ALL THREE PM3 laws", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  const qg = pick("isaac_game_update_slice_pm3_quiet_gate");
  const es = pick("isaac_game_update_slice_pm3_empty_pure_skip");
  const ss = pick("isaac_game_update_slice_pm3_empty_stop_split");
  assert.equal(typeof qg, "function", "pm3_quiet_gate missing from the module");
  assert.equal(typeof es, "function", "pm3_empty_pure_skip missing from the module");
  assert.equal(typeof ss, "function", "pm3_empty_stop_split missing from the module");
  for (const v of [0, -0, -1, -Infinity, Math.fround(0.01), 0.010000001, 0.1, 1,
    Infinity, NaN]) {
    const got = qg(v) | 0;
    const want = gameUpdateSlicePm3QuietGate(v);
    assert.equal(got, want, `wasm quiet_gate(${v})`);
  }
  const counts = [0, 1, 0xff, 0x100, 0x1ff, 0x7fffffff, 0x80000000, 0xffffffff];
  for (const c of counts) {
    for (const p of [0, 1, 0x100, 0x1ff]) {
      assert.equal(es(c, p) | 0, gameUpdateSlicePm3EmptyPureSkip(c, p),
        `wasm empty_pure_skip(count=0x${(c >>> 0).toString(16)}, playing=0x${(p >>> 0).toString(16)})`);
      assert.equal(ss(c, p) | 0, gameUpdateSlicePm3EmptyStopSplit(c, p),
        `wasm empty_stop_split(count=0x${(c >>> 0).toString(16)}, playing=0x${(p >>> 0).toString(16)})`);
    }
  }
});

/* ================= ABI v95 (record idx 39): mid-restock seed==0
   TYPED-EVENT DROP =====================
   PE 0x007e9026 mov edx,[esi] / 0x007e9028 test edx,edx / 0x007e902a jne
   0x7e9042 — RNG::RandomInt catches seed==0 (desc+0x58) and runs the CRT
   fatal 0xa112c0 ('RNG Seed is zero!\n' @0xb6bf54) + int3 0x007e9041 with
   ZERO game-memory stores before the fatal (desc+0xae @0x8054a4 is written
   only AFTER the call). FULL-DWORD seed compare (0x100 must NOT fatal).
   The v46 body wire DROPS the restock on this arm: no desc+0xae write, no
   MONOLITHIC rerun; the decision publishes the typed event key
   `midRestockSeedZeroDrop` (the coordinator's layout merge pins the typed
   event field `mid_restock_seed_zero_drop`). MONOLITHIC (desc_ready=0)
   and the inner-short-gate NONE arm are unchanged. */

test("ABI v95: midRestockSeedZero is a FULL-DWORD compare (0x100 must NOT fatal)", () => {
  assert.equal(gameUpdateSliceMidRestockSeedZero(0), 1, "seed==0 -> PE 0x7e902a falls into the CRT fatal");
  for (const wide of [1, 2, 0xff, 0x100, 0x1ff, 0x7fffffff, 0x80000000, 0xffffffff]) {
    assert.equal(gameUpdateSliceMidRestockSeedZero(wide), 0,
      `seed=0x${(wide >>> 0).toString(16)} must NOT fatal (full-dword test)`);
  }
});

/** Run the room-update-head resume and return the mid-restock deltas. The
 *  mid-restock block is the only writer of opaqueRoomUpdateTailMidRestock /
 *  the v95 typed drop key, and the only writer of roomDescShortAe. */
function midRestockResumeDelta(stateOverrides = {}, runtime = {}) {
  const base = step({});
  const shaped = { ...base.state, ...stateOverrides };
  const ev = {
    ...base.events,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD,
  };
  const preRestock = ev.opaqueRoomUpdateTailMidRestock >>> 0;
  const preAe = shaped.roomDescShortAe >>> 0;
  const out = resumeGameUpdateRoomUpdateHead(shaped, runtime, ev);
  assert.ok(out, "head resume returned a result");
  const events = { ...out.events };
  return {
    restock: (events.opaqueRoomUpdateTailMidRestock >>> 0) - preRestock,
    seedZero: events.midRestockSeedZeroDrop >>> 0,
    ae: (out.state.roomDescShortAe >>> 0) - preAe,
  };
}

/* Outer gate open: type==2 + owner + active + age>1. Body gate open:
   ac=5 > 0, ae=7 >= ac (PE 0x805463 jge body). AE values below are the
   oracle-transcribed RandomInt results (seed % movsx-ac, low16). */
const OPEN_STATE = { roomType8: 2, frameCounter264f8: 10 };
const OPEN_RT = {
  midRestockOwner0x209: 1, ambientRoomActive: 1, ambientRoomEntry11f0: 0,
  midRestockDescReady: 1, midRestockDescAc: 5, midRestockDescAe: 7,
};

test("ABI v95: seed==0 + desc captured -> TYPED DROP (no coarse event, no AE write)", () => {
  /* PE: RandomInt fatal; the machine never reaches 0x8054a4. Drop ==
     pre-crash state: no desc+0xae write, no monolithic rerun. */
  const out = midRestockResumeDelta(OPEN_STATE, { ...OPEN_RT, midRestockDescSeed58: 0 });
  assert.deepEqual(out, { restock: 0, seedZero: 1, ae: 0 },
    "seed58==0 -> typed drop; MONOLITHIC must NOT fire");
});

test("ABI v95: seed==0 drop also fires on the ae==-1 body-open arm", () => {
  const out = midRestockResumeDelta(OPEN_STATE, {
    ...OPEN_RT, midRestockDescAe: 0xffffffff /* int16 -1 */, midRestockDescSeed58: 0,
  });
  assert.deepEqual(out, { restock: 0, seedZero: 1, ae: 0 },
    "ae==-1 opens the body; seed 0 still drops (0x805465 cmp dx,-1 arm)");
});

test("ABI v95: WIDE seed 0x100/0x1ff/0xffffffff is PURE_COMPLETE (write, no events)", () => {
  /* M1 discriminator: a low-byte seed test would drop 0x100 like 0x00 —
     the machine runs the xorshift (0x100 & 0xff == 0 but seed != 0).
     AE expectations are the oracle-transcribed RandomInt low16 results
     (ac=5): 0x100->4, 0x1ff->1, 0xffffffff->4. */
  const want = { 0x100: 4, 0x1ff: 1, 0xffffffff: 4 };
  for (const [seed, expectAe] of Object.entries(want)) {
    const out = midRestockResumeDelta(OPEN_STATE, {
      ...OPEN_RT, midRestockDescSeed58: Number(seed),
    });
    assert.equal(out.seedZero, 0, `seed 0x${seed} must NOT drop`);
    assert.equal(out.restock, 0, `seed 0x${seed} is pure`);
    assert.equal(out.ae >>> 0, expectAe, `seed 0x${seed} writes desc+0xae (RandomInt low16)`);
  }
  /* Plain nonzero seed: exact value law (seed 7 -> low16 2). */
  const out = midRestockResumeDelta(OPEN_STATE, { ...OPEN_RT, midRestockDescSeed58: 7 });
  assert.deepEqual(out, { restock: 0, seedZero: 0, ae: 2 },
    "seed 7 -> PURE_COMPLETE, desc+0xae = 2");
});

