test("ABI v95: record idx 30 lands the 6 greedy-arm helpers + boundary evidence in JSON", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  const names = spec.translatedHelpers.map((h) => h.name);
  for (const n of [
    "isaac_game_update_slice_trigger_clear_greed_mode",
    "isaac_game_update_slice_trigger_clear_greed_arm",
    "isaac_game_update_slice_trigger_clear_greed_expected",
    "isaac_game_update_slice_trigger_clear_greed_match",
    "isaac_game_update_slice_trigger_clear_greed_next",
    "isaac_game_update_slice_trigger_clear_greed_tail_always",
  ]) {
    assert.ok(names.includes(n), `JSON translatedHelpers must include ${n}`);
  }
  /* ABI v131 (update-v131-greed-probe-pack): record idx 30 REMOVED —
     its evidence rides the resolvedBoundaries row. */
  const rec = spec.resolvedBoundaries.find((b) => b.idx === 30);
  assert.ok(rec, "record idx 30 rides resolvedBoundaries (REMOVED at ABI v131)");
  assert.match(rec.operation, /REMOVED at ABI v131/);
  assert.match(rec.evidence || "", /greed|Greed/, "record idx 30 evidence mentions the greed arm");
  assert.equal(spec.abiVersion, 99, "ABI 98 (wave-27 merge freeze-lift)");
});

/* ABI v131 (update-v131-greed-probe-pack): drive the TriggerClear fragment
   into the greed arm (difficulty 2) and return the greed event deltas. */
function greedRun(runtime, stateOverrides = {}) {
  const base = step({});
  const shaped = {
    ...base.state,
    timedTransitionCleanupMode: 0,
    roomClearDelay11ec: 0,
    roomAlive12c0: 0,
    roomAlive12c4: 0,
    roomGreedWave723c: 0,
    roomType8: 1,
    roomDescSubtype: 0,
    roomDescClearCount4a: 0,
    difficulty269c8: 2,
    ...stateOverrides,
  };
  const ev = { ...base.events, continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX };
  const out = resumeGameUpdateRoomUpdatePrefix(shaped, runtime, ev);
  assert.ok(out, "prefix resume returned a result");
  return {
    coarse: out.events.roomTriggerClearAwardsGreed >>> 0,
    probe9bf990: out.events.roomTriggerClearAwardsGreedProbe9bf990 >>> 0,
    probe9bfa00: out.events.roomTriggerClearAwardsGreedProbe9bfa00 >>> 0,
    probe9bfa70: out.events.roomTriggerClearAwardsGreedProbe9bfa70 >>> 0,
    fireCount: out.events.roomTriggerClearAwardsGreedFireCount >>> 0,
    fireMask: out.events.roomTriggerClearAwardsGreedFireMask >>> 0,
  };
}

test("ABI v131: record idx 30 — under the greed probe pack the probes run in-module and the coarse @188 retires", () => {
  /* Pack live, count 2: elem0 fully qualifying + quiet; elem1 disqualified
     (f2c != 0) with a set 20a9 byte.
     Hand-derived from the frozen v81 laws:
       qual(e0)=1 / qual(e1)=0 -> 9bf990 = (count_qual>1)?1:0 = 0;
       9bfa00 = qual && byte==0 = 1 ; 9bfa70 = qual && byte!=0 = 0 ;
       fire = byte!=0 elems -> count 1, mask bit1. */
  const rt = {
    greedProbePackReady: 1,
    greedProbeElemCount: 2,
    greedProbeF2c0: 0, greedProbeF3bc0: 0, greedProbeHasParent0: 0,
    greedProbeParent161c0: 0, greedProbeSelf161c0: 0,
    greedProbeParentIsSelf0: 0, greedProbeF20a90: 0,
    greedProbeF2c1: 1, greedProbeF3bc1: 0, greedProbeHasParent1: 0,
    greedProbeParent161c1: 0, greedProbeSelf161c1: 0,
    greedProbeParentIsSelf1: 0, greedProbeF20a91: 5,
  };
  const live = greedRun(rt);
  assert.equal(live.coarse, 0, "pack live -> coarse @188 retired");
  assert.equal(live.probe9bf990, 0, "one qualifier only -> seta clear");
  assert.equal(live.probe9bfa00, 1, "qual && quiet count");
  assert.equal(live.probe9bfa70, 0, "no loud qualifiers");
  assert.equal(live.fireCount, 1, "elem1 fires");
  assert.equal(live.fireMask, 2, "fire mask bit1");

  /* WIDE byte lanes re-narrow to their low byte (0x100 reads CLEAR). */
  const wide = greedRun({
    ...rt,
    greedProbeF20a91: 5,
    greedProbeF20a90: 0x100,
  });
  assert.equal(wide.fireCount, 1, "wide low-byte-clear elem0 stays quiet");
  assert.equal(wide.fireMask, 2);

  /* Capture absence keeps the pre-v95 monolith byte-for-byte. */
  const mono = greedRun({ ...rt, greedProbePackReady: 0 });
  assert.equal(mono.coarse, 1, "pack absent -> monolith fires");
  assert.equal(mono.fireCount, 0, "no carriers without capture");

  /* Over-cap keeps the monolith too. */
  const over = greedRun({ ...rt, greedProbeElemCount: 9 });
  assert.equal(over.coarse, 1, "over-cap -> monolith fires");
});

