test("ABI v95: the shipped Wasm agrees with the oracle on midRestockSeedZero", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  const sz = pick("isaac_game_update_slice_mid_restock_seed_zero");
  assert.equal(typeof sz, "function", "mid_restock_seed_zero missing from the module");
  /* Bytes cross UNMASKED: the MODULE must narrow, never the harness. */
  const seeds = [0, 1, 0xff, 0x100, 0x1ff, 0x7fffffff, 0x80000000, 0xffffffff];
  for (const s of seeds) {
    assert.equal(sz(s) | 0, gameUpdateSliceMidRestockSeedZero(s),
      `wasm seed_zero(0x${(s >>> 0).toString(16)})`);
  }
});

