test("every exported continuation resume is deterministic on a shaped state", () => {
  const base = step({});
  const twoArg = [
    [resumeGameUpdateGate1b83c, UPDATE_CONTINUATION.RESUME_AFTER_GATE_1B83C_UPDATES],
    [resumeGameUpdateGenericPrompt, UPDATE_CONTINUATION.RESUME_AFTER_GENERIC_PROMPT_UPDATE],
    [resumeGameUpdateStageTransitionEffect, UPDATE_CONTINUATION.RESUME_AFTER_STAGE_TRANSITION_EFFECT],
    [resumeGameUpdateRoomTransitionEffect, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_TRANSITION_EFFECT],
  ];
  for (const [fn, kind] of twoArg) {
    const ev = { ...base.events, continuationKind: kind };
    const out = fn(base.state, ev);
    assert.ok(out, "resume returned a result");
    assert.ok(out.events && typeof out.events === "object", "resume carries events");
    assert.ok(Number.isInteger(out.events.continuationKind), "continuation stays an int");
  }
  const threeArg = [
    [resumeGameUpdate92f1c0, UPDATE_CONTINUATION.RESUME_AFTER_92F1C0],
    [resumeGameUpdateItemOverlay, UPDATE_CONTINUATION.RESUME_AFTER_ITEM_OVERLAY_UPDATE],
    [continueGameUpdateTimedTransition, UPDATE_CONTINUATION.CONTINUE_AT_TIMED_TRANSITION],
    [continueGameUpdateMenuGates, UPDATE_CONTINUATION.CONTINUE_AFTER_TIMED_TRANSITION],
    [resumeGameUpdateMenuOpen, UPDATE_CONTINUATION.RESUME_AFTER_MENU_OPEN],
    [resumeGameUpdateMenuUpdate, UPDATE_CONTINUATION.RESUME_AFTER_MENU_UPDATE],
    [resumeGameUpdateFrameAuxUpdates, UPDATE_CONTINUATION.RESUME_AFTER_FRAME_AUX_UPDATES],
    [resumeGameUpdateEnginePrefix, UPDATE_CONTINUATION.RESUME_AFTER_ENGINE_PREFIX],
    [resumeGameUpdateRoomUpdatePrefixB2, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX_B2],
    [resumeGameUpdateRoomUpdatePrefix, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX],
    [resumeGameUpdateRoomClearNested, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_CLEAR_NESTED],
    [resumeGameUpdateRoomUpdateClear, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_CLEAR],
    [resumeGameUpdateRoomUpdateHead, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD],
    [resumeGameUpdate4257b0PassA, UPDATE_CONTINUATION.RESUME_AFTER_4257B0_PASS_A],
    [resumeGameUpdate98dba0PlayerWalk, UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK],
  ];
  for (const [fn, kind] of threeArg) {
    const ev = { ...base.events, continuationKind: kind };
    const out = fn(base.state, {}, ev);
    assert.ok(out, "resume returned a result");
    assert.ok(out.events && typeof out.events === "object", "resume carries events");
    assert.ok(Number.isInteger(out.events.continuationKind), "continuation stays an int");
  }
  /* B1 is (state, events); the frame-manager tail is (state, constants, runtime, events). */
  const b1 = resumeGameUpdateRoomUpdatePrefixB1(base.state, {
    ...base.events,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX_B1,
  });
  assert.ok(b1, "B1 resume on its continuation");
  assert.ok(Number.isInteger(b1.events.continuationKind), "B1 continuation stays an int");
  const fm = resumeGameUpdateFrameManagerUpdates(
    base.state,
    { transitionComplete: 1 },
    {},
    { ...base.events, continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_FRAME_MANAGER_UPDATES },
  );
  assert.ok(fm, "frame-manager resume returns");
  assert.ok(Number.isInteger(fm.events.continuationKind), "frame-manager continuation stays an int");
});


