test("ABI v64: FX-lerp gate lane follows the PE 0x006fae80..0x006faf0b + 0x006ef410 transcription", () => {
  /* PE lane: cmp byte[Game+0x676b4],0; je -> gate closed skips everything.
     Callee 0x006ef410 per element i: xmm2=cur, xmm1=goal[eax=0x676e8],
     xmm3=step[edx=0x676d0]; d=|cur-goal| (subss; andps 0x7fffffff);
     comiss step,d; jae -> cur=goal; else comiss goal,cur; jbe -> cur-step
     (equal or unordered), else cur+step. Gate clear (mov byte,0) only when
     all six post-call ucomiss cur-vs-step pairs are equal-or-unordered
     (`lahf; test ah,0x44; jp` exits on even parity of ZF|PF, i.e. only
     ordered-unequal pairs keep the gate open). */
  const stepVec = (v) => ({ fxStep676d0: v, fxStep676d4: v, fxStep676d8: v, fxStep676dc: v, fxStep676e0: v, fxStep676e4: v });
  const goalVec = (v) => ({ fxGoal676e8: v, fxGoal676ec: v, fxGoal676f0: v, fxGoal676f4: v, fxGoal676f8: v, fxGoal676fc: v });

  /* -- approach (all six elements driven identically; read element 0) -- */
  const one = (c, g, s) => step(
    { fxLerpGate676b4: 1, fxCur676b8: c, fxCur676bc: c, fxCur676c0: c, fxCur676c4: c, fxCur676c8: c, fxCur676cc: c },
    { ...stepVec(s), ...goalVec(g) },
  ).state.fxCur676b8;
  /* snap: ordered step >= |cur-goal| -> cur = goal (PE jae) */
  assert.equal(one(5, 8, 10), 8);
  assert.equal(one(6, 2, 4), 2);
  /* step up: goal > cur and step < gap -> cur + step */
  assert.equal(one(5, 8, 2), 7);
  assert.equal(one(2, 6, 3), 5);
  /* step down: goal <= cur -> cur - step (jbe taken) */
  assert.equal(one(6, 2, 1), 5);
  assert.equal(one(6, 2, 3), 3);
  /* NaN semantics: unordered flows to jbe -> subtract */
  assert.ok(Number.isNaN(one(5, 8, Number.NaN)), "NaN step: c + NaN");
  assert.equal(one(5, Number.NaN, 1), 4, "NaN goal: ordered cur - step");
  assert.ok(Number.isNaN(one(Number.NaN, 8, 1)), "NaN cur: cur - step = NaN");

  /* gate-clear predicate (gate open, approach keeps cur == step) */
  const eq = step(
    { fxLerpGate676b4: 1, fxCur676b8: 3, fxCur676bc: 3, fxCur676c0: 3, fxCur676c4: 3, fxCur676c8: 3, fxCur676cc: 3 },
    { ...stepVec(3), ...goalVec(3) },
  );
  assert.equal(eq.state.fxLerpGate676b4, 0, "all six equal pairs clear the gate");

  /* one ordered-unequal pair keeps the gate */
  const keep = step(
    { fxLerpGate676b4: 1, fxCur676b8: 3, fxCur676bc: 9, fxCur676c0: 3, fxCur676c4: 3, fxCur676c8: 3, fxCur676cc: 3 },
    { ...stepVec(3), ...goalVec(3) },
  );
  assert.equal(keep.state.fxCur676bc, 6, "cur[1] steps toward goal before the gate test");
  assert.equal(keep.state.fxLerpGate676b4, 1, "ordered-unequal pair keeps the gate open");

  /* NaN pair KEEPS the gate: ucomiss unordered -> ZF+PF set -> ah&0x44 =
     0x44 (even parity) -> jp taken. Only exact equality falls through. */
  const nanPair = step(
    { fxLerpGate676b4: 1, fxCur676b8: Number.NaN, fxCur676bc: 3, fxCur676c0: 3, fxCur676c4: 3, fxCur676c8: 3, fxCur676cc: 3 },
    { ...stepVec(3), ...goalVec(3) },
  );
  assert.equal(nanPair.state.fxLerpGate676b4, 1, "NaN pair keeps the gate open (R=0x44, jp taken)");

  /* wide byte gate drive: 0x100 must narrow to 0 and skip the lane */
  const wide = step(
    { fxLerpGate676b4: 0x100, fxCur676b8: 5, fxCur676bc: 5, fxCur676c0: 5, fxCur676c4: 5, fxCur676c8: 5, fxCur676cc: 5 },
    { ...stepVec(1), ...goalVec(9) },
  );
  assert.equal(wide.state.fxLerpGate676b4, 0, "gate byte narrowed: 0x100 -> 0");
  assert.equal(wide.state.fxCur676b8, 5, "gate closed: lane must not run");

  /* role pin: PE moves cur toward goal by step (not toward step by goal) */
  const role = step(
    { fxLerpGate676b4: 1, fxCur676b8: 6, fxCur676bc: 6, fxCur676c0: 6, fxCur676c4: 6, fxCur676c8: 6, fxCur676cc: 6 },
    { ...stepVec(4), ...goalVec(2) },
  );
  assert.equal(role.state.fxCur676b8, 2, "snap to goal (step 4 >= |6-2|)");
});

test("ABI v65: VA 0x00746560 notify boundary is a typed pure event at both PE sites", () => {
  /* The 0x00746560 BODY stays host — it builds two std::strings (0x007460b0 /
     0x00746260 over the 0x70-stride Game+0x1a564 vector), may append the
     0x009586f0 lookup of .rdata 0xb6a82c "#Online/DEATHMATCH_NAME", and drives
     the Game+0x216e0 widget 0x00840b00 (string intern + ANM2 play). What v65
     translates is everything the PE decides before entering it, plus the one
     post-state store that lands in a tracked sparse field. */

  /* -- pure helper 1: 0x0074661f `xor al,1` on the pushed byte -- */
  assert.equal(hostFun746560NotifyByte(1), 0, "0x0098de41 push 1 -> stores 0");
  assert.equal(hostFun746560NotifyByte(0), 1, "0x006fb7d2 push 0 -> stores 1");
  /* Bit flip, NOT a logical negation: a !param reading would give 0 here. */
  assert.equal(hostFun746560NotifyByte(2), 3, "xor al,1 flips bit 0 only");
  assert.equal(hostFun746560NotifyByte(3), 2);
  /* Wide unmasked drives: mov al,[ebp+8] and mov [edi+9],cl are byte ops. */
  assert.equal(hostFun746560NotifyByte(0x100), 1, "0x100 -> al == 0 -> 1");
  assert.equal(hostFun746560NotifyByte(0x101), 0, "0x101 -> al == 1 -> 0");
  assert.equal(hostFun746560NotifyByte(0x1ff), 0xfe);
  assert.equal(hostFun746560NotifyByte(0xffffffff), 0xfe);
  for (const p of [0, 1, 2, 0xff, 0x100, 0x1ff, 0xffffffff]) {
    assert.ok(hostFun746560NotifyByte(p) <= 0xff, `notify byte stays a byte for ${p}`);
  }

  /* -- pure helper 2: 0x007465b0 cmp [Game+0x26614],2 / 0x007465b7 jl (SIGNED) -- */
  assert.equal(hostFun746560DeathmatchSuffix(2), 1, "jl not taken at exactly 2");
  assert.equal(hostFun746560DeathmatchSuffix(3), 1);
  assert.equal(hostFun746560DeathmatchSuffix(1), 0);
  assert.equal(hostFun746560DeathmatchSuffix(-1), 0, "signed: -1 < 2");
  assert.equal(hostFun746560DeathmatchSuffix(0xffffffff), 0, "unsigned read would say 1");
  assert.equal(hostFun746560DeathmatchSuffix(-0x80000000), 0);
  assert.equal(hostFun746560DeathmatchSuffix(0x7fffffff), 1);

  /* -- walk-counter site: PE 0x0098de38 inc / cmp 0xa / jne, then push 1 -- */
  const walk = (overrides, runtime) => {
    const base = state({ gate1b83c: 1, frameOpaque98dba0Mode: 0, ...overrides });
    const first = stepGameUpdateSlice(base, { transitionComplete: 1 }, runtime ?? {});
    assert.equal(first.events.continuationKind, UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK);
    return resumeGameUpdate98dba0PlayerWalk(first.state, runtime ?? {}, first.events);
  };

  const fires = walk(
    { frameOpaque98dba0Counter: 9, timedTransitionCleanupMode: 5, hudMessageFlag8: 0 },
    { frameOpaque98dba0Bvar2: 1, hostFun746560PostReady: 1 },
  );
  assert.equal(fires.events.opaqueCall00746560, 1, "counter 9 -> 10 emits");
  assert.equal(fires.events.hostFun746560Site, HOST_FUN_746560_SITE.WALK_COUNTER);
  assert.equal(fires.events.hostFun746560Param, 1, "0x0098de41 pushes 1");
  assert.equal(fires.events.hostFun746560Byte216e9, 0, "0x00840b9c stores 0");
  assert.equal(fires.events.hostFun746560DeathmatchSuffix, 1, "cleanupMode 5 >= 2");
  assert.equal(fires.state.hudMessageFlag8, 1, "0x00840bd7 sets Game+0x216e8");

  /* ready=0 is the 0x00840b61 test-ebx failure path: nothing is stored. */
  const notReady = walk(
    { frameOpaque98dba0Counter: 9, timedTransitionCleanupMode: 5, hudMessageFlag8: 0 },
    { frameOpaque98dba0Bvar2: 1, hostFun746560PostReady: 0 },
  );
  assert.equal(notReady.events.opaqueCall00746560, 1);
  assert.equal(notReady.events.hostFun746560Byte216e9, 0, "carrier still reports the byte");
  assert.equal(notReady.state.hudMessageFlag8, 0, "0x00840bdd assert path stores nothing");

  /* Exactly 10 — the PE cmp [edi+8],0xa / jne is an equality, not >=. */
  const past = walk(
    { frameOpaque98dba0Counter: 10, hudMessageFlag8: 0 },
    { frameOpaque98dba0Bvar2: 1, hostFun746560PostReady: 1 },
  );
  assert.equal(past.events.opaqueCall00746560, 0, "11 does not fire");
  assert.equal(past.events.hostFun746560Site, HOST_FUN_746560_SITE.NONE);
  assert.equal(past.state.hudMessageFlag8, 0);

  /* bl == 0 skips 0x0098de38 entirely (PE 0x0098de36 je). */
  const noWalk = walk(
    { frameOpaque98dba0Counter: 9, hudMessageFlag8: 0 },
    { frameOpaque98dba0Bvar2: 0, hostFun746560PostReady: 1 },
  );
  assert.equal(noWalk.events.opaqueCall00746560, 0);
  assert.equal(noWalk.state.frameOpaque98dba0Counter, 0, "mode-0 fallthrough zeroes it");
  assert.equal(noWalk.state.hudMessageFlag8, 0);

  /* Machine fact worth pinning: an emission and the 0x0098df47 text_out gate can
     never happen on the same invocation. 0x0098de34 test bl,bl / je needs
     bl != 0; every predecessor of 0x0098df47 (0x0098df43 jne, 0x0098e157 je,
     0x0098e06c, 0x0098e089) needs bl == 0, and nothing between them writes ebx. */
  assert.equal(fires.events.hudMessageTextOut, 0, "emission excludes the text_out gate");
  const gateOnly = walk(
    { frameOpaque98dba0Counter: 9, hudMessageFlag8: 1 },
    { frameOpaque98dba0Bvar2: 0, hostFun746560PostReady: 1, frameOpaque98dba0Game216e9: 0x100 },
  );
  assert.equal(gateOnly.events.opaqueCall00746560, 0, "no emission on the gate path");
  assert.equal(gateOnly.events.hudMessageTextOut, 1, "0x100 narrows to 0: gate open");

  /* -- terminal-cleanup site: PE 0x006fb7d2 push 0, guarded by 0x006fb7b8 jge -- */
  const cleanupRuntime = {
    globalRangeByteLength: 4,
    monotonicCounterLow: 0,
    monotonicCounterHigh: 0,
    monotonicBaselineLow: 0,
    monotonicBaselineHigh: 0,
    globalMenuGuard4b3ca: 1,
    globalMenuEnable2a3a5: 0,
  };
  const cleanup = (cleanupMode, runtime) => {
    const rt = { ...cleanupRuntime, ...runtime };
    const base = state({
      timedTransitionProgress: 0.05,
      transitionRate: 0.1,
      timedTransitionForceFinish: 1,
      timedTransitionCleanupMode: cleanupMode,
      hudMessageFlag8: 0,
    });
    const first = stepGameUpdateSlice(base, { transitionComplete: 1 }, rt);
    assert.equal(first.events.continuationKind, UPDATE_CONTINUATION.CONTINUE_AT_TIMED_TRANSITION);
    return continueGameUpdateTimedTransition(first.state, rt, first.events);
  };

  const cleaned = cleanup(1, { hostFun746560PostReady: 1 });
  assert.equal(cleaned.events.opaqueCall00746560, 1);
  assert.equal(cleaned.events.hostFun746560Site, HOST_FUN_746560_SITE.TIMED_CLEANUP);
  assert.equal(cleaned.events.hostFun746560Param, 0, "0x006fb7d2 pushes 0");
  assert.equal(cleaned.events.hostFun746560Byte216e9, 1, "0x00840b9c stores 1 here");
  assert.equal(
    cleaned.events.hostFun746560DeathmatchSuffix,
    0,
    "the caller gate 0x006fb7b8 jge forces cleanupMode < 2, so the callee jl always skips",
  );
  assert.equal(cleaned.state.hudMessageFlag8, 1);

  const cleanedLegacy = cleanup(-1, { hostFun746560PostReady: 0 });
  assert.equal(cleanedLegacy.events.opaqueCall00746560, 1);
  assert.equal(cleanedLegacy.events.hostFun746560DeathmatchSuffix, 0, "signed -1 < 2");
  assert.equal(cleanedLegacy.state.hudMessageFlag8, 0);

  /* cleanupMode >= 2 closes the caller gate: no emission, no carrier. */
  const gated = cleanup(2, { hostFun746560PostReady: 1 });
  assert.equal(gated.events.opaqueCall00746560, 0);
  assert.equal(gated.events.hostFun746560Site, HOST_FUN_746560_SITE.NONE);
  assert.equal(gated.state.hudMessageFlag8, 0);
});

/* ================= ABI v95: record idx 6 (0x00746560) string-build
   decision laws. All six are transcribed branch-by-branch from the
   instruction stream (cpu-dump/00746560.txt + 00746260.txt + 007460b0.txt);
   the string CONTENT builders (0x7460b0/0x746260 host tails, 0x745ca0) and
   the intern/ANM2 widget 0x840b00 stay typed-host. ================= */

test("ABI v95: 746560_string_data_ptr mirrors the cmovae SSO-vs-heap law (UNSIGNED cap >= 0x10)", () => {
  /* PE 0x74660c cmp [str2+0x14],0x10 / 0x746613 cmovae edx,[str2] and
     0x746617 / 0x74661b for str1: the widget 0x840b00 receives the HEAP
     pointer iff _Myres UNSIGNED >= 0x10, else the SSO inline buffer
     (lea'd base). The widget null-tests that pointer (0x840b2b je / fatal).
     Reference transcribed from the instruction stream. */
  const base = 0x1000, ptr = 0x9000;
  assert.equal(hostFun746560StringDataPtr(0, ptr, base), base, "cap 0 -> SSO");
  assert.equal(hostFun746560StringDataPtr(0xf, ptr, base), base, "cap 15 -> SSO (cmp jb)");
  assert.equal(hostFun746560StringDataPtr(0x10, ptr, base), ptr, "cap 16 -> heap (ae)");
  assert.equal(hostFun746560StringDataPtr(0x11, ptr, base), ptr);
  assert.equal(hostFun746560StringDataPtr(0xff, ptr, base), ptr);
  /* WIDE drives unmasked: mov/cmp/cmovae are full-dword ops — 0x100/0x1ff/
     0xffffffff are all >= 0x10. */
  assert.equal(hostFun746560StringDataPtr(0x100, ptr, base), ptr);
  assert.equal(hostFun746560StringDataPtr(0x1ff, ptr, base), ptr);
  assert.equal(hostFun746560StringDataPtr(0xffffffff, ptr, base), ptr);
  /* An unsigned read is REQUIRED: cap 0xfffffff0 as int32 is negative. */
  assert.equal(hostFun746560StringDataPtr(0xfffffff0, ptr, base), ptr, "unsigned compare");
});

test("ABI v95: 746560_string_found mirrors the cmp/setne _Mysize law (widget 4th arg)", () => {
  /* PE 0x7465fb cmp [ebp-0x1c],0 — string2._Mysize — / 0x746608 setne
     [ebp-0x48]: the widget's 4th argument is `_Mysize2 != 0`, stored to
     Game+0x216ea at 0x840b91. FULL-DWORD compare. */
  assert.equal(hostFun746560StringFound(0), 0);
  assert.equal(hostFun746560StringFound(1), 1);
  assert.equal(hostFun746560StringFound(0xff), 1);
  assert.equal(hostFun746560StringFound(0x100), 1, "full dword: 0x100 != 0");
  assert.equal(hostFun746560StringFound(0xffffffff), 1);
});

test("ABI v95: 746560_free_plan mirrors the _Tidy_deallocate length/capacity gates (0 NONE / 1 SMALL / 2 LARGE)", () => {
  /* PE 0x746632..0x7466a0 (string2; identical block for string1): the
     inlined MSVC string teardown —
       746635 cmp edx,0x10 / jb   : _Myres < 0x10        -> SSO, NO free
       74663d inc edx / 746640 cmp edx,0x1000 / jb      : _Myres+1 < 0x1000
                                                          -> small free
       746648 mov ecx,[ecx-4]     : _Alval = *(ptr-4)    (block header)
       746653 cmp eax,0x1f / ja   : ptr-_Alval-4 > 0x1f  -> operator delete
     All compares UNSIGNED; the large-arm size adds 0x23 and the 7466a0
     fall-through (`jbe` into the push pair) is the small free. */
  assert.equal(hostFun746560FreePlan(0xf, 0x9000, 0x8000), 0, "SSO: no free");
  assert.equal(hostFun746560FreePlan(0, 0x9000, 0x8000), 0);
  assert.equal(hostFun746560FreePlan(0x10, 0x9000, 0x8000), 1, "_Myres+1=0x11 < 0x1000");
  assert.equal(hostFun746560FreePlan(0xffe, 0x9000, 0x8000), 1, "_Myres+1=0xfff < 0x1000");
  assert.equal(hostFun746560FreePlan(0xfff, 0x9000, 0x8000), 2,
    "_Myres+1=0x1000 clears the jb; delta=0x9000-0x8000-4=0xffc > 0x1f -> delete");
  /* delta boundaries: ptr-bh-4 == 0x20 (above) -> LARGE; 0x1f (not above)
     -> SMALL; 0x1c -> SMALL. PE 0x746653 `cmp eax,0x1f / ja 0x74669a`. */
  assert.equal(hostFun746560FreePlan(0xfff, 0x9000, 0x8fdc), 2, "delta 0x20 > 0x1f");
  assert.equal(hostFun746560FreePlan(0xfff, 0x9000, 0x8fdd), 1, "delta 0x1f NOT above -> small");
  assert.equal(hostFun746560FreePlan(0xfff, 0x9000, 0x8fe0), 1, "delta 0x1c -> small");
  /* _Myres+1 is a u32 that WRAPS: 0xffffffff + 1 = 0 -> small free. */
  assert.equal(hostFun746560FreePlan(0xffffffff, 0x9000, 0x8000), 1, "wrap: size 0 < 0x1000");
  assert.equal(hostFun746560FreePlan(0x1ff, 0x9000, 0x8000), 1);
});

test("ABI v95: 746260_walk_count mirrors the signed magic-divide by 28 (0x92492493, sar 4)", () => {
  /* PE 0x7462e8..0x746304:
       7462e8 mov ecx,[Game+0x1a568]; 7462ee sub ecx,[Game+0x1a564]
       7462f4 imul ecx (M=0x92492493 SIGNED); 7462f6 add edx,ecx
       7462f8 sar edx,4; 7462fb mov eax,edx; 7462fd shr eax,31; 746300 add
     = trunc(span / 28); 746302 test / 746304 jle skips the whole walk on
     count <= 0 (SIGNED). Verified over 599,987 int32 spans. */
  assert.equal(gameUpdateSlice746260WalkCount(0, 0), 0);
  assert.equal(gameUpdateSlice746260WalkCount(0x1c, 0), 1, "28 / 28");
  assert.equal(gameUpdateSlice746260WalkCount(0x1b, 0), 0, "27 / 28 -> 0");
  assert.equal(gameUpdateSlice746260WalkCount(0x1d, 0), 1, "29 / 28 -> 1");
  assert.equal(gameUpdateSlice746260WalkCount(0x70, 0), 4, "112 / 28");
  assert.equal(gameUpdateSlice746260WalkCount(0x2000, 0x1000), Math.trunc(0x1000 / 28),
    "end-begin span 0x1000");
  /* Signedness: negative spans truncate toward zero and jle keeps <= 0 out. */
  assert.equal(gameUpdateSlice746260WalkCount(0, 0x1c), -1, "-28 / 28");
  assert.equal(gameUpdateSlice746260WalkCount(0, 0x70), -4);
  assert.equal(gameUpdateSlice746260WalkCount(0, 0x1b), 0, "-27 / 28 -> 0");
  assert.equal(gameUpdateSlice746260WalkCount(0x12345678, 0x12345600), Math.trunc(0x78 / 28));
  /* 32-bit wrap: end=4, begin=0xfffffffd -> span 7 (not a huge unsigned). */
  assert.equal(gameUpdateSlice746260WalkCount(4, 0xfffffffd), 0, "wrap span 7 -> 0");
  assert.equal(gameUpdateSlice746260WalkCount(0x80000000, 0), Math.trunc(-0x80000000 / 28),
    "INT_MIN span");
  assert.equal(gameUpdateSlice746260WalkCount(0x7fffffff, 0), Math.trunc(0x7fffffff / 28),
    "INT_MAX span");
  assert.equal(gameUpdateSlice746260WalkCount(0xffffffff, 0), 0, "0xffffffff as int32 is -1");
});

test("ABI v95: 746260_index_matches mirrors the shl/and/test per-index mask law (index & 31)", () => {
  /* PE 0x74633c..0x746344: `not edx` (clear), `shl eax,cl` with cl = index
     low 5 bits (1 << (index & 31)), `and`, `test edi,edx / jne` — the
     0x82c600 lookup branch fires iff acc & ~clear & mask != 0. */
  assert.equal(gameUpdateSlice746260IndexMatches(3, 1, 1), 1, "acc 0b11 & ~0b01 & 0b10");
  assert.equal(gameUpdateSlice746260IndexMatches(3, 1, 0), 0, "bit 0 cleared by ~clear");
  assert.equal(gameUpdateSlice746260IndexMatches(0, 0, 7), 0, "acc 0 -> never");
  assert.equal(gameUpdateSlice746260IndexMatches(0xffffffff, 0xffffffff, 3), 0, "clear all");
  assert.equal(gameUpdateSlice746260IndexMatches(0x80000000, 0, 31), 1, "bit 31 mask");
  assert.equal(gameUpdateSlice746260IndexMatches(0x80000000, 0, 32), 0,
    "index 32 -> &31 = 0 -> mask bit 0, acc bit 31 -> miss");
  assert.equal(gameUpdateSlice746260IndexMatches(0x80000000, 0, 33), 0);
  assert.equal(gameUpdateSlice746260IndexMatches(1, 0, 32), 1, "index 32 wraps to bit 0");
  assert.equal(gameUpdateSlice746260IndexMatches(2, 0, 0x21), 1, "index 0x21 -> &31 = 1");
  assert.equal(gameUpdateSlice746260IndexMatches(0xffffffff, 0, 0xffffffff), 1,
    "index 0xffffffff -> &31 = 31");
  assert.equal(gameUpdateSlice746260IndexMatches(0xfffffffe, 0, 0), 0, "bit 0 clear in acc");
});

test("ABI v95: 7460b0_gate_26584 mirrors the cmp [Game+0x26584],0x2c / jne FULL-DWORD choice gate", () => {
  /* PE 0x7460c8 cmp dword [esi+0x26584],0x2c / 0x7460d5 jne 0x74619d:
     the string-1 builder takes path A exactly when Game+0x26584 == 0x2c.
     FULL-DWORD equality — 0x12c must NOT match, 0x100 must NOT match. */
  assert.equal(gameUpdateSlice7460b0Gate26584(0x2c), 1);
  assert.equal(gameUpdateSlice7460b0Gate26584(0), 0);
  assert.equal(gameUpdateSlice7460b0Gate26584(0x2b), 0);
  assert.equal(gameUpdateSlice7460b0Gate26584(0x2d), 0);
  assert.equal(gameUpdateSlice7460b0Gate26584(0x12c), 0, "full dword: 0x12c != 0x2c");
  assert.equal(gameUpdateSlice7460b0Gate26584(0x100), 0);
  assert.equal(gameUpdateSlice7460b0Gate26584(0xffffffff), 0);
  assert.equal(gameUpdateSlice7460b0Gate26584(0x80000000), 0);
});

test("ABI v95: the shipped Wasm agrees with the oracle on all six string-law exports", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  const dp = pick("isaac_game_update_slice_746560_string_data_ptr");
  const fd = pick("isaac_game_update_slice_746560_string_found");
  const fp = pick("isaac_game_update_slice_746560_free_plan");
  const wc = pick("isaac_game_update_slice_746260_walk_count");
  const im = pick("isaac_game_update_slice_746260_index_matches");
  const g2 = pick("isaac_game_update_slice_7460b0_gate_26584");
  for (const cap of [0, 0xf, 0x10, 0x11, 0xff, 0x100, 0x1ff, 0xfffffff0, 0xffffffff]) {
    assert.equal(dp(cap | 0, 0x9000, 0x1000) >>> 0,
      hostFun746560StringDataPtr(cap, 0x9000, 0x1000) >>> 0,
      `wasm data_ptr cap 0x${(cap >>> 0).toString(16)}`);
  }
  for (const size of [0, 1, 0xff, 0x100, 0xffffffff]) {
    assert.equal(fd(size | 0) | 0, hostFun746560StringFound(size) | 0,
      `wasm found size ${size >>> 0}`);
  }
  for (const [cap, ptr, bh] of [
    [0xf, 0x9000, 0x8000], [0x10, 0x9000, 0x8000], [0xffe, 0x9000, 0x8000],
    [0xfff, 0x9000, 0x8000], [0xfff, 0x9000, 0x8fdc], [0xfff, 0x9000, 0x8fdd],
    [0xfff, 0x9000, 0x8fe0], [0x1ff, 0x9000, 0x8000], [0xffffffff, 0x9000, 0x8000],
  ]) {
    assert.equal(fp(cap | 0, ptr | 0, bh | 0) >>> 0,
      hostFun746560FreePlan(cap, ptr, bh) >>> 0,
      `wasm free_plan cap 0x${(cap >>> 0).toString(16)} ptr 0x${(ptr >>> 0).toString(16)} bh 0x${(bh >>> 0).toString(16)}`);
  }
  for (const [e, b] of [
    [0, 0], [0x1c, 0], [0x1b, 0], [0x70, 0], [0x2000, 0x1000], [0, 0x1c],
    [0, 0x70], [4, 0xfffffffd], [0x80000000, 0], [0x7fffffff, 0], [0xffffffff, 0],
  ]) {
    assert.equal(wc(e | 0, b | 0) | 0, gameUpdateSlice746260WalkCount(e, b) | 0,
      `wasm walk_count(${(e >>> 0).toString(16)}, ${(b >>> 0).toString(16)})`);
  }
  for (const [a, c, i] of [
    [3, 1, 1], [3, 1, 0], [0, 0, 7], [0xffffffff, 0xffffffff, 3], [0x80000000, 0, 31],
    [0x80000000, 0, 32], [0x80000000, 0, 33], [1, 0, 32], [2, 0, 0x21],
    [0xffffffff, 0, 0xffffffff], [0xfffffffe, 0, 0],
  ]) {
    assert.equal(im(a | 0, c | 0, i | 0) | 0, gameUpdateSlice746260IndexMatches(a, c, i) | 0,
      `wasm index_matches(${(a >>> 0).toString(16)}, ${(c >>> 0).toString(16)}, ${(i >>> 0).toString(16)})`);
  }
  for (const m of [0x2c, 0, 0x2b, 0x2d, 0x12c, 0x100, 0xffffffff, 0x80000000]) {
    assert.equal(g2(m | 0) | 0, gameUpdateSlice7460b0Gate26584(m) | 0,
      `wasm gate_26584 0x${(m >>> 0).toString(16)}`);
  }
});

/* ============ ABI v95: FirstCollectibleOwner 0x009be080 decision laws =====
   Fresh census (wave-18 unit update-v95-record0-fco): 67 insns, ret 0xc,
   3 E8 (GetCollectible 0x72fd10 + HasCollectible 0x7706e0 x2), 0 indirect,
   174 direct rel32 callers, exact ZHL `FirstCollectibleOwner(CollectibleType,
   RNG**, bool)`. arg2 RNG** [ebp+0xc] is NEVER READ (no CRT/genrand draw)
   -> no RNG typed-host; the sparse hud_stat_owner_byte capture stays. Byte
   gates are RAW uint32 (WIDE-driven: 0x100 / 0x1ff / 0xffffffff) and
   re-narrow in the body — the Wasm ABI does not narrow i32 args. */

test("ABI v95: FCO twin_flag mirrors the bool-3rd-arg + config twin-bit gate (0x9be0a7..0x9be0c6)", () => {
  /* PE: cmp byte [ebp+0x10],0 / je; test eax,eax / je; and eax,0x80000000
     / or eax,0 / je -> [esp+0x13]=1 else 0. */
  assert.equal(fcoTwinFlag(1, 0x100, FCO9BE080_TWIN_BIT), 1, "arg3 && config && twin bit");
  assert.equal(fcoTwinFlag(1, 0x100, 0), 0, "no twin bit -> no shared byte");
  assert.equal(fcoTwinFlag(1, 0x100, 0x80000000 | 0x100), 1, "bit 31 among other flags");
  assert.equal(fcoTwinFlag(1, 0, FCO9BE080_TWIN_BIT), 0, "config NULL -> 0x9be0af je");
  assert.equal(fcoTwinFlag(0, 0x100, FCO9BE080_TWIN_BIT), 0, "arg3==0 -> 0x9be0ab je");
  /* arg3 is a LOW-BYTE test: 0x100 has a zero low byte and must NOT set the
     shared byte; 0x1ff has a nonzero low byte and must. */
  assert.equal(fcoTwinFlag(0x100, 0x100, FCO9BE080_TWIN_BIT), 0, "WIDE 0x100: low byte 0");
  assert.equal(fcoTwinFlag(0x1ff, 0x100, FCO9BE080_TWIN_BIT), 1, "WIDE 0x1ff: low byte 1");
  assert.equal(fcoTwinFlag(0xffffffff, 0x100, FCO9BE080_TWIN_BIT), 1);
  assert.equal(fcoTwinFlag(0x100, 0x100, 0), 0);
  assert.equal(fcoTwinFlag(0x1ff, 0x100, 0x100), 0, "twin bit is bit 31 only");
  assert.equal(fcoTwinFlag(0, 0, 0), 0);
});

test("ABI v95: FCO walk gate laws are FULL-DWORD (list_empty 0x9be0ce / slot_checkable 0x9be0d9 / twin_check_needed 0x9be0ed+0x9be0f9)", () => {
  /* list_empty: mov esi,[this]; cmp esi,[this+4] / je not-found. FULL dword. */
  assert.equal(fcoListEmpty(0x1000, 0x1000), 1, "begin == end");
  assert.equal(fcoListEmpty(0x1000, 0x1004), 0, "one entry");
  assert.equal(fcoListEmpty(0, 0), 1);
  assert.equal(fcoListEmpty(0x1000, 0), 0, "wrap-distinct still not empty");
  /* slot_checkable: cmp dword [player+0x2c],0 / jne step. FULL dword —
     0x100 and 0xffffffff are NOT checkable. */
  assert.equal(fcoSlotCheckable(0), 1);
  assert.equal(fcoSlotCheckable(1), 0);
  assert.equal(fcoSlotCheckable(0x100), 0, "WIDE: full dword, not low byte");
  assert.equal(fcoSlotCheckable(0xffffffff), 0);
  assert.equal(fcoSlotCheckable(0x80000000), 0);
  /* twin_check_needed: shared BYTE test FIRST (0x9be0ed cmp byte
     [esp+0x13],al / je skip), then the twin ptr FULL-dword test
     (0x9be0f9 test ecx,ecx / je). */
  assert.equal(fcoTwinCheckNeeded(1, 0x9000), 1);
  assert.equal(fcoTwinCheckNeeded(0, 0x9000), 0, "shared 0 -> skip");
  assert.equal(fcoTwinCheckNeeded(1, 0), 0, "twin NULL -> skip");
  assert.equal(fcoTwinCheckNeeded(0x100, 0x9000), 0, "WIDE shared 0x100: low byte 0");
  assert.equal(fcoTwinCheckNeeded(0x1ff, 0x9000), 1, "WIDE shared 0x1ff: low byte 1");
  assert.equal(fcoTwinCheckNeeded(0x1ff, 0x100), 1, "twin ptr is full dword (0x100 is a twin)");
  assert.equal(fcoTwinCheckNeeded(0, 0), 0);
});

test("ABI v95: FCO has_collectible_hit is a LOW-BYTE test (0x9be0e9 / 0x9be105 test al,al)", () => {
  assert.equal(fcoHasCollectibleHit(0), 0);
  assert.equal(fcoHasCollectibleHit(1), 1);
  assert.equal(fcoHasCollectibleHit(0xff), 1);
  assert.equal(fcoHasCollectibleHit(0x100), 0, "WIDE 0x100: al == 0 -> miss");
  assert.equal(fcoHasCollectibleHit(0x1ff), 1, "WIDE 0x1ff: al != 0 -> hit");
  assert.equal(fcoHasCollectibleHit(0xffffffff), 1);
  assert.equal(fcoHasCollectibleHit(0x80000000), 0);
});

test("ABI v95: FCO walk_next/continue mirror the stride-4 wrap loop (0x9be10d / 0x9be110)", () => {
  assert.equal(fcoWalkNext(0x1000), 0x1004);
  assert.equal(fcoWalkNext(0), 4);
  assert.equal(fcoWalkNext(0xfffffffc), 0, "32-bit wrap: 0xfffffffc + 4 == 0");
  assert.equal(fcoWalkNext(0xffffffff), 3);
  assert.equal(fcoWalkContinue(0x1004, 0x1004), 0, "iter == end -> stop");
  assert.equal(fcoWalkContinue(0x1004, 0x1008), 1);
  assert.equal(fcoWalkContinue(0xfffffffc, 0xffffffff), 1, "wrap iter still != end");
  assert.equal(fcoWalkContinue(0, 0), 0);
  assert.equal(fcoWalkContinue(4, 0x100), 1);
});

test("ABI v95: FCO walk_owner composes the full decision (primary / twin / not-found + skip arms)", () => {
  /* PE walk 0x9be0ce..0x9be113: list begin/end; per entry [p+0x2c]==0 gate,
     HasCollectible primary low-byte hit -> player; else shared byte && twin
     ptr -> twin HasCollectible low-byte hit -> twin; iter += 4. Probes are
     5-word entries {player_ptr, f2c, has_primary, twin_ptr, has_twin}. */
  const P1 = 0xa100, P2 = 0xa200, TW = 0xb100;
  const probe = (...words) => words;
  /* (a) primary hit on entry 0 -> returns player 1. */
  assert.equal(
    fcoWalkOwner(1, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x100c,
      probe(P1, 0, 1, 0, 0), 3),
    P1,
  );
  /* (b) primary miss + twin hit -> returns the TWIN ptr (0x9be120 mov
     eax,[edi+0x1e6c]). */
  assert.equal(
    fcoWalkOwner(1, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x100c,
      probe(P1, 0, 0, TW, 1), 3),
    TW,
  );
  /* (c) entry gated by f2c != 0 is skipped; hit on entry 1 wins. */
  assert.equal(
    fcoWalkOwner(1, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x1010,
      probe(P1, 1, 1, 0, 0, P2, 0, 1, 0, 0), 2),
    P2,
  );
  /* (d) shared byte 0 (arg3 0 / config null / no twin bit) skips the twin
     probe even when the twin has the collectible -> not-found. */
  assert.equal(
    fcoWalkOwner(0, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x100c,
      probe(P1, 0, 0, TW, 1), 3),
    0,
    "arg3==0 -> no twin probe -> not-found",
  );
  assert.equal(
    fcoWalkOwner(1, 0x100, 0, 0x1000, 0x100c,
      probe(P1, 0, 0, TW, 1), 3),
    0,
    "no twin bit -> twin probe skipped",
  );
  /* (e) empty list -> not-found without touching probes. */
  assert.equal(fcoWalkOwner(1, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x1000,
    [], 0), 0);
  assert.equal(fcoWalkOwner(1, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x1000,
    probe(P1, 0, 1, 0, 0), 3), 0, "begin == end -> 0x9be0d3 je not-found");
  /* (f) no hit anywhere -> 0 (0x9be115 xor eax,eax). */
  assert.equal(
    fcoWalkOwner(1, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x1010,
      probe(P1, 0, 0, 0, 0, P2, 0, 0, 0, 0), 2),
    0,
  );
  /* (g) primary miss + twin present but twin miss -> not-found. */
  assert.equal(
    fcoWalkOwner(1, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x100c,
      probe(P1, 0, 0, TW, 0), 3),
    0,
  );
  /* (h) WIDE drive: low-byte semantics flow through the owner decision.
     NOTE (fresh census): arg3 gates ONLY the twin probe — the shared byte
     is compared at 0x9be0ed AFTER the primary hit returned (0x9be0eb), so
     a primary owner is returned even when arg3's low byte is 0. */
  assert.equal(
    fcoWalkOwner(0x100, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x100c,
      probe(P1, 0, 1, 0, 0), 3),
    P1,
    "arg3 low byte 0: primary hit still returns the player (0x9be0eb first)",
  );
  assert.equal(
    fcoWalkOwner(0x1ff, 0x100, FCO9BE080_TWIN_BIT, 0x1000, 0x100c,
      probe(P1, 0, 0, TW, 0x1ff), 3),
    TW,
    "has_twin 0x1ff low byte 1 -> twin owner",
  );
  assert.equal(
    fcoWalkOwner(1, 0x100, 0x100, 0x1000, 0x100c,
      probe(P1, 0, 0, TW, 1), 3),
    0,
    "flags 0x100: twin bit absent (bit 31) -> shared 0",
  );
});

