test("ABI v100 (record-0 walker body): walker_probe1_clamped mirrors the 0x84d199..0x84d1c2 probe chain", () => {
  /* The walker's probe chain (the seam twin 0x84cb5b..0x84cb7e is
     byte-identical): maxss(probe1, 0.0) THEN minss(x, 1.0) — NaN -> 0.0
     (maxss returns the SECOND operand on NaN) — then the probe2 BOOL
     LOW-BYTE gate @0x84d1bb (test al,al) zeroing the clamped value
     (xorps @0x84d1c2). Returns f32 bits. */
  const F = f32BitsOf;
  const OUT = f32BitsOf;
  assert.equal(hudStatWalkerProbe1Clamped(F(0.5), 1), OUT(0.5), "gate open keeps the clamp");
  assert.equal(hudStatWalkerProbe1Clamped(F(0.5), 0), OUT(0.0), "gate closed zeroes the clamp");
  assert.equal(hudStatWalkerProbe1Clamped(F(0.5), 0x100), OUT(0.0),
    "LOW-BYTE gate: 0x100 -> probe2_live 0 (full-dword mutant bait)");
  assert.equal(hudStatWalkerProbe1Clamped(F(0.5), 0x80), OUT(0.5), "0x80 low byte live -> kept");
  assert.equal(hudStatWalkerProbe1Clamped(F(0.5), 0xffffffff), OUT(0.5), "all-ones live -> kept");
  assert.equal(hudStatWalkerProbe1Clamped(F(1.5), 1), OUT(1.0), "minss upper clamp");
  assert.equal(hudStatWalkerProbe1Clamped(F(-0.5), 1), OUT(0.0), "maxss lower clamp");
  assert.equal(hudStatWalkerProbe1Clamped(0x7fc00000, 1), OUT(0.0), "NaN probe1 -> 0.0 (maxss second-op)");
  assert.equal(hudStatWalkerProbe1Clamped(F(0.75), 0xff), OUT(0.75), "0xff live keeps 0.75");
});

test("ABI v100 (record-0 walker body): walker_e8_call_order pins the 4 direct E8 leaves' call ordering", () => {
  /* The walker has EXACTLY 4 direct E8: 0x84d18e -> 0x7f92b0 (PROBE1),
     0x84d1b6 -> 0x749830 (PROBE2), 0x84d1c7 -> 0x7f96f0 (PROBE3), and
     0x84d66d -> 0x84ca00 (the RecomputeStats seam) — the seam is LAST
     of the four and runs only on the swap-back row arm. Else 0. */
  assert.equal(hudStatWalkerE8CallOrder(0), 0x7f92b0, "position 0 -> probe1 leaf");
  assert.equal(hudStatWalkerE8CallOrder(1), 0x749830, "position 1 -> probe2 leaf");
  assert.equal(hudStatWalkerE8CallOrder(2), 0x7f96f0, "position 2 -> probe3 leaf");
  assert.equal(hudStatWalkerE8CallOrder(3), 0x84ca00, "position 3 -> the seam 0x84ca00 (LAST)");
  assert.equal(hudStatWalkerE8CallOrder(4), 0, "position out of range -> no leaf");
  assert.equal(hudStatWalkerE8CallOrder(0xffffffff), 0, "position -1 -> no leaf");
  assert.equal(hudStatWalkerE8CallOrder(0x100), 0, "position 0x100 -> no leaf");
});

test("ABI v100 (record-0 walker body): the probe2-live gate zeroes the k6/k7 targets through the walk lane", () => {
  /* The k6/k7 block consumes hudStatWalkerProbe1Clamped: probe2_live ==
     0 (incl. WIDE 0x100 with a zero low byte) collapses BOTH targets to
     0.0 on BOTH owner arms; probe2_live != 0 keeps the seeded formulas. */
  const f = Math.fround;
  const run = (overrides) => walkRun(walkRuntimeInputs(overrides, [walkPassPack()]));
  /* Owner arm, default probes (probe1 0.01, probe3 1.0): k6 = k7 = 1.0. */
  assert.equal(run({ hudStatWalkProbe2: 0 }).slots[slotIdx(0, 6)].current, 0.0,
    "owner probe2 0: k6 target zeroed");
  assert.equal(run({ hudStatWalkProbe2: 0 }).slots[slotIdx(0, 7)].current, 0.0,
    "owner probe2 0: k7 target zeroed");
  assert.equal(run({ hudStatWalkProbe2: 0x100 }).slots[slotIdx(0, 7)].current, 0.0,
    "owner probe2 0x100: LOW-BYTE gate zeroes k7 too");
  assert.equal(run({ hudStatWalkProbe2: 1 }).slots[slotIdx(0, 6)].current, 1.0,
    "owner probe2 1: k6 unchanged (1.0)");
  assert.equal(run({ hudStatWalkProbe2: 1 }).slots[slotIdx(0, 7)].current, 1.0,
    "owner probe2 1: k7 unchanged (1.0)");
  /* Non-owner arm, probe3 0.5: k6 = k7 = 0.5 with the gate open. */
  const nonOwner = { hudStatOwnerByte: 0, hudStatWalkProbe3: f32BitsOf(0.5) };
  assert.equal(run({ ...nonOwner, hudStatWalkProbe2: 1 }).slots[slotIdx(0, 6)].current, f(0.5),
    "non-owner probe2 1: k6 = (1-probe3)*c*100");
  assert.equal(run({ ...nonOwner, hudStatWalkProbe2: 1 }).slots[slotIdx(0, 7)].current, f(0.5),
    "non-owner probe2 1: k7 = probe3*c*100");
  assert.equal(run({ ...nonOwner, hudStatWalkProbe2: 0 }).slots[slotIdx(0, 6)].current, 0.0,
    "non-owner probe2 0: k6 zeroed");
  assert.equal(run({ ...nonOwner, hudStatWalkProbe2: 0 }).slots[slotIdx(0, 7)].current, 0.0,
    "non-owner probe2 0: k7 zeroed");
});

