test("ABI v101 (record-0 walker islands): walker_row_arm mirrors the 0x84cc9d/0x84d659 swap-gate row-arm", () => {
  /* The swap-gate (0x84cc9d cmp eax,[ebx+8] / 0x84cca0 jne 0x84d659) and
     the swap-back check (0x84d659 cmp eax,edx / 0x84d65b jne 0x84d698)
     are FULL-DWORD compares of the row entry [StatHUD+i*0xcc+0x114]
     against the live swap args (A = arg1 = swap-out, B = arg2 = swap-in):
     entry==A -> arm 1 (swap-to-B + inline body), entry==B -> arm 2
     (swap-back + the 0x84d66d seam call), else 0. A is checked before B. */
  assert.equal(hudStatWalkerRowArm(0x1000, 0x1000, 0x2000), 1, "entry == A -> arm 1");
  assert.equal(hudStatWalkerRowArm(0x1000, 0x2000, 0x1000), 2, "entry == B -> arm 2");
  assert.equal(hudStatWalkerRowArm(0x1000, 0x2000, 0x3000), 0, "neither player -> skip arm");
  assert.equal(hudStatWalkerRowArm(0x1000, 0x1000, 0x1000), 1, "A == B == entry -> A arm first (PE check order)");
  assert.equal(hudStatWalkerRowArm(0, 0x1000, 0x2000), 0, "NULL entry with live A/B -> skip");
  assert.equal(hudStatWalkerRowArm(0x100, 0x101, 0x100), 2, "FULL-DWORD: 0x100 entry vs 0x101 A, 0x100 B -> arm 2");
  assert.equal(hudStatWalkerRowArm(0x100, 0x100, 0x101), 1, "FULL-DWORD: 0x100 entry vs 0x100 A -> arm 1");
  assert.equal(hudStatWalkerRowArm(0xffffffff, 0xffffffff, 0), 1, "entry -1 vs A -1 -> arm 1");
});

test("ABI v101 (record-0 walker islands): walker_reset_split re-derives the seam mode formula at the walker site", () => {
  /* PE 0x84ccc8 sub eax,[edx+0x328] / cmp eax,1 / jg 0x84ce1b: flag
     [ebp-1] = (i32[Game+0x264f8] - i32[B+0x328]) > 1 -> TWEEN(1) else
     RESET(0). SIGNED full-dword — the EXACT lawed seam head formula
     hudStatTailRecomputeMode composed (parity drives below). */
  assert.equal(hudStatWalkerResetSplit(0, 0), 0, "equal frames -> RESET");
  assert.equal(hudStatWalkerResetSplit(1, 0), 0, "diff 1 -> RESET (the cmp eax,1 / jg bound)");
  assert.equal(hudStatWalkerResetSplit(2, 0), 1, "diff 2 -> TWEEN");
  assert.equal(hudStatWalkerResetSplit(3, 1), 1, "diff 2 -> TWEEN");
  assert.equal(hudStatWalkerResetSplit(0, 0xffffffff), 0, "frame 0 vs B.f328 -1 -> diff 1 -> RESET");
  assert.equal(hudStatWalkerResetSplit(1, 0xffffffff), 1, "frame 1 vs B.f328 -1 -> diff 2 -> TWEEN");
  assert.equal(hudStatWalkerResetSplit(0, 0x80000000), 0,
    "B.f328 INT_MIN: negative diff -> RESET (an unsigned compare would return 1)");
  assert.equal(hudStatWalkerResetSplit(0x80000000, 0), 0, "frame INT_MIN vs 0 -> negative -> RESET");
  assert.equal(hudStatWalkerResetSplit(0x7fffffff, 0), 1, "huge positive diff -> TWEEN");
  assert.equal(hudStatWalkerResetSplit(0x80000000, 0x80000000), 0, "equal INT_MIN frames -> RESET");
  /* Parity with the seam law (the walker site is the SAME formula). */
  const pairs = [[0, 0], [2, 0], [0, 0x80000000], [0xffffffff, 0x7ffffffe],
    [5, 3], [0x80000001, 0x80000000], [1, 0xffffffff], [0x7fffffff, 0]];
  for (const [frame, bF328] of pairs) {
    assert.equal(hudStatWalkerResetSplit(frame, bF328), hudStatTailRecomputeMode(frame, bF328),
      `walker split == seam mode formula (${frame}, ${bF328})`);
  }
});

test("ABI v101 (record-0 walker islands): walker_swap_store pins the 0x84cca6/0x84d666 store semantics", () => {
  /* Arm 1 store (0x84cca6 mov [edi+esi+0x114],edx) = entry := B; arm 2
     store (0x84d666 mov [edi+esi+0x114],eax) = entry := A — executed
     BEFORE the 0x84d66d seam call; arm 0 = no store (entry passthrough).
     The arm-1 store runs before the FULL-DWORD B==0 bail (0x84ccb5 test
     edx,edx / je — a NULL B still leaves the row at NULL, self-healing). */
  assert.equal(hudStatWalkerSwapStore(1, 0x1000, 0x1000, 0x2000), 0x2000, "arm 1 -> entry := B");
  assert.equal(hudStatWalkerSwapStore(2, 0x2000, 0x1000, 0x2000), 0x1000, "arm 2 -> entry := A");
  assert.equal(hudStatWalkerSwapStore(0, 0x1000, 0x2000, 0x3000), 0x1000, "arm 0 -> entry untouched");
  assert.equal(hudStatWalkerSwapStore(3, 0x1000, 0x2000, 0x3000), 0x1000, "invalid arm -> entry untouched");
  assert.equal(hudStatWalkerSwapStore(0xffffffff, 0x1000, 0x2000, 0x3000), 0x1000, "arm -1 -> entry untouched");
  assert.equal(hudStatWalkerSwapStore(1, 0, 0x1000, 0x2000), 0x2000,
    "arm 1 with NULL entry still stores B (store precedes the B==0 bail)");
  assert.equal(hudStatWalkerSwapStore(2, 0x2000, 0, 0x2000), 0, "arm 2 store := A can be NULL (self-healing row)");
  assert.equal(hudStatWalkerSwapStore(1, 0x1000, 0x1000, 0), 0, "arm 1 store := B==0 leaves the row NULL");
});

test("ABI v101 (record-0 walker islands): walker_probe1_arg pins the FULL-DWORD 0x84d188 read", () => {
  /* PE 0x84d188 mov ecx,[eax+0x18300] — the probe1 ARG (the game ROOM
     ptr word; seam twin 0x84cb47, PM swap twin 0x9bf31f) is transferred
     WHOLE into ecx for leaf 0x7f92b0: no byte gate, no narrowing. */
  assert.equal(hudStatWalkerProbe1Arg(0), 0, "NULL room word -> 0");
  assert.equal(hudStatWalkerProbe1Arg(0x100), 0x100, "FULL-DWORD: 0x100 passes whole (byte-gate mutant bait)");
  assert.equal(hudStatWalkerProbe1Arg(0xffffffff), 0xffffffff, "-1 passes whole");
  assert.equal(hudStatWalkerProbe1Arg(0x12345678), 0x12345678, "arbitrary dword passes whole");
  assert.equal(hudStatWalkerProbe1Arg(0x7fc00000), 0x7fc00000, "NaN bits pass whole (no float reinterpret)");
  assert.equal(hudStatWalkerProbe1Arg(0x80000000), 0x80000000, "high bit passes whole");
});

