/* ============ ABI v102 (wave update-v102-record0-wire): the walker lanes
   go LIVE — the k6/k7 block consumes the committed lanes (player A/B,
   b_frame328, probe1_arg) at the PLAN offsets (runtime 14276..14292,
   events 956..968; the wave-26 merge owns the ABI bump + JSON rows). The
   laws stay pass-through on the SEAM outputs (v101 bit-identical); the
   walker-side descriptions go live in the typed walker probe events. */

function walkRunEvents(rt, stateOverrides = {}, events = {}) {
  const ev = {
    hudStatWalkerProbe1: 0, hudStatWalkerProbe2: 0, hudStatWalkerProbe3: 0,
    ...events,
  };
  const out = hudStatWalkRun(
    walkSeedScratch(rt), rt, { frameCounter264f8: 0, ...stateOverrides }, ev,
  );
  return { ev, out };
}

