test("ABI v102 (record-0 walker wire): drive A/B so row_arm returns 1 vs 2 — the swap store fires and the events CHANGE results", () => {
  const f = Math.fround;
  const bits = (v) => f32BitsOf(v);
  /* entry (row slot 0) == 0x1000 (walkPassPack Ptr). A = entry -> arm 1. */
  const r1 = walkRunEvents(walkRuntimeInputs({
    hudStatWalkerPlayerA: 0x1000, hudStatWalkerPlayerB: 0x2000,
  }, [walkPassPack()]), {}, {});
  assert.equal(r1.ev.hudStatWalkerProbe1, 1, "reached: +1 per walker k6/k7-arm entry");
  assert.equal(r1.ev.hudStatWalkerProbe2, 1, "entry==A -> swap-to-B arm 1");
  /* B = entry -> arm 2 (swap-back). */
  const r2 = walkRunEvents(walkRuntimeInputs({
    hudStatWalkerPlayerA: 0x2000, hudStatWalkerPlayerB: 0x1000,
  }, [walkPassPack()]), {}, {});
  assert.equal(r2.ev.hudStatWalkerProbe1, 1, "reached again");
  assert.equal(r2.ev.hudStatWalkerProbe2, 2, "entry==B -> swap-back arm 2");
  /* neither -> arm 0: the seam block still ran (probe1 reached), the
     arm value is 0 — the WALKER-side skip arm. */
  const r0 = walkRunEvents(walkRuntimeInputs({
    hudStatWalkerPlayerA: 0x3000, hudStatWalkerPlayerB: 0x4000,
  }, [walkPassPack()]), {}, {});
  assert.equal(r0.ev.hudStatWalkerProbe2, 0, "entry matches neither -> arm 0");
  /* A = entry with B == 0: a real swap captured A (live) while the
     swap-in slot is NULL — the capture-live gate is OR (any A/B live
     fires the walker descriptions; the walker's own B==0 bail is a
     ROW-level arm-1 store semantics, 0x84ccb5). This case
     discriminates the OR gate from an AND gate (a `&&` gate would
     swallow the whole walker-side description). */
  const rb0 = walkRunEvents(walkRuntimeInputs({
    hudStatWalkerPlayerA: 0x1000, hudStatWalkerPlayerB: 0,
  }, [walkPassPack()]), {}, {});
  assert.equal(rb0.ev.hudStatWalkerProbe1, 1, "A live, B NULL -> still reached (OR gate)");
  assert.equal(rb0.ev.hudStatWalkerProbe2, 1, "A live, B NULL -> arm 1 (entry==A checked first)");
  /* The SEAM outputs stay bit-identical across the arm drives (the
     v101 pass-through contract — the lane values do NOT change the
     seam outputs). */
  assert.equal(r1.out.slots[slotIdx(0, 6)].current, 1.0, "arm-1 drive: seam k6 unchanged");
  assert.equal(r2.out.slots[slotIdx(0, 6)].current, 1.0, "arm-2 drive: seam k6 unchanged");
  /* Probe-k6 event: owner arm -> clamped*100 (probe1 0.01, probe2 live
     1 -> clamped 0.01 -> f(1.0)); non-owner -> (1-probe3)*clamped*100. */
  assert.equal(r1.ev.hudStatWalkerProbe3, bits(1.0), "probe3 event = the walker k6 target bits (owner)");
  const rn = walkRunEvents(walkRuntimeInputs({
    hudStatOwnerByte: 0,
    hudStatWalkProbe3: bits(0.25),
    hudStatWalkerPlayerA: 0x1000, hudStatWalkerPlayerB: 0x2000,
  }, [walkPassPack()]), {}, {});
  assert.equal(rn.ev.hudStatWalkerProbe3, bits(f(f(f(1.0 - 0.25) * f(0.01 * 100.0)))),
    "probe3 event = the walker k6 target bits (non-owner (1-probe3)*c*100; 0.25 drive discriminates k6=f(0.75) from k7=f(0.25))");
});

test("ABI v102 (record-0 walker wire): b_frame328 drives the walker-site split through the live lane", () => {
  /* state.frameCounter264f8 = 0 (walkRun default). b_frame328 == frame-2
     (signed diff > 1) -> TWEEN(1) vs b_frame328 > frame -> RESET(0). The
     split result is a (void) description (no seam-output change); the
     lane must be READ (the 0 stand-in would never see the drive). */
  const run = (b328, stateOverrides) => walkRunEvents(walkRuntimeInputs({
      hudStatWalkerPlayerA: 0x1000, hudStatWalkerPlayerB: 0x2000,
      hudStatWalkerBFrame328: b328,
    }, [walkPassPack()]), stateOverrides, {}).ev;
  assert.equal(run(0).hudStatWalkerProbe2, 1, "arm stays live with the split drive");
  assert.equal(run(0x10000000, { frameCounter264f8: 0 }).hudStatWalkerProbe3, f32BitsOf(1.0),
    "b_frame328 > frame -> RESET arm: the k6 description still the owner formula");
  /* A zero-frame drive would be the v101 stand-in; the WIDE drive proves
     the lane reaches the law (SIGNED: b328 0x80000000 with frame 0 ->
     negative diff -> RESET — an unsigned read would TWEEN). */
  assert.equal(hudStatWalkerResetSplit(0, 0x80000000), 0, "law-level signed pin");
});

test("ABI v102 (record-0 walker wire): capture absent (lanes all-zero) keeps the residual byte-for-byte", () => {
  /* The shipped host captures no walker lanes -> lanes 0 -> the law calls
     consume the same 0u stand-ins as v101 and the typed events stay 0. */
  const r = walkRunEvents(walkRuntimeInputs({}, [walkPassPack()]), {}, {});
  assert.equal(r.ev.hudStatWalkerProbe1, 0, "no walker capture -> no reached event");
  assert.equal(r.ev.hudStatWalkerProbe2, 0, "no walker capture -> arm stays 0");
  assert.equal(r.ev.hudStatWalkerProbe3, 0, "no walker capture -> k6 stays 0");
  /* The v101 battery stays bit-identical (owner k6=k7=1.0). */
  assert.equal(r.out.slots[slotIdx(0, 6)].current, 1.0, "owner k6 unchanged (clamped*100)");
  assert.equal(r.out.slots[slotIdx(0, 7)].current, 1.0, "owner k7 unchanged (clamped*100)");
  const rn = walkRunEvents(walkRuntimeInputs({
    hudStatOwnerByte: 0, hudStatWalkProbe3: f32BitsOf(0.5),
  }, [walkPassPack()]), {}, {});
  assert.equal(rn.out.slots[slotIdx(0, 6)].current, Math.fround(0.5), "non-owner k6 unchanged");
  assert.equal(rn.out.slots[slotIdx(0, 7)].current, Math.fround(0.5), "non-owner k7 unchanged");
});

test("ABI v66: the FUN_0098dba0 timer block is gated on a SIGNED Game+0x264e8 > 0", () => {
  /* PE, from the instruction stream:
       0098de4a  8b871c060000       mov  eax, dword ptr [edi + 0x61c]
       0098de50  85c0               test eax, eax
       0098de52  0f8ec7000000       jle  0x98df1f
     edi = Game+0x25ecc so +0x61c is Game+0x264e8. `0f 8e` is JLE, the SIGNED
     jump. Through v65 the model emitted opaqueCall0098dba0Timer on EVERY
     resume, so the port raised a timer host event the original does not raise
     whenever the counter was <= 0 — the common path. This is a correctness
     fix, not just a boundary narrowing. */

  /* -- the pure gate itself -- */
  assert.equal(frameOpaque98dba0TimerBlockLive(1), 1, "jle is <= 0, so 1 runs the block");
  assert.equal(frameOpaque98dba0TimerBlockLive(0x1e), 1, "0x007401e4 stores 0x1e");
  assert.equal(frameOpaque98dba0TimerBlockLive(0x7fffffff), 1, "INT_MAX is positive");
  assert.equal(frameOpaque98dba0TimerBlockLive(0), 0, "test/jle skips at exactly 0");
  assert.equal(frameOpaque98dba0TimerBlockLive(-1), 0, "signed: -1 <= 0");
  /* The two values that separate `jle` from `jbe`. An unsigned model reads
     these as 2147483648 / 4294967295 and RUNS the block the PE skips. */
  assert.equal(frameOpaque98dba0TimerBlockLive(0x80000000), 0, "INT_MIN skips; unsigned would run");
  assert.equal(frameOpaque98dba0TimerBlockLive(0xffffffff), 0, "-1 as a raw dword skips");
  assert.equal(frameOpaque98dba0TimerBlockLive(-0x80000000), 0);
  /* Word-wide, not a low-byte test: 0x100 has a zero low byte but is > 0. */
  assert.equal(frameOpaque98dba0TimerBlockLive(0x100), 1, "full-dword test, not test al,al");

  /* -- the wire: emission is gated, and ready=0 is pre-v66 compatible -- */
  const walk = (overrides, runtime) => {
    const base = state({ gate1b83c: 1, frameOpaque98dba0Mode: 0, ...overrides });
    const first = stepGameUpdateSlice(base, { transitionComplete: 1 }, runtime ?? {});
    assert.equal(first.events.continuationKind, UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK);
    return resumeGameUpdate98dba0PlayerWalk(first.state, runtime ?? {}, first.events);
  };
  const at = (timer, extra) => walk(
    { frameOpaque98dba0Counter: 4 },
    {
      frameOpaque98dba0Bvar2: 0,
      frameOpaque98dba0Game216e9: 1,
      frameOpaque98dba0TimerReady: 1,
      frameOpaque98dba0Timer264e8: timer,
      ...extra,
    },
  );

  assert.equal(at(0).events.opaqueCall0098dba0Timer, 0, "timer 0: whole block skipped");
  assert.equal(at(1).events.opaqueCall0098dba0Timer, 1, "timer 1: block runs");
  assert.equal(at(0x1e).events.opaqueCall0098dba0Timer, 1);
  assert.equal(at(0x7fffffff).events.opaqueCall0098dba0Timer, 1);
  /* Driven UNMASKED across the boundary — the whole point of carrying the
     capture as a full u32 rather than pre-narrowing it. */
  assert.equal(at(0x80000000).events.opaqueCall0098dba0Timer, 0, "INT_MIN skips");
  assert.equal(at(0xffffffff).events.opaqueCall0098dba0Timer, 0, "0xffffffff skips");
  assert.equal(at(-3).events.opaqueCall0098dba0Timer, 0);

  /* ready = 0 is the pre-v66 wire with no capture: emit unconditionally, so a
     host that has not been taught to capture Game+0x264e8 keeps the old,
     conservative behaviour rather than silently dropping a real host edge. */
  assert.equal(
    at(0, { frameOpaque98dba0TimerReady: 0 }).events.opaqueCall0098dba0Timer,
    1,
    "ready=0 reproduces the pre-v66 unconditional emission exactly",
  );
  assert.equal(at(0x1e, { frameOpaque98dba0TimerReady: 0 }).events.opaqueCall0098dba0Timer, 1);

  /* The gate must not disturb anything else the resume does. The mode-0
     fallthrough still zeroes the walk counter and still runs the text_out gate
     (0x0098df54 reads Game+0x216e9), on BOTH arms of the new gate. */
  for (const timer of [0, 0x1e]) {
    const r = walk(
      { frameOpaque98dba0Counter: 4, hudMessageFlag8: 1 },
      {
        frameOpaque98dba0Bvar2: 0,
        frameOpaque98dba0Game216e9: 0,
        frameOpaque98dba0TimerReady: 1,
        frameOpaque98dba0Timer264e8: timer,
      },
    );
    assert.equal(r.state.frameOpaque98dba0Counter, 0, `counter still zeroed at timer ${timer}`);
    assert.equal(r.events.hudMessageTextOut, 1, `text_out gate unaffected at timer ${timer}`);
  }

  /* The timer gate and the 0x00746560 walk-counter emission are independent:
     the counter tail is decided at 0x0098de34 (bl != 0), strictly before the
     timer read at 0x0098de4a, and nothing in between writes the counter. */
  const both = walk(
    { frameOpaque98dba0Counter: 9, timedTransitionCleanupMode: 0 },
    {
      frameOpaque98dba0Bvar2: 1,
      frameOpaque98dba0TimerReady: 1,
      frameOpaque98dba0Timer264e8: 0,
      hostFun746560PostReady: 1,
    },
  );
  assert.equal(both.events.opaqueCall00746560, 1, "counter 9 -> 10 still emits");
  assert.equal(both.events.opaqueCall0098dba0Timer, 0, "and the timer block is still skipped");
});

test("ABI v66: the timer gate is declared, exported and specified", () => {
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const build = readFileSync(join(root, "scripts", "decomp", "build-game-update-slice.mjs"), "utf8");
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  const name = "isaac_game_update_slice_98dba0_timer_block_live";
  assert.ok(header.includes(name), `${name} declared`);
  assert.ok(source.includes(name), `${name} defined`);
  assert.ok(build.includes(`_${name}`), `${name} exported from the Wasm build`);
  /* No uint8_t scalar parameters may reach the Wasm boundary. */
  assert.doesNotMatch(header, /98dba0_timer_block_live\(\s*uint8_t/);
  assert.match(header, /frame_opaque_98dba0_timer_ready/);
  assert.match(header, /frame_opaque_98dba0_timer_264e8/);
  assert.match(
    source,
    /static_assert\(offsetof\(IsaacGameUpdateSliceRuntimeInputs, frame_opaque_98dba0_timer_ready\) == 2148/,
  );
  assert.match(
    source,
    /static_assert\(offsetof\(IsaacGameUpdateSliceRuntimeInputs, frame_opaque_98dba0_timer_264e8\) == 2152/,
  );
  assert.match(source, /static_assert\(sizeof\(IsaacGameUpdateSliceRuntimeInputs\) == 23696/);
  assert.ok(
    spec.runtimeInputs.some((i) => i.name.includes("frameOpaque98dba0TimerReady")),
    "spec records the new runtime input",
  );
  const helper = spec.translatedHelpers.find((h) => h.targetVa === "0x0098de4a");
  assert.ok(helper, "spec records the timer-block gate helper");
  assert.match(helper.proof, /complete no-op/);
  /* The boundary is NARROWED, not removed: the draw + trig primitives are
     still host-owned even on the pure arm. */
  const boundary = spec.opaqueBoundaries.find((b) => b.targetVa === "0x0098dba0");
  assert.ok(boundary, "0x0098dba0 stays an opaque boundary");
  assert.match(boundary.evidence, /NOT removed/);
  assert.equal(spec.opaqueBoundaries.length, 24, "count 26 -> 25 (record idx 27 roomTriggerClearAudio REMOVED at ABI v138, update-v138-audio-alt-tail-pack); count 27 -> 26 (record idx 26 roomTriggerClearAudioNonGreed REMOVED at ABI v136, update-v136-audio-head-pack); count 32 -> 31 (record idx 45 REMOVED at v128, 18th removal since v79); count 33 -> 32 (record idx 38 REMOVED at v127, 17th removal since v79); count 34 -> 33 (record idx 40 REMOVED at v126, 16th removal since v79); count 35 -> 34 (record idx 25 REMOVED at v125, 15th removal since v79); count 36 -> 35 (record idx 46 REMOVED at v124, 14th removal since v79); v122 removed record idx 19 opaqueCall006fd7c0Mode4Sfx (37 -> 36); v121 removed record idx 47 playerManagerUpdateHeartbeatSfxStop (38 -> 37); v120 removed record idx 41 opaqueRoomUpdateTailEntity (39 -> 38); v119 removed records idx 24 opaqueRoomUpdateClearDoorSlots + idx 33 opaqueRoomUpdateClearDoors (41 -> 39); v115 removed record idx 23 opaqueRoomUpdateClearPath (42 -> 41); v114 removed record idx 42 opaqueRoomUpdateTailPath (43 -> 42); v110 removed record idx 16 opaqueRoomUpdatePrefixB8 (44 -> 43); v109 removed record idx 12 opaqueCall006fd7c0 (45 -> 44); v108 removed record idx 39 opaqueRoomUpdateTailMidRestock (46 -> 45); v100 removed record idx 1 opaqueCall0092e300 (47 -> 46); v99 removed record idx 10 opaqueCall004212c0 (48 -> 47); v98 removed record 22 opaqueRoomTransitionEnginePrefix (49 -> 48); v79 removed record 2 opaqueGlobal4aba0Refresh (50 -> 49); v76 removed record 34 (52 -> 51); frame-opaque ABI 31 removed record 49 listUpdate6772cFree (51 -> 50)");
});

/* ---- ABI v70: FUN_0098dba0 timer-interior wire (0x0098de58..0x0098df1e) ---- */

/* Local bit helpers for expectations. Hand-pinned values below are derived on
   paper from IEEE-754 semantics, NOT by running either implementation. */
function timerBitsOfF64(value) {
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, value, true);
  return { lo: view.getUint32(0, true), hi: view.getUint32(4, true) };
}

/* Module-scope copy of the step -> RESUME_AFTER_98DBA0_PLAYER_WALK driver that
   the v65 and v66 tests each define locally (identical bodies at the `const
   walk` inside those two test callbacks). timerPureWalk below is at module
   scope and referenced a bare `walk`, which resolves to nothing here — every
   v70 behavioural test threw ReferenceError before reaching its first
   assertion. Hoisting the same construction is the whole repair; no
   expectation is touched. */
function walk98dba0PlayerWalk(overrides, runtime) {
  const base = state({ gate1b83c: 1, frameOpaque98dba0Mode: 0, ...overrides });
  const first = stepGameUpdateSlice(base, { transitionComplete: 1 }, runtime ?? {});
  assert.equal(first.events.continuationKind, UPDATE_CONTINUATION.RESUME_AFTER_98DBA0_PLAYER_WALK);
  return resumeGameUpdate98dba0PlayerWalk(first.state, runtime ?? {}, first.events);
}

function timerPureWalk(timer, extra = {}) {
  const cos = timerBitsOfF64(1.0);
  const sin = timerBitsOfF64(-0.5);
  return walk98dba0PlayerWalk(
    { frameOpaque98dba0Counter: 4 },
    {
      frameOpaque98dba0Bvar2: 0,
      frameOpaque98dba0Game216e9: 1,
      frameOpaque98dba0TimerReady: 1,
      frameOpaque98dba0Timer264e8: timer,
      frameOpaque98dba0TimerPureReady: 1,
      frameOpaque98dba0TimerSample: 0x80000000,
      frameOpaque98dba0TimerUseCrtRand: 0,
      frameOpaque98dba0TimerX264ecBits: 0x3f800000, /* 1.0f */
      frameOpaque98dba0TimerY264f0Bits: 0xc0400000, /* -3.0f */
      frameOpaque98dba0TimerCosBitsLo: cos.lo,
      frameOpaque98dba0TimerCosBitsHi: cos.hi,
      frameOpaque98dba0TimerSinBitsLo: sin.lo,
      frameOpaque98dba0TimerSinBitsHi: sin.hi,
      ...extra,
    },
  );
}

test("ABI v70: the pure arm drops the timer host edge and publishes the exact float-store plan", () => {
  /* timer 0x1e (the ChangeRoom store): timerAfter = 0x1d = 29, mag = 29/10
     = 2.9f = 0x4039999a (nearest f32 to 2.9 — hand-derived: 2.9 in binary is
     1.0111001100... x 2^1; the 24th significand bit rounds up to ...99A).
     sample 0x80000000: (double)u32 = 2^31 exactly, x 2^-32f = 0.5 exactly,
     x 3.14f = exact halving (1.57f = 0x3fc8f5c3), doubled exactly back to
     0x4048f5c3 — theta IS the 3.14f constant, pinning the +2^32 fixup.
     cos supplied as exact 1.0 -> 1.0f; sin as exact -0.5 -> -0.5f.
     x' = fround(1.0f*2.9f) + fround(1.0f*0.5f) = 2.9f + 0.5f = 3.4f
        = 0x4059999a (3.4 rounds the same tail pattern up);
     y' = fround(-0.5f*2.9f) + fround(-3.0f*0.5f) = -1.45f + -1.5f = -2.95f
        = 0xc03ccccd (2.95 = 1.0111100110011... x 2^1, rounds up).
     All three of those f32 roundings were computed by hand from the binary
     expansions, not by calling the helpers. */
  const pure = timerPureWalk(0x1e);
  assert.equal(pure.events.opaqueCall0098dba0Timer, 0, "pure arm drops the host edge");
  assert.equal(pure.events.frameOpaque98dba0TimerPlanApplied, 1);
  assert.equal(pure.events.frameOpaque98dba0TimerMtAdvanced, 1, "useCrtRand 0 advances MT");
  assert.equal(pure.events.frameOpaque98dba0TimerAfter, 0x1d, "dec at 0x0098de58");
  assert.equal(pure.events.frameOpaque98dba0TimerThetaBits >>> 0, 0x4048f5c3,
    "theta(0x80000000) is exactly the 3.14f constant");
  assert.equal(pure.events.frameOpaque98dba0TimerXBits >>> 0, 0x4059999a,
    "x' = cos*mag + old*0.5 = 3.4f (cos lane feeds the 0x0098df0f store)");
  assert.equal(pure.events.frameOpaque98dba0TimerYBits >>> 0, 0xc03ccccd,
    "y' = sin*mag + old*0.5 = -2.95f (sin lane feeds the 0x0098df17 store)");

  /* Sanity on the rest of the resume: the pure arm must not disturb the
     counter tail or the text_out gate. */
  assert.equal(pure.state.frameOpaque98dba0Counter, 0);
});

test("ABI v70: theta per-instruction rounding — the cvtpd2ps tie and its neighbour", () => {
  /* sample 0xffffffff: cvtpd2ps(2^32-1) rounds UP (ulp = 256 there), the unit
     hits exactly 1.0f, theta = 2*3.14f = 0x40c8f5c3. sample 0xffffff7f: one
     below the round-to-even tie — 0x4f7fffff, unit (2^24-1)*2^-24, and the
     3.14f product rounds DOWN once, so theta = 0x40c8f5c2, one ULP under.
     A model that skips the intermediate f32 rounding (keeps the double
     through the pi multiply) lands on 0x40c8f5c1 for the second sample and
     fails here — this is the per-operation Math.fround discipline pin. */
  const top = timerPureWalk(2, { frameOpaque98dba0TimerSample: 0xffffffff });
  assert.equal(top.events.frameOpaque98dba0TimerThetaBits >>> 0, 0x40c8f5c3);
  const tie = timerPureWalk(2, { frameOpaque98dba0TimerSample: 0xffffff80 });
  assert.equal(tie.events.frameOpaque98dba0TimerThetaBits >>> 0, 0x40c8f5c3,
    "0xffffff80 is the round-to-even tie and lands on 2^32");
  const below = timerPureWalk(2, { frameOpaque98dba0TimerSample: 0xffffff7f });
  assert.equal(below.events.frameOpaque98dba0TimerThetaBits >>> 0, 0x40c8f5c2,
    "one ULP below — per-instruction f32 rounding is observable here");
});

test("ABI v70: useCrtRand is a LOW-BYTE gate and the CRT arm reports mt not advanced", () => {
  /* Byte 1: the PE's 0x006eef91 branch falls through to CRT rand() and the
     0x006eefa9 early return never touches mt[] — mtAdvanced must be 0 and the
     float plan must be identical in shape. */
  const crt = timerPureWalk(0x1e, { frameOpaque98dba0TimerUseCrtRand: 1 });
  assert.equal(crt.events.opaqueCall0098dba0Timer, 0, "CRT arm still drops the edge");
  assert.equal(crt.events.frameOpaque98dba0TimerPlanApplied, 1);
  assert.equal(crt.events.frameOpaque98dba0TimerMtAdvanced, 0, "mt[] NOT advanced");
  assert.equal(crt.events.frameOpaque98dba0TimerXBits >>> 0, 0x4059999a,
    "the float plan does not depend on the sample's source");

  /* Wide capture 0x100: `cmp byte ptr [0xc7ac68],0` reads the LOW BYTE only,
     so 0x100 is zero there and the MT stream DID advance. A full-word model
     inverts this. Driven unmasked end-to-end. */
  const wide = timerPureWalk(0x1e, { frameOpaque98dba0TimerUseCrtRand: 0x100 });
  assert.equal(wide.events.frameOpaque98dba0TimerMtAdvanced, 1, "0x100 low byte is 0");
  const wideHigh = timerPureWalk(0x1e, { frameOpaque98dba0TimerUseCrtRand: 0xffffff00 });
  assert.equal(wideHigh.events.frameOpaque98dba0TimerMtAdvanced, 1);
  const wideSet = timerPureWalk(0x1e, { frameOpaque98dba0TimerUseCrtRand: 0x1ff });
  assert.equal(wideSet.events.frameOpaque98dba0TimerMtAdvanced, 0, "0x1ff low byte is 0xff");
});

test("ABI v70: the last shake tick halves the offsets (timer 1 -> mag +0.0f)", () => {
  /* timerAfter = 0, cvtdq2ps 0 = +0.0f, /10 = +0.0f. Each lane collapses to
     fround(trig*+0) + fround(old*0.5f): x' = +0 + 0.5f = 0.5f (0x3f000000),
     y' = (-0.5*+0 = -0.0f) + (-1.5f) = -1.5f (0xbfc00000) — the signed-zero
     product does not disturb the sum. */
  const last = timerPureWalk(1);
  assert.equal(last.events.frameOpaque98dba0TimerAfter, 0);
  assert.equal(last.events.frameOpaque98dba0TimerXBits >>> 0, 0x3f000000);
  assert.equal(last.events.frameOpaque98dba0TimerYBits >>> 0, 0xbfc00000);
});

test("ABI v70: NaN old-x propagates through the recursive accumulate as canonical NaN", () => {
  const nan = timerPureWalk(5, { frameOpaque98dba0TimerX264ecBits: 0x7fc00000 });
  assert.equal(nan.events.frameOpaque98dba0TimerXBits >>> 0, 0x7fc00000,
    "NaN*0.5f + finite = NaN (canonical in, canonical out on both sides)");
  assert.notEqual(nan.events.frameOpaque98dba0TimerYBits >>> 0, 0x7fc00000,
    "the y lane is untouched by the x lane's NaN");
});

test("ABI v70: the pure plan never runs on the skip arm or without the gate capture", () => {
  /* Skip arm: the jle wins regardless of pureReady — no edge, no plan. */
  for (const timer of [0, 0x80000000, 0xffffffff]) {
    const skip = timerPureWalk(timer);
    assert.equal(skip.events.opaqueCall0098dba0Timer, 0, `timer 0x${(timer >>> 0).toString(16)} skips`);
    assert.equal(skip.events.frameOpaque98dba0TimerPlanApplied, 0, "no plan on the skip arm");
    assert.equal(skip.events.frameOpaque98dba0TimerThetaBits, 0);
    assert.equal(skip.events.frameOpaque98dba0TimerXBits, 0);
  }
  /* ready = 0: the pre-v66 unconditional emission wins — pureReady without
     the timer capture has nothing sound to decrement. */
  const legacy = timerPureWalk(0x1e, { frameOpaque98dba0TimerReady: 0 });
  assert.equal(legacy.events.opaqueCall0098dba0Timer, 1, "legacy arm keeps the edge");
  assert.equal(legacy.events.frameOpaque98dba0TimerPlanApplied, 0, "and never plans");
  /* Live arm with pureReady = 0 is the v66..v69 behaviour byte-for-byte. */
  const host = timerPureWalk(0x1e, { frameOpaque98dba0TimerPureReady: 0 });
  assert.equal(host.events.opaqueCall0098dba0Timer, 1, "live host arm keeps the edge");
  assert.equal(host.events.frameOpaque98dba0TimerPlanApplied, 0);
});

test("ABI v70: the four interior helpers are declared, exported, and free of uint8_t params", () => {
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const build = readFileSync(join(root, "scripts", "decomp", "build-game-update-slice.mjs"), "utf8");
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  for (const name of [
    "isaac_game_update_slice_98dba0_timer_theta_bits",
    "isaac_game_update_slice_98dba0_timer_mag_bits",
    "isaac_game_update_slice_98dba0_timer_trig_narrow_bits",
    "isaac_game_update_slice_98dba0_timer_axis_bits",
  ]) {
    assert.ok(header.includes(name), `${name} declared`);
    assert.ok(source.includes(name), `${name} defined`);
    assert.ok(build.includes(`_${name}`), `${name} exported from the Wasm build`);
  }
  /* Multi-line-aware uint8_t guard: no scalar uint8_t parameter may appear in
     any declaration or definition of the four helpers, even when the
     parameter list wraps across lines. (A single-line grep missed 6 by-value
     8-bit params elsewhere in this repo — scan the joined text.) */
  const joined = (header + source).replace(/\s+/g, " ");
  for (const stem of [
    "98dba0_timer_theta_bits", "98dba0_timer_mag_bits",
    "98dba0_timer_trig_narrow_bits", "98dba0_timer_axis_bits",
  ]) {
    const uses = joined.split(stem).slice(1);
    for (const tail of uses) {
      const params = tail.slice(0, tail.indexOf(")") + 1);
      assert.doesNotMatch(params, /uint8_t|int8_t/, `${stem} must not take 8-bit scalars`);
    }
  }
  /* The spec must carry the nine captures and the plan carriers. */
  for (const name of [
    "frameOpaque98dba0TimerPureReady", "frameOpaque98dba0TimerSample",
    "frameOpaque98dba0TimerUseCrtRand", "frameOpaque98dba0TimerX264ecBits",
    "frameOpaque98dba0TimerY264f0Bits", "frameOpaque98dba0TimerCosBitsLo",
    "frameOpaque98dba0TimerCosBitsHi", "frameOpaque98dba0TimerSinBitsLo",
    "frameOpaque98dba0TimerSinBitsHi",
  ]) {
    assert.ok(spec.runtimeInputs.some((i) => i.name === name), `spec records ${name}`);
  }
  const interior = spec.translatedHelpers.find((h) => h.targetVa === "0x0098de58");
  assert.ok(interior, "spec records the timer-interior translation");
  assert.match(interior.proof, /cvtpd2ps/);
  assert.match(interior.proof, /_libm_sse2_cos_precise/);
});

/* ---- ABI v76: FUN_0098dba0 timer-interior MT19937 wire (record 34 removed) ----
 *
 * The draw the PE performs at 0x0098de79 (call 0x6eef60) is now computed
 * IN-MODULE from the Room family's recovered law when the host vouches for a
 * THIS-boundary mt[624]+mti capture (frameOpaque98dba0TimerMtReady) and the
 * useCrtRand low byte is clear. The model must draw on a LOCAL COPY (never
 * mutate the shared genrandState — the H5 boundary capture later in the same
 * tick is an independent host observation), publish the new index, and leave
 * every fallback arm byte-for-byte (mtReady=0 keeps the v70 host-drawn plan;
 * a set low byte keeps it too). These pins are the behavioral half of the
 * boundary removal; the corpus half lives in verify-game-update-slice.mjs. */

/* The canonical MT19937 stream (seed 5489, mt19937ar.c init_genrand): its
   FIRST output is the published 0xd091bb5c. The PE's 625 cold path seeds
   5489 then reloads, so a single draw must yield exactly that word and
   indexOut = 1 — a fully independent, hand-pinned anchor for the in-module
   draw's seed+twist+temper chain. */
const mtFirst = 0xd091bb5c;

function timerMtWalk(timer, runtimeExtra) {
  return timerPureWalk(timer, runtimeExtra);
}

test("ABI v76: mt-ready arm draws IN-MODULE from the room law and publishes the post-state index", () => {
  const state0 = new Uint32Array(624);
  /* A filled-but-not-canonical state: emit at index 100 (plain emit arm). */
  for (let i = 0; i < 624; i += 1) state0[i] = (0x1234 + i * 0x9e37) >>> 0;
  const pre = Uint32Array.from(state0);
  const runtime = {
    frameOpaque98dba0TimerReady: 1,
    frameOpaque98dba0Timer264e8: 0x1e,
    frameOpaque98dba0TimerPureReady: 1,
    /* mtReady=1 means the host vouched for the capture; the sample must be
       IGNORED on this arm — set it to something that would produce a
       DIFFERENT theta if a side consulted it instead of drawing. */
    frameOpaque98dba0TimerSample: 0xdeadbeef,
    frameOpaque98dba0TimerUseCrtRand: 0,
    frameOpaque98dba0TimerMtReady: 1,
    frameOpaque98dba0TimerMtiIn: 100,
    genrandState: state0,
  };
  const out = timerMtWalk(0x1e, runtime);
  /* The oracle draw on a COPY: the shared array must be untouched. */
  const step = roomGenrandNext(Uint32Array.from(pre), 100);
  assert.deepEqual(Array.from(state0), Array.from(pre),
    "the model must draw on a local copy — the shared capture stays unchanged");
  assert.equal(out.events.opaqueCall0098dba0Timer, 0, "still pure: host edge dropped");
  assert.equal(out.events.frameOpaque98dba0TimerPlanApplied, 1);
  assert.equal(out.events.frameOpaque98dba0TimerMtAdvanced, 1);
  assert.equal(out.events.frameOpaque98dba0TimerMtIndexOut, step.indexOut,
    "the events carry the post-draw index the host applies to 0x00C34F04");
  assert.equal(out.events.frameOpaque98dba0TimerThetaBits >>> 0,
    frameOpaque98dba0TimerThetaBits(step.value >>> 0), "theta must be the DRAWN sample's, not 0xdeadbeef's");
});

test("ABI v76: cold-625 and strict-624 reload arms draw the canonical stream", () => {
  /* 625 = 0x271: the PE seeds with 5489 and reloads, so the draw is the first
     word of the canonical stream and indexOut = 1. */
  const cold = timerMtWalk(0x1e, {
    frameOpaque98dba0TimerReady: 1,
    frameOpaque98dba0Timer264e8: 0x1e,
    frameOpaque98dba0TimerPureReady: 1,
    frameOpaque98dba0TimerSample: 0xdeadbeef,
    frameOpaque98dba0TimerUseCrtRand: 0,
    frameOpaque98dba0TimerMtReady: 1,
    frameOpaque98dba0TimerMtiIn: 625,
    genrandState: new Uint32Array(624),
  });
  assert.equal(cold.events.frameOpaque98dba0TimerMtIndexOut, 1);
  assert.equal(cold.events.frameOpaque98dba0TimerThetaBits >>> 0, frameOpaque98dba0TimerThetaBits(mtFirst),
    "cold-625 draw is the canonical seed stream's first word");
  /* 624: strict twist WITHOUT the seed branch — same first-word value. */
  const filled = new Uint32Array(624);
  for (let i = 0; i < 624; i += 1) filled[i] = (0x5eed + i * 0x01a5) >>> 0;
  const twist = timerMtWalk(0x1e, {
    frameOpaque98dba0TimerReady: 1,
    frameOpaque98dba0Timer264e8: 0x1e,
    frameOpaque98dba0TimerPureReady: 1,
    frameOpaque98dba0TimerSample: 0xdeadbeef,
    frameOpaque98dba0TimerUseCrtRand: 0,
    frameOpaque98dba0TimerMtReady: 1,
    frameOpaque98dba0TimerMtiIn: 624,
    genrandState: filled,
  });
  const twistStep = roomGenrandNext(Uint32Array.from(filled), 624);
  assert.equal(twist.events.frameOpaque98dba0TimerMtIndexOut, twistStep.indexOut);
  assert.equal(twist.events.frameOpaque98dba0TimerThetaBits >>> 0,
    frameOpaque98dba0TimerThetaBits(twistStep.value >>> 0), "624 strict-reload emits the twisted stream's first word");
});

test("ABI v76: set low byte and mtReady=0 keep the v70 host-drawn plan exactly", () => {
  /* useCrtRand low byte SET: PE 0x006eef91 takes CRT rand() without touching
     mt[] — sample consulted, mtAdvanced 0, NO index published, theta of the
     sample. */
  const crt = timerMtWalk(0x1e, {
    frameOpaque98dba0TimerReady: 1,
    frameOpaque98dba0Timer264e8: 0x1e,
    frameOpaque98dba0TimerPureReady: 1,
    frameOpaque98dba0TimerSample: 0x3039,
    frameOpaque98dba0TimerUseCrtRand: 1,
    frameOpaque98dba0TimerMtReady: 1,
    frameOpaque98dba0TimerMtiIn: 10,
    genrandState: new Uint32Array(624),
  });
  assert.equal(crt.events.opaqueCall0098dba0Timer, 0);
  assert.equal(crt.events.frameOpaque98dba0TimerPlanApplied, 1);
  assert.equal(crt.events.frameOpaque98dba0TimerMtAdvanced, 0, "CRT arm does NOT advance mt[]");
  assert.equal(crt.events.frameOpaque98dba0TimerMtIndexOut, 0, "no index on the CRT arm");
  assert.equal(crt.events.frameOpaque98dba0TimerThetaBits >>> 0,
    frameOpaque98dba0TimerThetaBits(0x3039), "CRT arm consults the host sample");
  /* mtReady=0 without any capture: identical v70 plan. */
  const noMt = timerMtWalk(0x1e, {
    frameOpaque98dba0TimerReady: 1,
    frameOpaque98dba0Timer264e8: 0x1e,
    frameOpaque98dba0TimerPureReady: 1,
    frameOpaque98dba0TimerSample: 0x80000000,
    frameOpaque98dba0TimerUseCrtRand: 0,
    frameOpaque98dba0TimerMtReady: 0,
  });
  assert.equal(noMt.events.frameOpaque98dba0TimerMtAdvanced, 1);
  assert.equal(noMt.events.frameOpaque98dba0TimerMtIndexOut, 0);
  assert.equal(noMt.events.frameOpaque98dba0TimerThetaBits >>> 0, 0x4048f5c3,
    "mtReady=0 reproduces the v70 sample->theta exactly");
});

