/* ---- ABI v69: PM0/PM1 death-walk wire (PlayerManager::Update 0x009bb5d0) ---- */

/** Run the room-update-head resume on a shaped state and return the death
 *  event delta. The death block is the only writer of
 *  playerManagerUpdateDeath, so the delta isolates the wire. */
function deathResumeDelta(stateOverrides = {}, runtime = {}) {
  const base = step({});
  const shaped = { ...base.state, ...stateOverrides };
  const ev = {
    ...base.events,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD,
  };
  const pre = ev.playerManagerUpdateDeath >>> 0;
  const out = resumeGameUpdateRoomUpdateHead(shaped, runtime, ev);
  assert.ok(out, "head resume returned a result");
  return (out.events.playerManagerUpdateDeath >>> 0) - pre;
}

test("ABI v69: death-wire defaults keep the v68 monolithic emission byte-identical", () => {
  /* No pmDeath inputs at all: count defaults 1, blob defaults 0 →
     MONOLITHIC under dual-zero → exactly the pre-v69 single emit. */
  assert.equal(deathResumeDelta({}, {}), 1);
  /* blob explicitly 0 behaves the same. */
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: 1, pmDeathBlobReady: 0 }), 1);
  /* count > 8 cannot be covered by 8 packs: monolithic fallback. */
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: 9, pmDeathBlobReady: 1, pmDeathDead1730: 1 }), 1);
});

test("ABI v69: zero-eligible ready packs drop the death host (pure-complete walk)", () => {
  /* Nobody dead: the PE walk reads bytes/words and calls nothing — a pure
     no-op, so the pre-walk packs stay valid and the host edge is dropped. */
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: 2, pmDeathBlobReady: 1 }), 0);
  /* Dead but still animating: anim_7c != 0 AND anim_8c != 0 blocks. */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1,
      pmDeathDead1730: 1, pmDeathAnim7c0: 5, pmDeathAnim8c0: 1, pmDeathTwinNull0: 1,
    }),
    0,
  );
  /* Twin still animating blocks (twin present, twin busy). */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1,
      pmDeathDead1730: 1, pmDeathTwinNull0: 0, pmDeathTwinAnim7c0: 3, pmDeathTwinAnim8c0: 1,
    }),
    0,
  );
});

test("ABI v69: outer count 0 skips the loop with NO fatal (PE 0x009bb610 je)", () => {
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: 0 }), 0);
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: 0, pmDeathBlobReady: 1 }), 0);
  /* Negative counts are out-of-contract for a real vector; the family clamps
     to 0 (documented), so no emission. */
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: -3, pmDeathBlobReady: 1, pmDeathDead1730: 1 }), 0);
});

test("ABI v69: an eligible player emits exactly ONE monolithic walk (never per-player)", () => {
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1, pmDeathDead1730: 1, pmDeathTwinNull0: 1,
    }),
    1,
  );
  /* Twin present but idle also permits. */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1, pmDeathDead1730: 1,
      pmDeathTwinNull0: 0, pmDeathTwinAnim7c0: 0, pmDeathTwinAnim8c0: 0,
    }),
    1,
  );
  /* Second-slot eligibility counts; TWO eligible players still ONE walk emit
     (the host runs the whole PE loop live — pre-deciding per-player calls
     from pre-walk packs would fold post-TriggerDeath state to a snapshot). */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 3, pmDeathBlobReady: 1,
      pmDeathDead1731: 1, pmDeathTwinNull1: 1,
      pmDeathDead1732: 1, pmDeathTwinNull2: 1,
    }),
    1,
  );
});

test("ABI v69: byte lanes narrow at the pack exactly like the PE byte loads", () => {
  /* dead_173 is `cmp byte [ecx+0x173],0`: 0x100 has a zero low byte → NOT
     dead → dropped. A full-word model emits here and dies. */
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: 1, pmDeathBlobReady: 1, pmDeathDead1730: 0x100 }), 0);
  /* 0x101 has low byte 1 → dead → emits. */
  assert.equal(deathResumeDelta({}, { pmDeathPlayerCount: 1, pmDeathBlobReady: 1, pmDeathDead1730: 0x101, pmDeathTwinNull0: 1 }), 1);
  /* anim_8c is a byte: 0x100 reads idle even though anim_7c != 0. */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1,
      pmDeathDead1730: 1, pmDeathAnim7c0: 5, pmDeathAnim8c0: 0x100, pmDeathTwinNull0: 1,
    }),
    1,
  );
  /* twin_null carries the pack's low byte: 0x100 → twin PRESENT (and busy →
     dropped). A !=0 normalization would read it as twin-absent and emit. */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1,
      pmDeathDead1730: 1, pmDeathTwinNull0: 0x100, pmDeathTwinAnim7c0: 3, pmDeathTwinAnim8c0: 1,
    }),
    0,
  );
  /* twin_anim_8c byte: 0x100 → twin idle → emits. */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1,
      pmDeathDead1730: 1, pmDeathTwinNull0: 0, pmDeathTwinAnim7c0: 3, pmDeathTwinAnim8c0: 0x100,
    }),
    1,
  );
  /* anim_7c is a FULL WORD (`cmp dword`): 0x100 is busy, not idle — with
     anim_8c busy too the player is blocked. */
  assert.equal(
    deathResumeDelta({}, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1,
      pmDeathDead1730: 1, pmDeathAnim7c0: 0x100, pmDeathAnim8c0: 1, pmDeathTwinNull0: 1,
    }),
    0,
  );
});

test("ABI v69: PM0 re-tests the LIVE gates — closed gate suppresses the walk", () => {
  /* PE 0x009bb5df / 0x009bb5ee read Game+0x1b83c / Game+0x1ba78 live; a
     mid-pause host rewrite must suppress even an eligible ready pack. */
  assert.equal(
    deathResumeDelta({ gate1b83c: 1 }, {
      pmDeathPlayerCount: 1, pmDeathBlobReady: 1, pmDeathDead1730: 1, pmDeathTwinNull0: 1,
    }),
    0,
  );
  assert.equal(deathResumeDelta({ gate1ba78: 7 }, {}), 0);
});

