/* ---- ABI v71: FUN_004257b0 Pass A + Pass B wire ------------------------ */

const FO_STRIDE = 0x68;
const FO_LIST_BASE = 0x00040000;

/** Whole-pack blob with every field zeroed, then the overrides applied. */
function foBlobInputs(overrides = {}) {
  const out = {
    frameOpaque4257b0BlobReady: 1,
    frameOpaque4257b0ListBegin: FO_LIST_BASE,
    frameOpaque4257b0ListEnd: FO_LIST_BASE,
    frameOpaque4257b0ListCap: FO_LIST_BASE,
    frameOpaque4257b0PostListBegin: FO_LIST_BASE,
    frameOpaque4257b0PostListEnd: FO_LIST_BASE,
    frameOpaque4257b0IdvecBegin: 0x00020000,
    frameOpaque4257b0IdvecEnd: 0x00020000,
    frameOpaque4257b0CtrBegin: 0x00030000,
    frameOpaque4257b0CtrEnd: 0x00030000,
    frameOpaque4257b0InitialByte13: 0,
  };
  for (let i = 0; i < FRAME_OPAQUE_4257B0_MAX_PLAYERS; i += 1) {
    for (const stem of ["PPtr", "PId1618", "P161c", "QPtr", "Q161c",
                        "QId1618", "QqPtr", "Qq161c", "PChar13c0"]) {
      out[`frameOpaque4257b0${stem}${i}`] = 0;
    }
  }
  for (let i = 0; i < FRAME_OPAQUE_4257B0_MAX_ELEMS; i += 1) {
    for (const stem of ["ElemId", "ElemSubPtr", "ElemSubLo", "ElemSubHi"]) {
      out[`frameOpaque4257b0${stem}${i}`] = 0;
    }
  }
  for (let i = 0; i < FRAME_OPAQUE_4257B0_MAX_LIST; i += 1) {
    for (const stem of ["ListLo", "ListHi", "ListSlot8"]) {
      out[`frameOpaque4257b0${stem}${i}`] = 0;
    }
  }
  return { ...out, ...overrides };
}

/** Drive the head resume (where 4257b0 lives) and, when it stops at the F4
 *  recapture, the Pass A resume too. Returns the final events. */
function fo4257b0Run(runtime, stateOverrides = {}) {
  const base = step({});
  const shaped = { ...base.state, timedTransitionCleanupMode: 0, ...stateOverrides };
  const ev = {
    ...base.events,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD,
  };
  const head = resumeGameUpdateRoomUpdateHead(shaped, runtime, ev);
  assert.ok(head, "head resume returned a result");
  if (head.events.continuationKind !== UPDATE_CONTINUATION.RESUME_AFTER_4257B0_PASS_A) {
    return { events: head.events, stopped: false };
  }
  const resumed = resumeGameUpdate4257b0PassA(head.state, runtime, head.events);
  assert.ok(resumed, "pass-A resume returned a result");
  return { events: resumed.events, stopped: true, headEvents: head.events };
}

test("ABI v71: without the blob the FUN_004257b0 host edges are byte-identical to v70", () => {
  /* This is the shipped frame path: web/js/native-update-bridge.js supplies
     none of the blob fields, so blobReady stays 0. */
  const legacy = fo4257b0Run({
    frameOpaque4257b0IdCount: 3,
    frameOpaque4257b0ListCount: 2,
    frameOpaque4257b0PostPassAListCount: 5,
  });
  assert.equal(legacy.stopped, true, "id_count != 0 still stops at the F4 recapture");
  assert.equal(legacy.events.opaqueCall004257b0PassA, 1);
  assert.equal(legacy.events.opaqueCall004257b0PassB, 1);
  /* Not one of the v71 carriers may move on the legacy path. */
  assert.equal(legacy.events.frameOpaque4257b0PassAApplied, 0);
  assert.equal(legacy.events.frameOpaque4257b0PassBApplied, 0);
  assert.equal(legacy.events.frameOpaque4257b0IdCountOut, 0);
  assert.equal(legacy.events.frameOpaque4257b0Inserted, 0);
  assert.equal(legacy.events.frameOpaque4257b0PostCount, 0);
  assert.equal(legacy.events.frameOpaque4257b0PassBStores, 0);
  assert.equal(legacy.events.frameOpaque4257b0ListGrow, 0);
  /* id_count 0 keeps the v53 no-recapture arm and the pre-captured gate. */
  const noPassA = fo4257b0Run({
    frameOpaque4257b0IdCount: 0,
    frameOpaque4257b0ListCount: 4,
  });
  assert.equal(noPassA.stopped, false);
  assert.equal(noPassA.events.opaqueCall004257b0PassA, 0);
  assert.equal(noPassA.events.opaqueCall004257b0PassB, 1);
});

test("ABI v71: a usable blob retires BOTH FUN_004257b0 host edges", () => {
  /* One counted player, non-empty container whose element resolves to the
     pair (11, 12); the list is empty, so Pass A appends and the recaptured
     pair reports one element. */
  const runtime = foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020004,
    frameOpaque4257b0PPtr0: 0x00100000,
    frameOpaque4257b0P161c0: 1,
    frameOpaque4257b0PId16180: 3,
    frameOpaque4257b0PChar13c00: 2,
    frameOpaque4257b0CtrEnd: 0x00030004,
    frameOpaque4257b0ElemId0: 3,
    frameOpaque4257b0ElemSubPtr0: 0x00400000,
    frameOpaque4257b0ElemSubLo0: 11,
    frameOpaque4257b0ElemSubHi0: 12,
    frameOpaque4257b0ListCap: FO_LIST_BASE + 4 * FO_STRIDE,
    frameOpaque4257b0PostListEnd: FO_LIST_BASE + 1 * FO_STRIDE,
    /* Legacy inputs deliberately non-zero: if the blob path ever fell back
       silently these would light up the host counters. */
    frameOpaque4257b0IdCount: 7,
    frameOpaque4257b0ListCount: 7,
    frameOpaque4257b0PostPassAListCount: 7,
  });
  const run = fo4257b0Run(runtime);
  assert.equal(run.stopped, true, "Pass A ran, so the F4 pair must be recaptured");
  assert.equal(run.events.opaqueCall004257b0PassA, 0, "Pass A host edge is gone");
  assert.equal(run.events.opaqueCall004257b0PassB, 0, "Pass B host edge is gone");
  assert.equal(run.events.frameOpaque4257b0PassAApplied, 1);
  assert.equal(run.events.frameOpaque4257b0PassBApplied, 1);
  assert.equal(run.events.frameOpaque4257b0IdCountOut, 1);
  assert.equal(run.events.frameOpaque4257b0Inserted, 1);
  assert.equal(run.events.frameOpaque4257b0PostCount, 1);
  assert.equal(run.events.frameOpaque4257b0ListGrow, 0, "capacity 4 holds the append");
  /* The appended element is dw{+0 = lo, +4 = hi, +8 = 1} before Pass B. */
  const outcome = frameOpaque4257b0Outcome(runtime);
  assert.equal(outcome.triples.lo[0], 11);
  assert.equal(outcome.triples.hi[0], 12);
});

test("ABI v88: the Pass A resume mismatch arm keeps the PE 0x00425894 je (empty recapture emits NO Pass B host edge)", () => {
  /* Pass A ran (id_count 1 -> appended pair (11,12) -> purePost 1), but the
     host's post-Pass-A recapture reports ZERO elements. PE 0x00425894
     `je 0x004259a2` skips Pass B entirely on a zero re-derived count;
     the v71-era resume must NOT emit the 0x004257b0 Pass B host edge.
     This pins a measured defect: the oracle is a BOOLEAN, and the arm
     used to test it with `!== 0`, so `false !== 0` == true dead-gated the
     arm and every mismatch emitted the host edge (differential case 915). */
  const runtime = foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020004,
    frameOpaque4257b0PPtr0: 0x00100000,
    frameOpaque4257b0P161c0: 1,
    frameOpaque4257b0PId16180: 3,
    frameOpaque4257b0PChar13c00: 2,
    frameOpaque4257b0CtrEnd: 0x00030004,
    frameOpaque4257b0ElemId0: 3,
    frameOpaque4257b0ElemSubPtr0: 0x00400000,
    frameOpaque4257b0ElemSubLo0: 11,
    frameOpaque4257b0ElemSubHi0: 12,
    /* Empty recapture: the pure Pass A produced one element, the host
       recaptured none -> mismatch arm with recaptured == 0. */
    frameOpaque4257b0PostListBegin: FO_LIST_BASE,
    frameOpaque4257b0PostListEnd: FO_LIST_BASE,
    /* Legacy inputs non-zero: a silent fallback would light them up. */
    frameOpaque4257b0IdCount: 7,
    frameOpaque4257b0ListCount: 7,
    frameOpaque4257b0PostPassAListCount: 7,
  });
  const run = fo4257b0Run(runtime);
  assert.equal(run.stopped, true, "Pass A ran, so the F4 pair must be recaptured");
  assert.equal(run.events.frameOpaque4257b0PassAApplied, 1);
  assert.equal(run.events.frameOpaque4257b0PassBApplied, 0, "mismatch means Pass B did not run pure");
  assert.equal(run.events.opaqueCall004257b0PassA, 0, "Pass A host edge stays gone");
  assert.equal(run.events.opaqueCall004257b0PassB, 0,
    "PE 0x00425894: a ZERO re-derived count skips Pass B, so no host edge");
  /* Same setup but the recapture reports TWO elements (purePost 1): the
     mismatch arm's 0x00425894 test passes (count != 0) -> host edge. */
  const live = fo4257b0Run(foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020004,
    frameOpaque4257b0PPtr0: 0x00100000,
    frameOpaque4257b0P161c0: 1,
    frameOpaque4257b0PId16180: 3,
    frameOpaque4257b0PChar13c00: 2,
    frameOpaque4257b0CtrEnd: 0x00030004,
    frameOpaque4257b0ElemId0: 3,
    frameOpaque4257b0ElemSubPtr0: 0x00400000,
    frameOpaque4257b0ElemSubLo0: 11,
    frameOpaque4257b0ElemSubHi0: 12,
    frameOpaque4257b0PostListBegin: FO_LIST_BASE,
    frameOpaque4257b0PostListEnd: FO_LIST_BASE + 2 * FO_STRIDE,
  }));
  assert.equal(live.stopped, true);
  assert.equal(live.events.frameOpaque4257b0PassBApplied, 0);
  assert.equal(live.events.opaqueCall004257b0PassB, 1,
    "a NON-zero recapture that disagrees with purePassA keeps the host edge");
});

test("ABI v71: the F4 recapture is taken on ONE path only (PE 0x004257ee je 0x00425870)", () => {
  /* id_count == 0 — the PE jumps straight to the recount with the list
     untouched, so the PRE pair gates Pass B and the post fields are ignored.
     The post pair here claims FIVE elements; if the wire recaptured
     unconditionally the Pass B walk would run over five entries. */
  const runtime = foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020004,
    /* counted(p) false: q != 0, q161c != -1, q161c < p161c (SIGNED), q != p. */
    frameOpaque4257b0PPtr0: 0x00100000,
    frameOpaque4257b0QPtr0: 0x00200000,
    frameOpaque4257b0P161c0: 1,
    frameOpaque4257b0Q161c0: 0,
    frameOpaque4257b0PId16180: 3,
    frameOpaque4257b0PChar13c00: 2,
    frameOpaque4257b0ListEnd: FO_LIST_BASE + 2 * FO_STRIDE,
    frameOpaque4257b0ListCap: FO_LIST_BASE + 4 * FO_STRIDE,
    frameOpaque4257b0ListLo0: 3,
    frameOpaque4257b0ListHi0: 7,
    frameOpaque4257b0ListLo1: 4,
    frameOpaque4257b0ListHi1: 9,
    /* Poisoned post pair — must never be consulted on this path. It reports
       an EMPTY list, so an unconditional recapture would close the
       0x00425894 gate and Pass B would store nothing. */
    frameOpaque4257b0PostListBegin: FO_LIST_BASE + 0x8000,
    frameOpaque4257b0PostListEnd: FO_LIST_BASE + 0x8000,
  });
  const run = fo4257b0Run(runtime);
  assert.equal(run.stopped, false, "no Pass A means no recapture stop");
  assert.equal(run.events.frameOpaque4257b0PassAApplied, 0);
  assert.equal(run.events.frameOpaque4257b0PassBApplied, 1);
  assert.equal(run.events.frameOpaque4257b0IdCountOut, 0);
  /* The PRE pair says two elements; the poisoned post pair says none. */
  assert.equal(run.events.frameOpaque4257b0PostCount, 2);
  const outcome = frameOpaque4257b0Outcome(runtime);
  assert.equal(outcome.plan.preCount, 2);
  assert.equal(outcome.purePostCount, 2);
  assert.equal(outcome.recaptured, 0, "the post pair is not read on this path");
  /* Empty container: each entry's own dword +0 is the id (PE 0x00425943), so
     entry 0 (lo 3) matches the player's +0x1618 == 3 and stores. An
     unconditional recapture would walk ZERO entries and store nothing. */
  assert.equal(run.events.frameOpaque4257b0PassBStores, 1);
});

test("ABI v71: the list count is the PE's SIGNED magic division, not delta/0x68", () => {
  /* end - begin == -50. The PE's `imul 0x4ec4ec4f; sar edx,5` plus the
     sign-bit add truncates toward zero and yields 0 -> the 0x00425894 je
     returns before Pass B. An unsigned delta / 0x68 is 41297762, which would
     blow MAX_LIST and drop the whole blob back onto the v70 host residual. */
  const runtime = foBlobInputs({
    frameOpaque4257b0ListEnd: (FO_LIST_BASE - 50) >>> 0,
    frameOpaque4257b0PostListEnd: (FO_LIST_BASE - 50) >>> 0,
    frameOpaque4257b0ListCap: FO_LIST_BASE + 2 * FO_STRIDE,
    /* Legacy inputs non-zero so a fallback is loudly visible. */
    frameOpaque4257b0IdCount: 4,
    frameOpaque4257b0ListCount: 4,
  });
  const plan = frameOpaque4257b0Plan(runtime);
  assert.equal(plan.usable, true, "a negative delta is an EMPTY list, not an over-cap one");
  assert.equal(plan.preCount, 0);
  const run = fo4257b0Run(runtime);
  assert.equal(run.events.opaqueCall004257b0PassA, 0);
  assert.equal(run.events.opaqueCall004257b0PassB, 0);
  assert.equal(run.events.frameOpaque4257b0PassBApplied, 1);
  assert.equal(run.events.frameOpaque4257b0PostCount, 0);
  assert.equal(run.events.frameOpaque4257b0PassBStores, 0);
  /* Every delta strictly inside (-0x68, 0) is zero elements under the signed
     law and ~41 million under an unsigned one. */
  for (const delta of [1, 50, 103]) {
    const probe = frameOpaque4257b0Plan(foBlobInputs({
      frameOpaque4257b0ListEnd: (FO_LIST_BASE - delta) >>> 0,
    }));
    assert.equal(probe.preCount, 0, `delta -${delta} must be 0 elements`);
  }
});

test("ABI v71: the two list pointers are consumed as one pair after a grow", () => {
  /* Capacity 0 forces the 0x00426640 reallocation, which MOVES the buffer:
     the recaptured begin is 0x8000 above the pre-tick one. Reading the pre
     begin beside the post end (or the reverse) gives a nonsense count. */
  const runtime = foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020004,
    frameOpaque4257b0PPtr0: 0x00100000,
    frameOpaque4257b0P161c0: 1,
    frameOpaque4257b0PId16180: 3,
    frameOpaque4257b0PChar13c00: 2,
    frameOpaque4257b0CtrEnd: 0x00030004,
    frameOpaque4257b0ElemId0: 3,
    frameOpaque4257b0ElemSubPtr0: 0x00400000,
    frameOpaque4257b0ElemSubLo0: 11,
    frameOpaque4257b0ElemSubHi0: 12,
    frameOpaque4257b0PostListBegin: FO_LIST_BASE + 0x8000,
    frameOpaque4257b0PostListEnd: FO_LIST_BASE + 0x8000 + 1 * FO_STRIDE,
  });
  const run = fo4257b0Run(runtime);
  assert.equal(run.stopped, true);
  assert.equal(run.events.frameOpaque4257b0Inserted, 1);
  assert.equal(run.events.frameOpaque4257b0PostCount, 1);
  /* The allocator edge is the ONLY host edge the pure body leaves behind. */
  assert.equal(run.events.frameOpaque4257b0ListGrow, 1);
  assert.equal(run.events.opaqueCall004257b0PassA, 0);
  assert.equal(run.events.opaqueCall004257b0PassB, 0);
  assert.equal(run.events.frameOpaque4257b0PassBApplied, 1);
  /* Mixing the pre begin with the post end would be 0x8000 + 0x68 bytes of
     delta, i.e. 315 elements, not 1. */
  const mixedDelta = ((FO_LIST_BASE + 0x8000 + FO_STRIDE) - FO_LIST_BASE) >>> 0;
  assert.notEqual(Math.trunc(mixedDelta / FO_STRIDE), 1);
});

test("ABI v71: an over-cap or disagreeing blob falls back to the v70 host edges", () => {
  /* Player vector of 12 cannot be covered by 8 packs. */
  const overCap = fo4257b0Run(foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020000 + 12 * 4,
    frameOpaque4257b0IdCount: 2,
    frameOpaque4257b0ListCount: 3,
    frameOpaque4257b0PostPassAListCount: 3,
  }));
  assert.equal(frameOpaque4257b0Plan(foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020000 + 12 * 4,
  })).usable, false);
  assert.equal(overCap.events.frameOpaque4257b0PassAApplied, 0);
  assert.equal(overCap.events.opaqueCall004257b0PassA, 1);
  assert.equal(overCap.events.opaqueCall004257b0PassB, 1);

  /* A recaptured count the pure Pass A did not produce: the host applied
     something the slice did not model, so Pass B goes back to the host. */
  const mismatchRuntime = foBlobInputs({
    frameOpaque4257b0IdvecEnd: 0x00020004,
    frameOpaque4257b0PPtr0: 0x00100000,
    frameOpaque4257b0P161c0: 1,
    frameOpaque4257b0PId16180: 5,
    frameOpaque4257b0PChar13c00: 0xb,
    frameOpaque4257b0ListCap: FO_LIST_BASE + 4 * FO_STRIDE,
    frameOpaque4257b0PostListEnd: FO_LIST_BASE + 6 * FO_STRIDE,
  });
  const outcome = frameOpaque4257b0Outcome(mismatchRuntime);
  assert.equal(outcome.mismatch, true);
  assert.equal(outcome.recaptured, 6);
  const mismatch = fo4257b0Run(mismatchRuntime);
  assert.equal(mismatch.events.opaqueCall004257b0PassA, 0, "Pass A still ran pure");
  assert.equal(mismatch.events.frameOpaque4257b0PassAApplied, 1);
  assert.equal(mismatch.events.opaqueCall004257b0PassB, 1, "Pass B falls back");
  assert.equal(mismatch.events.frameOpaque4257b0PassBApplied, 0);
});

