test("ABI v77: lane law agrees with the anm2 family plan on the same images", () => {
  /* Cross-helper differential: the anm2 family's anm2LoadPlan (separately
     reasoned from the same PE body) re-walks layer/extras name images. Feed
     both the SAME image; every S-lane claim must agree. */
  const mem = new Uint8Array(0x10000);
  const w32 = (a, v) => {
    mem[a] = v & 0xff; mem[a + 1] = (v >>> 8) & 0xff; mem[a + 2] = (v >>> 16) & 0xff; mem[a + 3] = (v >>> 24) & 0xff;
  };
  const putName = (strAddr, s) => {
    for (let i = 0; i < s.length; i++) mem[strAddr + i] = s.charCodeAt(i) & 0xff;
    w32(strAddr + 0x14, 0); /* capacity < 0x10 -> SSO */
  };
  const anm2Addr = 0x1000;
  const layers = 0x2000;
  const extras = 0x4000;
  const names = ["shadow", "*star", "plain", "shadow", "*s2"];
  const extraNames = ["*e", "e2"];
  w32(anm2Addr + 0x10, 0); /* filename size 0 */
  w32(anm2Addr + 0x7c, layers);
  w32(anm2Addr + 0x80, names.length);
  w32(anm2Addr + 0x84, extras);
  w32(anm2Addr + 0x88, extraNames.length);
  let nh = 0x5000;
  for (let i = 0; i < names.length; i++) {
    const layerObj = layers + i * 0xa0;
    w32(layerObj, nh);
    putName(nh + 8, names[i]);
    nh += 0x20;
  }
  for (let k = 0; k < extraNames.length; k++) {
    putName(extras + k * 0x18, extraNames[k]);
  }
  const plan = anm2LoadPlan(mem, { anm2Addr, loadGraphics: 0 });
  assert.equal(plan.entered, 1);
  const rt = {
    engineAnm2BlobReady: 1,
    engineAnm2LatchReady: 1,
    engineAnm2Latch: 0,
    engineAnm2Bitflags110Pre: 0,
    engineAnm2LayerCount: names.length,
    engineAnm2ExtraCount: extraNames.length,
    engineAnm2LayerNames: names,
    engineAnm2ExtraNames: extraNames,
  };
  const st = { engineAnm2Loaded: 0, engineAnm2Slot10c: 0, engineAnm2Bitflags110: 0 };
  const ev = { engineAnm2LaneApplied: 0, engineAnm2StarLayerMask: 0 };
  assert.equal(applyEngineAnm2LoadLane(st, rt, ev), 1);
  /* S3: the plan's shadow is LAST-match-wins, exactly like the lane. */
  assert.equal(plan.shadowSet, 1);
  assert.equal(st.engineAnm2Slot10c, plan.shadowIndex);
  /* S4: the plan counts star layers — the lane's mask has exactly that many
     bits, all within the layer range. */
  const popcount = (x) => { let n = 0; while (x) { n += x & 1; x >>>= 1; } return n; };
  assert.equal(popcount(ev.engineAnm2StarLayerMask), plan.starLayerCount);
  assert.ok((ev.engineAnm2StarLayerMask & ((1 << names.length) - 1)) === ev.engineAnm2StarLayerMask,
    "no mask bit may sit outside the layer range");
  /* S5/S6: the flag bits agree with the plan. */
  assert.equal((st.engineAnm2Bitflags110 & 0x400) !== 0 ? 1 : 0, plan.bitflagsOr400);
  assert.equal((st.engineAnm2Bitflags110 & 0x800) !== 0 ? 1 : 0, plan.bitflagsOr800);
  assert.equal(plan.starExtraCount, 1);
});

/* ============ ABI v95: record idx 21 ANM2::Load frame laws ================
   The RECOVERABLE pure islands of ANM2::Load's frame (0x0040bd50..0x0040be99,
   111 insns, exact ZHL): the load-path host-call DECISION laws + the store
   census. Which of the six pre-lane host callees fire (PE order):
     H1 prologue     0x40e2b0  iff [recv+0x10] != 0      (0x40bd59 cmp dword/je
                                                          FULL-DWORD gate)
     H2 assign       0x40ccd0  iff recv != path          (0x40bd68 cmp esi,edi/je
                                                          ADDRESS equality)
     H3 cache guard  0x40db90  ALWAYS                    (0x40bd81)
     H4 cache fetch  0x40e110  ALWAYS                    (0x40bd88)
     H5 loader       0x40c000  iff (loadgraphics&0xff)!=0 (0x40bd8e cmp byte/je
                                                          LOW-BYTE gate)
     H6a/H6b anim    0x408830  (recv+0x30/+0x50) ALWAYS  (0x40bd9c)
   count = 4 + !is_self + path_present + graphics. Store census: S1 byte
   [recv+0x109]=1 (0x40bdb2) and S2 dword [recv+0x10c]=0xffffffff (0x40bdb9)
   are UNCONDITIONAL; S3 shadow last-match (0x40be29), S5 |=0x400 (0x40be40),
   S6 |=0x800 (0x40be82) and S4 heap [layer+0x8c]|=5 (0x40be39, starLayerMask
   event; closure read census shows zero [*+0x8c] readers on the Update
   path) are CONDITIONAL on the pure name scans. The host callees stay host;
   the six S-stores need NO body. */

test("ABI v95: path_present is a FULL-DWORD gate (0x100 is PRESENT)", () => {
  /* PE 0x0040bd59 cmp dword ptr [esi+0x10],0 / je 0x40bd65 — the machine
     reads the whole dword of the pre-call filename size. A low-byte
     narrowing would wrongly skip the 0x40e2b0 prologue on 0x100. */
  assert.equal(engineAnm2LoadPathPresent(0), 0);
  for (const v of [1, 2, 0x1d, 0xff, 0x100, 0x1ff, 0x7fffffff, 0x80000000,
                   0xffffff00, 0xffffffff]) {
    assert.equal(engineAnm2LoadPathPresent(v), 1, `0x${v.toString(16)} is present`);
  }
});

test("ABI v95: path_is_self is 32-bit ADDRESS equality", () => {
  /* PE 0x0040bd68 cmp esi,edi / je 0x40bd81 — the assign is skipped only
     when the receiver IS the path object. */
  assert.equal(engineAnm2LoadPathIsSelf(0x1b874, 0x1b874), 1);
  assert.equal(engineAnm2LoadPathIsSelf(0x1b874, 0x12345678), 0);
  assert.equal(engineAnm2LoadPathIsSelf(0, 0), 1);
  assert.equal(engineAnm2LoadPathIsSelf(0, 1), 0);
  assert.equal(engineAnm2LoadPathIsSelf(0xffffffff, 0xffffffff), 1);
  assert.equal(engineAnm2LoadPathIsSelf(0xffffffff, 1), 0);
});

test("ABI v95: graphics_needed is a LOW-BYTE gate (0x100 skips, 0x1ff runs)", () => {
  /* PE 0x0040bd8e cmp byte ptr [ebp+0xc],0 / je 0x40bd9c — the machine
     tests the BYTE at the arg slot. The module must own the narrowing
     (uint32_t param; the wasm i32 arrives unmasked):
       low byte SET -> the 0x40c000 loader runs: 1, 0xff, 0x1ff, 0xffffffff
       low byte CLEAR -> skipped: 0, 0x100, 0x80000000, 0xffffff00. */
  assert.equal(engineAnm2LoadGraphicsNeeded(0), 0);
  for (const v of [1, 2, 0xff, 0x1ff, 0x7fffffff, 0xffffffff]) {
    assert.equal(engineAnm2LoadGraphicsNeeded(v), 1, `0x${v.toString(16)} needs graphics`);
  }
  for (const v of [0x100, 0x10000, 0x80000000, 0xffffff00, 0x0100, 0x00ff0000]) {
    assert.equal(engineAnm2LoadGraphicsNeeded(v), 0, `0x${v.toString(16)} skips the loader`);
  }
});

test("ABI v95: frame_host_calls composes the ordered host-call law", () => {
  const SITE_RECV = 0x1b874;
  const SITE_PATH = 0x12345678; /* caller's constant copy — never == recv */
  /* 4 straight-line hosts (H3+H4+H6a+H6b) + the three gates. */
  assert.equal(engineAnm2LoadFrameHostCalls(0, SITE_RECV, SITE_PATH, 0), 5,
    "4 base + assign");
  assert.equal(engineAnm2LoadFrameHostCalls(0, SITE_RECV, SITE_PATH, 1), 6,
    "site shape: + loader");
  assert.equal(engineAnm2LoadFrameHostCalls(0x1d, SITE_RECV, SITE_PATH, 1), 7,
    "+ prologue + loader");
  assert.equal(engineAnm2LoadFrameHostCalls(0, SITE_RECV, SITE_RECV, 1), 5,
    "is-self skips the assign");
  assert.equal(engineAnm2LoadFrameHostCalls(0x1d, SITE_RECV, SITE_RECV, 0), 5,
    "4 base + prologue only");
  assert.equal(engineAnm2LoadFrameHostCalls(0x1d, SITE_RECV, SITE_PATH, 0x1ff), 7,
    "wide low-byte-set graphics (0x1ff) runs the loader");
  assert.equal(engineAnm2LoadFrameHostCalls(0, SITE_RECV, SITE_PATH, 0x100), 5,
    "0x100 low byte is CLEAR -> loader skipped (machine cmp byte)");
  assert.equal(engineAnm2LoadFrameHostCalls(0x1d, SITE_RECV, SITE_PATH, 0x100), 6,
    "same, with the prologue present (4+assign+prologue)");
  assert.equal(engineAnm2LoadFrameHostCalls(0x1d, SITE_RECV, SITE_PATH, 0xffffff00), 6,
    "wide-clear graphics skips the loader, prologue runs");
  assert.equal(engineAnm2LoadFrameHostCalls(0xffffff00, SITE_RECV, SITE_PATH, 0), 6,
    "wide filename size runs the prologue");
  assert.equal(engineAnm2LoadFrameHostCalls(0, SITE_RECV, SITE_RECV, 0), 4,
    "floor is the 4 unconditional hosts");
  assert.equal(engineAnm2LoadFrameHostCalls(0, SITE_RECV, SITE_PATH, 0xffffffff), 6);
});

test("ABI v95: site law is the fixed-point 6 and agrees with the composition", () => {
  /* Update site (record idx 21 gated arm): `push 1` loadgraphics is
     unconditional (0x0082ef0d); the path is the caller's copy of the
     .rdata constant, never == recv Game+0x1b874 (is_self 0); the latch
     low byte clear (PE 0x0082ee9e BYTE test) = never loaded = pre-call
     filename size [recv+0x10] == 0. 4 + 1 + 0 + 1 = 6 host calls on every
     ANM2::Load this record runs. */
  assert.equal(engineAnm2LoadSiteHostCalls(), 6);
  assert.equal(
    engineAnm2LoadSiteHostCalls(),
    engineAnm2LoadFrameHostCalls(0, 0x1b874, 0x12345678, 1),
    "site law == composition at the PE-proven site constants",
  );
  assert.equal(
    engineAnm2LoadSiteHostCalls(),
    engineAnm2LoadFrameHostCalls(0, 0x1b874, 0x12345678, 0x1ff),
    "wide low-byte-set loadgraphics keeps the site law (6)",
  );
  /* The graphics gate is a BYTE test: a 0x100 drive is NOT the site law —
     the loader is skipped and the count drops to 5 (machine cmp byte). */
  assert.equal(engineAnm2LoadFrameHostCalls(0, 0x1b874, 0x12345678, 0x100), 5);
});

test("ABI v95: store census — S1/S2 UNCONDITIONAL, S3/S4/S5/S6 conditional", () => {
  /* PE classification: S1 (0x40bdb2) and S2 (0x40bdb9) have NO gate — every
     branch above 0x40bdb0 rejoins there; S3 (0x40be29 shadow index), S5
     (0x40be40 |=0x400) and S6 (0x40be82 |=0x800) need the pure name scans;
     S4 (0x40be39 heap [layer+0x8c]|=5) needs the '*' scan and targets
     memory OUTSIDE the Game capture ABI (engineAnm2StarLayerMask; closure
     read census: zero [*+0x8c] readers on the Update path). Behavioural
     pin through the v77 lane:
       - EMPTY body -> exactly S1+S2 (none of S3..S6 can fire);
       - no shadow -> S2's 0xffffffff sentinel survives (S3 conditional);
       - no star  -> 0x110 untouched + mask 0 (S4/S5/S6 conditional). */
  const run = (over) => {
    const st = { engineAnm2Loaded: 0, engineAnm2Slot10c: 0, engineAnm2Bitflags110: 0 };
    const ev = { engineAnm2LaneApplied: 0, engineAnm2StarLayerMask: 0 };
    const rt = {
      engineAnm2BlobReady: 1,
      engineAnm2LatchReady: 1,
      engineAnm2Latch: 0,
      engineAnm2LayerCount: 0,
      engineAnm2ExtraCount: 0,
      engineAnm2Bitflags110Pre: 0,
      ...over,
    };
    applyEngineAnm2LoadLane(st, rt, ev);
    return { st, ev };
  };
  const empty = run({});
  assert.equal(empty.st.engineAnm2Loaded, 1, "S1 unconditional");
  assert.equal(empty.st.engineAnm2Slot10c, 0xffffffff, "S2 unconditional");
  assert.equal(empty.st.engineAnm2Bitflags110, 0, "S5/S6 conditional -> untouched");
  assert.equal(empty.ev.engineAnm2StarLayerMask, 0, "S4 conditional -> no mask");
  const shadow = run({ engineAnm2LayerCount: 1, engineAnm2LayerNames: ["shadow"] });
  assert.equal(shadow.st.engineAnm2Slot10c, 0, "S3 fires (index 0)");
  assert.equal(shadow.st.engineAnm2Bitflags110, 0, "no star -> no S5");
  const plain = run({ engineAnm2LayerCount: 1, engineAnm2LayerNames: ["x"] });
  assert.equal(plain.st.engineAnm2Slot10c, 0xffffffff, "no shadow -> S3 does NOT fire");
  const star = run({
    engineAnm2LayerCount: 1,
    engineAnm2ExtraCount: 1,
    engineAnm2LayerNames: ["*l"],
    engineAnm2ExtraNames: ["*e"],
  });
  assert.equal(star.ev.engineAnm2StarLayerMask, 1, "S4 star-layer mask bit");
  assert.equal(star.st.engineAnm2Bitflags110, 0x400 | 0x800, "S5 | S6");
  assert.equal(star.st.engineAnm2Slot10c, 0xffffffff, "S3 off (no shadow)");
});

test("ABI v95: the shipped Wasm agrees with the oracle on the frame laws", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  const pathPresent = pick("isaac_game_update_slice_engine_anm2_load_path_present");
  const pathIsSelf = pick("isaac_game_update_slice_engine_anm2_load_path_is_self");
  const graphicsNeeded = pick("isaac_game_update_slice_engine_anm2_load_graphics_needed");
  const frameHostCalls = pick("isaac_game_update_slice_engine_anm2_load_frame_host_calls");
  const siteHostCalls = pick("isaac_game_update_slice_engine_anm2_load_site_host_calls");
  for (const n of ["path_present", "path_is_self", "graphics_needed",
                   "frame_host_calls", "site_host_calls"]) {
    assert.equal(typeof pick(`isaac_game_update_slice_engine_anm2_load_${n}`),
      "function", `export ${n} missing`);
  }
  /* Values cross UNMASKED — the module must narrow, never the harness. */
  for (const v of [0, 1, 0x100, 0x1ff, 0xffffff00, 0xffffffff]) {
    assert.equal(pathPresent(v), engineAnm2LoadPathPresent(v),
      `path_present 0x${v.toString(16)}`);
    assert.equal(graphicsNeeded(v), engineAnm2LoadGraphicsNeeded(v),
      `graphics_needed 0x${v.toString(16)}`);
  }
  for (const [a, b] of [[0x1b874, 0x12345678], [0x1b874, 0x1b874],
                        [0, 1], [0xffffffff, 0xffffffff]]) {
    assert.equal(pathIsSelf(a, b), engineAnm2LoadPathIsSelf(a, b),
      `is_self ${a}==${b}`);
  }
  for (const [p, a, b, g] of [[0, 0x1b874, 0x12345678, 1],
                              [0x1d, 0x1b874, 0x12345678, 1],
                              [0, 0x1b874, 0x1b874, 1],
                              [0x1d, 0x1b874, 0x1b874, 0],
                              [0, 0x1b874, 0x12345678, 0xffffff00]]) {
    assert.equal(frameHostCalls(p, a, b, g), engineAnm2LoadFrameHostCalls(p, a, b, g),
      `frame_host_calls (${p},${a},${b},${g})`);
  }
  assert.equal(siteHostCalls(), engineAnm2LoadSiteHostCalls(), "site law");
});

test("ABI v95: build whitelist, header uint32_t, JSON record 21 land", () => {
  const build = readFileSync(
    join(root, "scripts", "decomp", "build-game-update-slice.mjs"),
    "utf8",
  );
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const spec = JSON.parse(
    readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"),
  );
  for (const n of ["engine_anm2_load_path_present", "engine_anm2_load_path_is_self",
                   "engine_anm2_load_graphics_needed",
                   "engine_anm2_load_frame_host_calls",
                   "engine_anm2_load_site_host_calls"]) {
    assert.match(build, new RegExp(`_isaac_game_update_slice_${n}`), `build whitelist ${n}`);
    assert.match(header, new RegExp(`isaac_game_update_slice_${n}`), `header decl ${n}`);
    assert.match(source, new RegExp(`isaac_game_update_slice_${n}`), `cpp export ${n}`);
  }
  /* No uint8_t scalar parameter may exist on the new exports. */
  for (const n of ["engine_anm2_load_path_present", "engine_anm2_load_path_is_self",
                   "engine_anm2_load_graphics_needed",
                   "engine_anm2_load_frame_host_calls"]) {
    assert.ok(
      !new RegExp(`isaac_game_update_slice_${n}\\(\\s*uint8_t`).test(header),
      `${n} must take uint32_t`,
    );
  }
  /* JSON: the 5 helper proofs + record idx 21 evidence mention v95. */
  const helperNames = spec.translatedHelpers.map((h) => h.name);
  for (const n of ["isaac_game_update_slice_engine_anm2_load_path_present",
                   "isaac_game_update_slice_engine_anm2_load_path_is_self",
                   "isaac_game_update_slice_engine_anm2_load_graphics_needed",
                   "isaac_game_update_slice_engine_anm2_load_frame_host_calls",
                   "isaac_game_update_slice_engine_anm2_load_site_host_calls"]) {
    assert.ok(helperNames.includes(n), `JSON helper proof ${n}`);
  }
  /* v98: record 22 was REMOVED — the v95/v97 evidence rides the
     resolvedBoundaries entry (name-match). */
  const rec21 = spec.resolvedBoundaries.find(
    (b) => b.name === "opaqueRoomTransitionEnginePrefix",
  );
  assert.ok(rec21, "resolvedBoundaries carries the ANM2::Load record");
  assert.match(rec21.evidence, /v95/);
});

test("ABI v75: the wire is declared, exported and specified on both sides", () => {
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const build = readFileSync(
    join(root, "scripts", "decomp", "build-game-update-slice.mjs"),
    "utf8",
  );
  const verifier = readFileSync(
    join(root, "scripts", "decomp", "verify-game-update-slice.mjs"),
    "utf8",
  );
  assert.match(header, /engine_anm2_latch_ready;/);
  assert.match(header, /engine_anm2_latch;/);
  assert.match(header, /isaac_game_update_slice_engine_prefix_drop_latched/);
  assert.match(source, /isaac_game_update_slice_engine_prefix_drop_latched/);
  assert.match(
    source,
    /static_assert\(offsetof\(IsaacGameUpdateSliceRuntimeInputs, engine_anm2_latch\) == 3208/,
  );
  assert.match(build, /_isaac_game_update_slice_engine_prefix_drop_latched/);
  /* The harness whitelist. Without these two lines the corpus rows below are
     delivered as ZERO and every v75 differential case is a silent no-op —
     measured three times in this repo. */
  assert.match(verifier, /engineAnm2LatchReady: corpus\[index\]\.engineAnm2LatchReady/);
  assert.match(verifier, /engineAnm2Latch: corpus\[index\]\.engineAnm2Latch/);
  /* No uint8_t scalar parameter may exist on the new export. */
  assert.ok(
    !/isaac_game_update_slice_engine_prefix_drop_latched\(\s*uint8_t/.test(header),
    "the byte gate must take uint32_t and narrow in the body",
  );
});

test("ABI v75: the v75 assertions are NOT vacuous — every claim was really driven", () => {
  /* The v70 failure mode: helpers exported, a green suite, zero behavioural
     assertions executed. Re-derive independently that each v75 claim has an
     input that exercises it AND one that contradicts it. */
  const answers = new Set();
  for (const v of [0, 1, 0x100, 0x1ff]) answers.add(enginePrefixDropLatched(v));
  assert.deepEqual([...answers].sort(), [0, 1], "the export returns BOTH values");

  /* Every census kind the trace can emit must actually have been emitted on
     some input — an unreached classification is a claim nothing tested. */
  const seen = new Set();
  for (const v of [0, 1]) {
    const c = enginePrefixResidualCensus(v);
    for (const [k, n] of Object.entries(c)) {
      if (k !== "reachedJoinVa" && n > 0) seen.add(k);
    }
  }
  for (const kind of [
    "observableStores",
    "gameLogicCalls",
    "platformCalls",
    "ownFrameStores",
    "balancedStores",
    "scratchStores",
  ]) {
    assert.ok(seen.has(kind), `${kind} was never exercised by any input`);
  }

  /* Both arms of the WIRE were really taken, and they really differ. */
  const kept = enginePrefixSite({ engineAnm2LatchReady: 1, engineAnm2Latch: 0 });
  const dropped = enginePrefixSite({ engineAnm2LatchReady: 1, engineAnm2Latch: 1 });
  assert.notDeepEqual(
    kept.events,
    dropped.events,
    "if these were equal the wire is not connected and every drop test is vacuous",
  );
  assert.equal(
    kept.events.opaqueRoomTransitionEnginePrefix -
      dropped.events.opaqueRoomTransitionEnginePrefix,
    1,
    "the difference is exactly one prefix event",
  );

  /* The site really reaches the prefix — if it did not, both arms would be 0
     and the test above would pass for the wrong reason. */
  assert.equal(
    kept.events.opaqueRoomTransitionEnginePrefix,
    1,
    "the driven site must actually reach FUN_0082ee40",
  );

  /* And the ready gate really gates: a set latch with ready = 0 must equal the
     kept arm, not the dropped one. */
  const readyOff = enginePrefixSite({ engineAnm2LatchReady: 0, engineAnm2Latch: 1 });
  assert.deepEqual(readyOff.events, kept.events, "ready = 0 is the KEPT arm");
  assert.notDeepEqual(readyOff.events, dropped.events);
});


/* ================= ABI v79: record 2 (opaqueGlobal4aba0Refresh) ========== */

/** Sentinel + chain tree in the record-2 pack shape. nodes[0] is the
    sentinel (self links, f0d 1); chain nodes follow with child = next,
    prev = previous, last child/next = sentinel. f18 per node. */
function tree4aba0Chain(f18s, f0ds) {
  const nodes = [];
  const addr = (i) => 0x1000 + i * 0x20;
  const n = f18s.length + 1; /* + sentinel */
  for (let i = 0; i < n; i += 1) {
    const isSentinel = i === 0;
    const last = n - 1;
    nodes.push({
      addr: addr(i),
      next: isSentinel ? (n > 1 ? addr(1) : addr(0)) : (i === last ? addr(0) : addr(i + 1)),
      prev: isSentinel ? addr(0) : addr(i - 1),
      child: isSentinel ? addr(0) : (i === last ? addr(0) : addr(i + 1)),
      f0d: isSentinel ? 1 : (f0ds ? f0ds[i - 1] : 0),
      f18: isSentinel ? 1 : f18s[i - 1],
    });
  }
  return nodes;
}

test("globalTree4aba0Refresh: hand-traced walk over a sentinel + chain (PE 0x006fb414..0x006fb474 + 0x00414a80)", () => {
  /* S(0x1000, f0d1) -> A(0x1020, f0d0, f18 0) -> B(0x1040, f0d1, f18 1)
     cur=A: flag += 1 (A.f18 == 0); advance: a=B f0d==0 -> c=B.next=S f0d!=0
     -> cur=B; flag += 0; advance: a=S f0d!=0 -> b=A f0d==0 ->
     B.addr != A.child(B)? equal -> node=A; b=S f0d!=0 -> cur=S. flag=1 -> 0. */
  const tree = tree4aba0Chain([0, 1], [0, 1]);
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 3, tree), 0);

  /* Same topology, both chain nodes f18 1 -> flag 0 -> byte 1. */
  const live = tree4aba0Chain([1, 1], [0, 1]);
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 3, live), 1);

  /* Empty tree (sentinel only) with a NONEMPTY Manager range: the PE's
     `cmp eax,esi / je` exits before the loop, flag stays 0 -> byte 1. */
  const onlySentinel = tree4aba0Chain([], []);
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 1, onlySentinel), 1);

  /* The advance f0d==0 side lands on a.next when the next node is LIVE
     (0x414ab7 jne -> *local = a); the run-descend only fires when a.next is
     itself dead (0x414ac0 loop to the last dead node). */
  const chain = tree4aba0Chain([1, 0, 1], [0, 0, 1]);
  /* cur=A (f18 1): advance: a=B (f0d 0); c=B.next=C live -> cur=B.
     cur=B (f18 0 -> flag 1): advance: a=C live -> b=B.prev=A (f0d 0) ->
     B.addr != A.child(B)? equal -> node=A; b=A.prev=S live -> cur=S.
     flag 1 -> byte 0. */
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 4, chain), 0);
  /* Run-descend: A.f0d 0, A.next=B dead, B.next=C dead, C.next=D live.
     cur=A -> a=B dead -> c=B.next=C dead -> loop: e=C.next=D live, d=C,
     c=D -> cur=C; C.f18 must be 0 for the flag to trip. */
  const run = tree4aba0Chain([1, 1, 0, 1], [0, 0, 0, 1]);
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 5, run), 0);

  /* The f0d!=0 side climbs prevs while node == prev.child. */
  const climb = tree4aba0Chain([0, 0], [1, 1]);
  /* cur=A (f18 0 -> flag 1): advance: a=B f0d1 -> b=A.prev=S f0d1 -> cur=S.
     flag 1 -> byte 0. */
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 3, climb), 0);
});

test("globalTree4aba0Refresh: out-of-contract blobs return -1 (monolith)", () => {
  const tree = tree4aba0Chain([0, 1], [0, 1]);
  /* begin == end: the PE skips the block; the caller never invokes the pure
     export, and the export defends anyway. */
  assert.equal(globalTree4aba0Refresh(0x100, 0x100, 3, tree), -1);
  /* count 0 / over cap. */
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 0, tree), -1);
  assert.equal(
    globalTree4aba0Refresh(0x100, 0x200, GLOBAL_TREE_4ABA0_MAX_NODES + 1, tree),
    -1,
  );
  /* dangling link: child points out of the table -> the walk cannot resolve
     the PE's advance reads -> fallback (host would re-walk the real tree). */
  const dangling = tree4aba0Chain([0, 1], [0, 1]);
  dangling[1].child = 0x9abcdef0;
  assert.equal(globalTree4aba0Refresh(0x100, 0x200, 3, dangling), -1);
});

test("step: record 2 blob-gated refresh replaces the host event on the pure arm", () => {
  const runtime = (tree) => ({
    globalTree4aba0BlobReady: 1,
    globalTree4aba0Count: 3,
    globalTree4aba0Begin: 0x100,
    globalTree4aba0End: 0x200,
    ...flattenGlobalTree4aba0NodesRuntime(tree),
  });
  const done = step({ gate1d520: 1, oneShot1d63c: 0 }, runtime(tree4aba0Chain([1, 1], [0, 1])));
  assert.equal(done.events.opaqueGlobal4aba0Refresh, 0,
    "pure arm suppresses the host event");
  assert.equal(done.state.globalTree4aba0Result, 1);
  const zero = step({ gate1d520: 1, oneShot1d63c: 0 }, runtime(tree4aba0Chain([0, 1], [0, 1])));
  assert.equal(zero.events.opaqueGlobal4aba0Refresh, 0);
  assert.equal(zero.state.globalTree4aba0Result, 0);
});

test("step: record 2 keeps v78 behavior byte-for-byte on every fallback arm", () => {
  const base = { gate1d520: 1, oneShot1d63c: 0 };
  const tree = tree4aba0Chain([0, 1], [0, 1]);
  /* No blob at all (the shipped default): the v78 unconditional host event
     and an untouched result byte. */
  const noBlob = step(base, {});
  assert.equal(noBlob.events.opaqueGlobal4aba0Refresh, 1);
  assert.equal(noBlob.state.globalTree4aba0Result, 0);
  /* Blob ready but EMPTY Manager range: the PE `je` skips the whole block —
     byte untouched, host event stays (the residual still owns the write). */
  const emptyRange = step(base, {
    globalTree4aba0BlobReady: 1,
    globalTree4aba0Count: 3,
    globalTree4aba0Begin: 0x100,
    globalTree4aba0End: 0x100,
    ...flattenGlobalTree4aba0NodesRuntime(tree),
  });
  assert.equal(emptyRange.events.opaqueGlobal4aba0Refresh, 1);
  assert.equal(emptyRange.state.globalTree4aba0Result, 0);
  /* Over-cap count and dangling links fall back identically. */
  const overCap = step(base, {
    globalTree4aba0BlobReady: 1,
    globalTree4aba0Count: GLOBAL_TREE_4ABA0_MAX_NODES + 1,
    globalTree4aba0Begin: 0x100,
    globalTree4aba0End: 0x200,
    ...flattenGlobalTree4aba0NodesRuntime(tree),
  });
  assert.equal(overCap.events.opaqueGlobal4aba0Refresh, 1);
  const dangling = tree4aba0Chain([0, 1], [0, 1]);
  dangling[1].child = 0x9abcdef0;
  const bad = step(base, {
    globalTree4aba0BlobReady: 1,
    globalTree4aba0Count: 3,
    globalTree4aba0Begin: 0x100,
    globalTree4aba0End: 0x200,
    ...flattenGlobalTree4aba0NodesRuntime(dangling),
  });
  assert.equal(bad.events.opaqueGlobal4aba0Refresh, 1);
});

