/* ================= ABI v95: TriggerDeath CALL-ARG laws (record idx 43) ====
   The PM1 death walk (PlayerManager::Update 0x009bb5d0) composes the
   pre-call pack at 0x009bb67d..0x009bb682: push 0; call 0x7a1090 with
   ecx = the LIVE cursor element. The v69 wire consumed the PM frozen death
   contract BY REFERENCE; v95 extends it with the arg-prep laws. Layout
   offsets/sizes are COORDINATOR-committed at wave end (names stay) — this
   group pins the LAW exports + wire behavior only. */

/** Run the room-update-head resume and return the arg-prep event delta. */
function deathArgPrepDelta(stateOverrides = {}, runtime = {}) {
  const base = step({});
  const shaped = { ...base.state, ...stateOverrides };
  const ev = {
    ...base.events,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD,
  };
  const pre = ev.playerManagerUpdateDeathArgPrep >>> 0;
  const out = resumeGameUpdateRoomUpdateHead(shaped, runtime, ev);
  assert.ok(out, "head resume returned a result");
  return (out.events.playerManagerUpdateDeathArgPrep >>> 0) - pre;
}

test("ABI v95: death_call_receiver is the walk cursor law (PE 0x9bb643 cmp/jae + 0x9bb647 lea)", () => {
  /* count2 = (end-begin) >> 2 SAR; u32 index < u32 count2 -> begin +
     index*4, else begin (element 0 dereferenced, NEVER skipped). */
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1010, 0), 0x1000);
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1010, 1), 0x1004);
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1010, 2), 0x1008);
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1010, 3), 0x100c);
  /* index == count -> OOB -> begin stays (the PE jae leaves the cursor at
     the vector base: element 0 is loaded and tested, never skipped). */
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1010, 4), 0x1000);
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1010, 5), 0x1000);
  /* WIDE index 0xffffffff: u32-huge -> OOB -> begin. */
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1010, 0xffffffff), 0x1000);
  /* Empty span (count 0): every index OOB -> begin. */
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1000, 0), 0x1000);
  assert.equal(gameUpdateSliceDeathCallReceiver(0x1000, 0x1000, 3), 0x1000);
  /* Wrapped span (end < begin): (end-begin) wraps; count is NEGATIVE
     (sar) -> u32 count huge -> index in-range -> begin + index*4. */
  assert.equal(gameUpdateSliceDeathCallReceiver(0x2000, 0x1000, 1), 0x2004);
  /* Pointer wrap on begin + index*4. */
  assert.equal(gameUpdateSliceDeathCallReceiver(0xfffffff0, 0x10000000, 1), 0xfffffff4);
});

test("ABI v95: receiver law cross-pins to the PM family walk cursor (consumed by reference)", () => {
  const cases = [
    [0x1000, 0x1010, 0], [0x1000, 0x1010, 4], [0x1000, 0x1000, 0],
    [0x2000, 0x1000, 1], [0xfffffff0, 0x10000000, 1], [0x1000, 0x1010, 0xffffffff],
    [0x0, 0x40, 3], [0x0, 0x40, 16], [0x7fffffff, 0x80000003, 2],
    [0x80000000, 0x80000010, 4], [0xfffffffc, 0x4, 1],
  ];
  for (const [begin, end, index] of cases) {
    const span = (((end >>> 0) - (begin >>> 0)) >>> 0) << 0;
    const count2 = pmPlayerCountFromSpan(span);
    const cursor = pmWalkElemCursor(begin, index, count2);
    assert.equal(
      gameUpdateSliceDeathCallReceiver(begin, end, index),
      cursor,
      `receiver(${begin},${end},${index}) must equal the PM walk cursor`,
    );
  }
});

