test("ABI v95: death arg-prep exports declared on all sides + v69 no-expansion pin kept", () => {
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const build = readFileSync(join(root, "scripts", "decomp", "build-game-update-slice.mjs"), "utf8");
  for (const name of [
    "isaac_game_update_slice_death_call_receiver",
    "isaac_game_update_slice_death_call_flag",
    "isaac_game_update_slice_death_call_arg_prep",
  ]) {
    assert.match(header, new RegExp(name), `${name} declared in header`);
    assert.match(source, new RegExp(name), `${name} defined in cpp`);
    assert.match(build, new RegExp("_" + name), `${name} exported by the build`);
  }
  assert.match(source, /frame_opaque_98dba0_walk_ready/);
  assert.match(source, /player_manager_update_death_arg_prep/);
  assert.match(header, /player_manager_update_death_arg_prep/);
  assert.match(source, /ISAAC_PM_DEATH_RESIDUAL_WALK/);
  /* The v69 no-expansion pin survives v95. */
  assert.doesNotMatch(source, /eligible_mask\s*&\s*\(1u?\s*<</);
});

