test("ABI v95: the shipped Wasm agrees with the listener oracles when the module is current", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (pre-v95); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const cnt = pick("isaac_game_update_slice_8ef990_listener_count");
  const find = pick("isaac_game_update_slice_8ef990_listener_find");
  const arm = pick("isaac_game_update_slice_8ef990_listener_arm_accept");
  const walk = pick("isaac_game_update_slice_8ef990_listener_walk_accept");
  assert.equal(typeof cnt, "function", "listener_count missing from the module");
  assert.equal(typeof find, "function", "listener_find missing from the module");
  assert.equal(typeof arm, "function", "listener_arm_accept missing from the module");
  assert.equal(typeof walk, "function", "listener_walk_accept missing from the module");
  /* Values cross UNMASKED — the MODULE must narrow, never the harness. The
     pointer-arg laws need the coordinator's layout commit to place the
     capture arrays; this probe pins the scalar count law + presence. */
  for (const [b, e] of [[0x1000, 0x1000], [0x1000, 0x1007], [0x1000, 0x1008], [0x1000, 0x1100], [0xfffffff0, 0x10]]) {
    assert.equal(cnt(b, e) | 0, gameUpdateSlice8ef990ListenerCount(b, e),
      `wasm listener_count(0x${(b >>> 0).toString(16)}, 0x${(e >>> 0).toString(16)})`);
  }
});

/* ================= ABI v95: record idx 9 FINAL IRREDUCIBLE assessment
   (unit update-v95-8ef990-assessment, wave-19) ======================
   The [0xc57b18] virtual Notify accept gate was v94-probed NEGATIVE
   (IRREDUCIBLE — no removal). The record must stay counted with the
   operation NARROWED-not-removed, the wave-18 v95 evidence intact, and
   the final assessment carrying the exact PE evidence: the six dispatch
   sites 0x8efa1f/0x8efa4f/0x8efa8f/0x8efb31/0x8efbd2/0x8efc45
   (call [eax+0x74], eax=[0xc57b18]), the walk 0xa20fb0, the callback
   0xa209e0, the find wrapper 0xa205a0, the [0xc7e814] hook, TAIL-A
   0x8efcea (SFX slot [0xc7169c]+0x4b3d8 @0x8efcf4) and the JOIN
   0x8efc92. Mutants: stripping "assessment" or flipping the operation
   both fail this test. */
test("ABI v95: record-9 final IRREDUCIBLE assessment is pinned in the JSON record", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const rec = spec.opaqueBoundaries.find((b) => b.idx === 9);
  assert.ok(rec, "record idx 9 exists");
  assert.equal(rec.name, "opaqueState24eccUpdate");
  assert.equal(rec.targetVa, "0x008ef990");
  assert.equal(rec.operation, "NARROWED not removed STAYS");
  assert.equal(spec.opaqueBoundaries.length, 24, "count 26 -> 25 (record idx 27 roomTriggerClearAudio REMOVED at ABI v138, update-v138-audio-alt-tail-pack); count 27 -> 26 (record idx 26 roomTriggerClearAudioNonGreed REMOVED at ABI v136, update-v136-audio-head-pack); count 32 -> 31 (record idx 45 REMOVED at v128, 18th removal since v79); count 33 -> 32 (record idx 38 REMOVED at v127, 17th removal since v79); count 34 -> 33 (record idx 40 REMOVED at v126, 16th removal since v79); count 35 -> 34 (record idx 25 REMOVED at v125, 15th removal since v79); count 36 -> 35 (record idx 46 REMOVED at v124, 14th removal since v79); v122 removed record idx 19 (37 -> 36); v121 removed record idx 47 (38 -> 37); v120 removed record idx 41 (39 -> 38); v119 removed records idx 24 + idx 33 (41 -> 39); v115 removed record idx 23 (42 -> 41); v114 removed record idx 42 (43 -> 42); v110 removed record idx 16 (44 -> 43); v109 removed record idx 12 (45 -> 44); v108 removed record idx 39 (46 -> 45); otherwise no removal — v94 probes negative; v98 removed record 22; v99 removed record idx 10; v100 removed record idx 1");
  /* wave-18 v95 capture-contract evidence stays intact. */
  assert.match(rec.abiV95 || "", /c57b18|listener|a20fb0|0xa209e0/);
  assert.match(rec.abiV95 || "", /NARROWED not removed|STAYS/);
  /* final assessment carries the exact PE evidence. */
  const a = rec.assessment || "";
  assert.match(a, /IRREDUCIBLE/);
  assert.match(a, /v94 probes negative/);
  for (const va of ["0x8efa1f", "0x8efa4f", "0x8efa8f", "0x8efb31", "0x8efbd2", "0x8efc45"]) {
    assert.ok(a.includes(va), `dispatch site ${va} in the assessment`);
  }
  assert.ok(a.includes("0xa20fb0"), "walk law VA in the assessment");
  assert.ok(a.includes("0xa209e0"), "callback VA in the assessment");
  assert.ok(a.includes("0xa205a0"), "find-wrapper VA in the assessment");
  assert.ok(a.includes("0xc7e814"), "hook VA in the assessment");
  assert.ok(a.includes("0x8efcea"), "TAIL-A entry in the assessment");
  assert.ok(a.includes("0x8efcf4"), "SFX-slot gate in the assessment");
  assert.ok(a.includes("0x8efc92"), "JOIN entry in the assessment");
  assert.ok(a.includes("0x8efdec"), "state==2 arm PE in the assessment");
  assert.ok(a.includes("0x92dc30"), "SFXManager::Play in the assessment");
  assert.match(a, /MAXIMUM narrowing landed/);
  assert.match(a, /STAYS NARROWED not removed/);
});

/* ================= ABI v95: record idx 3 (0x0092f1c0) case-arm pure laws ======
   Full-body instruction stream (0x92f1c0..0x92ffa3, dumps 0092f1c0.txt /
   0092f4bd.txt / 0092fa00.txt / 0092fb40.txt / 0092fe46.txt):
     0x92f1f0 mov eax,[ebx] ; 0x92f1f2 dec eax ; 0x92f1f3 cmp eax,3 ;
     0x92f1f6 ja 0x92ff60 ; 0x92f1fc jmp [eax*4+0x92ffa4]  (FULL-DWORD switch)
     case 0 (mode==1) 0x92f203: 0x92f231 call 0x4186c0 (Room+0x1218, push 1)
        UNCONDITIONAL before any eligibility -> ALWAYS HOST
     case 1 (mode==2) 0x92fa09: 0x92fa0f cmp edx,ecx / 0x92fa11 jb (unsigned
        counter<limit) -> 0x92fd7e; reset arm [recv+4]=0 [recv]=3 (+limit=8 ->
        0xf) + big body; 0x92fd7e..0x92fd83 counter==limit-2 -> host arm;
        0x92fe46..0x92fe4b counter==limit-1 -> 0x92fe51 byte [recv+0x14] test /
        0x92fe55 jne -> TAIL; else[jne] -> TAIL; field14 low 0 -> 0x74f090
        call -> host
     case 2 (mode==3) 0x92fe88: counter==2 && [recv+0x14] low != 0 ->
        call 0x7eb1b0 (host), counter RE-READ; 0x92feaa cmp eax,[ebx+8] /
        0x92fead jb (unsigned counter<limit) -> TAIL; else [recv]=4 [recv+4]=0
        call 0x746560 (host)
     case 3 (mode==4) 0x92fed2: 0x92fee9 call 0x4186c0 UNCONDITIONAL ->
        ALWAYS HOST
     tail 0x92ff60..0x92ff7e: inc [recv+4] (32-bit wrap); mode-after 2/3 ->
        [Game+0x22ed4]=2 [Game+0x22edc]=2 */

test("ABI v95: 92f1c0 dispatch_case is the FULL-DWORD switch index (PE 0x92f1f0..0x92f1fc)", () => {
  /* PE truth: (u32)(mode-1) > 3 -> jmp default 0x92ff60 (tail), else
     jmp [eax*4+0x92ffa4] with cases {0x92f203,0x92fa09,0x92fe88,0x92fed2}. */
  for (const [mode, want] of [[1, 0], [2, 1], [3, 2], [4, 3]]) {
    assert.equal(gameUpdateSlice92f1c0DispatchCase(mode), want, `mode=${mode}`);
  }
  for (const mode of [0, 5, 0x100, 0x101, 0x104, 0x1000004, 0x20000001, 0x1ff0002, 0xffffffff]) {
    assert.equal(gameUpdateSlice92f1c0DispatchCase(mode), -1,
      `mode=0x${(mode >>> 0).toString(16)}: full-word (mode-1)>3 -> default tail`);
  }
});

test("ABI v95: 92f1c0 cases 0 and 3 are NEVER pure (unconditional 0x4186c0 before eligibility)", () => {
  /* PE 0x92f231 / 0x92fee9: mov ecx,[Game+0x18300]; add ecx,0x1218;
     call 0x4186c0 — NO branch precedes. Any counter/limit/field_14 still
     hosts (the interior update mutates Room on EVERY entry). */
  for (const mode of [1, 4]) {
    for (const rt of [
      { counter: 0, limit: 0xffffffff, field14: 0 },
      { counter: 2, limit: 100, field14: 0x1ff },
      { counter: 0xffffffff, limit: 0, field14: 0x100 },
    ]) {
      assert.equal(gameUpdateSlice92f1c0TryPure({ mode, ...rt }), 0,
        `mode=${mode} must host (${JSON.stringify(rt)})`);
    }
  }
});

test("ABI v95: 92f1c0 case-1 (mode 2) pure-tail law — UNSIGNED counter/limit compares", () => {
  /* PE-truth: counter >= limit (jb not taken) -> reset arm host; counter ==
     limit-2 -> host; counter == limit-1 && field14 low 0 -> 0x74f090 host;
     else pure tail (0x92fe4b jne / 0x92fe55 jne -> 0x92ff60). */
  const pure = [
    /* counter < limit-2 */
    { counter: 5, limit: 100, field14: 0x0 }, { counter: 0, limit: 3, field14: 0x100 },
    { counter: 0, limit: 0xffffffff, field14: 0 },
    /* counter == limit-1 with field14 low byte set (PE 0x92fe51 jne) */
    { counter: 99, limit: 100, field14: 0x1ff }, { counter: 0, limit: 1, field14: 0xff },
  ];
  for (const rt of pure) {
    assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 2, ...rt }), 1,
      `pure ${JSON.stringify(rt)}`);
  }
  const host = [
    /* reset arm: counter >= limit (jb false) — a SIGNED compare would
       mis-read 0xffffffff < 0 as true (mutant discriminator) */
    { counter: 0xffffffff, limit: 0, field14: 0 },
    { counter: 100, limit: 100, field14: 0x1ff },
    /* limit-2 arm */
    { counter: 98, limit: 100, field14: 0x1ff }, { counter: 0, limit: 2, field14: 0xff },
    /* limit-1 arm with field14 low byte 0 -> 0x74f090 call (host) */
    { counter: 99, limit: 100, field14: 0x0 }, { counter: 99, limit: 100, field14: 0x100 },
  ];
  for (const rt of host) {
    assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 2, ...rt }), 0,
      `host ${JSON.stringify(rt)}`);
  }
});

test("ABI v95: 92f1c0 case-1 field_14 is the machine's BYTE test (WIDE drives)", () => {
  /* PE 0x92fe51 cmp byte ptr [ebx+0x14],0 / 0x92fe55 jne: the LOW byte
     decides. 0x100/0x1ff behave by their low byte (0 / 0xff). */
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 2, counter: 99, limit: 100, field14: 0x100 }), 0,
    "field14=0x100 low byte 0 -> 0x74f090 arm hosts");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 2, counter: 99, limit: 100, field14: 0x1ff }), 1,
    "field14=0x1ff low byte 0xff -> jne tail, pure");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 2, counter: 99, limit: 100, field14: 0xffffffff }), 1,
    "field14=0xffffffff low byte 0xff -> pure");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 2, counter: 99, limit: 100, field14: 0 }), 0,
    "field14=0 low byte 0 -> host");
});

test("ABI v95: 92f1c0 case-2 (mode 3) pure-tail law — 0x7eb1b0 exclusion + UNSIGNED limit", () => {
  /* PE-truth: counter==2 && [recv+0x14] low != 0 -> call 0x7eb1b0 (host,
     counter re-read after); counter >= limit -> [recv]=4 + call 0x746560
     (host); else pure tail (0x92fead jb -> 0x92ff60). */
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 3, counter: 2, limit: 100, field14: 0x1ff }), 0,
    "counter==2 && field14 low 1 -> 0x7eb1b0 host");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 3, counter: 2, limit: 100, field14: 0x100 }), 1,
    "counter==2 && field14 low 0 -> no 0x7eb1b0; counter<limit -> pure");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 3, counter: 7, limit: 100, field14: 0x1ff }), 1,
    "counter!=2, counter<limit -> pure");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 3, counter: 0xffffffff, limit: 100, field14: 0 }), 0,
    "counter >= limit (unsigned!) -> 0x746560 host (signed mutant would diverge)");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 3, counter: 2, limit: 2, field14: 0x1ff }), 0,
    "counter==2 && field14 low 1 && counter>=limit -> BOTH leaves (host)");
  assert.equal(gameUpdateSlice92f1c0TryPure({ mode: 3, counter: 0, limit: 0xffffffff, field14: 0 }), 1,
    "counter=0 < limit=0xffffffff (unsigned) -> pure");
});

test("ABI v95: 92f1c0_counter_next wraps at 32 bits (PE 0x92ff60 inc dword [ebx+4])", () => {
  assert.equal(gameUpdateSlice92f1c0CounterNext(7), 8);
  assert.equal(gameUpdateSlice92f1c0CounterNext(0x7fffffff), -2147483648, "0x7fffffff+1 wraps to INT32_MIN");
  assert.equal(gameUpdateSlice92f1c0CounterNext(-1) >>> 0, 0, "-1+1 wraps to 0");
});

test("ABI v95: 92f1c0HostLeaf codes match the typed host-leaf table", () => {
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 1 }), 1, "case 0: uncond 0x4186c0");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 4 }), 2, "case 3: uncond 0x4186c0");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 2, counter: 100, limit: 100 }), 3, "case 1 reset arm");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 2, counter: 98, limit: 100 }), 4, "case 1 limit-2 arm");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 2, counter: 99, limit: 100, field14: 0 }), 5, "case 1 0x74f090 arm");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 3, counter: 2, limit: 100, field14: 0x1ff }), 1, "case 2 0x7eb1b0");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 3, counter: 100, limit: 100 }), 2, "case 2 0x746560");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 3, counter: 2, limit: 2, field14: 0x1ff }), 3, "case 2 both");
  assert.equal(gameUpdateSlice92f1c0HostLeaf({ mode: 0 }), 0, "out-of-dispatch -> 0");
});

test("ABI v95: 92f1c0 case-1/2 pure tails drop the host edge and apply ONLY the tail", () => {
  const rt = (extra = {}) => ({
    opaque0092f1c0Ready: 1, opaque0092f1c0Mode: 2,
    opaque0092f1c0Counter: 5, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0,
    ...extra,
  });
  const out = step({ gate1ba78: 1, status22ed4: 0, status22edc: 0 }, rt());
  assert.equal(out.events.opaqueCall0092f1c0, 0, "mode 2 counter<limit-2 -> pure tail");
  assert.equal(out.events.continuationKind, UPDATE_CONTINUATION.RETURN_AFTER_GATE_1BA78);
  assert.equal(out.events.opaque0092f1c0CounterOut, 6, "tail counter inc");
  assert.equal(out.events.opaque0092f1c0Case, 0, "no typed event on the pure path");
  assert.equal(out.events.opaque0092f1c0HostLeaf, 0);
  /* mode-after 2 -> the tail stores Game+0x22ed4/0x22edc = 2 (PE 0x92ff6f:
     cmp eax,3/je + cmp eax,2/jne — mode 2 passes). */
  assert.equal(out.state.status22ed4, 2, "mode-after 2 -> status stores");
  assert.equal(out.state.status22edc, 2);
  const c2 = step({ gate1ba78: 1, status22ed4: 0, status22edc: 0 }, rt({
    opaque0092f1c0Mode: 3, opaque0092f1c0Counter: 2, opaque0092f1c0Field14: 0x100,
  }));
  assert.equal(c2.events.opaqueCall0092f1c0, 0, "mode 3 counter<limit && field14 low 0 -> pure tail");
  assert.equal(c2.events.opaque0092f1c0CounterOut, 3);
  assert.equal(c2.state.status22ed4, 2, "mode-after 3 -> status stores");
});

/* v109 dedupe (pairs 2/3, INTENTIONAL seams): 0x801ee0 Update/Room and
   0x92f1c0 Update/HUD are documented dual exports — the Update slice owns
   the in-module path (ABI 99 wire uses gameUpdateSliceTailmid801ee0* /
   gameUpdateSlice92f1c0* locally and relays the host-side tailmid laws to
   isaac_room_tailmid_801ee0_* BY NAME), while the Room/HUD law mirrors
   serve their own suites. Nothing is removed; both sides stay pinned to
   the SAME PE truth. Cross-family pin: Update laws == Room/HUD mirrors. */
test("v109 INTENTIONAL seam: 0x801ee0 update tailmid laws == room mirror", () => {
  assert.equal(
    gameUpdateSliceTailmid801ee0IsGreedMode(2),
    roomTailmid801ee0IsGreedMode(2),
    "is_greed_mode difficulty 2",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0IsGreedMode(3),
    roomTailmid801ee0IsGreedMode(3),
    "is_greed_mode difficulty 3",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0IsGreedMode(1),
    roomTailmid801ee0IsGreedMode(1),
    "is_greed_mode difficulty 1",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0BossCount(0x12c0, 0x12c4),
    roomTailmid801ee0BossCount(0x12c0, 0x12c4),
    "boss_count",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0TimerSet13(),
    roomTailmid801ee0TimerSet13(),
    "timer_set_13",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0DescClearBit40(0x55),
    roomTailmid801ee0DescClearBit40(0x55),
    "desc_clear_bit40",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0GameFlagOr1000(0x100),
    roomTailmid801ee0GameFlagOr1000(0x100),
    "game_flag_or_1000",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0NeedsTimerReset(0x14, 0),
    roomTailmid801ee0NeedsTimerResetHost(0x14, 0),
    "needs_timer_reset",
  );
  assert.equal(
    gameUpdateSliceTailmid801ee0NeedsSpawnWave(0, 1),
    roomTailmid801ee0NeedsSpawnWaveHost(0, 1),
    "needs_spawn_wave",
  );
});

test("v109 INTENTIONAL seam: 0x92f1c0 update dispatch laws == hud mirror", () => {
  for (const mode of [0, 1, 2, 3, 4, 0xffffffff]) {
    assert.equal(
      gameUpdateSlice92f1c0DispatchCase(mode),
      hudGate92f1c0DispatchCase(mode),
      `dispatch_case mode ${mode}`,
    );
  }
  for (const counter of [0, 1, 7, 0x7fffffff, -1]) {
    assert.equal(
      gameUpdateSlice92f1c0CounterNext(counter),
      hudGate92f1c0CounterNext(counter),
      `counter_next ${counter}`,
    );
  }
  /* try_pure: the update wire's 8318a0 gate calls the HUD law by
     reference (v87); mode-only forms must agree on the dispatch. */
  for (const mode of [0, 1, 2, 3, 4]) {
    assert.equal(
      gameUpdateSlice92f1c0TryPure({ mode, counter: 0, limit: 0, field14: 0 }) !== 0,
      hudGate92f1c0TryPure(mode),
      `try_pure mode ${mode}`,
    );
  }
});

test("ABI v95: 92f1c0 host arms publish the typed dispatch + leaf events (ready!=0)", () => {
  const run = (extra) => step({ gate1ba78: 1 },
    { opaque0092f1c0Ready: 1, ...extra });
  const c0 = run({ opaque0092f1c0Mode: 1, opaque0092f1c0Counter: 7, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0 });
  assert.equal(c0.events.opaqueCall0092f1c0, 1);
  assert.equal(c0.events.opaque0092f1c0Case, 0, "case 0 dispatch");
  assert.equal(c0.events.opaque0092f1c0HostLeaf, 1, "case 0 uncond 0x4186c0");
  const c3 = run({ opaque0092f1c0Mode: 4, opaque0092f1c0Counter: 7, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0 });
  assert.equal(c3.events.opaque0092f1c0Case, 3, "case 3 dispatch");
  assert.equal(c3.events.opaque0092f1c0HostLeaf, 2, "case 3 uncond 0x4186c0");
  const reset = run({ opaque0092f1c0Mode: 2, opaque0092f1c0Counter: 100, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0x1ff });
  assert.equal(reset.events.opaque0092f1c0Case, 1);
  assert.equal(reset.events.opaque0092f1c0HostLeaf, 3, "case 1 reset arm");
  const l2 = run({ opaque0092f1c0Mode: 2, opaque0092f1c0Counter: 98, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0x1ff });
  assert.equal(l2.events.opaque0092f1c0HostLeaf, 4, "case 1 limit-2 arm");
  const l1 = run({ opaque0092f1c0Mode: 2, opaque0092f1c0Counter: 99, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0 });
  assert.equal(l1.events.opaque0092f1c0HostLeaf, 5, "case 1 0x74f090 arm");
  const s1 = run({ opaque0092f1c0Mode: 3, opaque0092f1c0Counter: 2, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0x1ff });
  assert.equal(s1.events.opaque0092f1c0HostLeaf, 1, "case 2 0x7eb1b0");
  const s2 = run({ opaque0092f1c0Mode: 3, opaque0092f1c0Counter: 100, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0 });
  assert.equal(s2.events.opaque0092f1c0HostLeaf, 2, "case 2 0x746560");
  const both = run({ opaque0092f1c0Mode: 3, opaque0092f1c0Counter: 2, opaque0092f1c0Limit: 2, opaque0092f1c0Field14: 0x1ff });
  assert.equal(both.events.opaque0092f1c0HostLeaf, 3, "case 2 both");
  assert.equal(both.events.continuationKind, UPDATE_CONTINUATION.RESUME_AFTER_92F1C0);
});

test("ABI v95: 92f1c0 ready=0 keeps the pre-v95 always-host edge with NO typed events", () => {
  const out = step({ gate1ba78: 1 }, {
    opaque0092f1c0Ready: 0, opaque0092f1c0Mode: 1,
    opaque0092f1c0Counter: 7, opaque0092f1c0Limit: 100, opaque0092f1c0Field14: 0,
  });
  assert.equal(out.events.opaqueCall0092f1c0, 1, "ready=0 hosts (v86 lockstep)");
  assert.equal(out.events.opaque0092f1c0Case || 0, 0, "ready=0 never publishes typed events");
  assert.equal(out.events.opaque0092f1c0HostLeaf || 0, 0);
});

test("ABI v95: JSON record 0x0092f1c0 names the case-arm laws and stays counted", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const rec = spec.opaqueBoundaries.find((b) => b.targetVa === "0x0092f1c0");
  assert.ok(rec, "record stays in opaqueBoundaries");
  assert.equal(spec.opaqueBoundaries.length, 24);
  assert.match(rec.abiV95 || "", /0x4186c0|try_pure|pure-tail|case-arm/i);
  assert.match(rec.abiV95 || "", /[Nn]arrowed not removed|[Nn]ARROWED not removed|STAYS/);
  assert.ok(spec.runtimeInputs.some((i) => i.name === "opaque0092f1c0Limit"));
  assert.ok(spec.runtimeInputs.some((i) => i.name === "opaque0092f1c0Field14"));
  assert.ok(spec.events.some((e) => e.name === "opaque0092f1c0Case"));
  assert.ok(spec.events.some((e) => e.name === "opaque0092f1c0HostLeaf"));
  assert.ok(spec.translatedHelpers.some((t) => t.name === "isaac_game_update_slice_92f1c0_dispatch_case"));
  assert.ok(spec.translatedHelpers.some((t) => t.name === "isaac_game_update_slice_92f1c0_try_pure"));
  assert.ok(spec.translatedHelpers.some((t) => t.name === "isaac_game_update_slice_92f1c0_counter_next"));
});

