test("ABI v95: the shipped Wasm agrees with the 92f1c0 oracles when the module is current", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (pre-v95); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const dc = pick("isaac_game_update_slice_92f1c0_dispatch_case");
  const tp = pick("isaac_game_update_slice_92f1c0_try_pure");
  const cn = pick("isaac_game_update_slice_92f1c0_counter_next");
  if (typeof dc !== "function" || typeof tp !== "function" || typeof cn !== "function") {
    t.skip("the module predates the record-3 exports (mid-wave partial build); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  for (const mode of [1, 2, 3, 4, 0, 5, 0x100, 0x101, 0xffffffff]) {
    assert.equal(dc(mode) | 0, gameUpdateSlice92f1c0DispatchCase(mode),
      `wasm dispatch_case(0x${(mode >>> 0).toString(16)})`);
  }
  for (const rt of [
    { mode: 2, counter: 5, limit: 100, field14: 0 },
    { mode: 2, counter: 99, limit: 100, field14: 0x100 },
    { mode: 2, counter: 99, limit: 100, field14: 0x1ff },
    { mode: 2, counter: 0xffffffff, limit: 0, field14: 0 },
    { mode: 3, counter: 2, limit: 100, field14: 0x1ff },
    { mode: 3, counter: 7, limit: 100, field14: 0 },
    { mode: 3, counter: 0, limit: 0xffffffff, field14: 0 },
    { mode: 1, counter: 0, limit: 0xffffffff, field14: 0 },
    { mode: 4, counter: 7, limit: 100, field14: 0x1ff },
    { mode: 0, counter: 7, limit: 100, field14: 0 },
  ]) {
    assert.equal(tp(rt.mode, rt.counter, rt.limit, rt.field14) | 0,
      gameUpdateSlice92f1c0TryPure(rt),
      `wasm try_pure(${JSON.stringify(rt)})`);
  }
  for (const c of [7, 0x7fffffff, -1, 0xffffffff]) {
    assert.equal((cn(c) | 0) >>> 0, gameUpdateSlice92f1c0CounterNext(c) >>> 0,
      `wasm counter_next(0x${(c >>> 0).toString(16)})`);
  }
});

/* ABI v116 (record idx 3 case-arm leaves, ABI 99 frozen): 0x74f090
   complete predicate + 0x7eb1b0 prefix FULL-dword mode gates.
   Mutation legend (each flipped line fails THIS group, then restored
   sha256-byte-identical — NOTES.md update-v116-92f1c0-leaves):
   - M1: type_ok UNSIGNED (type-1)>5 folded SIGNED: type 0 (dec wrap) pin dies.
   - M2: flag mask 0x10000 -> 0xff: 0x10000 open pin dies.
   - M3: mode_2c FULL-dword ==0x2c narrowed to low-byte: 0x12c pin dies.
   - M4: mode_2d FULL-dword ==0x2d narrowed to low-byte: 0x12d pin dies. */

test("ABI v116: 92f1c0 leaf 0x74f090 type/flag/result laws", () => {
  assert.equal(gameUpdateSlice74f090TypeOk(0), 0, "type 0 dec-wrap UNSIGNED >5 (M1)");
  assert.equal(gameUpdateSlice74f090TypeOk(1), 1);
  assert.equal(gameUpdateSlice74f090TypeOk(6), 1);
  assert.equal(gameUpdateSlice74f090TypeOk(7), 0);
  assert.equal(gameUpdateSlice74f090TypeOk(0x100), 0, "WIDE 0x100");
  assert.equal(gameUpdateSlice74f090TypeOk(0xffffffff), 0, "WIDE -1");
  assert.equal(gameUpdateSlice74f090Flag(0), 0);
  assert.equal(gameUpdateSlice74f090Flag(0x100), 0, "bit8 is not 0x10000");
  assert.equal(gameUpdateSlice74f090Flag(0x10000), 1, "bit16 (M2)");
  assert.equal(gameUpdateSlice74f090Flag(0x10001), 1);
  assert.equal(gameUpdateSlice74f090Flag(0xffffffff), 1);
  assert.equal(gameUpdateSlice74f090Result(2, 0x10000), 1);
  assert.equal(gameUpdateSlice74f090Result(0, 0x10000), 0, "type window closed");
  assert.equal(gameUpdateSlice74f090Result(2, 0), 0, "flag closed");
  assert.equal(gameUpdateSlice74f090Result(2, 0x100), 0, "WIDE non-bit16");
});

test("ABI v116: 92f1c0 leaf 0x7eb1b0 mode_2c/mode_2d prefix", () => {
  assert.equal(gameUpdateSlice7eb1b0Mode2c(0x2c), 1);
  assert.equal(gameUpdateSlice7eb1b0Mode2c(0), 0);
  assert.equal(gameUpdateSlice7eb1b0Mode2c(0x12c), 0, "FULL-dword 0x12c (M3)");
  assert.equal(gameUpdateSlice7eb1b0Mode2c(0x2c00), 0);
  assert.equal(gameUpdateSlice7eb1b0Mode2c(0xffffffff), 0);
  assert.equal(gameUpdateSlice7eb1b0Mode2d(0x2d), 1);
  assert.equal(gameUpdateSlice7eb1b0Mode2d(0x2c), 0);
  assert.equal(gameUpdateSlice7eb1b0Mode2d(0x12d), 0, "FULL-dword 0x12d (M4)");
  assert.equal(gameUpdateSlice7eb1b0Mode2d(0x2d00), 0);
  assert.equal(gameUpdateSlice7eb1b0Mode2d(0xffffffff), 0);
});

