/* ABI v117 (record idx 3, 0x0074f690 mode-44 stage-type helper, ABI 99
   frozen): pure decision layer around the single host GetRoomByIdx call.
   Mutation legend (each flipped line fails THIS group, then restored
   sha256-byte-identical — NOTES.md update-v117-74f690):
   - M1: entry_plan room_idx==-10 -> ==-11: CONST4 pin dies.
   - M2: entry_plan flag gate (f & 0xff) -> f !== 0: wide 0x100 pin dies.
   - M3: clamp SIGNED v <= 0 -> v === 0: 0xffffffff pin dies.
   - M4: grid_dist /13 -> /12: dist pins die.
   - M5: stage_route SIGNED s <= 6 -> (s >>> 0) <= 6: 0xffffffff pin dies.
   - M6: table lane *5 -> *6: index pins die. */

test("ABI v117: 74f690 entry_plan + clamp laws", () => {
  /* mode gate FULL-dword (PE 0x74f69c): only 0x2c enters the helper. */
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, 5, 7, 1), 3, "flag set -> STAGE");
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, 5, 7, 0), 2, "flag clear -> GETROOM host");
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, 5, 7, 0x100), 2,
    "wide flag 0x100 low byte 0 -> GETROOM (M2)");
  assert.equal(gameUpdateSlice74f690EntryPlan(0x12c, 5, 7, 1), 0, "FULL-dword mode 0x12c -> TYPE4");
  assert.equal(gameUpdateSlice74f690EntryPlan(0, 5, 7, 1), 0);
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c00, 5, 7, 1), 0);
  assert.equal(gameUpdateSlice74f690EntryPlan(0xffffffff, 5, 7, 1), 0);
  /* room_idx == -10 arm (PE 0x74f6a8): stage==7 FULL-dword -> const 4. */
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, -10, 7, 0), 1, "idx -10 stage 7 -> CONST4 (M1)");
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, -10, 8, 1), 0, "idx -10 stage 8 -> TYPE4");
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, -10, 0x107, 1), 0, "FULL-dword stage 0x107");
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, -11, 7, 1), 0, "-11 is negative, not special");
  /* SIGNED js (PE 0x74f6bf): negative -> [ebx+4]. */
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, -1, 7, 1), 0);
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, 0xffffffff, 7, 1), 0, "WIDE -1 SIGNED negative");
  assert.equal(gameUpdateSlice74f690EntryPlan(0x2c, 0x80000000, 7, 1), 0, "WIDE INT_MIN");
  /* clamp (PE 0x74f6da..0x74f6ed): SIGNED cmovle 0 / cmovl 0xa8. */
  assert.equal(gameUpdateSlice74f690ClampDescDword0(0), 0);
  assert.equal(gameUpdateSlice74f690ClampDescDword0(7), 7);
  assert.equal(gameUpdateSlice74f690ClampDescDword0(0xa7), 0xa7);
  assert.equal(gameUpdateSlice74f690ClampDescDword0(0xa8), 0xa8);
  assert.equal(gameUpdateSlice74f690ClampDescDword0(0xa9), 0xa8, "above cap clamps");
  assert.equal(gameUpdateSlice74f690ClampDescDword0(0xffffffff), 0, "WIDE -1 SIGNED <= 0 (M3)");
  assert.equal(gameUpdateSlice74f690ClampDescDword0(0x80000000), 0, "WIDE INT_MIN");
  assert.equal(gameUpdateSlice74f690ClampDescDword0(0x7fffffff), 0xa8, "WIDE INT_MAX");
});

test("ABI v117: 74f690 grid_dist + stage_route + table_type laws", () => {
  /* SIGNED /13 grid (PE 0x74f76b..0x74f7a9): |r1-r2| + |q1-q2|. */
  assert.equal(gameUpdateSlice74f690GridDist(44, 7), 5, "|5-7|+|3-0|");
  assert.equal(gameUpdateSlice74f690GridDist(26, 13), 1, "|0-0|+|2-1|");
  assert.equal(gameUpdateSlice74f690GridDist(0, 0), 0);
  assert.equal(gameUpdateSlice74f690GridDist(12, 0), 12, "r-only distance (M4)");
  assert.equal(gameUpdateSlice74f690GridDist(169, 0), 13, "q-only distance");
  assert.equal(gameUpdateSlice74f690GridDist(0xffffffff, 0), 1,
    "WIDE -1: SIGNED trunc q=0 r=-1, not floor");
  /* stage dispatch (PE 0x74f6f0 re-read POST-call; 0x74f6f5 jg SIGNED). */
  assert.equal(gameUpdateSlice74f690StageRoute(3, 7, 44), 0, "stage<=6 -> TABLE_LO");
  assert.equal(gameUpdateSlice74f690StageRoute(6, 7, 44), 0);
  assert.equal(gameUpdateSlice74f690StageRoute(0xffffffff, 7, 44), 0,
    "WIDE -1 SIGNED <= 6 -> TABLE_LO (M5)");
  assert.equal(gameUpdateSlice74f690StageRoute(7, 7, 44), 2, "womb dist 5 > 3 -> FAR HI");
  assert.equal(gameUpdateSlice74f690StageRoute(8, 27, 26), 1,
    "womb dist(26,27)=1 <= 3 -> const 4");
  assert.equal(gameUpdateSlice74f690StageRoute(7, 7, 12), 2, "dist 12 -> FAR");
  assert.equal(gameUpdateSlice74f690StageRoute(9, 7, 44), 3, "stage 9 -> TYPE4");
  assert.equal(gameUpdateSlice74f690StageRoute(0x107, 7, 44), 3, "FULL-dword stage 0x107");
  /* tables (PE 0x74f6f7..0x74f74b lo / 0x74f7c3..0x74f813 hi): a*5+c. */
  assert.equal(gameUpdateSlice74f690TableType(0, 0x3f800000, 0), 1,
    "fa=1.0 a=4, c=0 -> LO[20]=1 (M6)");
  assert.equal(gameUpdateSlice74f690TableType(2, 0x3f800000, 0), 1, "hi arm HI[20]=1");
  assert.equal(gameUpdateSlice74f690TableType(0, 0, 0), 0, "zeros -> LO[0]=0");
  assert.equal(gameUpdateSlice74f690TableType(0, 0x3f19999a, 0x3ecccccd), 1,
    "fa=0.6 a=3, fb=0.4 c=2 -> LO[17]=1");
  assert.equal(gameUpdateSlice74f690TableType(0, 0x3f800000, 0x3f800000), 5,
    "a=4 c=4 -> LO[24]=5");
  assert.equal(gameUpdateSlice74f690TableType(2, 0x3f800000, 0x3f800000), 2,
    "HI[24]=2");
  assert.equal(gameUpdateSlice74f690TableType(0, 0x3f000000, 0), 0,
    "fa=0.5 a=2 -> LO[10]=0 (K pin)");
  assert.equal(gameUpdateSlice74f690TableType(0, 0x7fc00000, 0), 0,
    "NaN folds to lane 0 (maxss semantics)");
  assert.equal(gameUpdateSlice74f690TableType(0, 0x7f800000, 0), 1,
    "+inf -> minss 4.999 -> a=4");
  assert.equal(gameUpdateSlice74f690TableType(0, 0xbf800000, 0), 0,
    "-1.0 folds to 0");
});

