/* ====== ABI v95: record idx 35 opaqueRoomUpdateTailRain (B15 rain) =========
   Loop-frame pure laws + record wire (update-slice exports; room v54/v55/B1
   laws consumed by reference). The rain spawn loop 0x00802a80..0x00802e0d:
     once-flag gate  0x00802a93  test [Game+0x1839c],0x80000 / jne skip
     corner table    0x00802aa9..0x00802b48  t[4] from Room+0xc/+0x10
     buffer gate     0x00802b50  cmp [183a4],[183a8] / je skip
     quality         0x00802b82..0x00802ba6  4/6/8 from 0x7cb6e0 result
     count           0x00802bb1..0x00802bdc  magic 0x88888889 signed idiv
                     /0x78 + UNSIGNED cmovb min
     seed0           0x00802bf0  esi = [[Room+4]+0x58]
     loop            0x00802c20..0x00802e08  xorshift carry, UNSIGNED rem
                     div, 0x78 swap (host), corner world-xy 40/120, search
                     0x813520 (host), relay 0x428b20 (pure v54) -> create
                     0x6fe410 (host), bind 0x7ef420 (host), mark 0x32c=-1
   RNG draws inside the host search are typed-host via roomGenrandNext:
   counted into b15RainGenrandDraws (cap 448), in-module MT scratch advance
   when genrand_mt_ready.
   Mutation legend (each flipped line fails THIS group, then restored
   sha256-byte-identical — see NOTES.md update-v95-802a80-rain):
   - spawn_count owner gate dropped (quality 2/3 collapse to base 4): count
     vector (1,3,0x1000,0x14c0) dies.
   - frame arg_a3 masked to low byte: the WIDE search 0x100/0x1ff verbatim
     pins die.
   - wire host_swap moved AFTER the pre-corner fatal break: the fatal-2
     vector dies.
   - wire genrand cap 448 folded to 64: the 0x100000 draw pin dies.
   - once-flag gate inverted (apply when SET): the flag-set skip pin dies. */

test("ABI v95: record idx 35 JSON spec lands the rain loop-frame laws", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const rec = spec.opaqueBoundaries.find((b) => b.idx === 35);
  assert.ok(rec, "record idx 35 stays in opaqueBoundaries");
  assert.equal(rec.operation, "HOST", "record is NARROWED-not-removed this unit");
  assert.match(rec.abiV95 || "", /0x88888889|spawn-count|loop-frame|spawn-arg|0x813520|0x7ef420|roomGenrandNext/i,
    "record idx 35 abiV95 note names the landed laws");
  for (const name of [
    "isaac_game_update_slice_b15_rain_spawn_count",
    "isaac_game_update_slice_b15_rain_frame",
    "isaac_game_update_slice_b15_rain_wire",
  ]) {
    assert.ok(spec.translatedHelpers.some((h) => h.name === name), `spec records ${name}`);
  }
  for (const name of [
    "b15RainPureSteps", "b15RainHostSearch", "b15RainHostCreate",
    "b15RainHostBind", "b15RainHostSwap", "b15RainGenrandDraws",
  ]) {
    const ev = spec.events.find((e) => e.name === name);
    assert.ok(ev, `spec records ${name}`);
    assert.equal(ev.type, "u32");
    assert.equal(ev.bytes, 4);
  }
  assert.equal(spec.opaqueBoundaries.length, 24);
});

test("ABI v95: B15 rain count law drives the PE-truth vectors", () => {
  /* PE 0x00802bb1..0x00802bdc: esi = 4; owner != 0 -> q =
     0x7cb6e0(owner); q-2==0 -> 6, q-3==0 -> 8; spawn_count =
     min_u32(base, signed (end-begin)/0x78) via magic 0x88888889. */
  assert.equal(b15RainSpawnCount(1, 3, 0x1000, 0x14c0), 8,
    "quality 3 -> base 8; 1216 bytes / 0x78 = 10 -> min 8");
  assert.equal(b15RainSpawnCount(1, 2, 0x1000, 0x1300), 6,
    "quality 2 -> base 6; 768 / 0x78 = 6 -> min 6");
  assert.equal(b15RainSpawnCount(1, 0, 0x1000, 0x11e0), 4,
    "quality 0 -> base 4; 480 / 0x78 = 4 -> min 4");
  assert.equal(b15RainSpawnCount(0, 3, 0x1000, 0x11e0), 4,
    "owner 0 -> base 4 regardless of quality");
  assert.equal(b15RainSpawnCount(1, 3, 0x1000, 0x1000), 0,
    "empty span -> byte count 0 -> min 0 (loop never enters)");
  /* cmovb is UNSIGNED: a NEGATIVE byte length wraps huge and keeps the
     quality base. */
  assert.equal(b15RainSpawnCount(1, 3, 0x1000, 0x0f00), 8,
    "negative (end-begin) is u32-huge -> unsigned min keeps quality");
  assert.equal(b15RainSpawnCount(1, 3, 0x1000, 0xf00), 8);
});

test("ABI v95: B15 rain frame law matches the PE-truth iteration", () => {
  /* seed0 0x12345678: xorshift = 1205138758, twice = 421610981 (v55 spot
     vectors). seed_corner & 3 = 1 -> corner_table[1] with w=h=10:
     c0=11, c1=18, c2=81, c3=88 -> corner 18. 18 idiv 10 -> quot 1 rem 8;
     x = 8*40+40 = 360 = 0x43b40000; y = 1*40+120 = 160 = 0x43200000. */
  const f0 = b15RainFrame({
    seedIn: 0x12345678, index: 0, spawnCount: 4, roomWC: 10, roomHC: 10,
    slotF0: 0x11111111, slotF4: 0x22222222, slotF8: 0x33333333,
    slotF34: 0x44444444, searchResult: 0x55555555,
  });
  assert.equal(f0.remaining, 4, "spawn_count - index");
  assert.equal(f0.seedShuffle >>> 0, 1205138758, "xorshift(seed0)");
  assert.equal(f0.seedCorner >>> 0, 421610981, "xorshift(seed_shuffle)");
  assert.equal(f0.seedOut >>> 0, 421610981, "seed_corner is the esi carry");
  assert.equal(f0.shuffleRem >>> 0, 2, "1205138758 % 4 (unsigned)");
  assert.equal(f0.needsSwap, 1, "rem != 0 -> swap");
  assert.equal(f0.swapIndex, 2, "index + rem");
  assert.equal(f0.slotOffset, 0, "index * 0x78");
  assert.equal(f0.swapOffset, 240, "swap_index * 0x78");
  assert.equal(f0.continueLoop, 1, "next_index 1 < 4 (signed jge)");
  assert.equal(f0.seedFatal, B15_RAIN_SEED_OK, "no fatal");
  assert.equal(f0.cornerIndex, 18, "corner_table[seed_corner & 3]");
  assert.equal(f0.worldXBits >>> 0, 0x43b40000, "x = rem*40+40 f32 bits");
  assert.equal(f0.worldYBits >>> 0, 0x43200000, "y = quot*40+120 f32 bits");
  assert.equal(f0.argA1 >>> 0, 0x11111111, "a1 = *(slot+0)");
  assert.equal(f0.argA2 >>> 0, 0x22222222, "a2 = *(slot+4)");
  assert.equal(f0.argA3 >>> 0, 0x55555555, "a3 = search_result verbatim");
  assert.equal(f0.argA4 >>> 0, 0xc7b640, "a4 = pos-vec ptr");
  assert.equal(f0.argA5, 0, "a5 = 0");
  assert.equal(f0.argA6 >>> 0, 0x33333333, "a6 = *(slot+8)");
  assert.equal(f0.argA7 >>> 0, 0x44444444, "a7 = *(slot+0x34)");
  assert.equal(f0.spawnSiteVa >>> 0, 0x00802dc4, "relay site");
  assert.equal(f0.bindVa >>> 0, 0x007ef420, "bind host");
  assert.equal(f0.entityMarkValue >>> 0, 0xffffffff, "mark 0x32c");

  /* WIDE drive: index 0x100 -> remaining negative; rem must be UNSIGNED
     (div ecx is unsigned; v55 fixed oracle). search 0xffffffff stays
     verbatim (never masked). */
  const fw = b15RainFrame({
    seedIn: 0x12345678, index: 0x100, spawnCount: 0x100, roomWC: 10,
    roomHC: 10, slotF0: 0x100, slotF4: 0x1ff, slotF8: 0xffffffff,
    slotF34: 0x80000000, searchResult: 0xffffffff,
  });
  assert.equal(fw.remaining, 0, "count 0x100 - index 0x100");
  assert.equal(fw.argA1 >>> 0, 0x100, "wide slot f0 verbatim");
  assert.equal(fw.argA2 >>> 0, 0x1ff, "wide slot f4 verbatim");
  assert.equal(fw.argA3 >>> 0, 0xffffffff, "wide search verbatim");
  /* xorshift(0) == 0 -> pre-shuffle fatal (PE 0x00802c28 assert). */
  const ff = b15RainFrame({
    seedIn: 0, index: 0, spawnCount: 4, roomWC: 10, roomHC: 10,
    slotF0: 1, slotF4: 2, slotF8: 3, slotF34: 4, searchResult: 5,
  });
  assert.equal(ff.seedFatal, B15_RAIN_SEED_FATAL_PRE_SHUFFLE, "zero seed -> fatal");
});

test("ABI v95: B15 rain wire decide runs every PE arm", () => {
  const slots = (v) => [v, v + 1, v + 2, v + 3, v + 4, v + 5, v + 6, v + 7];
  const base = {
    flags1839c: 0, ownerNonzero: 1, quality: 3, begin183a4: 0x1000,
    end183a8: 0x14c0, seed0: 0x12345678, roomWC: 10, roomHC: 10,
    slotF0: slots(0x11111111), slotF4: slots(0x22222222),
    slotF8: slots(0x33333333), slotF34: slots(0x44444444),
    searchResults: slots(0x55555555), genrandCount: 3, genrandMtReady: 1,
  };
  const p = b15RainWireDecide(base);
  assert.equal(p.onceFlagApply, 1, "flag clear at gate 0x802a93");
  assert.equal(p.bufferEmpty, 0, "buffer nonempty 0x802b50");
  assert.equal(p.spawnCount, 8, "count law");
  assert.equal(p.loopEnter, 1, "spawn_count > 0 (jle 0x802c0a)");
  assert.equal(p.steps, 8, "exactly spawn_count iterations");
  assert.equal(p.hostSearch, 8, "1 search 0x813520 per iteration");
  assert.equal(p.hostCreate, 8, "1 create 0x6fe410 per iteration");
  assert.equal(p.hostBind, 8, "1 bind 0x7ef420 per iteration");
  assert.ok(p.hostSwap >= 1 && p.hostSwap <= 8, "swaps only on needs_swap");
  assert.equal(p.seedFatal, B15_RAIN_SEED_OK, "no fatal on this seed");
  assert.equal(p.genrandDraws, 3, "typed-host genrand draws");
  assert.equal(p.genrandMtAdvance, 1, "mt ready -> in-module advance");

  /* Flag set (B1 already OR'd 0x80000): the whole spawn is skipped. */
  const pSkip = b15RainWireDecide({ ...base, flags1839c: 0x80000 });
  assert.equal(pSkip.onceFlagApply, 0, "flag set -> no apply");
  assert.equal(pSkip.steps, 0, "no iterations");
  assert.equal(pSkip.hostSearch, 0, "no search");
  assert.equal(pSkip.seedOut >>> 0, 0x12345678, "seed untouched");

  /* Empty buffer: 0x802b53 je -> skip. */
  const pEmpty = b15RainWireDecide({ ...base, begin183a4: 0x1000, end183a8: 0x1000 });
  assert.equal(pEmpty.bufferEmpty, 1, "empty buffer gate");
  assert.equal(pEmpty.steps, 0, "no iterations");

  /* spawn_count 0: 0x802c0a jle -> direct exit (no loop). */
  const pZero = b15RainWireDecide({ ...base, quality: 0, end183a8: 0x1000 });
  assert.equal(pZero.spawnCount, 0, "count 0");
  assert.equal(pZero.loopEnter, 0, "loop does not enter");

  /* Genrand cap: host count capped at GENRAND_MAX_SAMPLES (448). */
  const pHuge = b15RainWireDecide({ ...base, genrandCount: 0x100000 });
  assert.equal(pHuge.genrandDraws, 448, "cap at max samples");
  /* MT not ready: draws still typed, no in-module advance. */
  const pNoMt = b15RainWireDecide({ ...base, genrandMtReady: 0 });
  assert.equal(pNoMt.genrandDraws, 3, "draws typed even without mt");
  assert.equal(pNoMt.genrandMtAdvance, 0, "no advance without mt");

  /* Fatal handling: the pre-corner fatal (0x00802cee assert, seed_shuffle
     == 0) is UNREACHABLE for nonzero seeds — the B1 xorshift is a
     bijection (xorshift(s) == 0 iff s == 0), so xorshift(xorshift(s))
     == 0 is impossible. The only reachable fatal is seed0 == 0 -> the
     PRE-SHUFFLE assert at 0x00802c28: the wire computes frame 0, records
     the fatal, and counts NO swap/search/create/bind (nothing ran before
     that assert). The host_swap-before-pre-corner ordering is still coded
     per the PE instruction order (0x00802c83..0x00802ccb < 0x00802cee)
     even though the arm cannot be driven by a valid seed. */
  const pFatal = b15RainWireDecide({ ...base, seed0: 0 });
  assert.equal(pFatal.seedFatal, B15_RAIN_SEED_FATAL_PRE_SHUFFLE,
    "zero seed0 trips the 0x802c28 assert");
  assert.equal(pFatal.steps, 1, "the fatal frame is written");
  assert.equal(pFatal.hostSearch, 0, "nothing searched");
  assert.equal(pFatal.hostCreate, 0, "nothing created");
  assert.equal(pFatal.hostBind, 0, "nothing bound");
  assert.equal(pFatal.hostSwap, 0, "no swap before the pre-shuffle assert");
  /* Bijection fact: no nonzero seed can reach the pre-corner assert. */
  {
    const xo = (s) => {
      let x = s >>> 0;
      x = ((x >>> 1) ^ x) >>> 0;
      x = ((((x << 9) >>> 0) ^ x) >>> 0);
      x = ((x >>> 29) ^ x) >>> 0;
      return x >>> 0;
    };
    for (let s = 1; s < 0x10000; s += 1) {
      assert.notEqual(xo(xo(s)), 0, `seed 0x${s.toString(16)} cannot reach seed_shuffle==0`);
    }
  }
});

test("ABI v95: shipped Wasm agrees with the oracle on the rain laws (wide args)", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  const sc = pick("isaac_game_update_slice_b15_rain_spawn_count");
  const fr = pick("isaac_game_update_slice_b15_rain_frame");
  assert.equal(typeof sc, "function", "b15_rain_spawn_count missing from the module");
  assert.equal(typeof fr, "function", "b15_rain_frame missing from the module");
  /* spawn_count: WIDE arrivals (0x100 / 0xffffffff quality etc.) cross
     UNMASKED; the C++ law re-narrows/wraps exactly like the oracle. */
  for (const [owner, quality, begin, end] of [
    [1, 3, 0x1000, 0x14c0], [1, 2, 0x1000, 0x1300], [1, 0, 0x1000, 0x11e0],
    [0, 3, 0x1000, 0x11e0], [1, 3, 0x1000, 0x1000], [1, 3, 0x1000, 0x0f00],
    [1, 0x100, 0x1000, 0x14c0], [1, 0xffffffff, 0x1000, 0x14c0],
    [0xffffffff, 3, 0x1000, 0x14c0],
  ]) {
    assert.equal(sc(owner >>> 0, quality >>> 0, begin >>> 0, end >>> 0) | 0,
      b15RainSpawnCount(owner >>> 0, quality >>> 0, begin >>> 0, end >>> 0) | 0,
      `wasm spawn_count(${owner >>> 0},${quality >>> 0},0x${begin.toString(16)},0x${end.toString(16)})`);
  }
  /* frame: write the 104-byte out-struct into low linear memory (below the
     0x100000 static base), call, read back all 26 dwords. */
  const view = new DataView(wasm.memory.buffer);
  const FRAME_BASE = 0x80000;
  const fields = {
    remaining: [0, "i32"], seedIn: [4, "u32"], seedShuffle: [8, "u32"],
    shuffleRem: [12, "u32"], needsSwap: [16, "i32"], swapIndex: [20, "i32"],
    slotOffset: [24, "i32"], swapOffset: [28, "i32"], seedCorner: [32, "u32"],
    seedOut: [36, "u32"], nextIndex: [40, "i32"], continueLoop: [44, "i32"],
    seedFatal: [48, "i32"], cornerIndex: [52, "i32"], worldXBits: [56, "u32"],
    worldYBits: [60, "u32"], argA1: [64, "u32"], argA2: [68, "u32"],
    argA3: [72, "u32"], argA4: [76, "u32"], argA5: [80, "u32"],
    argA6: [84, "u32"], argA7: [88, "u32"], spawnSiteVa: [92, "u32"],
    bindVa: [96, "u32"], entityMarkValue: [100, "u32"],
  };
  const readFrame = () => {
    const out = {};
    for (const [k, [off]] of Object.entries(fields)) out[k] = view.getUint32(FRAME_BASE + off, true) >>> 0;
    return out;
  };
  const WIDE = [0x11111111, 0x100, 0x1ff, 0xffffffff, 0x80000000, 0x12345678, 0, 0x55555555, 0xc7b640, 0x802dc4, 0x7ef420, 0xffffffff];
  const drives = [
    { seedIn: 0x12345678, index: 0, spawnCount: 4, roomWC: 10, roomHC: 10,
      slotF0: 0x11111111, slotF4: 0x22222222, slotF8: 0x33333333, slotF34: 0x44444444, search: 0x55555555 },
    { seedIn: 0x12345678, index: 0x100, spawnCount: 0x100, roomWC: 10, roomHC: 10,
      slotF0: 0x100, slotF4: 0x1ff, slotF8: 0xffffffff, slotF34: 0x80000000, search: 0xffffffff },
    { seedIn: 0, index: 0, spawnCount: 4, roomWC: 10, roomHC: 10,
      slotF0: 1, slotF4: 2, slotF8: 3, slotF34: 4, search: 5 },
  ];
  for (const d of drives) {
    fr(d.seedIn >>> 0, d.index | 0, d.spawnCount | 0, d.roomWC | 0, d.roomHC | 0,
       d.slotF0 >>> 0, d.slotF4 >>> 0, d.slotF8 >>> 0, d.slotF34 >>> 0,
       d.search >>> 0, FRAME_BASE);
    const w = readFrame();
    const o = b15RainFrame({
      seedIn: d.seedIn, index: d.index, spawnCount: d.spawnCount,
      roomWC: d.roomWC, roomHC: d.roomHC, slotF0: d.slotF0, slotF4: d.slotF4,
      slotF8: d.slotF8, slotF34: d.slotF34, searchResult: d.search,
    });
    for (const [k] of Object.entries(fields)) {
      assert.equal(w[k] >>> 0, (o[k] | 0) >>> 0,
        `wasm frame.${k} for seed 0x${(d.seedIn >>> 0).toString(16)} idx ${d.index | 0}`);
    }
  }
});

test("ABI v95: the room-head resume keeps the monolith and lands the blob wire", () => {
  const rt = (extra) => ({
    b15RainReady: 1, b15RainSeed58: 0x12345678, b15RainQuality: 3,
    b15RainBegin183a4: 0x1000, b15RainEnd183a8: 0x14c0,
    b15RainRoomWC: 10, b15RainRoomH10: 10,
    b15RainSlotF0: [0x11111111, 0xaaaaaaaa, 0x22222222, 0xbbbbbbbb, 0, 0, 0, 0],
    b15RainSlotF4: [0x22222222, 0xbbbbbbbb, 0x11111111, 0xaaaaaaaa, 0, 0, 0, 0],
    b15RainSlotF8: [0x33333333, 0xcccccccc, 0x33333333, 0xcccccccc, 0, 0, 0, 0],
    b15RainSlotF34: [0x44444444, 0xdddddddd, 0x44444444, 0xdddddddd, 0, 0, 0, 0],
    b15RainSearchResults: [0x55555555, 0xeeeeeeee, 0x55555555, 0xeeeeeeee, 0, 0, 0, 0],
    b15RainGenrandCount: 2, genrandMtReady: 1,
    ...extra,
  });
  const drive = (overrides, runtime) =>
    resumeGameUpdateRoomUpdateHead(state(overrides), runtime,
      { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD });
  /* No blob: pre-v95 monolith — event fires, carriers stay 0. */
  const noBlob = drive({}, {});
  assert.equal(noBlob.events.opaqueRoomUpdateTailRain, 1, "monolith event fires");
  assert.equal(noBlob.events.b15RainPureSteps ?? 0, 0, "no pure carrier without blob");
  assert.equal(noBlob.events.b15RainHostSearch ?? 0, 0, "no search carrier");
  assert.equal(noBlob.state.gameFlags1839c >>> 0, 0, "flag untouched");
  /* Blob + flag clear: wire runs, typed carriers publish, flag OR'd. */
  const blob = drive({}, rt());
  assert.equal(blob.events.opaqueRoomUpdateTailRain, 1, "host edge still fires");
  assert.equal(blob.events.b15RainPureSteps, 8, "8 iterations (span 1216 -> /0x78 = 10 -> min(quality3->8, 10) = 8)");
  assert.equal(blob.events.b15RainHostSearch, 8, "8 searches");
  assert.equal(blob.events.b15RainHostCreate, 8, "8 creates");
  assert.equal(blob.events.b15RainHostBind, 8, "8 binds");
  assert.equal(blob.events.b15RainGenrandDraws, 2, "typed genrand draws");
  assert.equal((blob.state.gameFlags1839c >>> 0) & 0x80000, 0x80000,
    "once-flag OR'd into Game+0x1839c (PE 0x802a9e..0x802aa3)");
  /* Blob + flag already set: skip everything (B1 OR'd first). */
  const flag = drive({ gameFlags1839c: 0x80000 }, rt());
  assert.equal(flag.events.b15RainPureSteps ?? 0, 0, "flag set -> no pure steps");
  assert.equal(flag.events.b15RainHostSearch ?? 0, 0, "flag set -> no search");
  assert.equal(flag.state.gameFlags1839c >>> 0, 0x80000, "flag unchanged");
});
/* =====================================================================
   ABI v95 (record idx 8 MenuGateOpen 0x009b7680 head laws) — wave-18
   update-v95-menu-open-census. PE-truth transcribed branch-by-branch from
   the instruction stream (cpu-dump/009b7680.txt). All scalars uint32 —
   WIDE drives 0x100/0x1ff/0xffffffff cross UNMASKED.
   ===================================================================== */

test("ABI v95: menu_open_slot_select mirrors the cmovne FULL-DWORD select (0x9b7733/0x9b774c)", () => {
  /* PE: 0x9b772f cmp dword [edi+4],1 / 0x9b7733 mov ebx,0x140 /
     0x9b7738 mov eax,0x2c / 0x9b774c cmovne esi,eax — the slot offset is
     0x140 ONLY when menu_mode == 1 (FULL dword); anything else (0, 2,
     0x100, 0xffffffff) falls to 0x2c. */
  assert.equal(menuOpenSlotSelect(1), 0x140);
  assert.equal(menuOpenSlotSelect(0), 0x2c);
  assert.equal(menuOpenSlotSelect(2), 0x2c);
  assert.equal(menuOpenSlotSelect(0x100), 0x2c, "WIDE 0x100 must NOT match ==1");
  assert.equal(menuOpenSlotSelect(0x1ff), 0x2c, "WIDE 0x1ff must NOT match ==1");
  assert.equal(menuOpenSlotSelect(0xffffffff), 0x2c, "WIDE 0xffffffff must NOT match ==1");
});

test("ABI v95: layer74_range_nonempty mirrors the setne FULL-DWORD begin!=end (0x9b7979..0x9b798c)", () => {
  /* PE: 0x9b7979 mov ecx,[edx+0x4b3d8] / 0x9b797f cmp ecx,[edx+0x4b3dc] /
     0x9b7989 setne al — the GetLayer#1 byte+0x74 is 1 iff the game range
     is non-empty. byte_length = end-begin (raw u32). */
  assert.equal(menuOpenLayer74RangeNonempty(0), 0, "empty range -> 0");
  assert.equal(menuOpenLayer74RangeNonempty(4), 1, "one element -> 1");
  assert.equal(menuOpenLayer74RangeNonempty(0x100), 1, "WIDE -> non-empty");
  assert.equal(menuOpenLayer74RangeNonempty(0xffffffff), 1, "WIDE -> non-empty");
});

test("ABI v95: layer74_count_gt_one mirrors SAR32 then UNSIGNED >1 (0x9b79c4..0x9b79dc)", () => {
  /* PE: 0x9b79c4 cmp edx,ecx / je 0; 0x9b79c8 sub ecx,edx /
     0x9b79ca sar ecx,2 (ARITHMETIC) / 0x9b79cd cmp ecx,1 /
     0x9b79d0 jbe 0 (UNSIGNED bound): byte+0x74 = 1 iff count > 1.
     Discriminators: byte_length 4 -> count 1 -> 0 (jbe taken);
     byte_length 8 -> 2 -> 1; 0xffffffff -> SAR -1 -> (u32)-1 > 1 -> 1
     (a signed compare would give -1 > 1 == false). */
  assert.equal(menuOpenLayer74CountGtOne(0), 0, "empty -> je -> 0");
  assert.equal(menuOpenLayer74CountGtOne(4), 0, "count 1 -> jbe -> 0");
  assert.equal(menuOpenLayer74CountGtOne(8), 1, "count 2 -> 1");
  assert.equal(menuOpenLayer74CountGtOne(0x100), 1, "count 0x40 -> 1");
  assert.equal(menuOpenLayer74CountGtOne(0xffffffff), 1,
    "SAR -1 as UNSIGNED is 0xffffffff > 1 -> 1 (signed compare would flip)");
});

test("ABI v95: layer74_difficulty_one mirrors the sete FULL-DWORD ==1 (0x9b7a04..0x9b7a0e)", () => {
  /* PE: 0x9b7a04 cmp dword [ecx+0x269c8],1 / 0x9b7a0b sete cl — byte+0x74
     is 1 iff difficulty_269c8 == 1 exactly (FULL dword). */
  assert.equal(menuOpenLayer74DifficultyOne(1), 1);
  assert.equal(menuOpenLayer74DifficultyOne(0), 0);
  assert.equal(menuOpenLayer74DifficultyOne(2), 0);
  assert.equal(menuOpenLayer74DifficultyOne(0x100), 0, "WIDE 0x100 must NOT match ==1");
  assert.equal(menuOpenLayer74DifficultyOne(0xffffffff), 0, "WIDE 0xffffffff must NOT match ==1");
});

test("ABI v95: menu_open_fac_index mirrors the SAR32 + UNSIGNED jb walk (0x9b76ed..0x9b7713)", () => {
  /* PE: 0x9b76fb sub esi,edx / 0x9b76fd sar esi,2 (count = SAR32(span,2))
     0x9b7700 test esi,esi / je 0x9b7710 (count==0 -> -1)
     0x9b7704 cmp [edx],eax / je (full-dword match -> i)
     0x9b7708 inc ecx / add edx,4 / 0x9b770c cmp ecx,esi / 0x9b770e jb
     (UNSIGNED loop bound) / 0x9b7710 or ecx,-1 (miss). */
  /* Empty span: begin==end -> -1 even with a matching sample present. */
  assert.equal(menuOpenFacIndex(0x1000, 0x1000, 7, [7], 1), -1, "empty span -> -1");
  /* One element, match: 0x1000..0x1004 (count 1). */
  assert.equal(menuOpenFacIndex(0x1000, 0x1004, 7, [7], 1), 0, "first element match");
  /* Two elements, second match. */
  assert.equal(menuOpenFacIndex(0x1000, 0x1008, 9, [7, 9], 2), 1, "second element match");
  /* Miss: -1. */
  assert.equal(menuOpenFacIndex(0x1000, 0x1008, 11, [7, 9], 2), -1, "miss -> -1");
  /* WIDE count: span 0x1000..0x1400 (count 0x100 = 256) must walk 256
     entries (UNSIGNED jb), NOT empty-skip. Target at index 0xff. */
  const wide = new Array(0x100).fill(0);
  wide[0xff] = 42;
  assert.equal(menuOpenFacIndex(0x1000, 0x1400, 42, wide, 0x100), 0xff,
    "WIDE count 0x100 walks to index 0xff");
  /* Wrapped span: end < begin -> count = SAR32(negative) < 0. The PE
     0x9b7700 test esi,esi / je only skips on count == 0, so a NEGATIVE
     count still walks (0x9b770c cmp ecx,esi / jb with esi as UNSIGNED
     huge). A matching captured sample therefore returns its index; a
     non-matching sample exhausts the capture cap -> -1. */
  assert.equal(menuOpenFacIndex(0x2000, 0x1000, 1, [1], 1), 0,
    "wrapped span still walks; first captured sample matches -> 0");
  assert.equal(menuOpenFacIndex(0x2000, 0x1000, 5, [1], 1), -1,
    "wrapped span with no captured match -> capped -1");
});

test("ABI v95: menu-open laws are declared in the header and whitelisted for the build", () => {
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const build = readFileSync(join(root, "scripts", "decomp", "build-game-update-slice.mjs"), "utf8");
  for (const name of [
    "menu_open_slot_select",
    "menu_open_layer74_range_nonempty",
    "menu_open_layer74_count_gt_one",
    "menu_open_layer74_difficulty_one",
    "menu_open_fac_index",
  ]) {
    assert.match(header, new RegExp(`isaac_game_update_slice_${name}\\(`),
      `header declares ${name}`);
    assert.match(source, new RegExp(`isaac_game_update_slice_${name}\\(`),
      `source defines ${name}`);
    assert.match(build, new RegExp(`"_isaac_game_update_slice_${name}"`),
      `build whitelist exports ${name}`);
  }
});

