test("ABI v95: true-probe interior keeps the record host edge and SUPPRESSES pair events", () => {
  /* Pair live (A ADVANCE_MID) + secondary==3 probe arm TRUE (bitfield set):
     the host runs the whole record (pair included) -> the pair events must
     NOT publish (deferral: events fire only when the record resolves pure). */
  const out = frameAux4212c0(
    { frameOpaque4212c0Mode: 2, frameOpaque4212c0Secondary: 3, frameOpaque4212c0Field3c: 7, frameOpaque4212c0Flag4c: 1, frameOpaque4212c0Flag111: 1 },
    {
      frameOpaque4212c0PairReady: 1, frameOpaque4212c0AbPackReady: 1,
      frameOpaque4212c0Field5c: 0, frameOpaque4212c0Flag6c: 1,
      frameOpaque4212c0AFloat10: f32BitsV95(2.0), frameOpaque4212c0ALayer104: f32BitsV95(1.0),
      frameOpaque4212c0AFrameBound: 10, frameOpaque4212c0ALoopFlag: 0,
      frameOpaque4212c0BFloat10: 0, frameOpaque4212c0BLayer104: 0,
      frameOpaque4212c0BFrameBound: 0, frameOpaque4212c0BLoopFlag: 0,
      frameOpaque4212c0ProbeReady: 1, frameOpaque4212c0ProbeResolved: 1,
      frameOpaque4212c0Add0Field4: 7, frameOpaque4212c0Add0ListCount: 1,
      frameOpaque4212c0Add0MatchIndex: 0, frameOpaque4212c0Add0Bitfield18: 1,
    },
  );
  assert.equal(out.events.opaqueCall004212c0, 1, "true-probe interior hosts");
  assert.equal(out.events.frameOpaque4212c0409030Advance ?? 0, 0, "pair events deferred");
  assert.equal(out.events.frameOpaque4212c0409030Rewind ?? 0, 0);
});

test("ABI v95: pair pure + probe-false pure -> record fully pure WITH pair events", () => {
  /* A live ADVANCE_MID + secondary==3 empty-list probe (pure-false) with
     flag4c low byte SET -> false-probe terminal leaves state unchanged
     (PE 0x4213de..0x4213ea ret) — the pair events DO publish. */
  const out = frameAux4212c0(
    { frameOpaque4212c0Mode: 2, frameOpaque4212c0Secondary: 3, frameOpaque4212c0Field3c: 7, frameOpaque4212c0Flag4c: 0x10b, frameOpaque4212c0Flag111: 1 },
    {
      frameOpaque4212c0PairReady: 1, frameOpaque4212c0AbPackReady: 1,
      frameOpaque4212c0Field5c: 0, frameOpaque4212c0Flag6c: 1,
      frameOpaque4212c0AFloat10: f32BitsV95(2.0), frameOpaque4212c0ALayer104: f32BitsV95(1.0),
      frameOpaque4212c0AFrameBound: 10, frameOpaque4212c0ALoopFlag: 0,
      frameOpaque4212c0BFloat10: 0, frameOpaque4212c0BLayer104: 0,
      frameOpaque4212c0BFrameBound: 0, frameOpaque4212c0BLoopFlag: 0,
      frameOpaque4212c0ProbeReady: 1, frameOpaque4212c0Add0Field4: 7,
      frameOpaque4212c0Add0ListCount: 0,
    },
  );
  assert.equal(out.events.opaqueCall004212c0, 0, "record fully pure");
  assert.equal(out.events.frameOpaque4212c0409030Advance, 1, "pair events publish on the pure path");
  assert.equal(out.events.frameOpaque4212c0409030Rewind, 0);
  assert.equal(out.state.frameOpaque4212c0Mode, 2, "flag4c low set -> false-probe ret unchanged");
});

