test("ABI v95: JSON evidence + pack/event names recorded", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const rec = spec.resolvedBoundaries.find((b) => b.targetVa === "0x004212c0");
  assert.ok(rec, "record rides resolvedBoundaries (REMOVED at ABI v99)");
  assert.ok(!spec.opaqueBoundaries.some((b) => b.targetVa === "0x004212c0"),
    "record 0x004212c0 is GONE from opaqueBoundaries");
  assert.match(rec.evidence || rec.abiV99 || rec.operation || "", /R1|409030|ADVANCE|REWIND|ab_pack/i);
  assert.equal(spec.opaqueBoundaries.length, 24);
  for (const name of [
    "frameOpaque4212c0AbPackReady", "frameOpaque4212c0AFloat10",
    "frameOpaque4212c0BFloat10", "frameOpaque4212c0ALayer104",
    "frameOpaque4212c0BLayer104", "frameOpaque4212c0AFrameBound",
    "frameOpaque4212c0BFrameBound", "frameOpaque4212c0ALoopFlag",
    "frameOpaque4212c0BLoopFlag",
  ]) {
    assert.ok(spec.runtimeInputs.some((i) => i.name === name), `spec records ${name}`);
  }
  for (const name of ["frameOpaque4212c0409030Advance", "frameOpaque4212c0409030Rewind"]) {
    assert.ok(spec.events.some((i) => i.name === name), `spec records ${name}`);
  }
});

/* ==================================================================== */
/* ABI v95 (record idx 37, opaqueRoomUpdateTailMid): pure DECISION laws
   of the three always-body calls — curse FUN_00820910 / greed-special
   FUN_00801ee0 / room mid-tail FUN_00800500 (census 0x00805378..
   0x008053e2). PE-truth references transcribed from the instruction
   stream; the BODIES stay typed-host (stateful). */
/* ==================================================================== */

const tailmidF32 = (bits) => {
  const u = new Uint32Array(1);
  u[0] = bits >>> 0;
  return new Float32Array(u.buffer)[0];
};

test("ABI v95 tailmid: curse gate open mirrors PE 0x80537e..0x8053aa (4 pure clauses)", () => {
  /* All four open: flags has 0x4000, desc lacks 0x4000, active byte != 0,
     frame-entry == 1. */
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x4000, 0, 1, 100, 99), 1, "all clauses open");
  /* flags lacks curse bit -> skip (PE 0x80537e test/jne) */
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0, 0, 1, 100, 99), 0, "no curse bit");
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x100, 0, 1, 100, 99), 0, "0x100 does not carry bit 0x4000");
  /* desc already has curse bit -> skip (PE 0x80538d test/jne) */
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x4000, 0x4000, 1, 100, 99), 0, "desc already cursed");
  /* room inactive -> skip (PE 0x805396 cmp byte / je) */
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x4000, 0, 0, 100, 99), 0, "room inactive");
  /* PE reads a BYTE: 0x100 has low byte 0 -> inactive (word test would
     wrongly open the gate; module must narrow, never the harness) */
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x4000, 0, 0x100, 100, 99), 0, "WIDE 0x100 low byte clear -> inactive");
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x4000, 0, 0x1ff, 100, 99), 1, "WIDE 0x1ff low byte set -> active");
  /* frame age != 1 -> skip (PE 0x80539b sub / cmp 1 / jne) */
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x4000, 0, 1, 100, 98), 0, "frame age 2");
  assert.equal(gameUpdateSliceTailmidCurseGateOpen(
    0x4000, 0, 1, 100, 100), 0, "frame age 0");
});

test("ABI v95 tailmid: curse needs-host folds the IsPaused sample (PE 0x8053ac)", () => {
  const base = [0x4000, 0, 1, 100, 99];
  assert.equal(gameUpdateSliceTailmidCurseNeedsHost(...base, 0), 1, "not paused -> host");
  assert.equal(gameUpdateSliceTailmidCurseNeedsHost(...base, 1), 0, "paused -> skip");
  assert.equal(gameUpdateSliceTailmidCurseNeedsHost(...base, 0xff), 0, "paused low byte");
  /* WIDE: 0x100 has a clear low byte -> NOT paused (host must NOT pre-mask) */
  assert.equal(gameUpdateSliceTailmidCurseNeedsHost(...base, 0x100), 1, "0x100 low byte clear");
  /* gate closed -> 0 regardless of pause */
  assert.equal(gameUpdateSliceTailmidCurseNeedsHost(0, 0, 1, 100, 99, 0), 0);
});

test("ABI v95 tailmid: curse arg prep + posts mirror PE imms", () => {
  assert.equal(gameUpdateSliceTailmidCurseArgZero(), 0, "push 0");
  assert.equal(gameUpdateSliceTailmidCursePosVecPtr(), 0x00c7b640, "push 0xc7b640");
  assert.equal(gameUpdateSliceTailmidCurseEffectType(), 0x3e8, "TYPE");
  assert.equal(gameUpdateSliceTailmidCurseEffectVariant(), 0x7f, "VARIANT");
  assert.equal(gameUpdateSliceTailmidCurseFlagOr4000(0), 0x4000, "post |0x4000");
  assert.equal(gameUpdateSliceTailmidCurseFlagOr4000(0x4000), 0x4000, "idempotent");
  assert.equal(gameUpdateSliceTailmidCurseFlagOr4000(0xffffffff), 0xffffffff, "WIDE keep");
});

