test("ABI v95 tailmid: 801ee0 boss count is SIGNED max(0, 12c0+12c4) (PE cmovg)", () => {
  assert.equal(gameUpdateSliceTailmid801ee0BossCount(2, 3), 5);
  assert.equal(gameUpdateSliceTailmid801ee0BossCount(-5, 4), 0, "negative sum clamps to 0");
  assert.equal(gameUpdateSliceTailmid801ee0BossCount(0, 0), 0);
  /* signed overflow: 0x7fffffff + 1 -> negative -> 0 (cmovg on signed flags) */
  assert.equal(gameUpdateSliceTailmid801ee0BossCount(0x7fffffff, 1), 0);
  assert.equal(gameUpdateSliceTailmid801ee0BossCount(-4, 5), 1);
});

