test("ABI v95 tailmid: the shipped Wasm agrees with the oracle on the new exports", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  assert.equal(pick("isaac_game_update_slice_abi_version")(), ABI_VERSION,
    "the probed module is the current module");
  const cases = [
    ["isaac_game_update_slice_tailmid_curse_gate_open", (f) => gameUpdateSliceTailmidCurseGateOpen(
      f, 0, 1, 100, 99), [0, 1, 100, 99]],
    ["isaac_game_update_slice_tailmid_curse_needs_host", (f) => gameUpdateSliceTailmidCurseNeedsHost(
      f, 0, 1, 100, 99, 0x100), [0, 1, 100, 99, 0x100]],
    ["isaac_game_update_slice_tailmid_801ee0_is_greed_mode", (f) => gameUpdateSliceTailmid801ee0IsGreedMode(f)],
    ["isaac_game_update_slice_tailmid_801ee0_boss_count", (f) => gameUpdateSliceTailmid801ee0BossCount(f, 4), [4]],
    ["isaac_game_update_slice_tailmid_801ee0_needs_timer_reset", (f) => gameUpdateSliceTailmid801ee0NeedsTimerReset(0x14, f), null, (f) => [0x14, f]],
    ["isaac_game_update_slice_tailmid_801ee0_needs_spawn_wave", (f) => gameUpdateSliceTailmid801ee0NeedsSpawnWave(0, f), null, (f) => [0, f]],
    ["isaac_game_update_slice_tailmid_801ee0_needs_special", (f) => gameUpdateSliceTailmid801ee0NeedsSpecial(7, 5, f, 2), null, (f) => [7, 5, f, 2]],
    ["isaac_game_update_slice_tailmid_800500_early_skip", (f) => gameUpdateSliceTailmid800500EarlySkip(f, 0)],
    ["isaac_game_update_slice_tailmid_800500_entity_list_empty", (f) => gameUpdateSliceTailmid800500EntityListEmpty(f)],
    ["isaac_game_update_slice_tailmid_800500_type_in_threat_band", (f) => gameUpdateSliceTailmid800500TypeInThreatBand(f)],
    ["isaac_game_update_slice_tailmid_800500_outer_include_candidate", (f) => gameUpdateSliceTailmid800500OuterIncludeCandidate(f, 10), [10]],
    ["isaac_game_update_slice_tailmid_800500_timer_72fc_needs_host", (f) => gameUpdateSliceTailmid800500Timer72fcNeedsHost(f)],
    ["isaac_game_update_slice_tailmid_800500_timer_72fc_inc", (f) => gameUpdateSliceTailmid800500Timer72fcInc(f)],
    ["isaac_game_update_slice_tailmid_800500_timer_72fc_needs_sfx_play", (f) => gameUpdateSliceTailmid800500Timer72fcNeedsSfxPlay(f)],
    ["isaac_game_update_slice_tailmid_800500_timer_72fc_needs_isplaying_host", (f) => gameUpdateSliceTailmid800500Timer72fcNeedsIsplayingHost(f)],
  ];
  const fields = [0, 1, 2, 3, 4, 5, 7, 10, 0x13, 0x14, 0xff, 0x100, 0x1ff, 0x1000, 0x4000,
    0x7fffffff, 0x80000000, 0xffffffff];
  for (const [name, oracle, extra, argsFn] of cases) {
    const fn = pick(name);
    assert.equal(typeof fn, "function", `${name} missing from the module`);
    for (const f of fields) {
      const args = argsFn ? argsFn(f) : (extra ? [f, ...extra] : [f]);
      assert.equal(fn(...args) | 0, oracle(f) | 0, `${name}(0x${(f >>> 0).toString(16)})`);
    }
  }
});

/* ================= ABI v95: record idx 40 opaqueRoomUpdateTailMid7230Spawn
   spawn-loop FRAME laws =================================================
   PE frame 0x008054ab..0x00805527 (countdown Room+0x7230 + periodic spawn
   every 5 frames, signed): gate (0x8054b1 test/jle SIGNED + 0x8054bf
   idiv-remainder), the PER-ITERATION BOUND RE-READ (0x805515 re-reads
   Room+0x7230 AFTER the pos/genrand/spawn/RTTI host calls; the dec is
   UNCONDITIONAL on the re-read), the 0x00813460 pos math (spans/unit/
   max_span/centers — radius_arg = unit*max_span is THE SQRT ARGUMENT),
   the CRT sqrt platform-primitive gate (0x435a5d ucomisd 0.0,x / ja), and
   the typed spawn-call arg prep (0x8054e7..0x80550a push imms + the typed
   host call sequence pos 813460 -> genrand 6eef60 -> spawn 428b20 ->
   RTTI af08b1). Bodies stay typed-host. Mutation legend (each flipped
   line fails THIS group, then restored sha256-byte-identical — NOTES.md
   update-v95-7230-spawn-frame):
   - gate signed jle -> unsigned (0x80000002 would open): T1 dies.
   - counter_next conditional dec (0 -> 0): T2 dies (PE stores -1).
   - max_span fmax (NaN -> NaN): T3 dies (PE maxss returns span_y).
   - sqrt_host_needed <= 0 (-0.0 would host): T4 dies. */

test("ABI v95 7230 spawn frame: gate_open is SIGNED pre>0 && pre%5==0 (PE 0x8054b1 jle / 0x8054bf idiv)", () => {
  assert.equal(gameUpdateSliceTailmid7230GateOpen(5), 1, "5 -> spawn frame");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(10), 1);
  assert.equal(gameUpdateSliceTailmid7230GateOpen(0), 0, "0 -> jle skip");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(-5), 0, "negative -> jle skip (SIGNED)");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(-1), 0, "-1 signed");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(0x80000000 | 0), 0, "INT_MIN signed negative");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(0x80000002 | 0), 0,
    "WIDE 0x80000002 signed NEGATIVE -> skip (an unsigned gate would open: 2147483650 % 5 == 0)");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(0xffffffff | 0), 0,
    "WIDE -1 signed skip (unsigned would treat as huge)");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(1), 0, "1 % 5 != 0");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(2), 0);
  assert.equal(gameUpdateSliceTailmid7230GateOpen(4), 0);
  assert.equal(gameUpdateSliceTailmid7230GateOpen(6), 0);
  assert.equal(gameUpdateSliceTailmid7230GateOpen(0x100), 0, "0x100 % 5 == 1 -> closed");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(0x10000004), 1, "WIDE positive 0x10000004 % 5 == 0 -> open");
  assert.equal(gameUpdateSliceTailmid7230GateOpen(0x10000005), 0, "0x10000005 % 5 == 1 -> closed");
});

test("ABI v95 7230 spawn frame: counter_next is the PER-ITERATION BOUND RE-READ (PE 0x805515) — UNCONDITIONAL dec", () => {
  /* 0x805515 mov ecx,[edi+0x7230] re-reads Room+0x7230 AFTER the four host
     calls; 0x80551e lea eax,[ecx-1] decrements UNCONDITIONALLY — the pre>0
     gate (0x8054b3) already passed. A drained re-read of 0 stores -1. */
  assert.equal(gameUpdateSliceTailmid7230CounterNext(5), 4);
  assert.equal(gameUpdateSliceTailmid7230CounterNext(1), 0);
  assert.equal(gameUpdateSliceTailmid7230CounterNext(0), -1, "drained re-read 0 -> -1 (0xffffffff)");
  assert.equal(gameUpdateSliceTailmid7230CounterNext(0) >>> 0, 0xffffffff);
  assert.equal(gameUpdateSliceTailmid7230CounterNext(-1), -2, "wrap -1 -> -2");
  assert.equal(gameUpdateSliceTailmid7230CounterNext(0x7fffffff), 0x7ffffffe);
  assert.equal(gameUpdateSliceTailmid7230CounterNext(0x80000000 | 0), 0x7fffffff, "INT_MIN wraps to INT_MAX");
  assert.equal(gameUpdateSliceTailmid7230CounterNext(0xffffffff | 0), -2, "WIDE -1 -> -2");
});

test("ABI v95 7230 spawn frame: 813460 pos spans are f32 subtracts (PE 0x81346c..0x813486)", () => {
  assert.equal(gameUpdateSliceTailmid7230SpanX(100, 340), 240, "span_x = x1 - x0");
  assert.equal(gameUpdateSliceTailmid7230SpanY(50, 170), 120, "span_y = y1 - y0");
  assert.equal(gameUpdateSliceTailmid7230SpanX(-100, 100), 200);
  assert.equal(gameUpdateSliceTailmid7230SpanX(0.5, 0.75), 0.25, "f32 sub");
});

test("ABI v95 7230 spawn frame: unit_float is MSVC u32->f32 * 2^-32 (PE 0x8134a2..0x8134cf)", () => {
  assert.equal(gameUpdateSliceTailmid7230UnitFloat(0), 0);
  assert.equal(gameUpdateSliceTailmid7230UnitFloat(0x80000000), 0.5, "bit31 -> +2^32 fix -> 0.5");
  assert.equal(gameUpdateSliceTailmid7230UnitFloat(0xffffffff), Math.fround(0.9999999997671694),
    "0xffffffff -> 1-ulp-below-1 (a signed conversion would give -2.3e-10)");
  assert.equal(gameUpdateSliceTailmid7230UnitFloat(0x7fffffff), Math.fround(0.4999999997671694));
  assert.equal(gameUpdateSliceTailmid7230UnitFloat(0x100), Math.fround(256 / 4294967296), "small u32 exact");
});

test("ABI v95 7230 spawn frame: max_span is maxss — span_y unless span_x STRICTLY greater (PE 0x8134d7)", () => {
  assert.equal(gameUpdateSliceTailmid7230MaxSpan(10, 20), 20, "span_y bigger");
  assert.equal(gameUpdateSliceTailmid7230MaxSpan(30, 20), 30, "span_x bigger");
  assert.equal(gameUpdateSliceTailmid7230MaxSpan(20, 20), 20, "equal -> span_y (maxss returns the second operand)");
  assert.equal(gameUpdateSliceTailmid7230MaxSpan(NaN, 20), 20, "NaN span_x -> span_y (maxss NaN yields src)");
  assert.equal(gameUpdateSliceTailmid7230MaxSpan(20, NaN), NaN, "NaN span_y propagates");
});

test("ABI v95 7230 spawn frame: centers — x0 + span_x*0.5 / y0 + span_y*0.5 (PE 0x8134c7..0x813500, v47 axis fix)", () => {
  assert.equal(gameUpdateSliceTailmid7230CenterX(100, 240), 220, "center_x");
  assert.equal(gameUpdateSliceTailmid7230CenterY(50, 120), 110, "center_y");
  assert.equal(gameUpdateSliceTailmid7230CenterX(-40, 200), 60);
  assert.equal(gameUpdateSliceTailmid7230CenterX(100, 3), 101.5, "f32 half");
});

test("ABI v95 7230 spawn frame: sqrt_arg = unit * max_span — THE SQRT ARGUMENT (PE 0x8134e8 mulss)", () => {
  assert.equal(gameUpdateSliceTailmid7230SqrtArg(0.5, 240), 120);
  assert.equal(gameUpdateSliceTailmid7230SqrtArg(0, 240), 0);
  assert.equal(gameUpdateSliceTailmid7230SqrtArg(0.25, 100), 25);
  assert.equal(gameUpdateSliceTailmid7230SqrtArg(1, 300), 300);
  assert.equal(gameUpdateSliceTailmid7230SqrtArg(0.1, 3), Math.fround(0.30000001192092896), "f32 product");
});

test("ABI v95 7230 spawn frame: sqrt_host_needed — CRT sqrt platform-primitive gate (PE 0x435a5d ucomisd 0.0,x / ja)", () => {
  assert.equal(gameUpdateSliceTailmid7230SqrtHostNeeded(-1), 1, "negative -> crt host");
  assert.equal(gameUpdateSliceTailmid7230SqrtHostNeeded(0), 0, "0 -> inline sqrtsd platform primitive");
  assert.equal(gameUpdateSliceTailmid7230SqrtHostNeeded(0.5), 0);
  assert.equal(gameUpdateSliceTailmid7230SqrtHostNeeded(-0.0), 0, "-0.0 equal -> NO host (ucomisd ZF)");
  assert.equal(gameUpdateSliceTailmid7230SqrtHostNeeded(NaN), 0, "NaN unordered -> NO host (ja needs CF=0 ZF=0)");
  assert.equal(gameUpdateSliceTailmid7230SqrtHostNeeded(0x7fffffff), 0, "huge positive");
});

test("ABI v95 7230 spawn frame: typed spawn-call arg prep (PE 0x8054e7..0x80550a push imms)", () => {
  assert.equal(gameUpdateSliceTailmid7230SpawnType(), TAILMID_7230_SPAWN_TYPE, "push 4");
  assert.equal(gameUpdateSliceTailmid7230SpawnVariant(), TAILMID_7230_SPAWN_VARIANT, "push 3");
  assert.equal(gameUpdateSliceTailmid7230SpawnPosVecPtr(), TAILMID_7230_SPAWN_POS_VEC_PTR, "push 0xc7b640");
  assert.equal(gameUpdateSliceTailmid7230SpawnArgPtrA(), TAILMID_7230_SPAWN_ARG_PTR_A, "push 0xc5d838");
  assert.equal(gameUpdateSliceTailmid7230SpawnArgPtrB(), TAILMID_7230_SPAWN_ARG_PTR_B, "push 0xc5d5dc");
  assert.equal(gameUpdateSliceTailmid7230SpawnPushZero(), 0, "push 0 (x4)");
  assert.equal(gameUpdateSliceTailmid7230GameRoomOffset(), TAILMID_7230_SPAWN_GAME_ROOM_OFF, "813460 receiver off 0x18300");
  const plan = gameUpdateSliceTailmid7230SpawnCallPlan(0x12345678);
  assert.deepEqual(plan.order,
    [0, 0xc5d838, 0xc5d5dc, 0, 0x12345678, 0, 0, 0xc7b640, "pos_out", 3, 4],
    "PE push order with the genrand dword and the pos-out slot in place");
  assert.equal(plan.type, 4);
  assert.equal(plan.variant, 3);
  assert.equal(plan.genrandDword >>> 0, 0x12345678);
});

