test("ABI v95: B8 grid blob path on the shipped Wasm mutates the scratch per the oracle", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (pre-v95); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const costsAddr = pick("isaac_game_update_slice_b8_costs_address")();
  const trailsAddr = pick("isaac_game_update_slice_b8_trails_address")();
  assert.equal(pick("isaac_game_update_slice_b8_max_cells")(), ROOM_B8_MAX_CELLS);
  assert.equal(typeof pick("isaac_game_update_slice_resume_room_update_prefix_b2_scratch"),
    "function", "B2 resume scratch export missing");
  const view = new DataView(wasm.memory.buffer);
  /* Seed the k-blob scratch with boundary cells (the host's live-grid
     capture at Room+0x76c / +0xe6c). */
  const costs = [3999, 1500, 900, 100, 1000, 0x7fffffff, 0, -5, 3998, 50];
  const trails = [50, 1, 99, 100, 1, 1, 0, 1, 100, 0];
  for (let i = 0; i < costs.length; i += 1) {
    view.setInt32(costsAddr + i * 4, costs[i] | 0, true);
    view.setInt16(trailsAddr + i * 2, trails[i] & 0xffff, true);
  }
  /* Drive the B2 resume on the blob path: gate open (frame%3==0, cells>0),
     blob ready, cells in [1, 448]. The wire runs the pure grid step over
     the seeded scratch and emits NO host residual. */
  pick("isaac_game_update_slice_reset_scratch")();
  const stateAddr = pick("isaac_game_update_slice_state_address")();
  const constAddr = pick("isaac_game_update_slice_constants_address")();
  const rtAddr = pick("isaac_game_update_slice_runtime_inputs_address")();
  const eventsAddr = pick("isaac_game_update_slice_events_address")();
  writeStruct(view, stateAddr, STATE_LAYOUT, { frameCounter264f8: 0 });
  writeStruct(view, rtAddr, RUNTIME_INPUTS_LAYOUT,
    normalizeRuntimeInputsForLayout({ roomGridCells: costs.length, roomB8BlobReady: 1 }));
  writeStruct(view, eventsAddr, EVENTS_LAYOUT, {
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX_B2,
  });
  for (let i = 0; i < costs.length; i += 1) {
    view.setInt32(costsAddr + i * 4, costs[i] | 0, true);
    view.setInt16(trailsAddr + i * 2, trails[i] & 0xffff, true);
  }
  assert.equal(pick("isaac_game_update_slice_resume_room_update_prefix_b2_scratch")(), 1,
    "B2 resume must accept the blob-path continuation");
  const eventsAfter = readStruct(view, eventsAddr, EVENTS_LAYOUT);
  assert.equal(eventsAfter.opaqueRoomUpdatePrefixB8 | 0, 0,
    "blob path must not emit the host residual");
  const oracleCosts = costs.slice();
  const oracleTrails = trails.slice();
  roomB8PathCostGridStep(oracleCosts, oracleTrails, costs.length);
  for (let i = 0; i < costs.length; i += 1) {
    assert.equal(view.getInt32(costsAddr + i * 4, true), oracleCosts[i] | 0,
      `wasm cost cell ${i} matches oracle`);
    assert.equal(view.getInt16(trailsAddr + i * 2, true), oracleTrails[i] | 0,
      `wasm trail cell ${i} matches oracle`);
  }
  /* Gate miss: frame%3!=0 leaves the scratch untouched and emits nothing. */
  pick("isaac_game_update_slice_reset_scratch")();
  writeStruct(view, stateAddr, STATE_LAYOUT, { frameCounter264f8: 1 });
  writeStruct(view, rtAddr, RUNTIME_INPUTS_LAYOUT,
    normalizeRuntimeInputsForLayout({ roomGridCells: costs.length, roomB8BlobReady: 1 }));
  writeStruct(view, eventsAddr, EVENTS_LAYOUT, {
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX_B2,
  });
  for (let i = 0; i < costs.length; i += 1) {
    view.setInt32(costsAddr + i * 4, costs[i] | 0, true);
    view.setInt16(trailsAddr + i * 2, trails[i] & 0xffff, true);
  }
  assert.equal(pick("isaac_game_update_slice_resume_room_update_prefix_b2_scratch")(), 1);
  const eventsMiss = readStruct(view, eventsAddr, EVENTS_LAYOUT);
  assert.equal(eventsMiss.opaqueRoomUpdatePrefixB8 | 0, 0, "gate miss emits nothing");
  for (let i = 0; i < costs.length; i += 1) {
    assert.equal(view.getInt32(costsAddr + i * 4, true), costs[i] | 0,
      `gate-miss cost cell ${i} untouched`);
    assert.equal(view.getInt16(trailsAddr + i * 2, true), trails[i] & 0xffff,
      `gate-miss trail cell ${i} untouched`);
  }
});

/* ------------------------------------------------------------------ v95 - */
/* Record idx 23 opaqueRoomUpdateClearPath — the two remaining pure laws:
   player-flag clear (flag gate + mask + target) and the post-door type-5
   decision (door result merge). Machine: cpu-dump 00804180.txt
   (0x00804212..0x0080424d; always-run type-5 loop 0x008042be..0x008042f3).
   FUN_00710dd0's open tail stays typed-host (v25 pin).
   Mutation legend (each flipped line fails THIS group, then restored
   sha256-byte-identical — NOTES.md update-v95-clear-path-laws):
   - flag_gate mode==0xd narrowed to a low-byte test (& 0xff): the WIDE
     0x1000000d drive dies (must CLEAR; a byte test SKIPS).
   - flag_gate range read UNSIGNED (mode > 6 via >>> 0): the signed
     0x80000000 drive dies (0x80000000 is signed < 1 -> CLEAR).
   - flag_gate bit16 read as bit0 (& 0x100): the 0xffffffff drive dies
     (bit16 set -> skip; bit0 test sees a set bit too, 0x1ff drive dies
     the other way).
   - door_result_merge `||` -> `&&`: the (1,0) and (0,1) drives die.
   - flag_target wrap dropped (no >>> 0 on the sum): the 0xffffffff
     drives die. */

test("ABI v95: clear-path flag gate mirrors the full-dword + signed machine gate", () => {
  /* PE 0x00804214 cmp eax,0xd / je SKIP — FULL-DWORD equality. */
  assert.equal(clearPathFlagGate(0xd, 0), 0, "mode 0xd skips the clear");
  assert.equal(clearPathFlagGate(0xd, 0x10000), 0, "mode 0xd skips regardless of flags");
  assert.equal(clearPathFlagGate(0x1000000d, 0), 1,
    "WIDE mode 0x1000000d != 0xd (full-dword) and > 6 -> CLEAR (low-byte mutant dies)");
  /* PE 0x00804219 cmp eax,1 jl CLEAR / 0x0080421e cmp eax,6 jg CLEAR — SIGNED. */
  assert.equal(clearPathFlagGate(0, 0), 1, "mode 0 < 1 -> CLEAR");
  assert.equal(clearPathFlagGate(1, 0x10000), 0, "mode 1 in range + flag -> skip");
  assert.equal(clearPathFlagGate(6, 0x10000), 0, "mode 6 in range + flag -> skip");
  assert.equal(clearPathFlagGate(7, 0x10000), 1, "mode 7 > 6 (signed) -> CLEAR even with flag");
  assert.equal(clearPathFlagGate(0xffffffff, 0), 1, "mode -1 < 1 signed -> CLEAR");
  assert.equal(clearPathFlagGate(0x80000000, 0x10000), 1,
    "mode 0x80000000 is signed-negative -> CLEAR (unsigned mutant dies)");
  /* PE 0x0080422b and ecx,0x10000 / jne SKIP — bit16 of Game+0x2654c. */
  assert.equal(clearPathFlagGate(2, 0), 1, "in-range + flag clear -> CLEAR");
  assert.equal(clearPathFlagGate(2, 0x10000), 0, "in-range + bit16 -> skip");
  assert.equal(clearPathFlagGate(2, 0xffffffff), 0,
    "WIDE flags keep bit16 -> skip (low-byte/bit0 mutant dies)");
  assert.equal(clearPathFlagGate(2, 0x1ff), 1, "flags low-only -> CLEAR");
});

test("ABI v95: clear-path flag mask is exactly the ~1 dword", () => {
  assert.equal(clearPathFlagMask(), 0xfffffffe,
    "PE 0x00804245 and dword,0xfffffffe clears bit 0 only");
});

test("ABI v95: clear-path flag target wraps manager + count*0x184 + 0x2a12c", () => {
  assert.equal(clearPathFlagTarget(0, 0), 0x2a12c, "base case");
  assert.equal(clearPathFlagTarget(0x1000, 1), 0x1000 + 0x184 + 0x2a12c, "single stride");
  assert.equal(clearPathFlagTarget(0, 0x100), 0x100 * 0x184 + 0x2a12c, "WIDE count");
  assert.equal(clearPathFlagTarget(0xffffffff, 1), ((0xffffffff + 0x184 + 0x2a12c) >>> 0),
    "32-bit wrap (imul + adds)");
  assert.equal(clearPathFlagTarget(0xffffffff, 0x100), ((0xffffffff + 0x100 * 0x184 + 0x2a12c) >>> 0),
    "wrap with WIDE count");
});

test("ABI v95: clear-path door result merge forces type-5 host on either side", () => {
  assert.equal(clearPathDoorResultMerge(0, 0), 0, "all early-out -> no type-5 host");
  assert.equal(clearPathDoorResultMerge(1, 0), 1, "clear-path door residual ran -> forced");
  assert.equal(clearPathDoorResultMerge(0, 1), 1, "pre-clear snapshot pure-gates type-5 -> host");
  assert.equal(clearPathDoorResultMerge(1, 1), 1, "both -> host");
  assert.equal(clearPathDoorResultMerge(0x100, 0), 1, "WIDE any (nonzero test, not bit0)");
  assert.equal(clearPathDoorResultMerge(0, 0x100), 1, "WIDE type5");
});

