test("ABI v95 tailmid 706c: hash step matches PE 0x8159cb..0x8159ea", () => {
  /* shr edx,cl(c1); xor edx,hash; shl eax,cl(c2); xor eax,edx;
     shr hash,cl(c3); xor hash,eax — 32-bit wrap, cl masked &31. */
  const refHash = (h, c1, c2, c3) => {
    const m1 = c1 & 31, m2 = c2 & 31, m3 = c3 & 31;
    const t = ((h >>> m1) ^ h) >>> 0;
    const u = ((t << m2) ^ t) >>> 0;
    return ((u >>> m3) ^ u) >>> 0;
  };
  const cases = [
    [0xdeadbeef, 13, 17, 5],
    [0, 13, 17, 5],
    [0xffffffff, 13, 17, 5],
    [0xdeadbeef, 31, 31, 31],
    [1, 1, 1, 1],
    [0x12345678, 32, 33, 34],  /* cl masks: 0,1,2 */
    [0xdeadbeef, 0, 0, 0],
  ];
  for (const [h, c1, c2, c3] of cases) {
    assert.equal(
      gameUpdateSliceTailmid706cExpireHashStep(h, c1, c2, c3),
      refHash(h, c1, c2, c3),
      `hash(0x${(h >>> 0).toString(16)}, ${c1}, ${c2}, ${c3})`,
    );
  }
  assert.equal(gameUpdateSliceTailmid706cExpireHashStep(0xdeadbeef, 13, 17, 5),
    0x4be231de, "fixed vector");
});

test("ABI v95 tailmid 706c: idiv pos floats mirror cvtdq2ps/mulss/addss (PE 0x815969..0x815997)", () => {
  const C4 = 0x3f000000; /* 0.5f @0xbaa904 */
  const C5 = 0x40000000; /* 2.0f @0xbaaa00 */
  const one = 0x3f800000; /* 1.0f */
  const refY = (rem, c4b) => {
    const c4 = tailmid706cF32(c4b);
    return Math.fround(Math.fround(Math.fround(rem) * c4) + c4);
  };
  const refX = (quot, c4b, c5b) => {
    const c4 = tailmid706cF32(c4b);
    const c5 = tailmid706cF32(c5b);
    return Math.fround(Math.fround(Math.fround(quot) * c4) + c5);
  };
  for (const [rem, c4b] of [[3, C4], [-3, C4], [0, C4], [0x1000001, C4],
    [0xffffff, C4], [5, one]]) {
    assert.equal(gameUpdateSliceTailmid706cExpirePosY(rem, c4b), refY(rem, c4b),
      `posY(${rem}, 0x${(c4b >>> 0).toString(16)})`);
  }
  for (const [quot, c4b, c5b] of [
    [3, C4, C5], [-3, C4, C5], [0, C4, C5],
    [0xffffff, C4, one],  /* mulss exact 8388607.5; addss +1 halfway -> even */
    [0x1000001, C4, C4],  /* cvtdq2ps rounds 16777217 -> 16777216 */
  ]) {
    assert.equal(gameUpdateSliceTailmid706cExpirePosX(quot, c4b, c5b), refX(quot, c4b, c5b),
      `posX(${quot}, 0x${(c4b >>> 0).toString(16)}, 0x${(c5b >>> 0).toString(16)})`);
  }
  /* Fixed PE-truth spot values (transcribed from the SSE pipeline). */
  assert.equal(gameUpdateSliceTailmid706cExpirePosY(3, C4), 2, "y = 3*0.5+0.5");
  assert.equal(gameUpdateSliceTailmid706cExpirePosY(-3, C4), -1, "y = -3*0.5+0.5");
  assert.equal(gameUpdateSliceTailmid706cExpirePosY(0x1000001, C4), 8388608,
    "cvtdq2ps(16777217)=16777216; *0.5=8388608; +0.5 halfway -> even 8388608");
  assert.equal(gameUpdateSliceTailmid706cExpirePosX(3, C4, C5), 3.5, "x = 3*0.5+2.0");
  assert.equal(gameUpdateSliceTailmid706cExpirePosX(-3, C4, C5), 0.5, "x = -3*0.5+2.0");
  assert.equal(gameUpdateSliceTailmid706cExpirePosX(0xffffff, C4, one), 8388608,
    "mulss 8388607.5 exact; addss +1 -> 8388608.5 halfway -> even 8388608");
});

