test("ABI v95 tailmid 706c: the shipped Wasm agrees with the oracle on the new exports", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (pre-v95); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const fields = [0, 1, 2, 3, 4, 5, 7, 0x13, 0x14, 0xff, 0x100, 0x1ff, 0x1000,
    0x7fffffff, 0x80000000, 0xffffffff];
  const cases = [
    ["isaac_game_update_slice_tailmid_706c_needs_expire_host", (f) => gameUpdateSliceTailmid706cNeedsExpireHost(f)],
    ["isaac_game_update_slice_tailmid_706c_countdown_next", (f) => gameUpdateSliceTailmid706cCountdownNext(f)],
    ["isaac_game_update_slice_tailmid_706c_expire_room_is_shop", (f) => gameUpdateSliceTailmid706cExpireRoomIsShop(f)],
    ["isaac_game_update_slice_tailmid_706c_expire_has_items", (f) => gameUpdateSliceTailmid706cExpireHasItems(f)],
    ["isaac_game_update_slice_tailmid_706c_expire_item_counter_byte_inc", (f) => gameUpdateSliceTailmid706cExpireItemCounterByteInc(f)],
    ["isaac_game_update_slice_tailmid_706c_expire_bucket_cell", (f) => gameUpdateSliceTailmid706cExpireBucketCell(f, 8), [8]],
    ["isaac_game_update_slice_tailmid_706c_expire_bucket_parity", (f) => gameUpdateSliceTailmid706cExpireBucketParity(f)],
    ["isaac_game_update_slice_tailmid_706c_expire_item_def_vcall_needed", (f) => gameUpdateSliceTailmid706cExpireItemDefVcallNeeded(f)],
    ["isaac_game_update_slice_tailmid_706c_expire_hash_step", (f) => gameUpdateSliceTailmid706cExpireHashStep(f, 13, 17, 5), [13, 17, 5]],
  ];
  for (const [name, oracle, extra, argsFn] of cases) {
    const fn = pick(name);
    assert.equal(typeof fn, "function", `${name} missing from the module`);
    for (const f of fields) {
      const args = argsFn ? argsFn(f) : (extra ? [f, ...extra] : [f]);
      assert.equal(fn(...args) | 0, oracle(f) | 0, `${name}(0x${(f >>> 0).toString(16)})`);
    }
  }
  /* Float laws: exact bit equality through the f32 pipeline. */
  const floatCases = [
    ["isaac_game_update_slice_tailmid_706c_expire_pos_y", (f) => gameUpdateSliceTailmid706cExpirePosY(f, 0x3f000000), [0x3f000000]],
    ["isaac_game_update_slice_tailmid_706c_expire_pos_x", (f) => gameUpdateSliceTailmid706cExpirePosX(f, 0x3f000000, 0x40000000), [0x3f000000, 0x40000000]],
  ];
  for (const [name, oracle, extra] of floatCases) {
    const fn = pick(name);
    assert.equal(typeof fn, "function", `${name} missing from the module`);
    for (const f of [0, 1, 3, -3, 0xff, 0x100, 0x1ff, 0xffffff, 0x1000001,
      0x7fffffff, 0xffffffff]) {
      const args = extra ? [f, ...extra] : [f];
      const gotBits = new Uint32Array(new Float32Array([fn(...args)]).buffer)[0] >>> 0;
      const wantBits = new Uint32Array(new Float32Array([oracle(f)]).buffer)[0] >>> 0;
      assert.equal(gotBits, wantBits, `${name}(0x${(f >>> 0).toString(16)}) bits`);
    }
  }
  for (const [name, want] of [
    ["isaac_game_update_slice_tailmid_706c_expire_drop_type", 0x96],
    ["isaac_game_update_slice_tailmid_706c_expire_drop_variant", 5],
    ["isaac_game_update_slice_tailmid_706c_expire_extra_type", 0x3e8],
    ["isaac_game_update_slice_tailmid_706c_expire_extra_variant", 0xf],
    ["isaac_game_update_slice_tailmid_706c_expire_entity_item_off", 0x32c],
    ["isaac_game_update_slice_tailmid_706c_expire_host_va", 0x008158a0],
  ]) {
    const fn = pick(name);
    assert.equal(typeof fn, "function", `${name} missing from the module`);
    assert.equal(fn() >>> 0, want >>> 0, `${name}() == 0x${(want >>> 0).toString(16)}`);
  }
});

/* ================= ABI v95: record idx 33 opaqueRoomUpdateClearDoors ====
   Type-5 door loop frame laws + typed door-open calls (unit
   update-v95-clear-doors-type5). PE-truth transcribed branch-by-branch from
   cpu-dump/00804230.txt (0x008042be..0x008042f3 — do NOT derive from the
   C++ or the model):
     count bound    0x8042be mov eax,8 ; counter STORED [ebp-0x98c]
                    (0x8042c9/0x8042ed) and RELOADED after the call
                    (0x8042e1) — 8 slots re-derived per iteration, never
                    folded once.
     per-door state 0x8042d2 test ecx,ecx / je skip (FULL-DWORD null);
                    0x8042d6 cmp dword [ecx+0xc],5 / jne skip (FULL-DWORD
                    field_c == 5). The type-5 loop runs ALWAYS (clear-path
                    AND set-10/20 paths converge here).
     arg prep       0x8042dc call 0x710dd0 — thiscall ecx=door, 0 stack
                    args. The callee's own prologue early-outs (pure no-op
                    gate, stepDoorHelper710dd0EarlyOut) — those calls are
                    not typed (zero observable work; the v25
                    any_type5_needs_host contract).
   The FORCED arm (clear-path door residual ran) re-runs the SAME loop over
   POST-clear states (open writes field_c=5) — qualifying set host-time, NO
   typed plan (stale-snapshot defect guard). The GATED arm (snapshot valid)
   publishes type5DoorOpenPlan; count > 0 == the any_type5_needs_host gate. */

test("ABI v95 type5 doors: loop count bound = 8 (PE 0x8042be mov eax,8, per-iteration store/reload)", () => {
  assert.equal(gameUpdateSliceType5DoorLoopCount(), 8,
    "PE 0x8042be mov eax,8; the counter is stored [ebp-0x98c] and reloaded "
    + "after the 0x710dd0 call (0x8042c9/e1/ea/ed/f3) — re-derived per iteration");
});

test("ABI v95 type5 doors: door_open_needed is FULL-DWORD present && field_c==5 (WIDE drives)", () => {
  /* PE 0x8042d2 test ecx,ecx / je + 0x8042d6 cmp dword [ecx+0xc],5 / jne. */
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(1, 5), 1, "present type-5 door");
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(0, 5), 0, "null slot skips");
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(0x100, 5), 1,
    "WIDE present 0x100 is nonzero in the FULL-DWORD test (a byte test would skip)");
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(0xffffffff, 5), 1,
    "WIDE present 0xffffffff is nonzero (full dword)");
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(1, 4), 0, "field_c 4 is not type-5");
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(1, 0x1000005), 0,
    "field_c 0x1000005 has low byte 5 but the FULL-DWORD compare must reject");
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(1, 0xffffffff), 0,
    "field_c 0xffffffff is not 5 (full dword)");
  assert.equal(gameUpdateSliceType5DoorOpenNeeded(0x100, 0x1000005), 0, "both wide -> no");
});

test("ABI v95 type5 doors: arg prep = thiscall door ptr, 0 stack args (PE 0x8042dc call 0x710dd0)", () => {
  assert.equal(gameUpdateSliceType5DoorOpenHostVa(), 0x00710dd0, "call target FUN_00710dd0");
  assert.equal(gameUpdateSliceType5DoorOpenStackArgCount(), 0,
    "ecx=door ptr only, no pushes before 0x8042dc");
});

test("ABI v95 type5 doors: plan builder types ONLY the doors that reach real 0x710dd0 work", () => {
  /* Type-5 loop law: call 0x710dd0 for each (ptr != 0 && field_c==5) door;
     the callee's early-out prologue (flags&0x10 && field8!=8 / flags&0x20 &&
     field8==4 / fieldC==2 / field8==7) is a pure no-op — excluded. */
  const slot = (over = {}) => ({ present: 1, field3a0: 0, field8: 1, fieldC: 5, ...over });
  const run = (slots) => type5DoorOpenPlan(
    slots.map((s) => (s ? { ...s } : { present: 0, field3a0: 0, field8: 0, fieldC: 0 })),
  );

  const empty = type5DoorOpenPlan([]);
  assert.equal(empty.count, 0, "no slots -> no calls");

  const single = run([slot()]);
  assert.equal(single.count, 1, "one type-5 door -> one typed call");
  assert.equal(single.doors[0].slotIndex, 0, "machine slot order");
  assert.equal(single.doors[0].present, 1);
  assert.equal(single.doors[0].field3a0, 0);
  assert.equal(single.doors[0].field8, 1);
  assert.equal(single.doors[0].fieldC, 5, "the type-5 discriminator");

  /* Slot indexing: a type-5 door at slot 4 (PE walk base Room+0x724 stride 4). */
  const idx = run([null, null, null, null, slot()]);
  assert.equal(idx.count, 1, "slot 4 door");
  assert.equal(idx.doors[0].slotIndex, 4, "slot_index must be 4");

  /* Early-out type-5 door: (flags&0x10 && field8!=8) -> 0x710dd0 no-ops. */
  const early = run([slot({ field3a0: 0x10 })]);
  assert.equal(early.count, 0, "flags&0x10 && field8!=8 -> pure early-out, not typed");
  const early2 = run([slot({ field3a0: 0x20, field8: 4 })]);
  assert.equal(early2.count, 0, "flags&0x20 && field8==4 -> pure early-out");
  const early3 = run([slot({ field8: 7 })]);
  assert.equal(early3.count, 0, "field8==7 -> pure early-out");

  /* Non-type-5 / null slots never qualify. */
  assert.equal(run([slot({ fieldC: 4 })]).count, 0, "field_c 4 not type-5");
  assert.equal(run([slot({ present: 0 })]).count, 0, "null slot (present 0) skipped");
  assert.equal(run([slot({ fieldC: 0x1000005 })]).count, 0, "WIDE field_c rejected (full dword)");
  assert.equal(run([slot({ present: 0x100 })]).count, 1, "WIDE present 0x100 qualifies (full dword)");

  /* Machine slot order, mixed set. */
  const mixed = run([
    slot({ fieldC: 4 }),      /* 0: not type-5 */
    slot(),                   /* 1: type-5 -> CALL */
    slot({ field3a0: 0x10 }), /* 2: type-5 but early-out -> no call */
    null,                     /* 3: null */
    slot(),                   /* 4: type-5 -> CALL */
  ]);
  assert.equal(mixed.count, 2, "two real calls");
  assert.equal(mixed.doors[0].slotIndex, 1, "first call in machine order");
  assert.equal(mixed.doors[1].slotIndex, 4, "second call in machine order");
});

test("ABI v95 type5 doors: gated arms (0x10/2 skip, non-clear side) publish the typed plan with the coarse event", () => {
  const base = step({});
  const ev = { ...base.events, continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX };
  /* Census (update-v95-clear-doors-type5): on the CLEAR side a working
     type-5 door (field_c==5, no early-out) ALSO fails the clear-path
     early-out -> the clear-path door residual fires -> FORCED arm (no
     plan). The typed-plan gated arms are exactly the no-clear-path arms:
     non-clear side (alive/greed/delay) and the 0x10/2 / 0x10/3 skips. */
  const gatedBase = {
    ...base.state,
    timedTransitionCleanupMode: 0,
    roomClearDelay11ec: 0, roomAlive12c0: 0, roomAlive12c4: 0, roomGreedWave723c: 0,
    roomDescFlags44: 0,
  };

  /* 0x10/2 skip: the whole clear-path block is skipped (no door residual)
     -> the type-5 decision is gated by the fresh snapshot -> typed plan. */
  const skip = resumeGameUpdateRoomUpdatePrefix(
    { ...gatedBase, roomType8: 0x10, roomDescSubtype: 2 },
    { doorSlots: [{ present: 1, field3a0: 0, field8: 1, fieldC: 5 }] },
    ev,
  );
  assert.equal(skip.events.opaqueRoomUpdateClearPath | 0, 0, "0x10/2 skips clear-path flag");
  assert.equal(skip.events.opaqueRoomUpdateClearDoorSlots | 0, 0, "0x10/2 skips the door residual");
  assert.equal(skip.events.opaqueRoomUpdateClearDoors | 0, 0,
    "coarse edge RETIRED at v119 — the typed plan is the carrier");
  assert.equal(skip.events.type5DoorOpenCalls | 0, 1, "typed plan count");
  assert.equal(skip.events.continuationKind, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_CLEAR);

  /* Two type-5 doors on the 0x10/2 arm -> plan count 2. */
  const two = resumeGameUpdateRoomUpdatePrefix(
    { ...gatedBase, roomType8: 0x10, roomDescSubtype: 2 },
    {
      doorSlots: [
        { present: 1, field3a0: 0, field8: 1, fieldC: 5 },
        { present: 1, field3a0: 0, field8: 1, fieldC: 5 },
      ],
    },
    ev,
  );
  assert.equal(two.events.opaqueRoomUpdateClearDoors | 0, 0,
    "coarse edge RETIRED at v119 — two typed open calls carry the residual");
  assert.equal(two.events.type5DoorOpenCalls | 0, 2, "two typed open calls");

  /* Non-clear side (alive>0 -> LAB_00804293 set-10 path): the machine still
     runs the type-5 loop with NO prior door mutation -> gated plan. */
  const alive = resumeGameUpdateRoomUpdatePrefix(
    { ...gatedBase, roomType8: 1, roomAlive12c0: 3 },
    { doorSlots: [{ present: 1, field3a0: 0, field8: 1, fieldC: 5 }] },
    ev,
  );
  assert.equal(alive.events.opaqueRoomUpdateClearDoors | 0, 0,
    "set-10 path still runs the type-5 loop (coarse RETIRED at v119, plan carries)");
  assert.equal(alive.events.type5DoorOpenCalls | 0, 1, "snapshot valid on the non-clear side");

  /* All type-5 doors early-out -> no coarse event, no plan (any arm). */
  const none = resumeGameUpdateRoomUpdatePrefix(
    { ...gatedBase, roomType8: 0x10, roomDescSubtype: 2 },
    { doorSlots: [{ present: 1, field3a0: 0x10, field8: 1, fieldC: 5 }] },
    ev,
  );
  assert.equal(none.events.opaqueRoomUpdateClearDoors | 0, 0, "all early-out -> no host");
  assert.equal(none.events.type5DoorOpenCalls | 0, 0, "no typed calls");
});

test("ABI v95 type5 doors: CLEAR-side type-5 doors are FORCED (door residual runs too) — NO typed plan", () => {
  /* A working type-5 door (field_c==5, no early-out) also fails the
     clear-path early-out, so the clear-path door residual runs first and
     may rewrite field_c — the type-5 loop then runs over POST-clear states.
     The stale snapshot cannot type it (defect class: post-call folded to
     pre-call snapshot): coarse event only. */
  const base = step({});
  const shaped = {
    ...base.state,
    timedTransitionCleanupMode: 0,
    roomClearDelay11ec: 0, roomAlive12c0: 0, roomAlive12c4: 0, roomGreedWave723c: 0,
    roomType8: 1, roomDescSubtype: 0, roomDescFlags44: 0,
  };
  const ev = { ...base.events, continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX };
  const out = resumeGameUpdateRoomUpdatePrefix(shaped, {
    doorSlots: [{ present: 1, field3a0: 0, field8: 1, fieldC: 5 }],
  }, ev);
  assert.equal(out.events.opaqueRoomUpdateClearDoorSlots | 0, 0,
    "idx-24 coarse RETIRED at v119 — the failing mask carries");
  assert.equal(out.events.opaqueRoomUpdateClearDoorSlotsMask | 0, 1, "the type-5 door also fails the clear-path early-out");
  assert.equal(out.events.opaqueRoomUpdateClearDoors | 0, 0, "forced type-5 coarse RETIRED at v119");
  assert.equal(out.events.type5DoorForcedRerun | 0, 1, "forced-arm typed carrier fires");
  assert.equal(out.events.type5DoorOpenCalls | 0, 0,
    "clear-side type-5 path is forced: host re-runs clear-path + type-5 loops over live states");
});

test("ABI v95 type5 doors: FORCED arm (clear-path doors ran) publishes NO typed plan", () => {
  /* The clear-path door residual fires for a door failing early-out; it may
     write field_c=5 on open, so the pre-clear snapshot cannot type the
     post-clear loop (defect class: post-call folded to pre-call snapshot). */
  const base = step({});
  const shaped = {
    ...base.state,
    timedTransitionCleanupMode: 0,
    roomClearDelay11ec: 0, roomAlive12c0: 0, roomAlive12c4: 0, roomGreedWave723c: 0,
    roomType8: 1, roomDescSubtype: 0, roomDescFlags44: 0,
  };
  const ev = { ...base.events, continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX };
  const out = resumeGameUpdateRoomUpdatePrefix(shaped, {
    doorSlots: [
      { present: 1, field3a0: 0, field8: 1, fieldC: 1 }, /* clear-path residual fires (no early-out) */
      { present: 1, field3a0: 0, field8: 1, fieldC: 5 }, /* type-5 in the STALE snapshot */
    ],
  }, ev);
  assert.equal(out.events.opaqueRoomUpdateClearDoorSlots | 0, 0,
    "idx-24 coarse RETIRED at v119 — the failing mask carries");
  assert.equal(out.events.opaqueRoomUpdateClearDoorSlotsMask | 0, 3,
    "both slots fail the clear-path early-out -> mask bits 0+1 (residual ran -> forced)");
  assert.equal(out.events.opaqueRoomUpdateClearDoors | 0, 0, "forced type-5 coarse RETIRED at v119");
  assert.equal(out.events.type5DoorForcedRerun | 0, 1, "forced-arm typed carrier fires");
  assert.equal(out.events.type5DoorOpenCalls | 0, 0,
    "forced arm must NOT type from the stale snapshot (host re-runs the loop over post-clear states)");
});

