/* ==================================================================== */
/* ABI v95 (record idx 31, Room::TriggerClear 0x008068f0): CALL-ARG /
   decision laws of the non-greed fragments. Bodies stay typed-host.
   PE-truth references transcribed branch-by-branch from
   section-notes/update-v95-8068f0-trigger-clear/disasm-8068f0-full.txt. */

test("ABI v95 trigger-clear stats call args: word truncation and bit-10 law", () => {
  /* PE 0x80691e shr eax,0xa / 0x806921 and al,1 / 0x806923 movzx: the 4th
     arg is bit 10 of RoomDescriptor flags ONLY (0x806926 push eax). 0x806927
     movzx eax, word ptr [edx+0x4a]: the 3rd arg is the 16-bit clear count. */
  const bits = (v) => (new Uint32Array(new Float32Array([v]).buffer))[0];
  void bits; /* f32 helper not needed here */
  const a = gameUpdateSliceTriggerClearStatsArgs(7, 0x12348, 0x1ffff, 0x400);
  assert.equal(a.roomType, 7, "room type passthrough");
  assert.equal(a.stageData, 0x12348, "stage data passthrough");
  assert.equal(a.clearCountWord, 0xffff, "0x1ffff truncates to word 0xffff (movzx)");
  assert.equal(a.flagBit10, 1, "flags 0x400 -> bit10 set");
  const b = gameUpdateSliceTriggerClearStatsArgs(7, 0, 0x10000, 0x800);
  assert.equal(b.clearCountWord, 0, "0x10000 -> 0 word (movzx truncation)");
  assert.equal(b.flagBit10, 0, "flags 0x800 -> bit10 clear (bit 11 set)");
  const c = gameUpdateSliceTriggerClearStatsArgs(7, 0, 0x10ff, 0xffffffff);
  assert.equal(c.clearCountWord, 0x10ff, "0x10ff stays 0x10ff in a word");
  assert.equal(c.flagBit10, 1, "0xffffffff bit10 set");
  /* WIDE: a full-dword model of clear_count would keep 0x1ffff — the word
     law is the PE movzx and the test must fail a dword mutant. */
  assert.notEqual(a.clearCountWord, 0x1ffff, "word truncation is NOT dword");
});

test("ABI v95 trigger-clear music args: non-greed fires 0x7f7a40; 0x7f83b0 always", () => {
  /* PE 0x8069c9 push 0 ; 0x8069cb push 1 ; call 0x7f7a40 -> cdecl (1, 0),
     this=room. Gated by mode != 2 && mode != 3 at 0x8069b9..0x8069c7
     (difficulty Game+0x269c8). 0x7f83b0 (0x8069d4) ALWAYS fires with the
     same (1, 0). */
  for (const mode of [0, 1, 4, 5, 0x100, 0x1ff, 0xffffffff]) {
    const m = gameUpdateSliceTriggerClearMusicArgs(mode);
    assert.equal(m.fire7f7a40, 1, `mode ${mode} is non-greed -> 7f7a40 fires`);
    assert.equal(m.fire7f83b0, 1, "7f83b0 always fires");
    assert.equal(m.arg1, 1, "arg1 = 1 (push 1)");
    assert.equal(m.arg2, 0, "arg2 = 0 (push 0)");
  }
  for (const mode of [2, 3]) {
    const m = gameUpdateSliceTriggerClearMusicArgs(mode);
    assert.equal(m.fire7f7a40, 0, `mode ${mode} greed -> 7f7a40 skipped`);
    assert.equal(m.fire7f83b0, 1, "7f83b0 still fires in greed");
    assert.equal(m.arg1, 1, "arg1 = 1");
    assert.equal(m.arg2, 0, "arg2 = 0");
  }
});

test("ABI v95 trigger-clear SFX plan: playSound low-byte gate + typed Play args", () => {
  /* PE 0x8069df cmp byte [ebp+8],0 / jne 0x806a26: LOW-BYTE test on the
     playSound bool arg, so 0x100 is a skip, 0xff/0x1ff are armed. The
     id slot seeded 0x24 (0x8069ee mov [ebp+8],0x24) feeds 0x956780 (host)
     then Play 0x92dc30 with the const args and receiver [0xc7169c]+0x2a324. */
  for (const ps of [0, 0x100, 0x1000000]) {
    const p = gameUpdateSliceTriggerClearSfxPlan(ps);
    assert.equal(p.armed, 1, `playSound 0x${ps.toString(16)} low byte 0 -> armed`);
    assert.equal(p.seedId, TRIGGER_CLEAR_SFX_SEED_NORMAL, "seed 0x24");
    assert.equal(p.volumeBits, 0x3f800000, "volume 1.0f");
    assert.equal(p.frameDelay, 2, "frame delay 2");
    assert.equal(p.loop, 0, "loop 0");
    assert.equal(p.pitchBits, 0x3f800000, "pitch 1.0f");
    assert.equal(p.pan, 0, "pan 0");
    assert.equal(p.receiverOff, TRIGGER_CLEAR_SFX_RECEIVER_OFF, "receiver +0x2a324");
  }
  for (const ps of [1, 0xff, 0x1ff, 0xffffffff]) {
    const p = gameUpdateSliceTriggerClearSfxPlan(ps);
    assert.equal(p.armed, 0, `playSound 0x${ps.toString(16)} low byte nonzero -> skip`);
  }
});

test("ABI v95 trigger-clear deep-music gate: head-clear/vec + five common gates", () => {
  /* PE 0x806a65..0x806b59. head-clear (byte 0x1bb84==0 && probe 0x9e9b50
     ==0 && probe 0x9595e0==0 && byte 0x26588==0) jumps DIRECT to 0x806aad
     (je 0x806a99); any nonzero -> vec non-empty gate (0x806a9b je skip).
     Common (0x806aad): count[+0x334]>0 jbe, [Game+0x1839c]&0x10000==0,
     room match, [Game]==1, [Game+4] not 4/5, [Game+0x264f8]<=0x708 SIGNED. */
  const base = {
    byte1bb84: 0, probe9e9b50: 0, probe9595e0: 0, byte26588: 0,
    vecBegin4b3d8: 0, vecEnd4b3dc: 0, count334: 1, flag1839c: 0,
    roomMatch: 1, game0: 1, game4: 0, frame264f8: 0,
  };
  const d = gameUpdateSliceTriggerClearDeepMusicGate(base);
  assert.equal(d.fire, 1, "all gates open -> deep music runs");
  assert.equal(d.flagOr10000, 0x10000, "[Game+0x1839c] |= 0x10000");
  assert.equal(d.sfxSeedId, TRIGGER_CLEAR_SFX_SEED_DEEP, "SFX seed 0x5a");
  assert.equal(d.room72fcZero, 1, "Room+0x72fc = 0");

  /* head blockers: any of the four head bytes nonzero -> vec gate. */
  for (const key of ["byte1bb84", "probe9e9b50", "probe9595e0", "byte26588"]) {
    const blocked = gameUpdateSliceTriggerClearDeepMusicGate({ ...base, [key]: 1 });
    assert.equal(blocked.fire, 0, `${key} nonzero with EMPTY vec -> skip (je 0x806a9b)`);
    /* but a NON-EMPTY vec restores reach 0x806aad */
    const ok = gameUpdateSliceTriggerClearDeepMusicGate({ ...base, [key]: 1, vecBegin4b3d8: 8, vecEnd4b3dc: 8 });
    assert.equal(ok.fire, 0, `${key} nonzero + vec equal -> still skip`);
    const ok2 = gameUpdateSliceTriggerClearDeepMusicGate({ ...base, [key]: 1, vecBegin4b3d8: 8, vecEnd4b3dc: 12 });
    assert.equal(ok2.fire, 1, `${key} nonzero + vec non-empty -> reach 0x806aad; common gates open`);
  }

  /* common gates, one at a time with vec non-empty (the harder arm). */
  const reach = { ...base, vecBegin4b3d8: 8, vecEnd4b3dc: 12 };
  const cases = [
    ["count334", 0, "count<=0 jbe skips"],
    ["flag1839c", 0x10000, "bit16 set jne skips"],
    ["roomMatch", 0, "room mismatch jne skips"],
    ["game0", 2, "[Game]!=1 jne skips"],
    ["game4", 4, "[Game+4]==4 je skips"],
    ["game4", 5, "[Game+4]==5 je skips"],
  ];
  for (const [k, v, why] of cases) {
    const out = gameUpdateSliceTriggerClearDeepMusicGate({ ...reach, [k]: v });
    assert.equal(out.fire, 0, `${k}=${v} -> ${why}`);
    assert.equal(out.flagOr10000, 0, `${k} no-flag when skipped`);
    assert.equal(out.room72fcZero, 0, `${k} no room write when skipped`);
  }
  /* frame gate is SIGNED: 0x700 passes, 0x709 fails, 0xffffffff (=-1) passes. */
  assert.equal(gameUpdateSliceTriggerClearDeepMusicGate({ ...reach, frame264f8: 0x700 }).fire, 1, "frame 0x700 <= 0x708");
  assert.equal(gameUpdateSliceTriggerClearDeepMusicGate({ ...reach, frame264f8: 0x709 }).fire, 0, "frame 0x709 > 0x708 (jg)");
  assert.equal(gameUpdateSliceTriggerClearDeepMusicGate({ ...reach, frame264f8: 0xffffffff }).fire, 1, "frame -1 signed <= 0x708");
  assert.equal(gameUpdateSliceTriggerClearDeepMusicGate({ ...reach, frame264f8: 0x80000000 }).fire, 1, "frame INT_MIN signed <= 0x708");
});

test("ABI v95 trigger-clear awards walk: bit7 gate + greed-room1 skip + receivers", () => {
  /* PE 0x806b63..0x806b98. flags bit7 clear -> walk; 0x9bb840 receiver lea
     ecx,[esi+0x1baa8] fires UNLESS greed && roomType==1 (0x806b80 cmp
     [ebx+8],1 / je 0x806b91); 0x7fb250 (this=room) ALWAYS when walk. */
  const W = gameUpdateSliceTriggerClearAwardsWalk(0x07f, 0, 1);
  assert.equal(W.walkActive, 1, "bit7 clear -> walk active");
  assert.equal(W.fire9bb840, 1, "non-greed -> 0x9bb840 fires");
  assert.equal(W.fire7fb250, 1, "walk -> 0x7fb250 fires");
  assert.equal(W.receiver9bb840Off, 0x1baa8, "receiver Game+0x1baa8");
  const G = gameUpdateSliceTriggerClearAwardsWalk(0x07f, 2, 1);
  assert.equal(G.fire9bb840, 0, "greed && roomType==1 -> skip 0x9bb840");
  assert.equal(G.fire7fb250, 1, "7fb250 still fires");
  const G2 = gameUpdateSliceTriggerClearAwardsWalk(0x07f, 3, 1);
  assert.equal(G2.fire9bb840, 0, "greedier && roomType==1 -> skip 0x9bb840");
  const G3 = gameUpdateSliceTriggerClearAwardsWalk(0x07f, 2, 5);
  assert.equal(G3.fire9bb840, 1, "greed but roomType!=1 -> 0x9bb840 fires");
  const S = gameUpdateSliceTriggerClearAwardsWalk(0x080, 0, 1);
  assert.equal(S.walkActive, 0, "bit7 set -> walk inactive");
  assert.equal(S.fire9bb840, 0, "no walk -> no 9bb840");
  assert.equal(S.fire7fb250, 0, "no walk -> no 7fb250");
  const WIDE = gameUpdateSliceTriggerClearAwardsWalk(0x10080, 0, 1);
  assert.equal(WIDE.walkActive, 0, "0x10080 still bit7 set (full word)");
});

test("ABI v95 trigger-clear rewind tail: always -1 (v74 frozen push)", () => {
  /* PE 0x806c0a push -1 ; call 0x705ee0 — unconditional, ALWAYS arg 0xffffffff. */
  const t = gameUpdateSliceTriggerClearRewindTailArg();
  assert.equal(t.fire, 1, "tail always fires");
  assert.equal(t.arg, 0xffffffff, "arg = -1 (0xffffffff)");
});

