test("ABI v95: the shipped Wasm agrees with the oracle on the trigger-clear laws", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("stale module — the coordinator rebuilds the Wasm at the wave-end layout merge");
    return;
  }
  const u32 = (v) => (new Uint32Array(new Float32Array([v]).buffer))[0];
  void u32;
  const statsW = pick("isaac_game_update_slice_trigger_clear_stats_args");
  const statsMem = new Uint32Array(wasm.memory.buffer);
  /* reuse a spare scratch address: the last 16 bytes of the state-free zone is
     not guaranteed — use the events address region tail instead. */
  const out = wasm.isaac_game_update_slice_events_address() + 512;
  statsW(7, 0x12348, 0x1ffff, 0x400, out);
  const a = gameUpdateSliceTriggerClearStatsArgs(7, 0x12348, 0x1ffff, 0x400);
  assert.equal(statsMem[(out >> 2)] >>> 0, a.roomType, "wasm stats roomType");
  assert.equal(statsMem[(out >> 2) + 1] >>> 0, a.stageData, "wasm stats stageData");
  assert.equal(statsMem[(out >> 2) + 2] >>> 0, a.clearCountWord, "wasm stats clearCountWord");
  assert.equal(statsMem[(out >> 2) + 3] >>> 0, a.flagBit10, "wasm stats flagBit10");
  const deepW = pick("isaac_game_update_slice_trigger_clear_deep_music_gate");
  const deep = {
    byte1bb84: 0, probe9e9b50: 0, probe9595e0: 0, byte26588: 0,
    vecBegin4b3d8: 8, vecEnd4b3dc: 12, count334: 1, flag1839c: 0,
    roomMatch: 1, game0: 1, game4: 0, frame264f8: 0,
  };
  deepW(deep.byte1bb84, deep.probe9e9b50, deep.probe9595e0, deep.byte26588,
    deep.vecBegin4b3d8, deep.vecEnd4b3dc, deep.count334, deep.flag1839c,
    deep.roomMatch, deep.game0, deep.game4, deep.frame264f8, out);
  const expectDeep = gameUpdateSliceTriggerClearDeepMusicGate(deep);
  assert.equal(statsMem[(out >> 2)] >>> 0, expectDeep.fire, "wasm deep fire");
  assert.equal(statsMem[(out >> 2) + 1] >>> 0, expectDeep.flagOr10000, "wasm deep flag");
  assert.equal(statsMem[(out >> 2) + 2] >>> 0, expectDeep.sfxSeedId, "wasm deep sfx seed");
  assert.equal(statsMem[(out >> 2) + 3] >>> 0, expectDeep.room72fcZero, "wasm deep room72fc");
  const walkW = pick("isaac_game_update_slice_trigger_clear_awards_walk");
  walkW(0x07f, 2, 1, out);
  const expectWalk = gameUpdateSliceTriggerClearAwardsWalk(0x07f, 2, 1);
  assert.equal(statsMem[(out >> 2)] >>> 0, expectWalk.walkActive, "wasm walk active");
  assert.equal(statsMem[(out >> 2) + 1] >>> 0, expectWalk.fire9bb840, "wasm walk 9bb840");
  assert.equal(statsMem[(out >> 2) + 2] >>> 0, expectWalk.fire7fb250, "wasm walk 7fb250");
  assert.equal(statsMem[(out >> 2) + 3] >>> 0, expectWalk.receiver9bb840Off, "wasm walk receiver");
});

/* ====== ABI v95: record idx 13 opaqueRoomUpdatePrefixB1 — B1 fragment wire v45
   The v45 wire routes the B1 first-frame residual host between MONOLITHIC
   (sparse packs missing) and the split opaqueRoomUpdatePrefixB1Sfx /
   opaqueRoomUpdatePrefixB1Spawn fragments (SFX site 0x00802a53, spawn suite
   0x00802b60..0x00802e1a). PE order inside 0x00802a40..0x00802e20:
     SFX gate (type==5 && desc+0x40==1 && bossId!=0 && !greed-suppress)
        -> FUN_00956780 pre + SFXManager::Play 0x92dc30 with imms id 0xbe,
           Vol 1.0f (0x3f800000 @0x802a69), FrameDelay 2 (push 2 @0x802a72),
           Loop 0, Pitch 1.0f (0x3f800000 @0x802a75), Pan 0  (PLAYS FIRST)
     once-flag 0x00802a93 test [Game+0x1839c],0x80000 / jne 0x802e25
        (skips ONLY corner+spawn; SFX already played)
     flag OR  0x00802a9e or 0x80000  (pure once-flag apply, pre-host)
     corner table 0x00802aa9..0x00802b48
     buffer gate 0x00802b4e cmp [183a4],[183a8] / je 0x802e25
     spawn suite 0x00802b60..0x00802e1a (view 0x752830, owner 0x9be6b0,
        quality 0x7cb6e0 of collectible 0x89, shuffle 0x4d3130/0x4d3230/
        0x4d6ee0, position 0x813520, spawn 0x428b20, bind 0x7ef420,
        cleanup 0x708e20).
   Mutation legend (each flipped line fails THIS group, then restored
   sha256-byte-identical — NOTES.md update-v95-b1-fragments):
   - model MONOLITHIC condition `sfxReady==0 || (once && !buffer)` folded to
     AND: open-outer + sfxReady=0 drive falls into fragments -> mono vector
     dies.
   - model pure-complete NONE branch dropped: outer-closed drive emits a
     monolithic event -> closed vector dies.
   - spawn relay de-gated from once-clear: flag-SET + nonempty buffer drive
     emits SPAWN (PE 0x802a98 jne 0x802e25 skips) -> flag-set vector dies.
   - roomB1SfxNeedsHost greed conjunct dropped: greed/stage-7/nested-0
     suppress case emits SFX -> suppress vector dies. */

test("ABI v95: record idx 13 JSON spec lands the B1 fragment wire v45", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  const rec = spec.opaqueBoundaries.find((b) => b.idx === 13);
  assert.ok(rec, "record idx 13 stays in opaqueBoundaries");
  assert.equal(rec.operation, "NARROWED", "record is NARROWED-not-removed this unit");
  assert.match(rec.abiV95 || "", /0x802a53|0x802b60|Play|0xbe|B1Sfx|B1Spawn|wire/i,
    "record idx 13 abiV95 note names the landed fragment wire");
  for (const name of [
    "b1SfxReady", "b1BufferReady", "b1DescField40", "b1NestedField10",
    "b1Begin183a4", "b1End183a8",
  ]) {
    const slot = spec.runtimeInputs.find((r) => r.name === name);
    assert.ok(slot, `spec records ${name}`);
    assert.equal(slot.type, "u32");
    assert.equal(slot.bytes, 4);
  }
  for (const name of [
    "opaqueRoomUpdatePrefixB1Sfx", "opaqueRoomUpdatePrefixB1Spawn",
  ]) {
    const ev = spec.events.find((e) => e.name === name);
    assert.ok(ev, `spec records ${name}`);
    assert.equal(ev.type, "u32");
    assert.equal(ev.bytes, 4);
  }
  /* Layout pins: runtime 804..824 (v45 append after PM2 @ 800), events
     340/344 (v45 append after 336). */
  for (const [name, off] of [
    ["b1SfxReady", 804], ["b1BufferReady", 808], ["b1DescField40", 812],
    ["b1NestedField10", 816], ["b1Begin183a4", 820], ["b1End183a8", 824],
  ]) {
    assert.equal(RUNTIME_INPUTS_LAYOUT[name].offset, off, `${name} offset`);
  }
  assert.equal(EVENTS_LAYOUT.opaqueRoomUpdatePrefixB1Sfx.offset, 340);
  assert.equal(EVENTS_LAYOUT.opaqueRoomUpdatePrefixB1Spawn.offset, 344);
  assert.equal(spec.opaqueBoundaries.length, 24);
});

test("ABI v95: B1 wire matrix drives every PE arm (packs missing -> MONOLITHIC)", () => {
  /* open outer: Room active byte != 0 && (frame - entry) == 1 (0x802a40
     gate; model increments frameCounter264f8 before the wire). */
  const open = { roomActiveByte0: 1, frame264f8: 10, roomEntry11f0: 9 };
  const sfxOn = {
    roomType8: 5, descField40: 1, bossId1bb0: 0x2a, difficulty269c8: 0,
    stage0: 1, nestedField10: 0, flags60e7: 0,
  };
  /* outer_ready=0: cannot prove skip -> MONOLITHIC (recipe matrix row 1). */
  const p0 = roomB1WireDecide({ outerReady: 0 });
  assert.equal(p0.residualKind, ROOM_B1_RESIDUAL_MONOLITHIC, "no outer inputs -> MONOLITHIC");
  assert.equal(p0.pureOnceFlagApply, 0, "no once apply without outer proof");
  /* outer open + !sfx_ready -> MONOLITHIC (row 3); once apply still markable. */
  const p1 = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 0, bufferReady: 0, ...sfxOn });
  assert.equal(p1.residualKind, ROOM_B1_RESIDUAL_MONOLITHIC, "open + !sfx_ready -> MONOLITHIC");
  assert.equal(p1.onceFlagClear, 1, "flag clear at 0x802a93");
  assert.equal(p1.pureOnceFlagApply, 1, "pure OR applied pre-host");
  /* open + once clear + !buffer_ready -> MONOLITHIC (row 4). */
  const p2 = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 0, ...sfxOn });
  assert.equal(p2.residualKind, ROOM_B1_RESIDUAL_MONOLITHIC, "open once-clear + !buffer_ready -> MONOLITHIC");
  assert.equal(p2.pureOnceFlagApply, 1, "still dual-safe flag apply");
  /* open + !sfx_ready but flag SET: SFX Play precedes the once gate, so the
     MONOLITHIC fallback still applies (sparse sfx pack missing). */
  const p1b = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 0, bufferReady: 0, ...sfxOn, flags60e7: 0x80000 });
  assert.equal(p1b.residualKind, ROOM_B1_RESIDUAL_MONOLITHIC, "open + !sfx_ready + flag set -> MONOLITHIC");
  assert.equal(p1b.pureOnceFlagApply, 0, "flag already set -> no OR");
});

test("ABI v95: B1 wire matrix — NONE / SFX / SPAWN / SFX_SPAWN fragment kinds (PE-truth)", () => {
  const open = { roomActiveByte0: 1, frame264f8: 10, roomEntry11f0: 9 };
  const sfxOn = {
    roomType8: 5, descField40: 1, bossId1bb0: 0x2a, difficulty269c8: 0,
    stage0: 1, nestedField10: 0, flags60e7: 0,
  };
  /* Outer closed -> pure-complete NONE (0x802a40 gate closed; no host). */
  const pNone = roomB1WireDecide({ ...open, roomActiveByte0: 0, outerReady: 1, sfxReady: 1, bufferReady: 1, ...sfxOn });
  assert.equal(pNone.residualKind, ROOM_B1_RESIDUAL_NONE, "outer closed -> NONE");
  assert.equal(pNone.pureComplete, 1, "pure-complete");
  assert.equal(pNone.hostNeeded, 0, "no host residual");
  assert.equal(pNone.pureOnceFlagApply, 0, "no flag apply when outer closed");
  /* Flag set + sfx gate open + buffer missing: PE Play already ran BEFORE the
     once gate (0x802a82 call < 0x802a93 test) -> SFX fragment, spawn skipped. */
  const pSfxFlag = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 0, ...sfxOn, flags60e7: 0x80000, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(pSfxFlag.residualKind, ROOM_B1_RESIDUAL_SFX, "flag set + sfx open -> SFX (spawn skipped by 0x802a98 jne)");
  assert.equal(pSfxFlag.spawnNeedsHost, 0, "spawn gated off by once flag");
  assert.equal(pSfxFlag.pureOnceFlagApply, 0, "no OR when set");
  /* SFX-only: buffer empty (0x802b53 je) or flag set. */
  const pSfxEmpty = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, ...sfxOn, begin183a4: 0x1000, end183a8: 0x1000 });
  assert.equal(pSfxEmpty.residualKind, ROOM_B1_RESIDUAL_SFX, "type5 + empty buffer -> SFX only");
  assert.equal(pSfxEmpty.sfxNeedsHost, 1, "sfx gate open");
  assert.equal(pSfxEmpty.spawnNeedsHost, 0, "empty buffer -> no spawn");
  /* SPAWN-only: type != 5 (sfx gate closed) + once clear + buffer nonempty. */
  const pSpawn = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, roomType8: 6, descField40: 1, bossId1bb0: 0x2a, difficulty269c8: 0, stage0: 1, nestedField10: 0, flags60e7: 0, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(pSpawn.residualKind, ROOM_B1_RESIDUAL_SPAWN, "type6 -> SPAWN only");
  assert.equal(pSpawn.sfxNeedsHost, 0, "sfx gate closed on type != 5");
  assert.equal(pSpawn.spawnNeedsHost, 1, "once clear + buffer nonempty -> spawn");
  /* SFX_SPAWN: type5 + once clear + buffer nonempty (PE order: Play, then
     flag OR, then spawn suite). */
  const pBoth = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, ...sfxOn, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(pBoth.residualKind, ROOM_B1_RESIDUAL_SFX_SPAWN, "type5 + nonempty -> SFX_SPAWN");
  assert.equal(pBoth.sfxNeedsHost, 1, "sfx arm");
  assert.equal(pBoth.spawnNeedsHost, 1, "spawn arm");
  assert.equal(pBoth.pureOnceFlagApply, 1, "flag OR between Play and spawn");
  /* Greed suppress: greed (diff 2/3) + stage 7 + nested 0 + !bit0x1000
     closes the SFX gate (roomB1SfxNeedsHost third conjunct); spawn stays. */
  const pGreed = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, roomType8: 5, descField40: 1, bossId1bb0: 0x2a, difficulty269c8: 2, stage0: 7, nestedField10: 0, flags60e7: 0, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(pGreed.residualKind, ROOM_B1_RESIDUAL_SPAWN, "greed suppress -> SPAWN only");
  assert.equal(pGreed.sfxNeedsHost, 0, "greed/stage7/nested0/!bit0x1000 -> sfx closed");
  const pGreedLift = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, roomType8: 5, descField40: 1, bossId1bb0: 0x2a, difficulty269c8: 2, stage0: 7, nestedField10: 0, flags60e7: 0x1000, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(pGreedLift.residualKind, ROOM_B1_RESIDUAL_SFX_SPAWN, "bit0x1000 lifts the suppress");
  /* WIDE drives: no pre-masking of sparse gate inputs. */
  const w1 = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, ...sfxOn, descField40: 0x100, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(w1.sfxNeedsHost, 0, "descField40 0x100 != 1 -> sfx closed (full-dword eq)");
  assert.equal(w1.residualKind, ROOM_B1_RESIDUAL_SPAWN, "WIDE desc -> SPAWN");
  const w2 = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, ...sfxOn, roomType8: 0x105, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(w2.sfxNeedsHost, 0, "roomType 0x105 != 5 -> sfx closed");
  /* Flags with high bits + bit 0x80000 clear: once gate must test the bit
     only (mask 0x80000), not a full-word equality. */
  const w3 = roomB1WireDecide({ ...open, outerReady: 1, sfxReady: 1, bufferReady: 1, ...sfxOn, flags60e7: 0x10000000, begin183a4: 0x1000, end183a8: 0x2000 });
  assert.equal(w3.onceFlagClear, 1, "flags 0x10000000 -> bit 0x80000 clear -> once open");
  assert.equal(w3.residualKind, ROOM_B1_RESIDUAL_SFX_SPAWN, "WIDE flags -> SFX_SPAWN");
  assert.equal(roomB1OnceFlagClear(0x180000), 0, "0x180000 keeps bit 0x80000 set");
  assert.equal(roomB1SpawnBufferNonemptyBits(0xffffffff, 0x100), 1,
    "buffer gate is a dword != cmp (0x802b50)");
  /* Once-path spawn relay: pre-OR flags decide the spawn arm. */
  assert.equal(roomB1SfxNeedsHost({ roomType8: 5, descField40: 1, difficulty269c8: 3, stage0: 7, nestedField10: 1, flags60e7: 0, bossId1bb0: 1 }), 1,
    "nested != 0 lifts greed suppress");
  assert.equal(roomB1SfxNeedsHost({ roomType8: 5, descField40: 1, difficulty269c8: 2, stage0: 6, nestedField10: 0, flags60e7: 0, bossId1bb0: 1 }), 1,
    "stage != 7 lifts greed suppress");
  assert.equal(roomB1SfxNeedsHost({ roomType8: 5, descField40: 1, difficulty269c8: 0, stage0: 7, nestedField10: 0, flags60e7: 0, bossId1bb0: 1 }), 1,
    "non-greed difficulty does not suppress");
  assert.equal(roomB1SfxNeedsHost({ roomType8: 5, descField40: 1, difficulty269c8: 2, stage0: 7, nestedField10: 0, flags60e7: 0x1000, bossId1bb0: 1 }), 1,
    "bit0x1000 lifts greed suppress");
  assert.equal(roomB1SfxNeedsHost({ roomType8: 5, descField40: 1, difficulty269c8: 2, stage0: 7, nestedField10: 0, flags60e7: 0, bossId1bb0: 0 }), 0,
    "bossId 0 closes the sfx gate");
  assert.equal(roomB1SfxNeedsHost({ roomType8: 5, descField40: 0x100, difficulty269c8: 0, stage0: 1, nestedField10: 0, flags60e7: 0, bossId1bb0: 1 }), 0,
    "WIDE desc 0x100 != 1 closes the gate");
});

test("ABI v95: B1 residual bodies typed-host the Play imms + FCO/manager chain", () => {
  /* The split fragments carry the PE-exact SFXManager::Play immediates
     (0x00802a69/0x00802a75 push 0x3f800000, 0x00802a72 push 2, 0x00802a70
     push 0, id from [ebp-0x9a0] = 0xbe) and the spawn-suite host VAs with
     NO PE emulation. */
  assert.equal(roomB1SfxId(), ROOM_B1_SFX_ID, "exact Play id 0xbe");
  assert.equal(roomB1SfxPlayVolume(), 1.0, "Vol 1.0f (0x3f800000)");
  assert.equal(roomB1SfxPlayFrameDelay(), 2, "FrameDelay 2");
  assert.equal(roomB1SfxPlayLoop(), 0, "Loop 0");
  assert.equal(roomB1SfxPlayPitch(), 1.0, "Pitch 1.0f");
  assert.equal(roomB1SfxPlayPan(), 0, "Pan 0");
  assert.equal(ROOM_B1_HOST_VA_SFX, 0x00802a53, "SFX fragment site");
  assert.equal(ROOM_B1_HOST_VA_SFX_PRE, 0x00956780, "SFX pre-call");
  assert.equal(ROOM_B1_HOST_VA_SFX_PLAY, 0x0092dc30, "exact SFXManager::Play");
  assert.equal(ROOM_B1_HOST_VA_SPAWN_SETUP, 0x00802b60, "spawn buffer view");
  assert.equal(ROOM_B1_HOST_VA_OWNER, 0x00802b7d, "owner call (FCO-adjacent 0x9be6b0)");
  assert.equal(ROOM_B1_HOST_VA_QUALITY, 0x00802b92, "quality call 0x7cb6e0");
  assert.equal(ROOM_B1_HOST_VA_SPAWN, 0x00802dc4, "spawn relay 0x428b20");
  assert.equal(ROOM_B1_HOST_VA_CLEANUP, 0x00802e1a, "cleanup 0x708e20");
  assert.ok(HOST_EVENT_KINDS.includes("opaqueRoomUpdatePrefixB1Sfx"), "sfx kind registered");
  assert.ok(HOST_EVENT_KINDS.includes("opaqueRoomUpdatePrefixB1Spawn"), "spawn kind registered");
  const bodies = createDefaultResidualBodies();
  const sfxBody = bodies.opaqueRoomUpdatePrefixB1Sfx({ kind: "opaqueRoomUpdatePrefixB1Sfx", count: 1 });
  assert.equal(sfxBody.residual, "b1-sfx", "typed residual tag");
  assert.equal(sfxBody.usesX86Emulation, false, "not routed through PE emulator");
  assert.equal(sfxBody.sfx.id, 0xbe, "body carries exact Play id");
  assert.equal(sfxBody.sfx.volume, 1.0, "body carries Vol 1.0f");
  assert.equal(sfxBody.sfx.frameDelay, 2, "body carries FrameDelay 2");
  assert.equal(sfxBody.sfx.loop, 0, "body carries Loop 0");
  assert.equal(sfxBody.sfx.pitch, 1.0, "body carries Pitch 1.0f");
  assert.equal(sfxBody.sfx.pan, 0, "body carries Pan 0");
  assert.equal(sfxBody.hostVas.sfxSite, 0x00802a53, "body carries sfx site VA");
  assert.equal(sfxBody.hostVas.sfxPre, 0x00956780, "body carries pre VA");
  assert.equal(sfxBody.hostVas.sfxPlay, 0x0092dc30, "body carries Play VA");
  const spawnBody = bodies.opaqueRoomUpdatePrefixB1Spawn({ kind: "opaqueRoomUpdatePrefixB1Spawn", count: 1 });
  assert.equal(spawnBody.residual, "b1-spawn", "typed residual tag");
  assert.equal(spawnBody.usesX86Emulation, false, "not routed through PE emulator");
  assert.equal(spawnBody.hostVas.spawnSetup, 0x00802b60, "body carries buffer-view VA");
  assert.equal(spawnBody.hostVas.owner, 0x00802b7d, "body carries owner VA");
  assert.equal(spawnBody.hostVas.quality, 0x00802b92, "body carries quality VA");
  assert.equal(spawnBody.hostVas.spawn, 0x00802dc4, "body carries spawn VA");
  assert.equal(spawnBody.hostVas.cleanup, 0x00802e1a, "body carries cleanup VA");
  assert.ok(Array.isArray(spawnBody.pureHelperNames) && spawnBody.pureHelperNames.length > 0,
    "body documents the spawn-iter pure helper names");
});

test("ABI v95: B1 wire emits the fragments in PE order through the Update oracle", () => {
  /* Continue-to-frame-manager-updates path: resumeGameUpdateRoomTransitionEffect
     -> applyFrameEffect6fd7c0PureAfterHost -> continueToFrameManagerUpdates
     (B0 roomByte7220 clear, then the B1 wire). The step increments
     frameCounter264f8 first, so entry 10 + pre frame 10 -> post frame 11 ->
     age == 1 -> outer open. */
  const drive = (rt, stateOver = {}, eventsOver = {}) => {
    const events = {
      continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_TRANSITION_EFFECT,
      ...eventsOver,
    };
    return resumeGameUpdateRoomTransitionEffect(
      {
        frameCounter264f8: 10,
        frameCounter264fc: 0,
        roomType8: 5,
        difficulty269c8: 0,
        gameFlags1839c: 0,
        ...stateOver,
      },
      events,
      { ambientRoomActive: 1, ambientRoomEntry11f0: 10, ...rt },
    );
  };
  /* Defaults (no sparse packs): open outer -> MONOLITHIC + pure flag OR. */
  const a = drive({ ambientRoomSubtype1bb0: 0x2a });
  assert.equal(a.events.opaqueRoomUpdatePrefixB1, 1, "defaults -> monolithic B1");
  assert.equal(a.events.opaqueRoomUpdatePrefixB1Sfx, 0, "no sfx fragment under defaults");
  assert.equal(a.events.opaqueRoomUpdatePrefixB1Spawn, 0, "no spawn fragment under defaults");
  assert.equal(a.state.gameFlags1839c >>> 0, 0x80000, "once-flag OR applied pure");
  assert.equal(a.events.continuationKind, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX_B1,
    "continuation resumes after B1");
  /* Outer closed -> pure-complete, nothing emitted, flag untouched. */
  const b = drive({ ambientRoomActive: 0, b1SfxReady: 1, b1BufferReady: 1 });
  assert.equal(b.events.opaqueRoomUpdatePrefixB1, 0, "closed outer -> no monolithic");
  assert.equal(b.events.opaqueRoomUpdatePrefixB1Sfx, 0, "closed outer -> no sfx");
  assert.equal(b.events.opaqueRoomUpdatePrefixB1Spawn, 0, "closed outer -> no spawn");
  assert.equal(b.state.gameFlags1839c >>> 0, 0, "closed outer -> flag untouched");
  /* SFX-only: all packs ready + buffer empty (0x802b53 je) -> B1Sfx. */
  const c = drive({ b1SfxReady: 1, b1BufferReady: 1, b1DescField40: 1, b1NestedField10: 0, b1Begin183a4: 0x1000, b1End183a8: 0x1000, ambientStage: 1, ambientRoomSubtype1bb0: 0x2a });
  assert.equal(c.events.opaqueRoomUpdatePrefixB1Sfx, 1, "sfx-only -> B1Sfx fragment");
  assert.equal(c.events.opaqueRoomUpdatePrefixB1Spawn, 0, "empty buffer -> no spawn fragment");
  assert.equal(c.events.opaqueRoomUpdatePrefixB1, 0, "no monolithic when split");
  assert.equal(c.state.gameFlags1839c >>> 0, 0x80000, "flag OR still applied");
  /* SPAWN-only: type != 5 closes sfx; once clear + nonempty buffer. */
  const d = drive({ b1SfxReady: 1, b1BufferReady: 1, b1DescField40: 1, b1NestedField10: 0, b1Begin183a4: 0x1000, b1End183a8: 0x2000, ambientStage: 1, ambientRoomSubtype1bb0: 0 }, { roomType8: 6 });
  assert.equal(d.events.opaqueRoomUpdatePrefixB1Sfw ?? d.events.opaqueRoomUpdatePrefixB1Sfx, 0, "type6 -> no sfx");
  assert.equal(d.events.opaqueRoomUpdatePrefixB1Spawn, 1, "type6 + nonempty -> B1Spawn fragment");
  /* SFX_SPAWN: both fragments, PE order (Play before spawn). */
  const e = drive({ b1SfxReady: 1, b1BufferReady: 1, b1DescField40: 1, b1NestedField10: 0, b1Begin183a4: 0x1000, b1End183a8: 0x2000, ambientStage: 1, ambientRoomSubtype1bb0: 0x2a });
  assert.equal(e.events.opaqueRoomUpdatePrefixB1Sfx, 1, "both -> B1Sfx");
  assert.equal(e.events.opaqueRoomUpdatePrefixB1Spawn, 1, "both -> B1Spawn");
  assert.equal(e.events.opaqueRoomUpdatePrefixB1, 0, "both -> no monolithic");
  /* Pre-OR spawn gate: high-bit flags survive; bit OR adds 0x80000. */
  const f = drive({ b1SfxReady: 1, b1BufferReady: 1, b1DescField40: 1, b1NestedField10: 0, b1Begin183a4: 0x1000, b1End183a8: 0x2000, ambientStage: 1, ambientRoomSubtype1bb0: 0x2a }, { difficulty269c8: 1, gameFlags1839c: 0x10000000 });
  assert.equal(f.events.opaqueRoomUpdatePrefixB1Spawn, 1, "high-bit flags (0x80000 clear) -> spawn arm runs");
  assert.equal(f.state.gameFlags1839c >>> 0, 0x10080000, "OR keeps high bits + sets 0x80000");
  /* Flag already set: spawn skipped, sfx fragment still emitted (Play ran
     before the once gate). */
  const g = drive({ b1SfxReady: 1, b1BufferReady: 1, b1DescField40: 1, b1NestedField10: 0, b1Begin183a4: 0x1000, b1End183a8: 0x2000, ambientStage: 1, ambientRoomSubtype1bb0: 0x2a }, { gameFlags1839c: 0x80000 });
  assert.equal(g.events.opaqueRoomUpdatePrefixB1Sfx, 1, "flag set -> Play (sfx fragment) still fires");
  assert.equal(g.events.opaqueRoomUpdatePrefixB1Spawn, 0, "flag set -> spawn arm skipped (0x802a98 jne)");
  assert.equal(g.state.gameFlags1839c >>> 0, 0x80000, "flag unchanged when already set");
  /* Flag set + !sfx_ready: sparse sfx pack missing still routes MONOLITHIC. */
  const h = drive({ b1BufferReady: 1, b1DescField40: 1, b1NestedField10: 0, b1Begin183a4: 0x1000, b1End183a8: 0x2000, ambientStage: 1, ambientRoomSubtype1bb0: 0x2a }, { gameFlags1839c: 0x80000 });
  assert.equal(h.events.opaqueRoomUpdatePrefixB1, 1, "open outer + sfx pack missing -> MONOLITHIC");
  assert.equal(h.events.opaqueRoomUpdatePrefixB1Sfx, 0, "no split under MONOLITHIC");
});

test("ABI v95: shipped Wasm agrees with the B1 fragment wire (wide args)", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  const abi = pick("isaac_game_update_slice_abi_version")();
  if (abi !== ABI_VERSION) {
    t.skip(`shipped module is ABI ${abi}; coordinator rebuild pending (current ${ABI_VERSION})`);
    return;
  }
  const resume = pick("isaac_game_update_slice_resume_frame_aux_updates");
  assert.equal(typeof resume, "function", "resume_frame_aux_updates missing from the module");
  const view = new DataView(wasm.memory.buffer);
  pick("isaac_game_update_slice_reset_scratch")();
  const stateAddr = pick("isaac_game_update_slice_state_address")();
  const constAddr = pick("isaac_game_update_slice_constants_address")();
  const rtAddr = pick("isaac_game_update_slice_runtime_inputs_address")();
  const eventsAddr = pick("isaac_game_update_slice_events_address")();
  const run = (stateOver, rt, eventsOver = {}) => {
    writeStruct(view, stateAddr, STATE_LAYOUT, {
      frameCounter264f8: 10,
      roomType8: 5,
      gameFlags1839c: 0,
      ...stateOver,
    });
    writeStruct(view, rtAddr, RUNTIME_INPUTS_LAYOUT,
      normalizeRuntimeInputsForLayout({
        ambientRoomActive: 1,
        ambientRoomEntry11f0: 10,
        b1SfxReady: 1,
        b1BufferReady: 1,
        b1DescField40: 1,
        b1NestedField10: 0,
        b1Begin183a4: 0x1000,
        b1End183a8: 0x2000,
        ambientStage: 1,
        ambientRoomSubtype1bb0: 0x2a,
        ...rt,
      }));
    const events = {
      continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_FRAME_AUX_UPDATES,
      ...eventsOver,
    };
    writeStruct(view, eventsAddr, EVENTS_LAYOUT, events);
    assert.equal(resume(stateAddr, constAddr, rtAddr, eventsAddr), 1, "resume accepts the continuation");
    return {
      ev: readStruct(view, eventsAddr, EVENTS_LAYOUT),
      flags: view.getUint32(stateAddr + STATE_LAYOUT.gameFlags1839c.offset, true) >>> 0,
    };
  };
  /* SFX_SPAWN: both fragments; flag OR 0x80000; continuation after B1. */
  const both = run({});
  assert.equal(both.ev.opaqueRoomUpdatePrefixB1Sfx | 0, 1, "wasm emits B1Sfx");
  assert.equal(both.ev.opaqueRoomUpdatePrefixB1Spawn | 0, 1, "wasm emits B1Spawn");
  assert.equal(both.ev.opaqueRoomUpdatePrefixB1 | 0, 0, "wasm does NOT emit monolithic when split");
  assert.equal(both.flags, 0x80000, "wasm applied the pure once-flag OR");
  assert.equal(both.ev.continuationKind | 0, UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX_B1,
    "wasm continuation resumes after B1");
  /* Flag set: spawn skipped, sfx fragment still fires. */
  const flagSet = run({ gameFlags1839c: 0x80000 });
  assert.equal(flagSet.ev.opaqueRoomUpdatePrefixB1Sfx | 0, 1, "wasm: sfx plays with flag set");
  assert.equal(flagSet.ev.opaqueRoomUpdatePrefixB1Spawn | 0, 0, "wasm: spawn skipped with flag set");
  assert.equal(flagSet.flags, 0x80000, "wasm: flag unchanged");
  /* Outer closed: pure-complete NONE. */
  const closed = run({}, { ambientRoomActive: 0 });
  assert.equal(closed.ev.opaqueRoomUpdatePrefixB1 | 0, 0, "wasm: closed outer -> no monolithic");
  assert.equal(closed.ev.opaqueRoomUpdatePrefixB1Sfx | 0, 0, "wasm: closed outer -> no sfx");
  assert.equal(closed.ev.opaqueRoomUpdatePrefixB1Spawn | 0, 0, "wasm: closed outer -> no spawn");
  assert.equal(closed.flags, 0, "wasm: flag untouched when closed");
  /* Wide buffer ends cross the dword gate unmasked (0x802b4e cmp). */
  const wide = run({}, { b1Begin183a4: 0xffffffff, b1End183a8: 0x100 });
  assert.equal(wide.ev.opaqueRoomUpdatePrefixB1Spawn | 0, 1, "wasm: wide unequal buffer ends -> spawn arm");
});

/* ABI v95 (record idx 27 roomTriggerClearAudio): always-music body
   decision law of 0x7f83b0 (Room::TriggerClear callsite 0x8069da with
   arg1=1, arg2=0). PE-truth transcribed branch-by-branch from
   section-notes/update-v95-7f83b0-audio-always/cpu-dump/007f83b0.txt:
   seed [game+0x182e4]; xorshift32 shifts {2,0x15,9} (qword 0xb1f594 +
   dword 0xb1f59c); uint32->double sign-fix (0xbacb00 table);
   cvtpd2ps; mulss 0x2f7ffffe (2.3283061589829401e-10); comiss
   value,rnd / ja + comiss value,1.0f / jae. NaN: CF set -> neither
   taken -> music==0. */

test("ABI v95 trigger-clear audio music law: xorshift32 + float rnd + comiss pair", () => {
  const f32b = (v) => (new Uint32Array(new Float32Array([v]).buffer))[0];
  /* PE 0x7f8453 jne 0x7f8509: arg2 (WIDE, full dword) forces music. */
  for (const arg2 of [1, 0x100, 0x1ff, 0xffffffff]) {
    assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(arg2, 0x00000000, 1), 1,
      `arg2=0x${arg2.toString(16)} forces the music path`);
  }
  /* arg2==0: value 0.5f (0x3f000000) with seed 1 -> rnd tiny -> 0.5 > rnd. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x3f000000, 1), 1,
    "0.5f > tiny rnd -> music");
  /* seed 0xffffffff: xorshift -> 0xc0600000; as u32 double 3227516928 *
     2.3283061589829401e-10 ~= 0.75146f; 0.5f NOT > 0.75146f, NOT >= 1 -> 0. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x3f000000, 0xffffffff), 0,
    "0.5f <= 0.75146f rnd, < 1.0f -> no music (flag store arm)");
  /* same seed, value 0.8f (0x3f4ccccd): 0.8f > 0.75146f -> music. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x3f4ccccd, 0xffffffff), 1,
    "0.8f > 0.75146f rnd -> music");
  /* value >= 1.0f -> music regardless of rnd. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x3f800000, 0xffffffff), 1,
    "1.0f >= 1.0f -> music");
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x3f8020c5, 1), 1,
    "1.001f >= 1.0f -> music");
  /* NaN value (0x7fc00000): comiss CF=1 -> ja/jae NOT taken -> 0. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x7fc00000, 1), 0,
    "NaN value -> no music (matches comiss semantics)");
  /* negative value: not > rnd, not >= 1.0 -> 0. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, f32b(-1.0), 1), 0,
    "-1.0f -> no music");
});

test("ABI v95 trigger-clear audio: mutants discriminate the law", () => {
  /* M1: shift-2 omission (x ^ x>>2 dropped) would change the rnd for
     seed 0xffffffff -> the 0.8f arm below flips (0.8f > rnd is the true
     law; a wrong rnd of ~0.5f also passes, so this case alone is not the
     discriminator — see M2/M3 which are). */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x3f4ccccd, 0xffffffff), 1,
    "true law: 0.8f > rnd(seed 0xffffffff)");
  /* M2: jae misread as ja on the 1.0f arm — value exactly 1.0f must pass. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x3f800000, 1), 1,
    "true law: 1.0f >= 1.0f (jae, not ja)");
  /* M3: NaN misread as music (unordered takes the branch) — must be 0. */
  assert.equal(gameUpdateSliceRoomTriggerClearAudioMusic(0, 0x7fc00000, 1), 0,
    "true law: NaN closes both comiss branches");
});

