/* ========== ABI v95: record idx 28 roomTriggerClearAwardsNonGreed — =
   awards non-greed music SUITE-ORDER (PE 0x806a26..0x806a64). When
   difficulty is NOT 2/3 (FULL-DWORD cmp 0x806a32/0x806a3b, je 0x806b63
   skip), the machine runs an ordered three-call music suite, every
   receiver the ROOM (thiscall ecx=ebx):
     0x7f9960(0, 0)   — pushes 0x806a44/0x806a46
     0x820170(1, 0, 0)— pushes 0x806a4f/0x806a51/0x806a53 (cdecl (1,0,0))
     0x8204b0(0)      — push 0x806a5c
   All three bodies stay TYPED-HOST; this law pins gate + order + args. */

test("ABI v95: TriggerClearAwardsSuite gate is FULL-DWORD difficulty not 2/3 (WIDE 0x102 closes)", () => {
  assert.equal(gameUpdateSliceTriggerClearAwardsSuite(0).fire, 1, "difficulty 0 opens");
  assert.equal(gameUpdateSliceTriggerClearAwardsSuite(1).fire, 1, "difficulty 1 opens");
  assert.equal(gameUpdateSliceTriggerClearAwardsSuite(2).fire, 0, "difficulty 2 (Greed) closes");
  assert.equal(gameUpdateSliceTriggerClearAwardsSuite(3).fire, 0, "difficulty 3 (Greedier) closes");
  assert.equal(gameUpdateSliceTriggerClearAwardsSuite(4).fire, 1, "difficulty 4 opens");
  for (const n of [0x100, 0x102, 0x1ff, 0x80000000, 0xffffffff, 0x80000002]) {
    assert.equal(gameUpdateSliceTriggerClearAwardsSuite(n).fire, 1,
      `WIDE 0x${(n >>> 0).toString(16)} is NOT 2/3 -> suite must open (FULL-DWORD equality)`);
  }
});

test("ABI v95: TriggerClearAwardsSuite pins the ordered trio 0x7f9960 -> 0x820170 -> 0x8204b0", () => {
  const s = gameUpdateSliceTriggerClearAwardsSuite(1);
  assert.equal(s.call1Va, 0x007f9960, "call1 VA");
  assert.equal(s.call1Arg1, 0, "call1 arg1");
  assert.equal(s.call1Arg2, 0, "call1 arg2");
  assert.equal(s.call2Va, 0x00820170, "call2 VA");
  assert.equal(s.call2Arg1, 1, "call2 arg1 = 1 (last push 0x806a53 is FIRST cdecl arg)");
  assert.equal(s.call2Arg2, 0, "call2 arg2");
  assert.equal(s.call2Arg3, 0, "call2 arg3");
  assert.equal(s.call3Va, 0x008204b0, "call3 VA");
  assert.equal(s.call3Arg1, 0, "call3 arg1");
  assert.equal(s.receiverIsRoom, 1, "all three receivers are the ROOM");
  /* Closed gate still pins the same suite (the pack is the machine's
     constant call sequence; only fire changes). */
  const c = gameUpdateSliceTriggerClearAwardsSuite(2);
  assert.equal(c.fire, 0, "closed fire");
  assert.equal(c.call1Va, s.call1Va, "closed pack keeps call1 VA");
  assert.equal(c.call2Va, s.call2Va, "closed pack keeps call2 VA");
  assert.equal(c.call3Va, s.call3Va, "closed pack keeps call3 VA");
  assert.equal(c.call2Arg1, s.call2Arg1, "closed pack keeps call2 arg1");
});

