/* =========================================================================
 * ABI v95 (record idx 15 opaqueRoomUpdatePrefixB3B7): typed-host B3-B7.
 * The B3 decision laws (FCO query gate, challenge id, TE list walk
 * bounds/pre) + the B4-B7 frame laws (entity/grid per-step decisions) run
 * in-module; the leaf bodies stay typed-host. PE truth transcribed from
 * section-notes/room-b3b7-v33/disasm-803321-803cf0.txt (0x00803327..
 * 0x00803bfb) — never derived from the model/C++.
 * ========================================================================= */

/* Independent PE-truth reference for the whole B3-B7 plan, transcribed
   branch-by-branch from the instruction stream. Slot names follow the PE
   stack slots ([ebp-0xa74] lookup count etc.). */
function peB3b7PlanRef(rt, frame264f8) {
  const u = (v) => (v >>> 0);
  const i32 = (v) => (v | 0);
  /* xorshift(seed, a, b, c) — PE shr/xor/shl/xor/shr/xor sequence. */
  const xs = (s, a, b, c) => {
    let x = s >>> 0;
    x = ((x >>> (a & 31)) ^ x) >>> 0;
    x = (((x << (b & 31)) >>> 0) ^ x) >>> 0;
    x = ((x >>> (c & 31)) ^ x) >>> 0;
    return x >>> 0;
  };
  const plan = {
    b3HostFco: 0, b3HostChallenge: 0, b3HostTeCall: 0,
    b4HostLookup: 0, b4HostPosA: 0, b4HostPosFinish: 0,
    b4GenrandDraws: 0, b4HostSpawns: 0, b4HostCleanup: 0, b4SeedFatal: 0,
    b5HostCount708250: 0, b5HostVcall48: 0, b5HostGrow: 0,
    b5HostVcall4c: 0, b5SeedFatal: 0,
    b6HostDestroy: 0, b6HostIterate: 0, b6HostClear: 0, b7HostUpdate: 0,
  };
  /* ---- B3 (0x803327..0x8033b1) ---- */
  plan.b3HostFco = 1; /* 0x80333b call 0x9be080 unconditional */
  if (((u(rt.b3b7Hce2a5Hit)) & 0xff) !== 0) plan.b3HostChallenge = 1; /* 0x80335b test al,al / je 0x803374 */
  if (((u(rt.b3b7TeByte7321)) & 0xff) === 0) { /* 0x803374 cmp byte / 0x80337b jne 0x8033b6 */
    if (u(rt.b3b7TeBegin) !== u(rt.b3b7TeEnd)) { /* 0x803389 cmp eax,edx / je 0x8033b6 */
      const n = Math.min(u(rt.b3b7TeEntriesCount) || 0, 8);
      for (let i = 0; i < n; i += 1) { /* 0x803390..0x8033a2 stride 0x10 */
        const t = (Array.isArray(rt.b3b7TeEntryType) ? rt.b3b7TeEntryType[i] : 0) >>> 0;
        const v = (Array.isArray(rt.b3b7TeEntryId) ? rt.b3b7TeEntryId[i] : 0) >>> 0;
        if (t === 0 && v === 0x40) { plan.b3HostTeCall = 1; break; } /* 0x803392/0x803397 je 0x8033a6 */
      }
    }
  }
  /* ---- B4 (0x8033b6..0x803854) ---- */
  if (i32(u(rt.b3b7DescType0)) === -0x14) { /* 0x8033b9 cmp [eax],-0x14 */
    plan.b4HostLookup = 1; /* 0x8033df call 0x41af60 */
    if (u(rt.b3b7LookupCount) === 0) { /* 0x8033eb cmp [ebp-0xa74],0 / jne 0x803457 */
      plan.b4HostPosA = 1; /* 0x80340b call 0x812d00 */
      plan.b4HostPosFinish += 1; /* 0x80341a call 0x813520 */
      plan.b4GenrandDraws += 1; /* 0x80341f call 0x6eef60 */
      plan.b4HostSpawns += 1; /* 0x803450 call 0x428b20 */
    }
    if (((u(rt.b3b7RoomByte1)) & 0xff) !== 0 && i32(frame264f8) === i32(rt.ambientRoomEntry11f0)) {
      /* 0x803472 cmp byte [edi+1],0 / 0x803487 cmp frame,entry */
      if (u(rt.b3b7DescSeed5c) === 0) { /* 0x8034da test esi,esi / jne 0x8034ee */
        plan.b4SeedFatal = 1; /* 0x8034e5 call 0xa112c0 + int3 -> suite stops */
      } else {
        plan.b4GenrandDraws += 1; /* 0x80357d G1 */
        plan.b4HostPosFinish += 1; /* 0x8035ed 813520 reward pos */
        plan.b4HostSpawns += 1; /* 0x8035a1 G1 spawn */
        /* seed chain: 0x8034ee xorshift(seed,5,9,7) -> rem1 -> pickup;
           0x80361f xorshift -> rem2 -> band; 0x80379d xorshift -> third. */
        const s1 = xs(u(rt.b3b7DescSeed5c), 5, 9, 7);
        const s2 = xs(s1, 5, 9, 7);
        const s3 = xs(s2, 5, 9, 7);
        const rem2 = (s2 % 100) >>> 0; /* 0x803648..0x80365e mod100 magic */
        let kind = 0;
        if (rem2 < 0x19) kind = 1; /* 0x803660 cmp 0x19 / jae */
        else if (rem2 < 0x32) kind = 2;
        else if (rem2 < 0x3c) kind = 3;
        else if (rem2 < 0x3d) kind = 4; /* 0x80372c cmp 0x3d / jae skip */
        if (kind !== 0) {
          let ok = 1;
          if (kind !== 1) {
            const opt = kind === 2 ? rt.b3b7MgrByte1b4 : (kind === 3 ? rt.b3b7MgrByte2bf : rt.b3b7MgrByte1ba);
            /* 0x80368f/0x8036f0/0x803731 option-byte test; 0x803698..0x80371d
               mode==2 && game && (26630>0 || 26589) */
            ok = (((u(opt)) & 0xff) !== 0) ||
                 (u(rt.b3b7MgrMode8) === 2 && u(rt.b3b7GameNonnull) !== 0 &&
                  (u(rt.b3b7Game26630) !== 0 || ((u(rt.b3b7GameByte26589)) & 0xff) !== 0));
          }
          if (ok) { plan.b4GenrandDraws += 1; plan.b4HostSpawns += 1; } /* band genrand + spawn */
        }
        if ((s3 & 3) === 0) { /* 0x8037c1 and eax,3 / jne 0x803822 */
          plan.b4HostPosFinish += 1; /* 0x8037f8 813520 third pos */
          plan.b4GenrandDraws += 1; /* 0x8037fd G3 */
          plan.b4HostSpawns += 1; /* 0x80381d third spawn */
        }
      }
    }
    /* 0x803829 cleanup: NOT reached after the seed-null fatal (int3). */
    if (plan.b4SeedFatal === 0 && ((u(rt.b3b7LookupResultByte)) & 0xff) === 0) {
      plan.b4HostCleanup = 1;
    }
  }
  if (plan.b4SeedFatal !== 0) return plan; /* int3 terminates the residual */
  /* ---- B5 (0x803854..0x803b1d) ---- */
  if (((u(rt.b3b7RoomByte0)) & 0xff) !== 0 && i32(frame264f8) === i32(rt.ambientRoomEntry11f0)) {
    /* 0x803886 cmp byte [edi],0 / 0x803895..0x8038a1 frame==entry */
    plan.b5HostCount708250 = 1; /* 0x8039a3 call 0x708250 */
    let end = u(rt.b3b7ListEnd);
    const cap = u(rt.b3b7ListCap);
    const n = Math.min(u(rt.b3b7EntityCount), 32);
    const cand = (i) => {
      /* 0x8038e6..0x803900 type candidate */
      const mode = i32(u(rt.b3b7Game26614));
      const type = i32(u((Array.isArray(rt.b3b7B5Type) ? rt.b3b7B5Type[i] : 0)));
      if (mode >= 2 && type === 1) return 1;
      return (((type - 0xa) >>> 0) < 0x3de) ? 1 : 0;
    };
    if (u(rt.b3b7Game26584) === 0x28) { /* 0x8038a7 cmp [ecx+0x26584],0x28 / jne 0x8039a3 */
      for (let i = 0; i < n; i += 1) { /* pass1 0x8038d0..0x8039a3 */
        if (cand(i) === 0) continue;
        const fl = u((Array.isArray(rt.b3b7B5Flags168) ? rt.b3b7B5Flags168[i] : 0));
        if ((fl & 0x20000000) !== 0) continue; /* 0x803908 and / or / jne skip */
        plan.b5HostVcall48 += 1; /* 0x80391f call [vt+0x48] */
        const vt48 = ((Array.isArray(rt.b3b7B5Vt48Al) ? rt.b3b7B5Vt48Al[i] : 0) >>> 0) & 0xff;
        const f32c = i32((Array.isArray(rt.b3b7B5Field32c) ? rt.b3b7B5Field32c[i] : 0));
        const type = i32(u((Array.isArray(rt.b3b7B5Type) ? rt.b3b7B5Type[i] : 0)));
        const variant28 = i32(u((Array.isArray(rt.b3b7B5Variant) ? rt.b3b7B5Variant[i] : 0)));
        const excluded = type === 0x2d || type === 0x54 || type === 0x112 || type === 0x113 ||
          (type === 0x4e && variant28 === 0xa); /* 0x80392e..0x803952 */
        if (vt48 !== 0 && f32c >= 0 && !excluded) { /* 0x803921 test al,al / 0x803925 cmp 0x32c jl */
          if (end === cap) plan.b5HostGrow += 1; /* 0x80395f cmp end,cap / je grow 0x42c920 */
          end = (end + 4) >>> 0; /* 0x803963 add end,4 */
        }
      }
    }
    if (i32(u(rt.b3b7Count708250)) > 3) { /* 0x8039ae cmp eax,3 / jle 0x803b1d */
      const budget = (i32(u(rt.b3b7Count708250)) - 3) | 0;
      for (let i = 0; i < n && plan.b5SeedFatal === 0; i += 1) { /* pass2 0x8039d0 */
        if (cand(i) === 0) continue;
        const fl = u((Array.isArray(rt.b3b7B5Flags168) ? rt.b3b7B5Flags168[i] : 0));
        if ((fl & 0x20000000) !== 0) continue;
        plan.b5HostVcall48 += 1; /* 0x803a24 call [vt+0x48] */
        const vt48 = ((Array.isArray(rt.b3b7B5Vt48Al) ? rt.b3b7B5Vt48Al[i] : 0) >>> 0) & 0xff;
        const f32c = i32((Array.isArray(rt.b3b7B5Field32c) ? rt.b3b7B5Field32c[i] : 0));
        if (vt48 === 0 || f32c < 0) continue;
        plan.b5HostVcall4c += 1; /* 0x803a42 call [vt+0x4c] */
        const vt4c = ((Array.isArray(rt.b3b7B5Vt4cAl) ? rt.b3b7B5Vt4cAl[i] : 0) >>> 0) & 0xff;
        if (vt4c !== 0) continue; /* 0x803a47 test al,al / jne 0x803b04 */
        let seed = u((Array.isArray(rt.b3b7B5Seed3dc) ? rt.b3b7B5Seed3dc[i] : 0));
        const sh0 = u((Array.isArray(rt.b3b7B5Shift3e0) ? rt.b3b7B5Shift3e0[i] : 0));
        const sh1 = u((Array.isArray(rt.b3b7B5Shift3e4) ? rt.b3b7B5Shift3e4[i] : 0));
        const sh2 = u((Array.isArray(rt.b3b7B5Shift3e8) ? rt.b3b7B5Shift3e8[i] : 0));
        for (let b = 0; b < budget; b += 1) { /* 0x803a60..0x803af2 */
          if (seed === 0) { /* 0x803a66 test edx,edx / jne 0x803a84 */
            plan.b5SeedFatal = 1; /* 0x803a71 call 0xa112c0 + int3 */
            seed = 0;
            break;
          }
          seed = xs(seed, sh0, sh1, sh2); /* xorshift with entity shifts, store-back */
          if ((seed & 1) === 0) { /* 0x803aae and eax,1 / jne 0x803ae3 */
            if (end === cap) plan.b5HostGrow += 1;
            end = (end + 4) >>> 0;
          }
        }
      }
    }
  }
  if (plan.b5SeedFatal !== 0) return plan; /* pass2 int3 @0x803a83 terminates */
  /* ---- B6 (0x803b2e..0x803bb4) ---- */
  if (u(rt.b3b7TreeCount7238) !== 0) { /* 0x803b2e cmp [edi+0x7238],0 / je 0x803bb4 */
    const m = Math.min(u(rt.b3b7B6NodeCount), 32);
    const cells = (i32(rt.b3b7Height10) * i32(rt.b3b7WidthC)) | 0; /* 0x803b57 imul */
    for (let i = 0; i < m; i += 1) {
      plan.b6HostIterate += 1; /* 0x803b7e call 0x414a80 per node */
      const idx = i32((Array.isArray(rt.b3b7B6NodeIdx) ? rt.b3b7B6NodeIdx[i] : 0));
      if (idx < 0 || idx >= cells) continue; /* 0x803b53 js / 0x803b5e jge skip */
      if (((Array.isArray(rt.b3b7B6NodeSlotNonnull) ? rt.b3b7B6NodeSlotNonnull[i] : 0) >>> 0) === 0) continue; /* 0x803b68 je skip */
      plan.b6HostDestroy += 1; /* 0x803b6e call [vt+0] push 1 */
    }
    plan.b6HostClear = 1; /* 0x803b9d call 0x424540 */
  }
  /* ---- B7 (0x803bb4..0x803bfb) ---- */
  {
    const cells = (i32(rt.b3b7Height10) * i32(rt.b3b7WidthC)) | 0; /* 0x803bbe imul */
    if (cells > 0) { /* 0x803bc7 test eax,eax / jle 0x803bfb */
      plan.b7HostUpdate = Math.min(u(rt.b3b7B7NonnullSlotCount), 64);
    }
  }
  return plan;
}

test("ABI v95 B3B7: B3 FCO query gate + challenge id + HCE gate (WIDE drives)", () => {
  assert.equal(gameUpdateSliceB3b7B3FcoFlagGate(0), 0, "FCO 0 -> flag 0 (setne)");
  assert.equal(gameUpdateSliceB3b7B3FcoFlagGate(1), 1, "FCO nonzero -> flag 1");
  assert.equal(gameUpdateSliceB3b7B3FcoFlagGate(0x100), 1, "WIDE nonzero is a hit (full dword)");
  assert.equal(gameUpdateSliceB3b7B3FcoFlagGate(0xffffffff), 1);
  assert.equal(gameUpdateSliceB3b7B3FcoId(), 0x28d, "challenge collectible id 0x28d @0x803336");
  assert.equal(gameUpdateSliceB3b7B3HceId(), 0x2a5, "HCE effect id 0x2a5 @0x803348");
  assert.equal(gameUpdateSliceB3b7B3ChallengeHostGate(0), 0, "HCE miss -> no challenge body");
  assert.equal(gameUpdateSliceB3b7B3ChallengeHostGate(1), 1);
  assert.equal(gameUpdateSliceB3b7B3ChallengeHostGate(0x100), 0, "LOW-BYTE test: 0x100 al=0 -> miss");
  assert.equal(gameUpdateSliceB3b7B3ChallengeHostGate(0xff), 1);
});

test("ABI v95 B3B7: TE list walk bounds/pre (0x803374..0x8033b1)", () => {
  assert.equal(gameUpdateSliceB3b7B3TeWalkGate(0), 1, "byte 0x7321==0 -> walk");
  assert.equal(gameUpdateSliceB3b7B3TeWalkGate(1), 0, "byte !=0 -> skip (jne 0x8033b6)");
  assert.equal(gameUpdateSliceB3b7B3TeWalkGate(0x100), 1, "LOW-BYTE: 0x100 is byte 0 -> walk");
  assert.equal(gameUpdateSliceB3b7B3TeWalkGate(0xffffffff), 0);
  assert.equal(gameUpdateSliceB3b7B3TeWalkNonempty(0x100, 0x100), 0, "begin==end -> empty (full dword)");
  assert.equal(gameUpdateSliceB3b7B3TeWalkNonempty(0x100, 0x110), 1);
  assert.equal(gameUpdateSliceB3b7B3TeWalkNonempty(0, 0x10000000), 1, "full-dword compare");
  assert.equal(gameUpdateSliceB3b7B3TeEntryMatch(0, 0x40), 1, "type0==0 && id==0x40");
  assert.equal(gameUpdateSliceB3b7B3TeEntryMatch(0, 0x140), 0, "FULL-DWORD id compare");
  assert.equal(gameUpdateSliceB3b7B3TeEntryMatch(0x1000000, 0x40), 0, "FULL-DWORD type compare");
  assert.equal(gameUpdateSliceB3b7B3TeEntryMatch(5, 3), 0);
  assert.equal(gameUpdateSliceB3b7B3TeWalkContinue(0x110, 0x110), 0, "next==end -> stop");
  assert.equal(gameUpdateSliceB3b7B3TeWalkContinue(0x110, 0x120), 1);
  assert.equal(gameUpdateSliceB3b7B3TeHostThisOff(), 0x1618, "0x8033a6 lea ecx,[edi+0x1618]");
  assert.equal(gameUpdateSliceB3b7B3TeHostArg(), 0xc5d108, "0x8033ac push 0xc5d108");
});

test("ABI v95 B3B7: B4 frame laws — desc gate / frame-in-room / route / pickup / band / third / cleanup", () => {
  assert.equal(gameUpdateSliceB3b7B4DescTypeGate(0xffffffec), 1, "-0x14 full dword");
  assert.equal(gameUpdateSliceB3b7B4DescTypeGate(0x10000000), 0, "positive wide value is not -0x14 (full dword)");
  assert.equal(gameUpdateSliceB3b7B4DescTypeGate(0x7fffffec), 0, "0x7fffffec positive != -0x14");
  assert.equal(gameUpdateSliceB3b7B4DescTypeGate(0xffffffff), 0, "0xffffffff is -1");
  assert.equal(gameUpdateSliceB3b7B4DescTypeGate(0), 0);
  assert.equal(gameUpdateSliceB3b7B4FrameInRoomGate(1, 7, 7), 1);
  assert.equal(gameUpdateSliceB3b7B4FrameInRoomGate(0x100, 7, 7), 0, "LOW-BYTE byte1=0x100 is 0");
  assert.equal(gameUpdateSliceB3b7B4FrameInRoomGate(1, 7, 8), 0, "frame != entry (full dword)");
  assert.equal(gameUpdateSliceB3b7B4LookupRoute(0), 1, "count==0 -> G0");
  assert.equal(gameUpdateSliceB3b7B4LookupRoute(1), 0);
  assert.equal(gameUpdateSliceB3b7B4LookupRoute(0x100), 0, "FULL-DWORD count");
  assert.equal(gameUpdateSliceB3b7B4PickupVariantFromRem(3), 0x35, "<4 -> 0x35");
  assert.equal(gameUpdateSliceB3b7B4PickupVariantFromRem(4), 0x34, "<9 -> 0x34");
  assert.equal(gameUpdateSliceB3b7B4PickupVariantFromRem(0x35), 0x3c, "<0x36 -> 0x3c");
  assert.equal(gameUpdateSliceB3b7B4PickupVariantFromRem(0x36), 0x32, "else 0x32");
  assert.equal(gameUpdateSliceB3b7B4PickupVariantFromRem(0x100), 0x32, "WIDE rem falls to default");
  assert.equal(gameUpdateSliceB3b7B4SecondBandKind(0x18), 1, "<0x19 A");
  assert.equal(gameUpdateSliceB3b7B4SecondBandKind(0x31), 2, "<0x32 B");
  assert.equal(gameUpdateSliceB3b7B4SecondBandKind(0x3b), 3, "<0x3c C");
  assert.equal(gameUpdateSliceB3b7B4SecondBandKind(0x3c), 4, "<0x3d D");
  assert.equal(gameUpdateSliceB3b7B4SecondBandKind(0x3d), 0, ">=0x3d none");
  assert.equal(gameUpdateSliceB3b7B4SecondBandKind(0x40000019), 0, "WIDE rem: 0x40000019 >= all bounds (unsigned)");
  assert.equal(gameUpdateSliceB3b7B4BandOptionGate(0x100, 2, 1, 0, 0), 0, "option byte 0x100 LOW-BYTE is 0");
  assert.equal(gameUpdateSliceB3b7B4BandOptionGate(1, 0, 0, 0, 0), 1, "byte!=0 -> spawn");
  assert.equal(gameUpdateSliceB3b7B4BandOptionGate(0, 2, 1, 1, 0), 1, "mode==2 && count>0");
  assert.equal(gameUpdateSliceB3b7B4BandOptionGate(0, 2, 1, 0, 1), 1, "mode==2 && byte26589");
  assert.equal(gameUpdateSliceB3b7B4BandOptionGate(0, 3, 1, 0, 0), 0, "mode!=2");
  assert.equal(gameUpdateSliceB3b7B4BandOptionGate(0, 2, 0, 1, 0), 0, "game null");
  assert.equal(gameUpdateSliceB3b7B4ThirdSpawnGate(0), 1, "(rng&3)==0");
  assert.equal(gameUpdateSliceB3b7B4ThirdSpawnGate(4), 1, "4&3==0 (full dword)");
  assert.equal(gameUpdateSliceB3b7B4ThirdSpawnGate(2), 0);
  assert.equal(gameUpdateSliceB3b7B4ThirdSpawnGate(0x10000003), 0, "WIDE low bits 3");
  assert.equal(gameUpdateSliceB3b7B4CleanupGate(0), 1, "result byte 0 -> cleanup");
  assert.equal(gameUpdateSliceB3b7B4CleanupGate(0x100), 1, "LOW-BYTE 0x100 is 0 -> cleanup");
  assert.equal(gameUpdateSliceB3b7B4CleanupGate(1), 0);
  assert.equal(gameUpdateSliceB3b7B4CleanupGate(0xff), 0);
});

test("ABI v95 B3B7: B5 frame laws — outer / pass1 mode / type candidate / flag / exclude / vt48 / pass2 / rng", () => {
  assert.equal(gameUpdateSliceB3b7B5OuterGate(1, 9, 9), 1);
  assert.equal(gameUpdateSliceB3b7B5OuterGate(0x100, 9, 9), 0, "LOW-BYTE room byte0");
  assert.equal(gameUpdateSliceB3b7B5OuterGate(1, 9, 10), 0, "frame != entry");
  assert.equal(gameUpdateSliceB3b7B5Pass1Mode(0x28), 1);
  assert.equal(gameUpdateSliceB3b7B5Pass1Mode(0x10000028), 0, "FULL-DWORD mode compare");
  assert.equal(gameUpdateSliceB3b7B5Pass1Mode(0), 0);
  assert.equal(gameUpdateSliceB3b7B5TypeCandidate(2, 1), 1, "mode>=2 && type==1");
  assert.equal(gameUpdateSliceB3b7B5TypeCandidate(1, 1), 0, "mode 1: range test only");
  assert.equal(gameUpdateSliceB3b7B5TypeCandidate(1, 0xa), 1, "(10-0xa)<0x3de");
  assert.equal(gameUpdateSliceB3b7B5TypeCandidate(1, 0x3e7), 1, "(0x3e7-0xa)=0x3dd < 0x3de -> candidate");
  assert.equal(gameUpdateSliceB3b7B5TypeCandidate(1, 0x3e8), 0, "(0x3e8-0xa)=0x3de not < -> reject");
  assert.equal(gameUpdateSliceB3b7B5TypeCandidate(1, 0x4000000a), 0, "WIDE type: unsigned range must reject");
  assert.equal(gameUpdateSliceB3b7B5FlagClear(0), 1);
  assert.equal(gameUpdateSliceB3b7B5FlagClear(0x20000000), 0, "bit set -> skip");
  assert.equal(gameUpdateSliceB3b7B5FlagClear(0x20000001), 0);
  assert.equal(gameUpdateSliceB3b7B5FlagClear(0x10000000), 1);
  assert.equal(gameUpdateSliceB3b7B5ExcludedType(0x2d, 0), 1);
  assert.equal(gameUpdateSliceB3b7B5ExcludedType(0x54, 0), 1);
  assert.equal(gameUpdateSliceB3b7B5ExcludedType(0x112, 0), 1);
  assert.equal(gameUpdateSliceB3b7B5ExcludedType(0x113, 0), 1);
  assert.equal(gameUpdateSliceB3b7B5ExcludedType(0x4e, 0xa), 1, "0x4e && variant==0xa");
  assert.equal(gameUpdateSliceB3b7B5ExcludedType(0x4e, 0xb), 0, "variant 0xb not excluded");
  assert.equal(gameUpdateSliceB3b7B5ExcludedType(0x2e, 0), 0);
  assert.equal(gameUpdateSliceB3b7B5PostVcall48Ok(1, 0), 1, "vt48 al!=0 && field32c>=0");
  assert.equal(gameUpdateSliceB3b7B5PostVcall48Ok(0x100, 0), 0, "LOW-BYTE vt48 0x100 is 0");
  assert.equal(gameUpdateSliceB3b7B5PostVcall48Ok(1, -1), 0, "field32c signed < 0");
  assert.equal(gameUpdateSliceB3b7B5PostVcall48Ok(1, 0xffffffff), 0, "0xffffffff signed negative");
  assert.equal(gameUpdateSliceB3b7B5PostVcall48Ok(1, 0x7fffffff), 1);
  assert.equal(gameUpdateSliceB3b7B5Pass2CountGate(3), 0, "count 3 -> no pass2 (jle)");
  assert.equal(gameUpdateSliceB3b7B5Pass2CountGate(4), 1);
  assert.equal(gameUpdateSliceB3b7B5Pass2CountGate(0xffffffff), 0, "SIGNED 0xffffffff is -1");
  assert.equal(gameUpdateSliceB3b7B5NeedsRng(0), 1, "vt4c al==0 -> rng");
  assert.equal(gameUpdateSliceB3b7B5NeedsRng(0x100), 1, "LOW-BYTE 0x100 is 0");
  assert.equal(gameUpdateSliceB3b7B5NeedsRng(1), 0);
  assert.equal(gameUpdateSliceB3b7B5AppendGate(0), 1, "(rng&1)==0 -> append");
  assert.equal(gameUpdateSliceB3b7B5AppendGate(2), 1, "2&1==0");
  assert.equal(gameUpdateSliceB3b7B5AppendGate(1), 0);
  assert.equal(gameUpdateSliceB3b7B5AppendGate(0x10000001), 0, "FULL-DWORD low-bit test");
  assert.equal(gameUpdateSliceB3b7B5SeedFatalGate(0), 1, "seed==0 -> fatal");
  assert.equal(gameUpdateSliceB3b7B5SeedFatalGate(0x100), 0, "FULL-DWORD nonzero");
});

test("ABI v99 leaf peel: FUN_00708250 player-count body laws", () => {
  /* Mutation legend (each flipped line fails THIS group, then restored
     sha256-byte-identical — NOTES.md update-v111-count-708250):
     - M1: node_value SIGNED jg -> unsigned: 0xffffffff reject pin dies.
     - M2: node_byte_d drop &0xff: 0x100/0x1ff reject pins die.
     - M3: player include 2c/3bc byte-narrow: 0x100/0x1ff skip pins die. */
  assert.equal(B5_COUNT_708250_MAX_PLAYERS, 8);
  assert.equal(gameUpdateSliceB5Count708250HostVa(), B5_COUNT_708250_HOST_VA);
  assert.equal(gameUpdateSliceB5Count708250HostVa7db860(), B5_COUNT_708250_HOST_VA_7DB860);
  assert.equal(gameUpdateSliceB5Count708250HostVa4288a0(), B5_COUNT_708250_HOST_VA_4288A0);

  /* Node reject: LOW-BYTE d — do NOT pre-mask. */
  assert.equal(gameUpdateSliceB5Count708250NodeReject(0, 0x4f, 0), 0, "open");
  assert.equal(gameUpdateSliceB5Count708250NodeReject(1, 0x4f, 0), 1, "byte_d != 0");
  assert.equal(gameUpdateSliceB5Count708250NodeReject(0x100, 0x4f, 0), 0,
    "LOW-BYTE 0x100 is 0 -> open (M2 full-dword mutant dies)");
  assert.equal(gameUpdateSliceB5Count708250NodeReject(0x1ff, 0x4f, 0), 1,
    "LOW-BYTE 0x1ff is 0xff -> reject (M2 dies)");
  assert.equal(gameUpdateSliceB5Count708250NodeReject(0xffffffff, 0x4f, 0), 1,
    "LOW-BYTE 0xffffffff is 0xff -> reject (M2 dies)");
  assert.equal(gameUpdateSliceB5Count708250NodeReject(0, 0x50, 0), 1, "0x50 > 0x4f SIGNED");
  assert.equal(gameUpdateSliceB5Count708250NodeReject(0, 0xffffffff, 0), 0,
    "SIGNED 0xffffffff is -1 not > 0x4f (M1 unsigned mutant dies)");
  assert.equal(gameUpdateSliceB5Count708250NodeReject(0, 0x4f, 0x100), 1, "FULL-DWORD head 0x100");

  /* Player include: FULL-DWORD 2c AND 3bc zero — do NOT pre-mask. */
  assert.equal(gameUpdateSliceB5Count708250PlayerInclude(0, 0), 1);
  assert.equal(gameUpdateSliceB5Count708250PlayerInclude(0x100, 0), 0,
    "FULL-DWORD 2c 0x100 skips (M3 byte-narrow mutant dies)");
  assert.equal(gameUpdateSliceB5Count708250PlayerInclude(0x1ff, 0), 0,
    "FULL-DWORD 2c 0x1ff skips (M3 dies)");
  assert.equal(gameUpdateSliceB5Count708250PlayerInclude(0xffffffff, 0), 0,
    "FULL-DWORD 2c 0xffffffff skips (M3 dies)");
  assert.equal(gameUpdateSliceB5Count708250PlayerInclude(0, 0x100), 0, "3bc 0x100 skips");
  assert.equal(gameUpdateSliceB5Count708250PlayerInclude(0, 0x1ff), 0, "3bc 0x1ff skips");

  assert.equal(gameUpdateSliceB5Count708250Empty(0), 1);
  assert.equal(gameUpdateSliceB5Count708250Empty(0x100), 0, "0x100 nonempty");

  /* Loop bound re-derived per iteration: UNSIGNED jb. */
  assert.equal(gameUpdateSliceB5Count708250Continue(0, 1), 1);
  assert.equal(gameUpdateSliceB5Count708250Continue(1, 1), 0);
  assert.equal(gameUpdateSliceB5Count708250Continue(0, 0x100), 1, "WIDE count 0x100 walks");
  assert.equal(gameUpdateSliceB5Count708250Continue(0x100, 0x100), 0);
  assert.equal(gameUpdateSliceB5Count708250Continue(0x80000000, 1), 0,
    "UNSIGNED 0x80000000 < 1 is false (signed mutant dies)");

  const live = (byte) => ({ field2c: 0, field3bc: 0, bufBegin: 0, bufEnd: 0x90, bufByte: byte });
  /* Three included players: cap-2 wasm fold would sum 1+2=3, cap-8 sums 7. */
  const three = gameUpdateSliceB5Count708250({
    nodeByteD: 0, nodeValue10: 0x4f, nodeIsHead: 0, playerCount: 3,
    players: [live(1), live(2), live(4)],
  });
  assert.equal(three.result, 7, "cap-8 walks 3 players (cap-2 fold dies here)");
  assert.equal(three.host7db860, 3);
  assert.equal(gameUpdateSliceB5Count708250Result(
    0, 0x4f, 0, 3, [live(1), live(2), live(4)],
  ), 7);
  /* Shrinking bound re-read: counts[0]=3 then counts[1]=1 -> stop after i=0. */
  const shrink = gameUpdateSliceB5Count708250({
    nodeByteD: 0, nodeValue10: 0x4f, nodeIsHead: 0, playerCount: 3,
    players: [live(1), live(2), live(4)],
    counts: [3, 1],
  });
  assert.equal(shrink.result, 1, "re-derived bound 1 stops after first player");
  assert.equal(shrink.host7db860, 1);
});

test("ABI v99 leaf peel: FUN_00708250 shipped Wasm agrees with the oracle", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale; rebuild flips this probe");
    return;
  }
  const nodeReject = pick("isaac_game_update_slice_b5_count_708250_node_reject");
  const include = pick("isaac_game_update_slice_b5_count_708250_player_include");
  const empty = pick("isaac_game_update_slice_b5_count_708250_empty");
  const cont = pick("isaac_game_update_slice_b5_count_708250_continue");
  const nested = pick("isaac_game_update_slice_b5_count_708250_7db860");
  const result = pick("isaac_game_update_slice_b5_count_708250_result");
  if (typeof nodeReject !== "function" || typeof result !== "function" || typeof cont !== "function") {
    t.skip("the module predates the 708250 cap-8 exports");
    return;
  }
  const wide = [0, 1, 0x100, 0x1ff, 0xffffffff];
  for (const d of wide) {
    assert.equal(nodeReject(d, 0x4f, 0) | 0, gameUpdateSliceB5Count708250NodeReject(d, 0x4f, 0) | 0,
      `wasm node_reject(d=0x${(d >>> 0).toString(16)}) unmasked`);
  }
  assert.equal(nodeReject(0, 0xffffffff, 0) | 0, 0, "wasm SIGNED 0xffffffff does not reject");
  for (const v of wide) {
    assert.equal(include(v, 0) | 0, gameUpdateSliceB5Count708250PlayerInclude(v, 0) | 0,
      `wasm include(2c=0x${(v >>> 0).toString(16)}) unmasked`);
    assert.equal(include(0, v) | 0, gameUpdateSliceB5Count708250PlayerInclude(0, v) | 0,
      `wasm include(3bc=0x${(v >>> 0).toString(16)}) unmasked`);
  }
  for (const c of wide) {
    assert.equal(empty(c) | 0, gameUpdateSliceB5Count708250Empty(c) | 0,
      `wasm empty(0x${(c >>> 0).toString(16)})`);
  }
  assert.equal(cont(0x80000000, 1) | 0, gameUpdateSliceB5Count708250Continue(0x80000000, 1) | 0,
    "wasm continue UNSIGNED");
  assert.equal(nested(0, 0x4f, 0, 0, 0x90, 0x103) | 0,
    gameUpdateSliceB5Count708250_7db860(0, 0x4f, 0, 0, 0x90, 0x103) | 0);
  const mem = wasm.memory ?? wasm.exports?.memory;
  if (!(mem instanceof WebAssembly.Memory)) {
    t.skip("module does not export memory");
    return;
  }
  const packOff = 0x200000;
  const view = new DataView(mem.buffer);
  const writePlayers = (rows) => {
    for (let i = 0; i < B5_COUNT_708250_MAX_PLAYERS; i += 1) {
      const pl = rows[i] ?? {};
      const o = packOff + i * 20;
      view.setUint32(o + 0, (pl.field2c ?? 0) >>> 0, true);
      view.setUint32(o + 4, (pl.field3bc ?? 0) >>> 0, true);
      view.setUint32(o + 8, (pl.bufBegin ?? 0) >>> 0, true);
      view.setUint32(o + 12, (pl.bufEnd ?? 0) >>> 0, true);
      view.setUint32(o + 16, (pl.bufByte ?? 0) >>> 0, true);
    }
  };
  const live = (byte) => ({ field2c: 0, field3bc: 0, bufBegin: 0, bufEnd: 0x90, bufByte: byte });
  writePlayers([live(1), live(2), live(4)]);
  assert.equal(result(0, 0x4f, 0, 3, packOff) >>> 0, 7,
    "wasm cap-8 result walks 3 players (cap-2 fold dies)");
  assert.equal(result(0, 0x4f, 0, 3, packOff) >>> 0,
    gameUpdateSliceB5Count708250Result(0, 0x4f, 0, 3, [live(1), live(2), live(4)]));
  writePlayers([live(1), live(2), live(4), live(8), live(16), live(32), live(64), live(7)]);
  assert.equal(result(0, 0x4f, 0, 8, packOff) >>> 0, 1 + 2 + 4 + 8 + 16 + 32 + 64 + 7,
    "wasm walks all 8 cap slots");
});

test("ABI v99 leaf peel: FUN_00710dd0 open-tail prefix laws", () => {
  /* Mutation legend:
     - M1: arm_0xb byte-narrow: 0x10b would match; pin dies.
     - M2: bl 7||8 byte-narrow: 0x107 would match; pin dies.
     - M3: skip drop &0xff on al: 0x100 would skip; pin dies. */
  assert.equal(gameUpdateSlice710dd0OpenTailHostVa748760(), DOOR_710DD0_OPEN_TAIL_HOST_VA_748760);
  assert.equal(gameUpdateSlice710dd0OpenTailArm0b(0xb), 1);
  assert.equal(gameUpdateSlice710dd0OpenTailArm0b(0), 0);
  assert.equal(gameUpdateSlice710dd0OpenTailArm0b(0x10b), 0,
    "FULL-DWORD 0x10b != 0xb (byte-narrow mutant dies)");
  assert.equal(gameUpdateSlice710dd0OpenTailArm0b(0xffffffff), 0);
  assert.equal(gameUpdateSlice710dd0OpenTailBl(7), 1);
  assert.equal(gameUpdateSlice710dd0OpenTailBl(8), 1);
  assert.equal(gameUpdateSlice710dd0OpenTailBl(6), 0);
  assert.equal(gameUpdateSlice710dd0OpenTailBl(0x107), 0,
    "FULL-DWORD 0x107 != 7 (byte-narrow mutant dies)");
  assert.equal(gameUpdateSlice710dd0OpenTailBl(0x108), 0);
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(0, 0, 0), 1, "al=0 392=0 bl=0 -> RET");
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(1, 0, 0), 0, "al!=0 join");
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(0, 1, 0), 0, "392!=0 join");
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(0, 0, 1), 0, "bl!=0 join");
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(0x100, 0, 0), 1,
    "LOW-BYTE al 0x100 is 0 -> skip (full-dword mutant dies)");
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(0x1ff, 0, 0), 0,
    "LOW-BYTE al 0x1ff is 0xff -> join");
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(0, 0x100, 0), 1,
    "LOW-BYTE 392 0x100 is 0 -> skip");
  assert.equal(gameUpdateSlice710dd0OpenTailSkipAfter748760(0, 0, 0x100), 1,
    "LOW-BYTE bl 0x100 is 0 -> skip");
});

