  assert.equal(gameUpdateSlice710dd0711740FalseFieldC(), DOOR_710DD0_711740_FALSE_FIELD_C);
  assert.equal(gameUpdateSlice710dd0GetroomArg1(), DOOR_710DD0_GETROOM_ARG1);

  assert.equal(gameUpdateSlice5cd5f0(0, 1, 0), 1, "field15c==arg");
  assert.equal(gameUpdateSlice5cd5f0(1, 0, 0), 1, "field160==arg");
