test("ABI v95 trigger-clear audio: the resume wire emits the typed leaves", () => {
  /* Drive resumeGameUpdateRoomUpdatePrefix into the TriggerClear fragment
     (same setup as the TCS stats group): clear-side open, non-(0x10,2)
     room, (flags & 9) == 0. The audio seam captures seed/value/playSound/
     gate749830/roomMatch -> music|flag_store|sfx replace the monolithic
     counter content; all-zero captures keep the monolithic (ready=0). */
  const base = step({});
  const shaped = {
    ...base.state,
    timedTransitionCleanupMode: 0,
    roomClearDelay11ec: 0,
    roomAlive12c0: 0,
    roomAlive12c4: 0,
    roomGreedWave723c: 0,
    roomType8: 1,
    roomDescSubtype: 0,
    roomDescFlags44: 0,
    roomDescClearCount4a: 0,
  };
  const ev = {
    ...base.events,
    roomTriggerClearStats: 0,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX,
  };
  const run = (rt) => resumeGameUpdateRoomUpdatePrefix({ ...shaped }, rt, { ...ev });
  /* G1+G2 open, value 0.5f (0x3f000000) seed 1 -> music leaf; playSound 0
     -> sfx leaf. */
  const a = run({
    ...normalizeRuntimeInputsForLayout({}),
    roomTriggerClearAudioSeed: 1,
    roomTriggerClearAudioValue: 0x3f000000,
    roomTriggerClearAudioPlaySound: 0,
    roomTriggerClearAudioGate749830: 1,
    roomTriggerClearAudioRoomMatch: 1,
  });
  assert.equal(a.events.roomTriggerClearAudioMusic >>> 0, 1, "0.5f>rnd(seed1) -> music leaf");
  assert.equal(a.events.roomTriggerClearAudioFlagStore >>> 0, 0, "no flag store when music fires");
  assert.equal(a.events.roomTriggerClearAudioSfx >>> 0, 1, "playSound 0 -> caller SFX leaf");
  assert.equal(a.events.roomTriggerClearAudio >>> 0, 1, "coarse mono counter still fires");
  /* Gate G1 closed (0x749830 result 0): pure skip — NO music, NO flag store. */
  const b = run({
    ...normalizeRuntimeInputsForLayout({}),
    roomTriggerClearAudioSeed: 1,
    roomTriggerClearAudioValue: 0x3f000000,
    roomTriggerClearAudioPlaySound: 1,
    roomTriggerClearAudioGate749830: 0,
    roomTriggerClearAudioRoomMatch: 1,
  });
  assert.equal(b.events.roomTriggerClearAudioMusic >>> 0, 0, "G1 closed -> no music");
  assert.equal(b.events.roomTriggerClearAudioFlagStore >>> 0, 0, "G1 closed -> no flag store");
  assert.equal(b.events.roomTriggerClearAudioSfx >>> 0, 0, "playSound 1 -> no caller SFX");
  /* Value 0.0f seed 1 -> flag store; playSound 0 -> SFX still fires (the
     caller's SFX leaf is gated ONLY on playSound, PE 0x8069df). */
  const c = run({
    ...normalizeRuntimeInputsForLayout({}),
    roomTriggerClearAudioSeed: 1,
    roomTriggerClearAudioValue: 0x00000000,
    roomTriggerClearAudioPlaySound: 0,
    roomTriggerClearAudioGate749830: 1,
    roomTriggerClearAudioRoomMatch: 1,
  });
  assert.equal(c.events.roomTriggerClearAudioMusic >>> 0, 0, "0.0f <= rnd, < 1.0 -> no music");
  assert.equal(c.events.roomTriggerClearAudioFlagStore >>> 0, 1, "flag store leaf fires");
  assert.equal(c.events.roomTriggerClearAudioSfx >>> 0, 1, "playSound 0 -> SFX leaf fires");
  /* All-zero captures -> ready=0 keeps the monolithic exactly. */
  const d = run({
    ...normalizeRuntimeInputsForLayout({}),
    roomTriggerClearAudioSeed: 0,
    roomTriggerClearAudioValue: 0,
    roomTriggerClearAudioPlaySound: 0,
    roomTriggerClearAudioGate749830: 0,
    roomTriggerClearAudioRoomMatch: 0,
  });
  assert.equal(d.events.roomTriggerClearAudio >>> 0, 1, "mono still fires");
  assert.equal(d.events.roomTriggerClearAudioMusic >>> 0, 0, "no typed leaves without captures");
  assert.equal(d.events.roomTriggerClearAudioFlagStore >>> 0, 0, "no flag store without captures");
  assert.equal(d.events.roomTriggerClearAudioSfx >>> 0, 0, "no sfx leaf without captures");
});
/* ================= ABI v95: record idx 17 (opaqueRoomUpdatePrefixB9B11)
   B9 challenge-result laws + B10 fatal gate (typed-event) + B11
   camera/manager decision laws. All transcribed branch-by-branch from
   section-notes/room-b9b11/disasm-803ce5.txt (0x803cfe..0x803f8c); the
   B9 free body, B10 deathspawn warn, B11 manager chain and TempFX camera
   body stay typed-host (typed events name the bodies the host must run).
   The typed-event wire fires ONLY on the b9b11InputsReady arm;
   ready=0 keeps the v48 monolithic parent counter. ================= */

test("ABI v95: b9b11 challenge gate is FULL-DWORD result + LOW-BYTE active + EXACT age 4 + type 0x11 + flag bit clear", () => {
  /* PE 0x803cfe test eax,eax / je; 0x803d06 cmp byte [edi],0 / je;
     0x803d21 cmp eax,4 / jne; 0x803d30 cmp dword [eax+8],0x11 / jne;
     0x803d43 test al,1 / jne. */
  const g = (r, a, f, e, t, fl) => gameUpdateSliceB9b11ChallengeGate(r, a, f, e, t, fl);
  assert.equal(g(0x226, 1, 100, 96, 0x11, 0), 1, "open gate");
  assert.equal(g(1, 1, 100, 96, 0x11, 0), 1, "result nonzero is enough (full dword)");
  /* WIDE result: 0x100 is nonzero FULL-DWORD -> gate stays open. */
  assert.equal(g(0x100, 1, 100, 96, 0x11, 0), 1, "wide result nonzero");
  assert.equal(g(0, 1, 100, 96, 0x11, 0), 0, "result zero closes");
  /* LOW-BYTE active: 0x100 has low byte 0 -> closed (a full-word test
     would wrongly open). */
  assert.equal(g(1, 0x100, 100, 96, 0x11, 0), 0, "active 0x100 low byte 0 -> closed");
  assert.equal(g(1, 0x1ff, 100, 96, 0x11, 0), 1, "active 0x1ff low byte 1 -> open");
  /* EXACT age == 4 (signed sub, equality): 3 and 5 close. */
  assert.equal(g(1, 1, 100, 97, 0x11, 0), 0, "age 3 closes");
  assert.equal(g(1, 1, 100, 95, 0x11, 0), 0, "age 5 closes");
  assert.equal(g(1, 1, 100, 96, 0x11, 0), 1, "age 4 opens");
  /* Signed-sub wrap: frame 0 entry 0xfffffffc -> (0 - -4) = 4. */
  assert.equal(g(1, 1, 0, 0xfffffffc, 0x11, 0), 1, "wrapped age == 4");
  /* type FULL-DWORD equality: 0x111 must NOT match 0x11. */
  assert.equal(g(1, 1, 100, 96, 0x111, 0), 0, "type 0x111 does not match");
  assert.equal(g(1, 1, 100, 96, 0x10, 0), 0, "type 0x10 closes");
  /* flag bit ((flags>>3)&1): bit 3 set closes, wide value keeps bit. */
  assert.equal(g(1, 1, 100, 96, 0x11, 8), 0, "flags bit3 set closes");
  assert.equal(g(1, 1, 100, 96, 0x11, 0x108), 0, "flags 0x108 bit3 set closes");
  assert.equal(g(1, 1, 100, 96, 0x11, 0x10), 1, "flags bit4 does not close");
});

test("ABI v95: B9 free sub-laws — helper FULL-DWORD count, path LOW-BYTE, ptr != 0", () => {
  /* PE 0x803d6e cmp dword [ebp-0xa3c],0 / jne: count==0 is FULL-DWORD. */
  assert.equal(gameUpdateSliceB9b11FreeHelperNeeded(0), 1, "count 0 -> helper");
  assert.equal(gameUpdateSliceB9b11FreeHelperNeeded(1), 0);
  assert.equal(gameUpdateSliceB9b11FreeHelperNeeded(0x100), 0, "0x100 count != 0 (a byte test would trigger)");
  assert.equal(gameUpdateSliceB9b11FreeHelperNeeded(0xffffffff), 0);
  /* PE 0x803d8f cmp byte [ebp-0xa48],0 / jne: LOW-BYTE path gate. */
  assert.equal(gameUpdateSliceB9b11FreePathNeeded(0), 1, "byte 0 -> free path");
  assert.equal(gameUpdateSliceB9b11FreePathNeeded(1), 0);
  assert.equal(gameUpdateSliceB9b11FreePathNeeded(0x100), 1, "0x100 low byte 0 -> free path (a word test would close)");
  assert.equal(gameUpdateSliceB9b11FreePathNeeded(0xffffff00), 1);
  assert.equal(gameUpdateSliceB9b11FreePathNeeded(0x101), 0);
  /* PE 0x803db2 test ecx,ecx / je: ptr != 0 FULL-DWORD. */
  assert.equal(gameUpdateSliceB9b11FreePtrNeeded(0), 0, "null ptr -> no free");
  assert.equal(gameUpdateSliceB9b11FreePtrNeeded(0x1000), 1);
  assert.equal(gameUpdateSliceB9b11FreePtrNeeded(0xffffffff), 1);
});

test("ABI v95: B9 free heap account mirrors sub + sbb borrow (u32 wrap, UNSIGNED)", () => {
  /* PE 0x803dbc sub dword [edx],eax / 0x803dbf sbb dword [edx+4],0. */
  assert.equal(gameUpdateSliceB9b11FreeHeapLo(0x1000, 0x100), 0xf00, "lo - size");
  /* Wrap: lo 4 size 8 -> 0xfffffffc. */
  assert.equal(gameUpdateSliceB9b11FreeHeapLo(4, 8), 0xfffffffc);
  /* Borrow is lo < size (UNSIGNED). */
  assert.equal(gameUpdateSliceB9b11FreeHeapHi(0x1000, 5, 0x100), 5, "lo >= size -> no borrow");
  assert.equal(gameUpdateSliceB9b11FreeHeapHi(4, 5, 8), 4, "lo < size -> hi - 1");
  assert.equal(gameUpdateSliceB9b11FreeHeapHi(0, 0, 1), 0xffffffff, "hi 0 wraps with borrow");
  assert.equal(gameUpdateSliceB9b11FreeHeapHi(0x80000000, 7, 0x80000000), 7, "equal lo/size (u32) is NOT a borrow");
});

test("ABI v95: B10 enemies = SIGNED max(0, 12c8+12cc) — wrap + negative sums clamp to 0", () => {
  /* PE 0x803e0a..0x803e1a: xor esi,esi; add eax,[edi+0x12cc]; test
     eax,eax; cmovg esi,eax — SIGNED cmovg. */
  assert.equal(gameUpdateSliceB9b11B10Enemies(0, 0), 0);
  assert.equal(gameUpdateSliceB9b11B10Enemies(3, 4), 7);
  assert.equal(gameUpdateSliceB9b11B10Enemies(-5, 2), 0, "negative sum clamps");
  assert.equal(gameUpdateSliceB9b11B10Enemies(-5, 7), 2, "signed sum 2");
  /* 32-bit wrap: 0x7fffffff + 1 -> 0x80000000 (negative) -> 0. */
  assert.equal(gameUpdateSliceB9b11B10Enemies(0x7fffffff, 1), 0, "wrapped negative clamps");
  assert.equal(gameUpdateSliceB9b11B10Enemies(0xffffffff, 1), 0, "-1 + 1 = 0");
  assert.equal(gameUpdateSliceB9b11B10Enemies(0x80000000, 0x80000000), 0, "INT_MIN+INT_MIN wraps 0");
});

test("ABI v95: B10 fatal gate = enemies <= 0 && old_7224 > 0 (SIGNED) — the typed-event", () => {
  /* PE 0x803e1d test esi,esi / jg skip; 0x803e21 cmp [edi+0x7224],0 /
     jle skip. */
  assert.equal(gameUpdateSliceB9b11B10FatalNeeded(0, 1), 1, "fatal fires (typed event)");
  assert.equal(gameUpdateSliceB9b11B10FatalNeeded(-1, 1), 1, "negative enemies -> fatal");
  assert.equal(gameUpdateSliceB9b11B10FatalNeeded(1, 1), 0, "enemies > 0 -> no fatal");
  assert.equal(gameUpdateSliceB9b11B10FatalNeeded(0, 0), 0, "old <= 0 -> no fatal");
  assert.equal(gameUpdateSliceB9b11B10FatalNeeded(0, -1), 0, "old -1 (SIGNED) -> no fatal");
  /* old_7224 0x80000000 is negative SIGNED -> no fatal (a full-word
     nonzeroness would wrongly fire). */
  assert.equal(gameUpdateSliceB9b11B10FatalNeeded(0, 0x80000000), 0, "old 0x80000000 signed negative");
  assert.equal(gameUpdateSliceB9b11B10FatalNeeded(0, 0x7fffffff), 1, "old 0x7fffffff signed positive");
});

test("ABI v95: B11 mode hooks = FULL-DWORD type 0xb/0x11 && LOW-BYTE game byte", () => {
  /* PE 0x803dd9 cmp eax,0xb / je; 0x803de1 cmp eax,0x11 / jne;
     0x803de6 cmp byte [ecx+0x265e8],0 / je. */
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0xb, 1), 1, "type 0xb + byte");
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0x11, 1), 1, "type 0x11 + byte");
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0xb, 0), 0, "byte 0 closes");
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0xb, 0x100), 0, "byte 0x100 low 0 closes (word test would open)");
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0xb, 0x1ff), 1, "byte 0x1ff low 1 opens");
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0x10b, 1), 0, "type 0x10b FULL-DWORD does not match 0xb");
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0x111, 1), 0, "type 0x111 does not match 0x11");
  assert.equal(gameUpdateSliceB9b11ModeHooksNeeded(0x1, 1), 0, "type 1 closes");
});

test("ABI v95: B11 flag 11f4 + double 409030 are LOW-BYTE tests; stage-1a is FULL-DWORD 0x1a", () => {
  /* 0x803dfa cmp byte [edi+0x11f4],0 / je; 0x803e82 cmp byte [edi+0x1d0d],0
     / je; 0x803ea1 cmp dword [edi+0x1d18],0x1a / jne. */
  assert.equal(gameUpdateSliceB9b11Flag11f4Needed(0), 0);
  assert.equal(gameUpdateSliceB9b11Flag11f4Needed(1), 1);
  assert.equal(gameUpdateSliceB9b11Flag11f4Needed(0x100), 0, "0x100 low 0");
  assert.equal(gameUpdateSliceB9b11Flag11f4Needed(0x1ff), 1);
  assert.equal(gameUpdateSliceB9b11Double409030Needed(0), 0);
  assert.equal(gameUpdateSliceB9b11Double409030Needed(1), 1);
  assert.equal(gameUpdateSliceB9b11Double409030Needed(0x100), 0, "0x100 low 0");
  assert.equal(gameUpdateSliceB9b11Double409030Needed(0x1ff), 1);
  assert.equal(gameUpdateSliceB9b11Stage1aNeeded(0x1a), 1);
  assert.equal(gameUpdateSliceB9b11Stage1aNeeded(0x11a), 0, "0x11a FULL-DWORD does not match 0x1a");
  assert.equal(gameUpdateSliceB9b11Stage1aNeeded(0x19), 0);
  assert.equal(gameUpdateSliceB9b11Stage1aNeeded(0xffffffff), 0);
});

test("ABI v95: B11 age1 gate = LOW-BYTE active && EXACT age == 1", () => {
  /* PE 0x803f21 cmp byte [edi],0 / je; 0x803f31 sub / 0x803f37 cmp eax,1. */
  assert.equal(gameUpdateSliceB9b11Age1Needed(1, 100, 99), 1);
  assert.equal(gameUpdateSliceB9b11Age1Needed(0x100, 100, 99), 0, "active 0x100 low 0");
  assert.equal(gameUpdateSliceB9b11Age1Needed(1, 100, 98), 0, "age 2");
  assert.equal(gameUpdateSliceB9b11Age1Needed(1, 100, 100), 0, "age 0");
  assert.equal(gameUpdateSliceB9b11Age1Needed(0, 100, 99), 0);
  assert.equal(gameUpdateSliceB9b11Age1Needed(1, 0, 0xffffffff), 1, "wrapped age 1");
});

test("ABI v95: B11 TempFX entry — flag LOW-BYTE clear + list FULL-DWORD non-empty + candidate + walk", () => {
  /* PE 0x803f43 cmp byte [edi+0x7321],0 / jne 0x804101;
     0x803f5c cmp eax,esi / je 0x804101; 0x803f68..0x803f77 type/variant
     FULL-DWORD; 0x803f80 add eax,0x10; 0x803f83 cmp eax,esi / jne. */
  assert.equal(gameUpdateSliceB9b11TempfxFlagClear(0), 1);
  assert.equal(gameUpdateSliceB9b11TempfxFlagClear(1), 0);
  assert.equal(gameUpdateSliceB9b11TempfxFlagClear(0x100), 1, "0x100 low 0 is clear");
  assert.equal(gameUpdateSliceB9b11TempfxFlagClear(0x1ff), 0);
  assert.equal(gameUpdateSliceB9b11TempfxListEmpty(0x1000, 0x1000), 1, "begin==end empty");
  assert.equal(gameUpdateSliceB9b11TempfxListEmpty(0x1000, 0x1010), 0);
  assert.equal(gameUpdateSliceB9b11TempfxIsCandidate(1, 0x1e1), 1);
  assert.equal(gameUpdateSliceB9b11TempfxIsCandidate(3, 0x1e1), 1);
  assert.equal(gameUpdateSliceB9b11TempfxIsCandidate(4, 0x1e1), 1);
  assert.equal(gameUpdateSliceB9b11TempfxIsCandidate(2, 0x1e1), 0, "type 2 not candidate");
  assert.equal(gameUpdateSliceB9b11TempfxIsCandidate(1, 0x1e0), 0, "variant 0x1e0");
  assert.equal(gameUpdateSliceB9b11TempfxIsCandidate(1, 0x2e1), 0, "variant FULL-DWORD 0x2e1 (bit 9) does not match 0x1e1");
  assert.equal(gameUpdateSliceB9b11TempfxIsCandidate(1, 0xffffffff), 0);
  assert.equal(gameUpdateSliceB9b11TempfxWalkNext(0x1000), 0x1010, "stride 0x10");
  assert.equal(gameUpdateSliceB9b11TempfxWalkNext(0xfffffff0), 0, "u32 wrap");
  assert.equal(gameUpdateSliceB9b11TempfxWalkContinue(0x1000, 0x1010), 1);
  assert.equal(gameUpdateSliceB9b11TempfxWalkContinue(0x1010, 0x1010), 0);
});

test("ABI v95: B9B11 wire emits typed events on the ready arm; ready=0 keeps the v48 monolithic", () => {
  const base = (over) => ({
    b9b11InputsReady: 1,
    b9b11ChallengeResultNonzero: 0x226,
    ambientRoomActive: 1,
    ambientRoomEntry11f0: 96,
    globalClearSkip997a: 1,
    b9b11RoomByte11f4: 1,
    b9b11RoomByte1d0d: 1,
    ambientRoom1d18: 0x1a,
    b9b11RoomByte7321: 0,
    b9b11ListBegin7314: 0x1000,
    b9b11ListEnd7318: 0x1010,
    ...over,
  });
  const st = (over) => ({
    frameCounter264f8: 100,
    roomType8: 0x11,
    roomDescFlags44: 0,
    roomBossCount12c8: 0,
    roomBossCount12cc: 0,
    roomBossSnapshot7224: 1,
    ...over,
  });
  const run = (rtOver, stOver) => resumeGameUpdateRoomUpdatePrefixB2(
    st(stOver || {}),
    base(rtOver || {}),
    { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX_B2 },
  );
  /* All-open frame: challenge gate open (result 0x226, active 1, age 4,
     type 0x11, flags 0) -> Free; mode hooks 0x11+byte -> ModeHooks;
     flag 11f4 -> Flag11f4; enemies 0 + old 1 -> B10Fatal; manager always;
     tempfx flag clear + list non-empty -> Camera. */
  const open = run({}, {});
  assert.equal(open.events.opaqueRoomUpdatePrefixB9B11, 1, "parent fires");
  assert.equal(open.events.opaqueRoomUpdatePrefixB9B11Free, 1);
  assert.equal(open.events.opaqueRoomUpdatePrefixB9B11ModeHooks, 1);
  assert.equal(open.events.opaqueRoomUpdatePrefixB9B11Flag11f4, 1);
  assert.equal(open.events.opaqueRoomUpdatePrefixB9B11B10Fatal, 1, "typed-event fires");
  assert.equal(open.events.opaqueRoomUpdatePrefixB9B11Manager, 1, "always-host chain");
  assert.equal(open.events.opaqueRoomUpdatePrefixB9B11Camera, 1);
  /* Challenge gate closed (result 0): Free stays 0. */
  const noChallenge = run({ b9b11ChallengeResultNonzero: 0 }, {});
  assert.equal(noChallenge.events.opaqueRoomUpdatePrefixB9B11Free, 0, "result 0 drops Free");
  /* WIDE result 0x100 still opens (FULL-DWORD). */
  const wideResult = run({ b9b11ChallengeResultNonzero: 0x100 }, {});
  assert.equal(wideResult.events.opaqueRoomUpdatePrefixB9B11Free, 1, "wide result opens");
  /* Fatal gate: enemies 2 -> no B10Fatal. */
  const noFatal = run({}, { roomBossCount12c8: 2 });
  assert.equal(noFatal.events.opaqueRoomUpdatePrefixB9B11B10Fatal, 0);
  /* old 7224 0 -> no fatal. */
  const noOld = run({}, { roomBossSnapshot7224: 0 });
  assert.equal(noOld.events.opaqueRoomUpdatePrefixB9B11B10Fatal, 0);
  /* Camera entry closed: flag 7321 set. */
  const noCamera = run({ b9b11RoomByte7321: 1 }, {});
  assert.equal(noCamera.events.opaqueRoomUpdatePrefixB9B11Camera, 0);
  /* Camera entry closed: list empty. */
  const emptyList = run({ b9b11ListEnd7318: 0x1000 }, {});
  assert.equal(emptyList.events.opaqueRoomUpdatePrefixB9B11Camera, 0);
  /* ready=0: monolithic parent only, no typed carriers. */
  const mono = run({ b9b11InputsReady: 0 }, {});
  assert.equal(mono.events.opaqueRoomUpdatePrefixB9B11, 1);
  assert.equal(mono.events.opaqueRoomUpdatePrefixB9B11Free, 0);
  assert.equal(mono.events.opaqueRoomUpdatePrefixB9B11B10Fatal, 0);
  assert.equal(mono.events.opaqueRoomUpdatePrefixB9B11Manager, 0);
  assert.equal(mono.events.opaqueRoomUpdatePrefixB9B11Camera, 0);
});

test("ABI v95: JSON + header record the B9B11 typed events + laws; exports in the build list", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.equal(spec.abiVersion, 99);
  for (const name of [
    "opaqueRoomUpdatePrefixB9B11Free",
    "opaqueRoomUpdatePrefixB9B11ModeHooks",
    "opaqueRoomUpdatePrefixB9B11Flag11f4",
    "opaqueRoomUpdatePrefixB9B11B10Fatal",
    "opaqueRoomUpdatePrefixB9B11Manager",
    "opaqueRoomUpdatePrefixB9B11Camera",
  ]) {
    const ev = spec.events.find((e) => e.name === name);
    assert.ok(ev, `spec records event ${name}`);
    assert.match(ev.abiV95 || "", /record idx 17|B9|B10|B11|TempFX|deathspawn/i);
  }
  const rec = spec.opaqueBoundaries.find((b) => b.idx === 17);
  assert.ok(rec, "record stays in opaqueBoundaries");
  assert.match(rec.evidence || "", /B9|B10|B11|challenge|fatal/i);
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const build = readFileSync(join(root, "scripts", "decomp", "build-game-update-slice.mjs"), "utf8");
  for (const law of [
    "challenge_gate", "free_helper_needed", "free_path_needed", "free_ptr_needed",
    "free_heap_lo", "free_heap_hi", "b10_enemies", "b10_fatal_needed",
    "mode_hooks_needed", "flag_11f4_needed", "double_409030_needed",
    "stage_1a_needed", "age1_needed", "tempfx_flag_clear", "tempfx_list_empty",
    "tempfx_is_candidate", "tempfx_walk_next", "tempfx_walk_continue",
  ]) {
    assert.match(header, new RegExp(`isaac_game_update_slice_b9b11_${law}`), `header decl ${law}`);
    assert.match(source, new RegExp(`isaac_game_update_slice_b9b11_${law}`), `cpp def ${law}`);
    assert.match(build, new RegExp(`isaac_game_update_slice_b9b11_${law}`), `build export ${law}`);
  }
  for (const ev of [
    "opaque_room_update_prefix_b9_b11_free",
    "opaque_room_update_prefix_b9_b11_mode_hooks",
    "opaque_room_update_prefix_b9_b11_flag_11f4",
    "opaque_room_update_prefix_b9_b11_b10_fatal",
    "opaque_room_update_prefix_b9_b11_manager",
    "opaque_room_update_prefix_b9_b11_camera",
  ]) {
    assert.match(header, new RegExp(ev), `header event field ${ev}`);
    assert.match(source, new RegExp(ev), `cpp uses ${ev}`);
  }
});

test("ABI v95: the shipped Wasm agrees with the oracle on the B9B11 laws", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  assert.equal(WebAssembly.Module.imports(module).length, 0, "slice must be zero-import");
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (mid-wave partial build); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const gate = pick("isaac_game_update_slice_b9b11_challenge_gate");
  if (typeof gate !== "function") {
    t.skip("the module predates the B9B11 exports (mid-wave partial build)");
    return;
  }
  for (const [r, a, f, e, ty, fl] of [
    [0x226, 1, 100, 96, 0x11, 0], [0, 1, 100, 96, 0x11, 0],
    [0x100, 1, 100, 96, 0x11, 0], [1, 0x100, 100, 96, 0x11, 0],
    [1, 1, 100, 97, 0x11, 0], [1, 1, 100, 96, 0x111, 0],
    [1, 1, 100, 96, 0x11, 8], [1, 1, 0, 0xfffffffc, 0x11, 0],
  ]) {
    assert.equal(gate(r | 0, a | 0, f | 0, e | 0, ty | 0, fl | 0) | 0,
      gameUpdateSliceB9b11ChallengeGate(r, a, f, e, ty, fl),
      `wasm challenge_gate(r=0x${(r >>> 0).toString(16)},a=${a})`);
  }
  const enemies = pick("isaac_game_update_slice_b9b11_b10_enemies");
  const fatal = pick("isaac_game_update_slice_b9b11_b10_fatal_needed");
  for (const [a, b] of [[0, 0], [3, 4], [-5, 2], [0x7fffffff, 1], [0x80000000, 0x80000000]]) {
    assert.equal(enemies(a | 0, b | 0) | 0, gameUpdateSliceB9b11B10Enemies(a, b),
      `wasm enemies(${a | 0},${b | 0})`);
    assert.equal(fatal(enemies(a | 0, b | 0) | 0, 1) | 0,
      gameUpdateSliceB9b11B10FatalNeeded(gameUpdateSliceB9b11B10Enemies(a, b), 1),
      `wasm fatal(enemies(${a | 0},${b | 0}),1)`);
  }
  const modeHooks = pick("isaac_game_update_slice_b9b11_mode_hooks_needed");
  for (const [ty, gb] of [[0xb, 1], [0x11, 1], [0xb, 0], [0xb, 0x100], [0x10b, 1]]) {
    assert.equal(modeHooks(ty | 0, gb | 0) | 0, gameUpdateSliceB9b11ModeHooksNeeded(ty, gb),
      `wasm mode_hooks(0x${(ty >>> 0).toString(16)},0x${(gb >>> 0).toString(16)})`);
  }
  const cand = pick("isaac_game_update_slice_b9b11_tempfx_is_candidate");
  for (const [ty, v] of [[1, 0x1e1], [3, 0x1e1], [4, 0x1e1], [2, 0x1e1], [1, 0x1e0], [1, 0x2e1]]) {
    assert.equal(cand(ty | 0, v | 0) | 0, gameUpdateSliceB9b11TempfxIsCandidate(ty, v),
      `wasm tempfx_candidate(${ty},0x${(v >>> 0).toString(16)})`);
  }
});

/* ==========================================================================
 * ABI v95 (record idx 29 roomTriggerClearAwardsBit7): FUN_007fb250
 * award-spawner HEAD dispatch + arithmetic laws. PE-truth transcribed
 * branch-by-branch from cpu-dump 007fb250.txt / 00812d00.txt /
 * 00823ec0.txt (census section-notes/update-v95-awards-bit7-head/
 * NOTES.md) — the references below are the instruction stream, NOT the
 * model/cpp. FULL-DWORD / LOW-BYTE / SIGNED gates are driven WIDE.
 * ========================================================================== */

test("ABI v95: AwardsBit7WalkDecision — 5/0x11 walk, 0x10 skip, FULL-DWORD", () => {
  /* 0x7fb464 mov eax,[Room+8] / cmp 5 / je 0x7fbb64 + cmp 0x11 / je
     0x7fbb64 + cmp 0x10 / je 0x7fe087. */
  assert.equal(gameUpdateSliceAwardsBit7WalkDecision(5), 1, "room type 5 -> walk arm");
  assert.equal(gameUpdateSliceAwardsBit7WalkDecision(0x11), 1, "room type 0x11 -> walk arm");
  assert.equal(gameUpdateSliceAwardsBit7WalkDecision(0x10), 2, "room type 0x10 -> tail-store skip");
  for (const n of [0, 1, 3, 4, 6, 0x100, 0x105, 0x101, 0x110, 0xffffffff]) {
    assert.equal(gameUpdateSliceAwardsBit7WalkDecision(n), 0,
      `type 0x${(n >>> 0).toString(16)} -> other (FULL-DWORD equality)`);
  }
});

test("ABI v95: AwardsBit7MerchantGate — ptr!=0 && kind 0x23 && type 0x10", () => {
  /* 0x7fb40f [Room+4] -> +0x10 / test / je + cmp [ptr+8],0x10 / jne +
     cmp [ptr],0x23 / jne. NULL-check on the LOADED pointer. */
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(1, 0x23, 0x10), 1, "merchant struct present");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(0, 0x23, 0x10), 0, "null ptr (0x7fb415 je)");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(0xffffffff, 0x23, 0x10), 1, "non-null wide ptr");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(1, 0x23, 0x101), 0, "type WIDE 0x101 != 0x10");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(1, 0x23, 0x100), 0, "type WIDE 0x100 != 0x10");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(1, 0x23f, 0x10), 0, "kind WIDE 0x23f != 0x23");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(1, 0, 0x10), 0, "kind 0 != 0x23");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(1, 0x23, 0), 0, "type 0 != 0x10");
  assert.equal(gameUpdateSliceAwardsBit7MerchantGate(1, 0x23, 0xffffffff), 0, "type WIDE -1 != 0x10");
});

test("ABI v95: AwardsBit7HeadSelect — greed > merchant > walk > skip (machine order)", () => {
  /* 0x7fb3f7 fresh [Game+0x269c8] / cmp 2 / je 0x7fd8e2 + cmp 3 / je
     0x7fd8e2 (greed precedes EVERY other check); merchant gate next;
     walk_decision 1 -> walk, 2 -> skip, else generic. */
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(2, 1, 1), 1, "diff 2 + merchant + walk -> GREED");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(3, 1, 1), 1, "diff 3 -> GREED");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(0x102, 1, 0), 2, "WIDE 0x102 not greed -> merchant");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(0xffffffff, 1, 0), 2, "WIDE -1 not greed -> merchant");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(1, 1, 1), 2, "merchant precedes walk");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(0, 0, 1), 3, "walk 5/0x11");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(0, 0, 2), 4, "skip 0x10");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(0, 0, 0), 0, "generic");
  assert.equal(gameUpdateSliceAwardsBit7HeadSelect(0x103, 0, 1), 3, "WIDE 0x103 -> walk (not greed)");
});

test("ABI v95: AwardsBit7GenericSkip — mineshaft al LOW-BYTE && dim FULL-DWORD == 1", () => {
  /* 0x7fb482 call 0x74efd0 / test al,al / je 0x7fb49d + cmp
     [Game+0x1830c],1 / je 0x7fe087. */
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(1, 1), 1, "al!=0 && dim 1 -> skip");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(0, 1), 0, "al 0 -> generic arm (0x7fb489 je)");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(0x100, 1), 0, "WIDE 0x100 al low byte 0 -> generic");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(0xff, 1), 1, "0xff low byte -> skip");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(0x1ff, 1), 1, "WIDE 0x1ff low byte 0xff -> skip");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(1, 0), 0, "dim 0 -> generic");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(1, 2), 0, "dim 2 -> generic");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(1, 0x100), 0, "dim WIDE 0x100 != 1 (FULL-DWORD)");
  assert.equal(gameUpdateSliceAwardsBit7GenericSkip(0xffffffff, 1), 1, "WIDE -1 al low byte 0xff -> skip");
});

test("ABI v95: AwardsBit7LuaGateSkip — 0x866220 al LOW-BYTE (WIDE 0x100 -> 0)", () => {
  /* 0x7fb2c6 call 0x866220 / 0x7fb2cb test al,al / 0x7fb2cd jne 0x7fe099
     — nonzero LOW BYTE skips ALL award spawning + the tail store. */
  assert.equal(gameUpdateSliceAwardsBit7LuaGateSkip(0), 0, "gate open (no skip)");
  assert.equal(gameUpdateSliceAwardsBit7LuaGateSkip(1), 1, "gate closed -> skip all");
  assert.equal(gameUpdateSliceAwardsBit7LuaGateSkip(0x100), 0, "WIDE 0x100 al==0 (test al,al)");
  assert.equal(gameUpdateSliceAwardsBit7LuaGateSkip(0xff), 1, "0xff skips");
  assert.equal(gameUpdateSliceAwardsBit7LuaGateSkip(0x1ff), 1, "WIDE 0x1ff low byte 0xff skips");
  assert.equal(gameUpdateSliceAwardsBit7LuaGateSkip(0xffffffff), 1, "WIDE -1 skips");
});

test("ABI v95: AwardsBit7TailStoreFire — [Room+4+0x60] store iff !lua skip", () => {
  /* 0x7fe087..0x7fe096 store runs on EVERY non-Lua-skip path (greed/walk/
     merchant/0x10-skip/mineshaft-skip all converge); ONLY 0x7fb2cd jne
     0x7fe099 skips it. */
  assert.equal(gameUpdateSliceAwardsBit7TailStoreFire(0), 1, "gate open -> tail store runs");
  assert.equal(gameUpdateSliceAwardsBit7TailStoreFire(1), 0, "lua skip -> 0x7fe099 no store");
});

test("ABI v95: 812d00Arithmetic — stage table {9:0x148,10:0x13b,11:0x84,12:0x77} + SIGNED idiv + f32 out", () => {
  /* PE 0x812d00: chain4/chain4_10 null -> no store (0x812d13/0x812d1a
     je); stage48-9<=3 UNSIGNED (0x812d1f sub / 0x812d22 cmp 3 / 0x812d25
     ja); jump table 0x812dc8 {9:0x148, 10:0x13b, 11:0x84, 12:0x77};
     SIGNED idiv by [Game+0x18300+0xc]; out0 = cvtdq2ps(rem)*40.0f+40.0f
     (mulss 0xbaa904 / addss), out1 = cvtdq2ps(quot)*40.0f+120.0f (addss
     0xbaaa00), each op rounding once. References hand-computed. */
  assert.equal(gameUpdateSlice812d00Arithmetic(0, 1, 10, 10).fire, 0, "chain4 null -> no store");
  assert.equal(gameUpdateSlice812d00Arithmetic(1, 0, 10, 10).fire, 0, "chain4_10 null -> no store");
  assert.equal(gameUpdateSlice812d00Arithmetic(1, 1, 8, 10).fire, 0, "stage 8 out of [9..12]");
  assert.equal(gameUpdateSlice812d00Arithmetic(1, 1, 13, 10).fire, 0, "stage 13 out of range");
  assert.equal(gameUpdateSlice812d00Arithmetic(1, 1, 0x109, 10).fire, 0, "stage WIDE 0x109 (dec 0x100 > 3 UNSIGNED)");
  assert.equal(gameUpdateSlice812d00Arithmetic(1, 1, 10, 0).fire, 0, "divisor 0 -> fire 0 (PE #DE; documented)");
  /* stage 9: 328; div 10 -> quot 32 rem 8 -> out0 360.0f, out1 1400.0f */
  assert.deepEqual(gameUpdateSlice812d00Arithmetic(1, 1, 9, 10),
    { fire: 1, out0Bits: 0x43b40000, out1Bits: 0x44af0000 }, "stage 9 div 10");
  /* stage 10: 315; div 10 -> quot 31 rem 5 -> out0 240.0f, out1 1360.0f */
  assert.deepEqual(gameUpdateSlice812d00Arithmetic(1, 1, 10, 10),
    { fire: 1, out0Bits: 0x43700000, out1Bits: 0x44aa0000 }, "stage 10 div 10");
  /* stage 11: 132; div 10 -> quot 13 rem 2 -> out0 120.0f, out1 640.0f */
  assert.deepEqual(gameUpdateSlice812d00Arithmetic(1, 1, 11, 10),
    { fire: 1, out0Bits: 0x42f00000, out1Bits: 0x44200000 }, "stage 11 div 10");
  /* stage 12: 119; div 10 -> quot 11 rem 9 -> out0 400.0f, out1 560.0f */
  assert.deepEqual(gameUpdateSlice812d00Arithmetic(1, 1, 12, 10),
    { fire: 1, out0Bits: 0x43c80000, out1Bits: 0x440c0000 }, "stage 12 div 10");
  /* stage 9 div 3: 328/3 = 109 r 1 -> out0 80.0f, out1 4480.0f */
  assert.deepEqual(gameUpdateSlice812d00Arithmetic(1, 1, 9, 3),
    { fire: 1, out0Bits: 0x42a00000, out1Bits: 0x458c0000 }, "stage 9 div 3");
  /* WIDE divisor 0xffffffff (-1): 328/-1 = -328 r 0 -> out0 40.0f,
     out1 -13000.0f */
  assert.deepEqual(gameUpdateSlice812d00Arithmetic(1, 1, 9, 0xffffffff),
    { fire: 1, out0Bits: 0x42200000, out1Bits: 0xc64b2000 }, "stage 9 div -1");
  /* WIDE divisor 0x100 (256): 328/256 = 1 r 72 -> out0 2920.0f, out1
     160.0f */
  assert.deepEqual(gameUpdateSlice812d00Arithmetic(1, 1, 9, 0x100),
    { fire: 1, out0Bits: 0x45368000, out1Bits: 0x43200000 }, "stage 9 div 256");
});

test("ABI v95: 823ec0Index — f32 pipeline + SIGNED bounds + 32-bit wrap index", () => {
  /* PE 0x823ec0: x=(out0+0.0f-40.0f)/40.0f+0.5f cvttss2si (trunc);
     y=(out1-80.0f-120.0f)/40.0f+0.5f cvttss2si; SIGNED js/jge bounds
     [Room+0xc] / [Room+0x10]; return [Room+0xc]*yd+xd (imul+add 32-bit
     wrap) else -1. cvttss2si NaN/overflow -> 0x80000000 -> -1. fire==0 ->
     -1 (PE reads uninitialized stack; documented). */
  assert.equal(gameUpdateSlice823ec0Index(0, 0x43b40000, 0x44af0000, 40, 40), -1, "fire 0 -> -1");
  /* stage 9 div 10: out0 360.0 -> x=8.5 -> 8; out1 1400.0 -> y=30.5 ->
     30; index 40*30+8 = 1208 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0x43b40000, 0x44af0000, 40, 40), 1208, "stage9/div10 index");
  assert.equal(gameUpdateSlice823ec0Index(1, 0x43b40000, 0x44af0000, 8, 40), -1, "xd 8 >= room_c 8 (jge SIGNED)");
  assert.equal(gameUpdateSlice823ec0Index(1, 0x43b40000, 0x44af0000, 40, 30), -1, "yd 30 >= room_10 30");
  assert.equal(gameUpdateSlice823ec0Index(1, 0x43b40000, 0x44af0000, 0x100, 0x100), 7688, "WIDE bounds 256*30+8");
  /* WIDE room_c 0xffffffff is -1 SIGNED -> xd 8 >= -1 -> -1 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0x43b40000, 0x44af0000, 0xffffffff, 40), -1,
    "room_c WIDE -1 (signed jge) closes");
  /* negative x: out0 -80.0f -> x = (-80-40)/40+0.5 = -2.5 -> trunc -2 -> js -> -1 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0xc2a00000, 0x44af0000, 40, 40), -1, "negative xd (js)");
  /* negative y: out1 -200.0f -> y = (-200-200)/40+0.5 = -9.5 -> -9 -> -1 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0x43b40000, 0xc3480000, 40, 40), -1, "negative yd (js)");
  /* NaN out0 -> cvttss2si 0x80000000 -> -1 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0x7fc00000, 0x44af0000, 40, 40), -1, "NaN out0");
  /* +inf out0 -> indefinite -> -1 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0x7f800000, 0x44af0000, 40, 40), -1, "+inf out0");
  /* 1e6.0 both lanes (0x49742400): x=(1e6-40)/40+0.5=24999.5 -> 24999;
     y=(1e6-200)/40+0.5=24995.5 -> 24995; index 25000*24995+24999 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0x49742400, 0x49742400, 25000, 25000), 624899999, "1e6 lanes");
  /* wrap: room_c 0x20000 (131072) * yd 24995 = 3276144640 mod 2^32 =
     -1018822656; + xd 24999 -> -1018797657 */
  assert.equal(gameUpdateSlice823ec0Index(1, 0x49742400, 0x49742400, 0x20000, 25000), -1018797657,
    "imul+add 32-bit wrap");
});

