/** Drive the clear-path TriggerClear residual and return the record-29
 *  typed-carrier deltas (the bit7 block is inside
 *  resumeGameUpdateRoomUpdatePrefix, the v31 TriggerClear fragment). */
function awardsBit7ResumeDelta(stateOverrides = {}, runtime = {}) {
  const base = step({});
  const shaped = {
    ...base.state,
    roomClearDelay11ec: 0, roomAlive12c0: 0, roomAlive12c4: 0,
    roomGreedWave723c: 0, roomDescFlags44: 0,
    ...stateOverrides,
  };
  const ev = {
    ...base.events,
    opaqueRoomTransitionEnginePrefix: 0,
    opaqueCall006fd7c0Mode4Sfx: 0,
    opaqueRoomUpdateClearPath: 0,
    continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX,
  };
  const pre = ev.roomTriggerClearAwardsBit7 >>> 0;
  const out = resumeGameUpdateRoomUpdatePrefix(shaped, runtime, ev);
  assert.ok(out, "room-update prefix resume returned a result");
  const events = out.events || {};
  return {
    bit7: (events.roomTriggerClearAwardsBit7 >>> 0) - pre,
    head: events.roomTriggerClearAwardsBit7Head >>> 0,
    walk: events.roomTriggerClearAwardsBit7Walk >>> 0,
    merchant: events.roomTriggerClearAwardsBit7Merchant >>> 0,
    luaSkip: events.roomTriggerClearAwardsBit7LuaSkip >>> 0,
    genericSkip: events.roomTriggerClearAwardsBit7GenericSkip >>> 0,
    tailStore: events.roomTriggerClearAwardsBit7TailStore >>> 0,
    tailStoreValue: events.roomTriggerClearAwardsBit7TailStoreValue >>> 0,
    r812d00Fire: events.roomTriggerClearAwardsBit7812d00Fire >>> 0,
    r812d00Out0Bits: events.roomTriggerClearAwardsBit7812d00Out0Bits >>> 0,
    r812d00Out1Bits: events.roomTriggerClearAwardsBit7812d00Out1Bits >>> 0,
  };
}

test("ABI v95: awards-bit7 wire — walk head on type 5, Lua gate open, tail store captures ac", () => {
  const out = awardsBit7ResumeDelta(
    { roomType8: 5, difficulty269c8: 5 },
    { triggerClearAwardsGateAl: 0, triggerClearAwardsAcFinal: 0x1234 },
  );
  assert.equal(out.bit7, 1, "walk-active -> the 0x7fb250 call fires");
  assert.equal(out.head, 3, "type 5 non-greed -> WALK arm");
  assert.equal(out.walk, 1, "walk decision 1");
  assert.equal(out.merchant, 0, "no merchant struct");
  assert.equal(out.luaSkip, 0, "gate al 0 -> no skip");
  assert.equal(out.genericSkip, 0, "mineshaft al 0 -> not skipped");
  assert.equal(out.tailStore, 1, "store runs (not Lua-skipped)");
  assert.equal(out.tailStoreValue, 0x1234, "final ac captured at the 0x7fe087 seam");
  assert.equal(out.r812d00Fire, 0, "no 812d00 chain captures -> fire 0");
});

