test("ABI v114: coarse retirement equivalence — gate-open fires carriers only; gate-miss/no-blob keeps the byte-for-byte monolith", () => {
  const rt = (extra) => ({
    tailPathReady: 1, tailPathListBeginC82674: 0x1000, tailPathListEndC82678: 0x1010,
    tailPathMode26614: 2, tailPathGenrandDraws: 2,
    tailPathEntries: [
      { type28: 0x1c, flags16c: 0x1000, field3c0: 1, child3bc: 0, childType28: 0, posX: 0x3f800000, posY: 0 },
      { type28: 0x4e, flags16c: 0, field3c0: 1, child3bc: 0, childType28: 0, posX: 0x3f800000, posY: 0 },
      { type28: 0x66, flags16c: 0, field3c0: 1, child3bc: 0, childType28: 0, posX: 0, posY: 0x40000000 },
    ],
    ...extra,
  });
  const drive = (overrides, runtime) =>
    resumeGameUpdateRoomUpdateHead(state(overrides), runtime,
      { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD });
  /* (a) gate open + capture live: typed carriers fire, coarse does NOT. */
  const live = drive({ roomFlag7769: 0x12 }, rt());
  assert.equal(live.events.opaqueRoomUpdateTailPath, 0, "no coarse edge under live capture");
  assert.equal(live.events.tailPathHostRebuild, 1, "rebuild carrier IS the B19 record");
  assert.equal(live.events.tailPathHostTrail, 1, "trail carrier IS the B20 record");
  assert.equal(live.events.tailPathHostPush, 1);
  assert.equal(live.events.tailPathHostSpawn, 3);
  assert.equal(live.events.tailPathPureSteps, 3);
  /* B19-only arm (begin==end): rebuild carrier alone, still no coarse. */
  const b19Only = drive({ roomFlag7769: 0x12 }, rt({ tailPathListEndC82678: 0x1000 }));
  assert.equal(b19Only.events.opaqueRoomUpdateTailPath, 0, "no coarse edge on B19-only");
  assert.equal(b19Only.events.tailPathHostRebuild, 1);
  assert.equal(b19Only.events.tailPathHostTrail ?? 0, 0);
  /* (b) gate miss (flag low byte 0) + capture live: pure skip, no edge,
     no carriers — byte-for-byte the pre-v114 stream. */
  const miss = drive({ roomFlag7769: 0x100 }, rt());
  assert.equal(miss.events.opaqueRoomUpdateTailPath, 0, "gate miss stays silent");
  assert.equal(miss.events.tailPathHostRebuild ?? 0, 0);
  assert.equal(miss.events.tailPathHostTrail, 1, "B20 still hosts under capture");
  /* (b) no-blob (ready=0): capture-absence gate miss — coarse fires ONCE,
     byte-for-byte the pre-v95 monolith; carriers stay 0. */
  const noBlob = drive({ roomFlag7769: 0x12 }, {});
  assert.equal(noBlob.events.opaqueRoomUpdateTailPath, 1,
    "capture-absence gate miss keeps the monolith byte-for-byte");
  assert.equal(noBlob.events.tailPathPureSteps ?? 0, 0, "no carriers without blob");
});

