      "isaac_game_update_slice_b18_path_b_needs_host",
      "isaac_game_update_slice_b18_rtti_src_ptr",
      "isaac_game_update_slice_b18_rtti_dst_ptr",
      "isaac_game_update_slice_b18_walk_frame",
