test("ABI v95: the shipped Wasm agrees with the 82ee40 body laws when the module is current", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  if (pick("isaac_game_update_slice_abi_version")() !== ABI_VERSION) {
    t.skip("the shipped module is stale (pre-v95); the coordinator's wave-end rebuild flips this probe");
    return;
  }
  const eligible = pick("isaac_game_update_slice_82ee40_body_eligible");
  const predicate = pick("isaac_game_update_slice_82ee40_body_predicate");
  const abcc0 = pick("isaac_game_update_slice_82ee40_body_7abcc0_needed");
  const arg = pick("isaac_game_update_slice_82ee40_body_7abcc0_arg");
  const abe20 = pick("isaac_game_update_slice_82ee40_body_7abe20_needed");
  const plan = pick("isaac_game_update_slice_82ee40_body_entry_plan");
  if (typeof eligible !== "function" || typeof plan !== "function") {
    t.skip("the module predates the 82ee40 body exports (mid-wave partial build)");
    return;
  }
  const fields = [0, 1, 0x100, 0x1ff, 3, 0xb, 0xc, 0xd, 0x14, 0x114, 0x1000003, 0xffffffff];
  for (const f of fields) {
    assert.equal(eligible(f) | 0, gameUpdateSlice82ee40BodyEligible(f) | 0,
      `body_eligible(0x${(f >>> 0).toString(16)})`);
    assert.equal(predicate(f) | 0, gameUpdateSlice82ee40BodyPredicate(f) | 0,
      `body_predicate(0x${(f >>> 0).toString(16)})`);
    assert.equal(abcc0(1, f) | 0, gameUpdateSlice82ee40Body7abcc0Needed(1, f) | 0,
      `body_7abcc0_needed(0x${(f >>> 0).toString(16)})`);
    assert.equal(arg(f) | 0, gameUpdateSlice82ee40Body7abcc0Arg(f) | 0,
      `body_7abcc0_arg(0x${(f >>> 0).toString(16)})`);
    assert.equal(abe20(f, 0, 0) | 0, gameUpdateSlice82ee40Body7abe20Needed(f, 0, 0) | 0,
      `body_7abe20_needed(0x${(f >>> 0).toString(16)})`);
  }
  /* Composed plan lockstep across the eligibility/pred/173/anim space.
     The plan export writes 5 i32 into wasm memory — use the module's
     exported memory at a scratch offset above GLOBAL_BASE (1 MiB) and
     inside INITIAL_MEMORY (4 MiB), outside the exported scratch statics. */
  const mem = wasm.memory ?? wasm.exports?.memory;
  if (!(mem instanceof WebAssembly.Memory)) {
    t.skip("module does not export memory (mid-wave partial build)");
    return;
  }
  const planView = new DataView(mem.buffer, 0x200000, 5 * 4);
  for (const eligibleV of [0, 1, 0x100, 0xffffffff]) {
    for (const predV of [0, 1]) {
      for (const byteV of [0, 1, 0x100, 0x1ff]) {
        for (const fieldV of [3, 0x14, 0x114, 0]) {
          for (const animV of [0xb, 0x10b, 20]) {
            plan(eligibleV, predV, byteV, fieldV, animV, 0x200000);
            const expected = gameUpdateSlice82ee40BodyEntryPlan({
              eligible: eligibleV, predicate: predV, entry173Byte: byteV,
              field1c: fieldV, anim: animV,
            });
            assert.equal(planView.getInt32(0, true) | 0, expected.call7abcc0 | 0, "plan.call7abcc0");
            assert.equal(planView.getInt32(4, true) | 0, expected.arg7abcc0 | 0, "plan.arg7abcc0");
            assert.equal(planView.getInt32(8, true) | 0, expected.call7abe20 | 0, "plan.call7abe20");
            assert.equal(planView.getInt32(12, true) | 0, expected.anyHost | 0, "plan.anyHost");
            assert.equal(planView.getInt32(16, true) | 0, expected.gameReread | 0, "plan.gameReread");
          }
        }
      }
    }
  }
});

/* ================= ABI v95: record idx 24 opaqueRoomUpdateClearDoorSlots ====
   Composed per-slot early-out decision + typed failing-slot open (unit
   update-v95-clear-door-slots-mask). PE-truth transcribed from
   cpu-dump/00804100.txt (0x0080424d..0x0080427d) + cpu-dump/00710dd0.txt
   (the FUN_00710dd0 prologue 0x710ddb..0x710e07 — do NOT derive from the
   C++ or the model):
     loop        0x804260 mov ecx,[esi] ; 0x804262 test ecx,ecx je SKIP
                 (FULL-DWORD present gate) ; call 0x710dd0 per non-null
                 slot; 8 slots, counter stored/reloaded per iteration.
     early-out   0x710ddb test al,0x10 / 0x710ddf cmp dword [esi+8],8
                 jne RET1 (PASS); 0x710de9 test al,0x20 / 0x710ded cmp
                 dword,4 je RET1 (PASS); 0x710df7 cmp dword [esi+0xc],2
                 je RET1 (PASS); 0x710e01/0x710e07 cmp dword,7 je RET1
                 (PASS). Otherwise FALL THROUGH -> the residual open body
                 (0x710e0d..0x710f4b: calls 0x748760/0x5cd5f0/0x710f70/
                 0x740bc0/0x711740, jmp 0x70ee40, stores [esi+8]=1/8,
                 [esi+0xc]=2/5, Game+0x26548/0x2654c |= 0x20000) — TYPED
                 HOST per v25. bit i of the failing mask = present slot i
                 fails the early-out (needs host open). */

test("ABI v95 clear-door-slots: failing mask = present slots failing the 0x710dd0 early-out (per-slot, WIDE drives)", () => {
  const slot = (present, field3a0, field8, fieldC) => ({ present, field3a0, field8, fieldC });
  /* All early-out PASS clauses: (f3a0&0x10 && f8!=8), (f3a0&0x20 && f8==4),
     fc==2, f8==7 — each alone makes the slot pure (mask bit clear). */
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0x10, 1, 0)]), 0,
    "f3a0 bit4 + f8!=8 passes");
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0x20, 4, 0)]), 0,
    "f3a0 bit5 + f8==4 passes");
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0, 0, 2)]), 0,
    "fc==2 passes");
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0, 7, 0)]), 0,
    "f8==7 passes");
  /* Absent slots (present==0) never set bits even with failing fields. */
  assert.equal(doorSlots710dd0FailingMask([slot(0, 0, 1, 0)]), 0,
    "absent slot skipped (FULL-DWORD present==0)");
  /* A FAILING present slot sets its bit: no clause matches. */
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0, 1, 0)]), 1,
    "f8=1/fc=0 fails -> bit0");
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0x10, 8, 0)]), 1,
    "bit4 but f8==8 cancels the first clause -> fails");
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0x20, 5, 0)]), 1,
    "bit5 but f8!=4 cancels the second clause -> fails");
  /* WIDE present: 0x100/0xffffffff are nonzero FULL-DWORD -> qualified;
     byte-narrowing would wrongly skip (defect guard). */
  assert.equal(doorSlots710dd0FailingMask([slot(0x100, 0, 1, 0)]), 1,
    "WIDE present 0x100 with failing fields -> bit0");
  assert.equal(doorSlots710dd0FailingMask([slot(0xffffffff, 0, 1, 0)]), 1,
    "WIDE present 0xffffffff with failing fields -> bit0");
  /* Per-slot bit positions across the 8 slots. */
  assert.equal(doorSlots710dd0FailingMask([
    slot(1, 0, 1, 0), slot(0, 0, 0, 0), slot(1, 0x10, 1, 0), slot(1, 0, 5, 9),
    slot(0, 0, 0, 0), slot(1, 0x20, 4, 0), slot(1, 0, 7, 0), slot(1, 0, 3, 3),
  ]), (1 | 8 | 0x80) >>> 0, "slots 0,3,7 fail; 2/5/6 pass; 1/4 absent");
  /* WIDE field drives: fc=0x1000002 low byte 2 must NOT pass (FULL-DWORD
     cmp 2 at 0x710df7); f8=0x1000007 must NOT pass (FULL-DWORD cmp 7). */
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0, 0, 0x1000002)]), 1,
    "fc 0x1000002 is not 2 in a FULL-DWORD compare -> fails");
  assert.equal(doorSlots710dd0FailingMask([slot(1, 0, 0x1000007, 0)]), 1,
    "f8 0x1000007 is not 7 in a FULL-DWORD compare -> fails");
  /* f3a0 bit-test is LOW-BYTE (test al,0x10 at 0x710ddb): the low byte
     decides; see the dedicated test below. */
});

test("ABI v95 clear-door-slots: f3a0 bit tests are LOW-BYTE (PE test al,0x10 / al,0x20)", () => {
  /* 0x710ddb a810 = test al,0x10; 0x710de9 a820 = test al,0x20. A door with
     f3a0=0x10000010 has al=0x10 -> the 0x10 clause APPLIES (bit4 of the LOW
     byte); a full-word mask would wrongly see only bit 0x10000000. */
  assert.equal(doorSlots710dd0FailingMask([{ present: 1, field3a0: 0x10000010, field8: 1, fieldC: 0 }]), 0,
    "0x10000010 low byte 0x10 -> clause 1 applies (f8!=8) -> PASS");
  assert.equal(doorSlots710dd0FailingMask([{ present: 1, field3a0: 0x10000010, field8: 8, fieldC: 0 }]), 1,
    "clause 1 applies but f8==8 cancels -> FAILS");
  assert.equal(doorSlots710dd0FailingMask([{ present: 1, field3a0: 0x10000020, field8: 4, fieldC: 0 }]), 0,
    "0x10000020 low byte 0x20 -> clause 2 applies (f8==4) -> PASS");
  assert.equal(doorSlots710dd0FailingMask([{ present: 1, field3a0: 0x10000030, field8: 4, fieldC: 0 }]), 0,
    "low byte 0x30 = bits 0x10|0x20; clause 2 (f8==4) passes");
});

test("ABI v119 clear-door-slots (idx-24 coarse RETIRED): the mask carrier fires iff mask != 0 and types the open", () => {
  const base = {
    globalClearSkip997a: 0, alive12c0: 0, alive12c4: 0, roomGreedWave723c: 0,
    roomClearDelay11ec: 0, roomType8: 0, roomDescSubtype: 0,
    roomDescFlags44: 9, /* skip TriggerClear tail */
    doorSlots: [],
  };
  const run = (doorSlots, flags44 = 9) => {
    const st = { roomDescFlags44: flags44, roomDescClearCount4a: 0, flags2654c: 0,
      roomAlive12c0: 0, roomAlive12c4: 0, roomGreedWave723c: 0, roomClearDelay11ec: 0,
      roomType8: 0, roomDescSubtype: 0, difficulty269c8: 0, roomBossCount12c8: 0,
      roomBossCount12cc: 0, roomBossSnapshot7224: 0, roomTimer722c: 0,
      roomCollectibleTimer7764: 0, roomTimer7214: 0, roomTimer706c: 0,
      roomTimer7230: 0, roomWaterAmount7240: 0, roomLavaIntensity7740: 0,
      roomFlag7894: 0, roomFlag7769: 0, roomByte7220: 0, mode26584: 0 };
    const rt = { ...base, doorSlots };
    const ev = { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX };
    const out = resumeGameUpdateRoomUpdatePrefix(st, rt, ev);
    return out.events ?? out;
  };
  /* All slots early-out: no event, mask 0. */
  const pure = run([{ present: 1, field3a0: 0x10, field8: 1, fieldC: 0 }]);
  assert.equal(pure.opaqueRoomUpdateClearDoorSlots | 0, 0, "all early-out -> no residual (coarse RETIRED)");
  assert.equal(pure.opaqueRoomUpdateClearDoorSlotsMask | 0, 0, "mask stays 0");
  /* One failing slot: carrier fires, mask bit 0, coarse stays 0. */
  const one = run([{ present: 1, field3a0: 0, field8: 1, fieldC: 0 }]);
  assert.equal(one.opaqueRoomUpdateClearDoorSlots | 0, 0, "idx-24 coarse RETIRED at v119 — never fires");
  assert.equal(one.opaqueRoomUpdateClearDoorSlotsMask >>> 0, 1, "typed open mask bit0 (the carrier)");
  /* Failing slots at 0 and 7: mask 0x81. */
  const two = run([
    { present: 1, field3a0: 0, field8: 1, fieldC: 0 }, { present: 0 },
    { present: 0 }, { present: 0 }, { present: 0 }, { present: 0 },
    { present: 0 }, { present: 1, field3a0: 0x10, field8: 8, fieldC: 0 },
  ]);
  assert.equal(two.opaqueRoomUpdateClearDoorSlots | 0, 0, "two failing slots still ONE residual (coarse stays 0)");
  assert.equal(two.opaqueRoomUpdateClearDoorSlotsMask >>> 0, 0x81, "mask bits 0 and 7");
  /* No clear side (enemies present) -> no door-slot residual at all. */
  const nc = resumeGameUpdateRoomUpdatePrefix(
    { roomDescFlags44: 9, roomDescClearCount4a: 0, flags2654c: 0,
      roomAlive12c0: 1, roomAlive12c4: 0, roomGreedWave723c: 0,
      roomClearDelay11ec: 0, roomType8: 0, roomDescSubtype: 0, difficulty269c8: 0,
      roomBossCount12c8: 0, roomBossCount12cc: 0, roomBossSnapshot7224: 0,
      roomTimer722c: 0, roomCollectibleTimer7764: 0, roomTimer7214: 0,
      roomTimer706c: 0, roomTimer7230: 0, roomWaterAmount7240: 0,
      roomLavaIntensity7740: 0, roomFlag7894: 0, roomFlag7769: 0,
      roomByte7220: 0, mode26584: 0 },
    { ...base, alive12c0: 1, alive12c4: 0,
      doorSlots: [{ present: 1, field3a0: 0, field8: 1, fieldC: 0 }] },
    { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX },
  );
  assert.equal((nc.events ?? nc).opaqueRoomUpdateClearDoorSlots | 0, 0,
    "clear-side closed -> no door residual");
});

