test("ABI v135: record idx28 — the deep-music gate runs in-module under its voucher; coarse @180 retires on capture only", () => {
  /* Gate OPENS: head-clear byte set (so probes were SKIPPED — RAN bits
     clear, al bytes clear), byte26588 zero, vec pair NONEMPTY, count>0,
     flags bit16 clear, room match nonzero, game0==1, game4 notin {4,5},
     frame small. Fire package applies: flags bit16 ORed into state. */
  const open = dmRun({
    tcaDmGateReady: 1,
    tcaDmHeadClear1bb84: 1,
    tcaDmProbeA9e9b50: 0,        /* RAN bit clear = skipped */
    tcaDmProbeB9595e0: 0,
    tcaDmByte26588: 0,
    tcaDmVecBegin4b3d8: 0x1000, tcaDmVecEnd4b3dc: 0x1010,
    tcaDmCount334: 3,
    tcaDmRoomMatchRet8: 7, tcaDmGame18314: 7,
    tcaDmGame4: 0,
    clearPathGameMode0: 1,
  });
  assert.equal(open.coarse, 0, "voucher live -> coarse @180 retired");
  assert.equal(open.fire, 1, "gate opens -> fire carrier");
  assert.equal((open.flags1839c & 0x10000) >>> 0, 0x10000,
    "flags bit16 apply-back");

  /* Gate CLOSED via vec-empty fallback (vec pair equal): retired too
     (no fire), because the decision is still in-module. */
  const closedVec = dmRun({
    tcaDmGateReady: 1,
    tcaDmHeadClear1bb84: 0,
    tcaDmProbeA9e9b50: 0x100,   /* RAN set, al=0 */
    tcaDmProbeB9595e0: 0x100,
    tcaDmByte26588: 0,
    tcaDmVecBegin4b3d8: 0, tcaDmVecEnd4b3dc: 0,
    tcaDmCount334: 3,
    tcaDmRoomMatchRet8: 7, tcaDmGame18314: 7,
    tcaDmGame4: 0,
  });
  assert.equal(closedVec.coarse, 0, "vec-empty fallback -> decision in-module, coarse retired");
  assert.equal(closedVec.fire, 0);

  /* Capture absence -> monolith byte-for-byte; no fire carrier. */
  const absent = dmRun({
    tcaDmGateReady: 0,
    tcaDmHeadClear1bb84: 1,
    tcaDmVecBegin4b3d8: 0x1000, tcaDmVecEnd4b3dc: 0x1010,
    tcaDmCount334: 3,
  });
  assert.equal(absent.coarse, 1, "absence -> monolith fires");
  assert.equal(absent.fire, 0, "no fire carrier on absence");
});
test("ABI v134: records idx28/29 — the awards head plan retires its decision arms under capture; SPAWN_LOOP keeps the coarse", () => {
  /* Exit 6 RT_ALT (roomType8 == 5): fully retired under the voucher. */
  const rtAlt = awardsRun({
    ...AWARDS_SRC_BASE,
    roomType8: 5,
  }, { roomType8: 5 });
  assert.equal(rtAlt.exitKind, 6, "head picks RT_ALT for roomType 5");
  assert.equal(rtAlt.coarse, 0, "exit 6 -> coarse @184 retired");
  assert.equal(rtAlt.plannedSpawns, 0);

  /* Exit 2 RT_END (roomType8 == 0x10): retired. */
  const rtEnd = awardsRun({ ...AWARDS_SRC_BASE, roomType8: 0x10 }, { roomType8: 0x10 });
  assert.equal(rtEnd.exitKind, 2);
  assert.equal(rtEnd.coarse, 0, "exit 2 -> retired");

  /* Exit 3 GREED_ARM dispatch-only (difficulty 2): retired (dispatch). */
  const greedArm = awardsRun({ ...AWARDS_SRC_BASE, awardsHeadSrcmode269c8: 2 },
    { difficulty269c8: 2 });
  assert.equal(greedArm.exitKind, 3);
  assert.equal(greedArm.coarse, 0, "exit 3 dispatch -> retired");

  /* Exit 0 LUA_TAIL (lua gate al != 0): retired. */
  const luaTail = awardsRun({
    ...AWARDS_SRC_BASE, awardsHeadSrcluaGate: 1,
  });
  assert.equal(luaTail.exitKind, 0);
  assert.equal(luaTail.coarse, 0, "exit 0 -> retired");

  /* Exit 7 NO_SPAWNS via rnd64 >= 0x42 with mode-1 id-0xa leg... simplest:
     gate_f1 + id != 0x15e + count law zeroes via comiss leg (h4e4690*0.5 >
     h7e9080 with h7e9080 = 0). */
  const noSpawns = awardsRun({
    ...AWARDS_SRC_BASE,
    awardsHeadSrcgateF1: 1, awardsHeadSrcpickedId: 0x14,
    awardsHeadSrch9be750: 1, awardsHeadSrch4e4690Bits: 0x3f800000,
    awardsHeadSrch7e9080Bits: 0,
  });
  assert.equal(noSpawns.exitKind, 7, "count zeroed -> NO_SPAWNS");
  assert.equal(noSpawns.count, 0);
  assert.equal(noSpawns.coarse, 0, "exit 7 -> retired on the full count-law pack");

  /* Capture absence keeps the monolith byte-for-byte (v95 carrier path). */
  const absent = awardsRun({ ...AWARDS_SRC_BASE, awardsHeadReady: 0 });
  assert.equal(absent.coarse, 1, "absence -> monolith");
  assert.equal(absent.exitKind, 0, "no head carriers publish on absence");
});

