test("ABI v140: record idx29 — the SPAWN_LOOP continuation retires under its voucher with inert blockers; every arm is mutation-checked", () => {
  /* Full live pack: coarse @184 silent, carriers publish. Row 0 arms the
     door arm (type28==5, variant2c==0x34) with the door gate OPEN-al=0 ->
     one fire; owner probe hits -> one chase; flag66 clear -> no RMW. */
  const live = spawnLoopRun(SPAWN_LOOP_LIVE);
  assert.equal(live.roomTriggerClearAwardsBit7 >>> 0, 0,
    "capture-live + inert blockers -> SPAWN_LOOP retired");
  assert.equal(live.roomAwardsHeadExitKind >>> 0, 4, "head picks SPAWN_LOOP");
  assert.equal(live.roomAwardsSpawnLoopRowsApplied >>> 0, 1);
  assert.equal(live.roomAwardsSpawnLoopDoorSpawnFires >>> 0, 1,
    "door arm fired (variant2c 0x34 in {0x34,0x36}, gate al 0)");
  assert.equal(live.roomAwardsSpawnLoopSfxChaseFires >>> 0, 1);
  assert.equal(live.roomAwardsSpawnLoopFlagRmwMask >>> 0, 0);
  assert.equal(live.roomAwardsSpawnLoopVariantFinal | 0, 1,
    "door fire latches [ebp-0x8c] := 1");
  assert.equal(live.roomAwardsSpawnLoopB1Pass >>> 0, 1,
    "min(0.69, 0.33)=0.33 > 0.01 ordered-above pass");
  assert.equal(live.roomAwardsSpawnLoopB1SiteArmed >>> 0, 1);
  assert.equal(live.roomAwardsSpawnLoopB1ChaseFired >>> 0, 1);

  /* M-A: door-arm variant gate — 0x99 leaves BOTH the {0x34,0x36}
     pair and the 6ee340 membership set -> no fire, and the al==0
     lane re-latches the variant from entityField30. */
  const mVariant = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopRow0EntityVariant2c: 0x99 });
  assert.equal(mVariant.roomAwardsSpawnLoopDoorSpawnFires >>> 0, 0,
    "M-A: variant outside {0x34,0x36} kills the door arm");
  assert.equal(mVariant.roomAwardsSpawnLoopVariantFinal >>> 0, 9,
    "M-A: al==0 re-latches variant from entityField30");

  /* M-B: door gate al != 0 suppresses the fire even inside the pair. */
  const mGate = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopRow0DoorGateAl: 1 });
  assert.equal(mGate.roomAwardsSpawnLoopDoorSpawnFires >>> 0, 0,
    "M-B: host door gate open -> no door spawn");
  assert.equal(mGate.roomAwardsSpawnLoopVariantFinal | 0, -1,
    "M-B: jne skips fire AND the :=1 store (0x7fb84d->0x7fb86c); " +
    "6ee340(0x34)=1 keeps variantCur");

  /* M-C: owner probe miss -> no chase. */
  const mOwner = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopRow0SfxOwner: 0 });
  assert.equal(mOwner.roomAwardsSpawnLoopSfxChaseFires >>> 0, 0,
    "M-C: owner==0 kills the chase leaf");
  /* M-D: flag66 && counter==0 arms the RMW mask bit. flag66 needs the
     head-plan eligibility set: gate202 && rnd4==0 && count>=1 && id
     in {0x14,0xa,0x1e,0x45,0x28}. */
  const mFlag = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsHeadSrcpickedId: 0x14,
    awardsHeadSrcgate202: 1, awardsHeadSrchRnd4: 0 });
  assert.equal(mFlag.roomAwardsSpawnLoopFlagRmwMask & 1, 1,
    "M-D: flag66 armed on row 0 -> mask bit0");
  assert.equal(mFlag.roomTriggerClearAwardsBit7 >>> 0, 0,
    "M-D: flag66 does not gate retirement (still capture-live)");

  /* M-E: blocker lane B ([Game+0x26584] == 0x2b) -> monolith names the
     un-modeled final create; NO carriers publish. */
  const m2b = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopGame26584: 0x2b });
  assert.equal(m2b.roomTriggerClearAwardsBit7 >>> 0, 1,
    "M-E: final spawn gate armed -> coarse byte-for-byte");
  assert.equal(m2b.roomAwardsSpawnLoopRowsApplied >>> 0, 0,
    "M-E: no carriers on poisoned ticks");

  /* M-F: blocker lane A (gate al!=0 WITH room type 0xb) -> monolith. */
  const mB = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopTailGateB1Al: 1 }, { roomType8: 0xb });
  assert.equal(mB.roomTriggerClearAwardsBit7 >>> 0, 1,
    "M-F: 0xb-band armed -> coarse byte-for-byte");
  /* Same gate al but room type != 0xb stays inert (disjunct). */
  const mBGateOnly = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopTailGateB1Al: 1 });
  assert.equal(mBGateOnly.roomTriggerClearAwardsBit7 >>> 0, 0,
    "M-F counterarm: al!=0 alone does NOT block (room not 0xb)");
  /* M-G: over-cap never truncates (iter_count > 16 poisons). */
  const mCap = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsHeadSrcpickedId: 0x14, awardsHeadSrcgateF1: 1,
    awardsHeadSrch9be750: 20, awardsHeadSrch4e4690Bits: 0x3f000000,
    awardsHeadSrch7e9080Bits: 0x3f800000, /* NOT above -> keep c2 = 21 */
    awardsSpawnLoopIterCount: 21 });
  assert.equal(mCap.roomAwardsHeadCount >>> 0, 21,
    "count law produces 21 (> cap 16)");
  assert.equal(mCap.roomTriggerClearAwardsBit7 >>> 0, 1,
    "M-G: over-cap -> coarse (never truncate)");

  /* M-H: count mismatch poisons the whole voucher. */
  const mMis = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopIterCount: 2 });
  assert.equal(mMis.roomTriggerClearAwardsBit7 >>> 0, 1,
    "M-H: dense PE-order mismatch -> coarse");

  /* M-I: voucher absence on an exit-4 tick keeps the monolith. */
  const mAbs = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopReady: 0 });
  assert.equal(mAbs.roomTriggerClearAwardsBit7 >>> 0, 1, "M-I: absence");
  assert.equal(mAbs.roomAwardsSpawnLoopRowsApplied >>> 0, 0);

  /* M-J: B1 luck arms — quality 0 drives val to 0 -> minss 0 vs rnd
     0.01 ordered-NOT-above -> no pass, no site, no chase; picker low
     kills only the chase, not the site. */
  const mLuck = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopB1QualityInt: 0 });
  assert.equal(mLuck.roomAwardsSpawnLoopB1Pass >>> 0, 0,
    "M-J: val 0 < rnd -> comiss NOT above");
  assert.equal(mLuck.roomAwardsSpawnLoopB1SiteArmed >>> 0, 0);
  const mPicker = spawnLoopRun({ ...SPAWN_LOOP_LIVE,
    awardsSpawnLoopB1PickerAl: 0 });
  assert.equal(mPicker.roomAwardsSpawnLoopB1ChaseFired >>> 0, 0,
    "M-J: picker al==0 kills only the B1 chase");
});

/* ABI v141 (update-v141-b-block-probe-pack): drive the TriggerClear
   fragment to exit 4 with the post-loop 0xb-band ARMED and the probe
   capture pack live. Expected carrier values are derived from the frozen
   room-pure ABI v86 laws consumed BY REFERENCE (roomIdx29At9b92c0 /
   roomCount7cb6e0Plan / roomRoll7c3980Core / _followupGate /
   roomIdx29RollPlan) -- never re-derived. Row 0 packs q = 4 (has-8b
   width 2 + two nested bit-15 slot matches @0x7cb913) -> double roll;
   row 1 stays fully neutral -> q = 0, no roll. RNG s0 = 0x12345678 with
   shifts {5,7,3} threads to 0x48546362 then 0x49582366 (indexes 2, 4). */
const BBLOCK_LIVE = {
  ...SPAWN_LOOP_LIVE,
  awardsSpawnLoopTailGateB1Al: 1,
  awardsBBlockReady: 1, awardsBBlockIterCount: 2,
  awardsBBlockVecBegin: 0x1000, awardsBBlockVecEnd: 0x1008,
  awardsBBlockDescChainBit: 1,
  awardsBBlockPosXBits: 0x41a00000, awardsBBlockPosYBits: 0x42100000,
  awardsBBlockDraw: 0xdeadbeef,
  awardsBBlockRngS0: 0x12345678, awardsBBlockRngS1: 5,
  awardsBBlockRngS2: 7, awardsBBlockRngS3: 3,
  awardsBBlockElemValue0: 0x7fb000, awardsBBlockElemValue1: 0x7fb100,
  awardsBBlockRow0Has8b: 1,
  awardsBBlockRow0Slot0: 0x8000 | 0xb1,
  awardsBBlockRow0Slot1: 0x8000 | 0xb1,
};

test("ABI v141: record idx29 — the post-loop 0xb-block retires under its voucher via the frozen probe laws; every arm is mutation-checked", () => {
  /* Full live pack, band armed: coarse @184 silent, carriers publish.
     Row 0: q=4 -> first AND second roll (masks bit0), follow-up gates
     open on both fires; row 1: q=0 -> no roll. */
  const live = spawnLoopRun(BBLOCK_LIVE, { roomType8: 0xb });
  assert.equal(live.roomTriggerClearAwardsBit7 >>> 0, 0,
    "capture-live + valid pack -> armed 0xb-band retired");
  assert.equal(live.roomAwardsHeadExitKind >>> 0, 4);
  assert.equal(live.roomAwardsSpawnLoopRowsApplied >>> 0, 1,
    "SPAWN_LOOP body carriers still publish under v141");
  assert.equal(live.roomAwardsBBlockRowsApplied >>> 0, 2);
  assert.equal(live.roomAwardsBBlockOobDefects >>> 0, 0,
    "jb loop guard pins index<count UNSIGNED -> defect arm unreachable");
  assert.equal(live.roomAwardsBBlockCountSum | 0, 4,
    "row0 slot legs sum to q=4, row1 neutral q=0");
  assert.equal(live.roomAwardsBBlockRollFirstMask >>> 0, 1);
  assert.equal(live.roomAwardsBBlockRollSecondMask >>> 0, 1,
    "q=4 > 2 SIGNED jle @0x7fbacc -> second roll");
  assert.equal(live.roomAwardsBBlockFollowupFires >>> 0, 2,
    "[this+0x3fc]==0 && byte[0x173]==0 on both fires -> 0x7abd30 x2");
  assert.equal(live.roomAwardsBBlockRngFinal >>> 0, 0x49582366,
    "s0 threads through both rolls of [ebp-0xac]");
  assert.equal(live.roomAwardsBBlockPreloopCreateVariant >>> 0, 0x64,
    "desc-chain bit set -> arm A count 0x64");
  assert.equal(live.roomAwardsBBlockTailCreateFired >>> 0, 0);

  /* M-A: voucher absence with the band ARMED -> monolith names the
     un-modeled probes byte-for-byte; no b-block carriers publish. */
  const mAbs = spawnLoopRun({ ...BBLOCK_LIVE, awardsBBlockReady: 0 },
    { roomType8: 0xb });
  assert.equal(mAbs.roomTriggerClearAwardsBit7 >>> 0, 1, "M-A: absence");
  assert.equal(mAbs.roomAwardsBBlockRowsApplied >>> 0, 0);

  /* M-B: recount mismatch poisons the whole voucher (PE recount is
     sar(vec_end-vec_begin,2) = 2). */
  const mMis = spawnLoopRun({ ...BBLOCK_LIVE, awardsBBlockIterCount: 1 },
    { roomType8: 0xb });
  assert.equal(mMis.roomTriggerClearAwardsBit7 >>> 0, 1, "M-B: mismatch");

  /* M-C: over-cap never truncates (PE recount 9 > cap 8). */
  const mCap = spawnLoopRun({ ...BBLOCK_LIVE, awardsBBlockVecEnd: 0x1024 },
    { roomType8: 0xb });
  assert.equal(mCap.roomTriggerClearAwardsBit7 >>> 0, 1, "M-C: over-cap");

  /* M-D: q <= 1 arm -- all rows neutral -> no rolls at all; rng state
     passes through untouched. */
  const mQuiet = spawnLoopRun({
    ...BBLOCK_LIVE,
    awardsBBlockRow0Has8b: 0,
    awardsBBlockRow0Slot0: 0, awardsBBlockRow0Slot1: 0,
  }, { roomType8: 0xb });
  assert.equal(mQuiet.roomTriggerClearAwardsBit7 >>> 0, 0,
    "M-D: still retired (band decided in-module)");
  assert.equal(mQuiet.roomAwardsBBlockCountSum | 0, 0);
  assert.equal(mQuiet.roomAwardsBBlockRollFirstMask >>> 0, 0);
  assert.equal(mQuiet.roomAwardsBBlockRollSecondMask >>> 0, 0);
  assert.equal(mQuiet.roomAwardsBBlockRngFinal >>> 0, 0x12345678,
    "M-D: s0 passes through when no roll fires");

  /* M-E: desc-chain bit clear -> arm B count 0x32. */
  const mArmB = spawnLoopRun(
    { ...BBLOCK_LIVE, awardsBBlockDescChainBit: 0 }, { roomType8: 0xb });
  assert.equal(mArmB.roomAwardsBBlockPreloopCreateVariant >>> 0, 0x32,
    "M-E: [eax+0x10]!=1 -> jne 0x7fba40 arm B");

  /* M-F: band inert (gate al == 0 despite room type 0xb) -> SPAWN_LOOP
     retirement stands and NO b-block carriers publish. */
  const mInert = spawnLoopRun(
    { ...BBLOCK_LIVE, awardsSpawnLoopTailGateB1Al: 0 }, { roomType8: 0xb });
  assert.equal(mInert.roomTriggerClearAwardsBit7 >>> 0, 0);
  assert.equal(mInert.roomAwardsBBlockRowsApplied >>> 0, 0,
    "M-F: band skipped -> zero carriers");

  /* M-G: final gate 0x2b arms WITH a valid pack -> tail create carrier,
     coarse silent. */
  const mTail = spawnLoopRun(
    { ...BBLOCK_LIVE, awardsSpawnLoopGame26584: 0x2b },
    { roomType8: 0xb });
  assert.equal(mTail.roomTriggerClearAwardsBit7 >>> 0, 0,
    "M-G: 0x2b extra create retired under the same voucher");
  assert.equal(mTail.roomAwardsBBlockTailCreateFired >>> 0, 1);

  /* M-H: gate al != 0 but room type != 0xb stays inert (disjunct). */
  const mGateOnly = spawnLoopRun(BBLOCK_LIVE);
  assert.equal(mGateOnly.roomTriggerClearAwardsBit7 >>> 0, 0,
    "M-H: al!=0 alone does NOT arm the band");
  assert.equal(mGateOnly.roomAwardsBBlockRowsApplied >>> 0, 0);

  /* Source pins: both mirrors consume the frozen room-pure ABI v86 laws
     BY REFERENCE (never re-derived); ledger rides resolvedBoundaries. */
  const cppSrc = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  const modelSrc = readFileSync(join(root, "scripts", "decomp", "game-update-model.mjs"), "utf8");
  for (const n of ["isaac_room_idx29_at_9b92c0", "isaac_room_count_7cb6e0_plan",
      "isaac_room_roll_7c3980_core", "isaac_room_idx29_roll_plan"]) {
    assert.ok(cppSrc.includes(n + "("), `cpp consumes ${n}`);
  }
  for (const n of ["roomIdx29At9b92c0", "roomCount7cb6e0Plan",
      "roomRoll7c3980Core", "roomIdx29RollPlan"]) {
    assert.ok(modelSrc.includes(n + "("), `model consumes ${n}`);
  }
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  assert.ok(!spec.opaqueBoundaries.some((b) => b.idx === 29),
    "record idx 29 GONE from opaqueBoundaries");
  assert.ok(spec.resolvedBoundaries.some((b) => b.idx === 29 &&
      /REMOVED at ABI v141/.test(b.operation)),
    "record idx 29 rides resolvedBoundaries");
  assert.ok(spec.runtimeInputs.some((r) => r.name === "awardsBBlockReady" &&
      r.offset === 22572), "ledger pins the voucher lane @22572");
  assert.ok(spec.events.some((e) => e.name === "roomAwardsBBlockTailCreateFired" &&
      e.offset === 1240), "ledger pins the tail-create carrier @1240");
});

test("ABI v132: record idx 36 — an armed spawn walk is carried by its enumeration rows (full-carry extension)", () => {
  const b16BitsLocal = (v) => { const u = new Uint32Array(1); new Float32Array(u.buffer)[0] = v; return u[0]; };
  const st = {
    roomWaterAmount7240: 0.5, roomLavaIntensity7740: 0.5,
    roomType8: 1, roomTransitionMode1830c: 1,
    difficulty269c8: 0, flags2654c: 0, roomDescFlags44: 0,
    fxCur676b8: 0, fxCur676bc: 0, fxCur676c0: 0,
    fxCur676c4: 0, fxCur676c8: 0, fxCur676cc: 0, fxLerpGate676b4: 0,
  };
  const rt = {
    waterB16BlobReady: 1,
    waterB16GameByte183a0: 0, waterB16GameByte269e9: 0,
    waterB16GameType0: 4, waterB16GameSubtype4: 4,
    waterB16UnlockAcc: 0, waterB16UnlockClear: 0,
    waterB16Src1b10_0: b16BitsLocal(0.5), waterB16Src1b10_1: 0,
    waterB16Src1b10_2: 0, waterB16Src1b10_3: 0,
    waterB16Src1b10_4: 0, waterB16Src1b10_5: 0,
    waterB16GridFlags44: 0, waterB16CellDword54: 0,
    ambientRoom1d18: 0, b3b7WidthC: 0, b3b7Height10: 0,
    challenge0x123: 0,
  };
  const ev0 = { ...emptyEventsForTest(), continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_HEAD };
  const readyRt = {
    ...rt,
    challenge0x123: 1,
    waterB16SpawnRowsReady: 1,
    waterB16WaterHitCount: 3,
    waterB16LavaHitCount: 0,
    waterB16GridWEcho: 0,
    waterB16GridHEcho: 0,
  };
  const carried = resumeGameUpdateRoomUpdateHead(
    { ...st, roomWaterAmount7240: 0.8, roomDescFlags44: 32 },
    readyRt, { ...ev0 });
  assert.equal(carried.events.opaqueRoomUpdateTailWaterB16, 0,
    "v132: armed walk + ready rows -> full carry, coarse retired");
  assert.equal(carried.events.waterB16SpawnRowsApplied, 1);
  assert.equal(carried.events.waterB16WalkArmMask, 1, "bit0 = lane W armed");
  assert.equal(carried.events.waterB16WaterHitCount, 3);
  assert.equal(carried.events.waterB16CastCount, 3, "one cast per W hit");
  assert.equal(carried.events.waterB16LeafCallCount, 0);

  /* Same arm WITHOUT the voucher -> monolith byte-for-byte (v130 shape). */
  const notReady = resumeGameUpdateRoomUpdateHead(
    { ...st, roomWaterAmount7240: 0.8, roomDescFlags44: 32 },
    { ...readyRt, waterB16SpawnRowsReady: 0 }, { ...ev0 });
  assert.equal(notReady.events.opaqueRoomUpdateTailWaterB16, 1,
    "rows not ready -> monolith keeps naming the spawns");
  assert.equal(notReady.events.waterB16SpawnRowsApplied, 0);
  assert.equal(notReady.events.waterB16WalkArmMask, 1,
    "arm mask observable even when rows are not ready");

  /* Over-cap hit count poisons the WHOLE voucher -> monolith. */
  const overCap = resumeGameUpdateRoomUpdateHead(
    { ...st, roomWaterAmount7240: 0.8, roomDescFlags44: 32 },
    { ...readyRt, waterB16WaterHitCount: 65 }, { ...ev0 });
  assert.equal(overCap.events.opaqueRoomUpdateTailWaterB16, 1,
    "over-cap -> monolith (never truncate)");

  /* Dims-echo mismatch poisons the voucher -> monolith. */
  const echoBad = resumeGameUpdateRoomUpdateHead(
    { ...st, roomWaterAmount7240: 0.8, roomDescFlags44: 32 },
    { ...readyRt, waterB16GridWEcho: 9 }, { ...ev0 });
  assert.equal(echoBad.events.opaqueRoomUpdateTailWaterB16, 1,
    "echo mismatch -> monolith");

  /* Lava arm armed (old 0.21 decays below the band) + rows ready ->
     coarse retired; leaf-call carrier counts lane-L hits. */
  const lavaCarried = resumeGameUpdateRoomUpdateHead(
    { ...st, roomLavaIntensity7740: 0.21 },
    { ...rt, challenge0x123: 0,
      waterB16SpawnRowsReady: 1, waterB16WaterHitCount: 0,
      waterB16LavaHitCount: 2, waterB16GridWEcho: 0, waterB16GridHEcho: 0 },
    { ...ev0 });
  assert.equal(lavaCarried.events.opaqueRoomUpdateTailWaterB16, 0,
    "lava arm + ready rows -> full carry");
  assert.equal(lavaCarried.events.waterB16WalkArmMask, 2, "bit1 = lane L armed");
  assert.equal(lavaCarried.events.waterB16LeafCallCount, 2,
    "one 0x714610 leaf per lava hit");
});

function emptyEventsForTest() {
  const e = {};
  for (const k of Object.keys(EVENTS_LAYOUT)) e[k] = 0;
  e.continuationKind = UPDATE_CONTINUATION.RETURN_AFTER_GAME_UPDATE;
  e.dispatchKind = TRANSITION_DISPATCH.NONE;
  return e;
}

