test("ABI v98: the shipped Wasm agrees with the oracle on the fold exports", (t) => {
  const slicePath = join(root, "output", "decomp", "wasm-slice", "game-update-slice.wasm");
  if (!existsSync(slicePath)) {
    t.skip("run `npm run decomp:build-slice` first — this probe needs the module");
    return;
  }
  const module = new WebAssembly.Module(readFileSync(slicePath));
  const wasm = new WebAssembly.Instance(module, {}).exports;
  const pick = (n) => wasm[n] ?? wasm[`_${n}`];
  const fold = pick("isaac_game_update_slice_engine_anm2_prefix_fold_ready");
  const cache = pick("isaac_game_update_slice_engine_anm2_cache_fetch_decision");
  const loadimage = pick("isaac_game_update_slice_engine_anm2_loadimage_decision");
  const anim = pick("isaac_game_update_slice_engine_anm2_anim_apply_decision");
  if (typeof fold !== "function" || typeof cache !== "function" ||
      typeof loadimage !== "function" || typeof anim !== "function") {
    t.skip("the shipped module predates the v98 exports — coordinator rebuilds it");
    return;
  }
  const lane = { engineAnm2BlobReady: 1, engineAnm2LatchReady: 1, engineAnm2Latch: 0,
    engineAnm2LayerCount: 1, engineAnm2ExtraCount: 0 };
  assert.equal(fold(1, 1, 1, 1, 1), 1);
  assert.equal(fold(1, 1, 1, 0, 1), 0, "anim_ready 0 -> no fold");
  assert.equal(cache(1, 1, 0, 0, 0, 1), 1);
  assert.equal(cache(1, 1, 0, 0, 0, 0), 0);
  assert.equal(loadimage(1, 1, 0, 1, 0, 1, 1), 1);
  assert.equal(loadimage(1, 1, 0, 0, 0, 1, 1), 0, "entered(0) closes");
  assert.equal(loadimage(1, 1, 0, 1, 0, 0x100, 1), 0, "clear low byte closes");
  assert.equal(anim(1, 1, 0, 0, 0, 1), 1);
  assert.equal(anim(1, 1, 0, 0, 0, 0), 0);
  /* Cross-check against the JS oracle on a grid. */
  for (const latch of [0, 0x100, 0x1ff]) {
    assert.equal(cache(1, 1, latch, 0, 0, 1),
      engineAnm2CacheFetchDecision({ ...lane, engineAnm2Latch: latch, engineAnm2FilenameReady: 1 }));
    assert.equal(anim(1, 1, latch, 0, 0, 1),
      engineAnm2AnimApplyDecision({ ...lane, engineAnm2Latch: latch, engineAnm2AnimReady: 1 }));
  }
});

