  const esSlot0 = spec.runtimeInputs.find((r) => r.name === "frameOpaque98dba0EntitySurfaceCapture[0]");
  const esSlot7 = spec.runtimeInputs.find((r) => r.name === "frameOpaque98dba0EntitySurfaceCapture[7]");
