test("ABI v115: coarse retirement equivalence — gate open fires the carrier only; gate closed / 0xd / bit16 fire nothing; idx-24/33 keep their counters", () => {
  const run = (runtime, stateOverrides = {}) =>
    tcsStatsRun(runtime, stateOverrides);
  /* (a) gate open (mode 0): carrier fires once, coarse NEVER fires. */
  const open = run({ clearPathGameMode0: 0 });
  assert.equal(open.events.clearPathFlagStore | 0, 1, "carrier fires on gate open");
  assert.equal(open.events.opaqueRoomUpdateClearPath | 0, 0,
    "coarse edge RETIRED — never fires under any input");
  /* (b) gate closed arms: mode 0xd skip; mode 2 + bit16; mode 1 + bit16. */
  for (const [rt, st, label] of [
    [{ clearPathGameMode0: 0xd }, {}, "mode 0xd"],
    [{ clearPathGameMode0: 2 }, { flags2654c: 0x10000 }, "mode 2 + bit16"],
    [{ clearPathGameMode0: 1 }, { flags2654c: 0x10000 }, "mode 1 + bit16"],
    [{ clearPathGameMode0: 6 }, { flags2654c: 0x10000 }, "mode 6 + bit16"],
  ]) {
    const r = run(rt, st);
    assert.equal(r.events.clearPathFlagStore | 0, 0, `${label}: no carrier`);
    assert.equal(r.events.opaqueRoomUpdateClearPath | 0, 0, `${label}: no coarse`);
  }
  /* WIDE 0x1000000d is NOT 0xd (FULL-DWORD law) and signed > 6 -> carrier. */
  assert.equal(run({ clearPathGameMode0: 0x1000000d }).events.clearPathFlagStore | 0, 1,
    "WIDE 0x1000000d -> carrier (low-byte mutant dies)");
  /* (c) idx-24/33 coupling: the door-slot residual still arms its OWN
     typed carrier (v119: the mask event — the coarse counter is RETIRED)
     independently of the retired idx-23 edge. */
  const slotsRun = run({
    clearPathGameMode0: 0xd,
    doorSlots: [{
      present: 1, field3a0: 0, field8: 0, fieldC: 0,
    }],
  });
  assert.equal(slotsRun.events.opaqueRoomUpdateClearDoorSlots | 0, 0,
    "idx-24 coarse RETIRED at v119 — never fires");
  assert.equal(slotsRun.events.opaqueRoomUpdateClearDoorSlotsMask | 0, 1,
    "idx-24 mask carrier keeps arming off the failing-mask loop");
  assert.equal(slotsRun.events.type5DoorForcedRerun | 0, 1,
    "idx-33 forced-arm carrier rides the same tick (merge law)");
  assert.equal(slotsRun.events.opaqueRoomUpdateClearPath | 0, 0,
    "idx-24 firing does NOT re-arm the retired idx-23 edge");
});


/* Wave-34: records idx 24 + idx 33 REMOVED — the boundary rows moved to
   resolvedBoundaries (41 -> 39; 9th + 10th removals since v79).
   Full-capture theorems (update-v119-door-removal):
   - idx-24: the ONLY coarse firing site arms on the pure failing-mask law;
     the entire door-open residual (Game+0x2654c |= 0x20000, GetRoomByIdx
     0x740bc0, 0x748760, jmp 0x70ee40 SEH/ANM2 tail) is fully typed — the
     0x70ee40 census (extent 0x70ee40..0x70f5db, 596 insns, 36 E8, 0
     indirect, 1 SEH frame) proves every leaf is ZHL-typed / platform /
     typed-host-standing / pure-relay. Carrier = the EXISTING mask event
     @900 under the IDENTICAL condition. No new slot needed.
   - idx-33: per-arm carriers — gated arm type5DoorOpenCalls (plan
     predicate IDENTICAL to the any_type5_needs_host gate), forced arm NEW
     tail slot type5DoorForcedRerun @992 (events 992 -> 996, 5-CHECK).
   No capture gate exists (door_slots are captured runtime inputs), so
   there is no capture-absence arm: the coarse counters @164/@196 STAY in
   the frozen events ABI but NEVER fire. */
test("ABI v119 (wave-34): records idx 24 + idx 33 ride resolvedBoundaries — JSON rows, event slot @992 (5-CHECK), coarse @164/@196 stay, count 41 -> 39", () => {
  const spec = JSON.parse(readFileSync(join(root, "decomp", "game-update-slice.json"), "utf8"));
  const rec24 = spec.resolvedBoundaries.find((b) => b.idx === 24 && b.name === "opaqueRoomUpdateClearDoorSlots");
  const rec33 = spec.resolvedBoundaries.find((b) => b.idx === 33 && b.name === "opaqueRoomUpdateClearDoors");
  assert.ok(rec24, "record idx 24 rides resolvedBoundaries (REMOVED at ABI v119)");
  assert.ok(rec33, "record idx 33 rides resolvedBoundaries (REMOVED at ABI v119)");
  assert.match(rec24.operation, /REMOVED at ABI v119/);
  assert.match(rec33.operation, /REMOVED at ABI v119/);
  assert.match(rec24.evidence || "", /full-capture|update-v119-door-removal/i,
    "idx24 evidence names the removal theorem");
  assert.match(rec33.evidence || "", /equivalence|update-v119-door-removal/i,
    "idx33 evidence names the equivalence theorem");
  assert.match(rec24.abiV119 || "", /41 -> 40|41->40/i, "idx24 abiV119 key");
  assert.match(rec33.abiV119 || "", /40 -> 39|40->39/i, "idx33 abiV119 key");
  assert.ok(!spec.opaqueBoundaries.some((b) => b.idx === 24),
    "record idx 24 is GONE from opaqueBoundaries");
  assert.ok(!spec.opaqueBoundaries.some((b) => b.idx === 33),
    "record idx 33 is GONE from opaqueBoundaries");
  assert.equal(spec.opaqueBoundaries.length, 24,
    "count 26 -> 25 (record idx 27 roomTriggerClearAudio REMOVED at ABI v138, update-v138-audio-alt-tail-pack); count 27 -> 26 (record idx 26 roomTriggerClearAudioNonGreed REMOVED at ABI v136, update-v136-audio-head-pack); count 32 -> 31 (record idx 45 REMOVED at v128, 18th removal since v79); count 33 -> 32 (record idx 38 REMOVED at v127, 17th removal since v79); count 34 -> 33 (record idx 40 REMOVED at v126, 16th removal since v79); count 35 -> 34 (record idx 25 REMOVED at v125, 15th removal since v79); count 36 -> 35 (record idx 46 REMOVED at v124, 14th removal since v79); count 41 -> 39 (records idx 24 + idx 33 REMOVED at v119, 9th + 10th removals since v79)");
  /* CHECK 1 — JSON event row: offset 992, u32, 4 B. */
  const ev = spec.events.find((e) => e.name === "type5DoorForcedRerun");
  assert.ok(ev, "spec records type5DoorForcedRerun");
  assert.equal(ev.offset, 992, "event offset 992 (next-free after 988)");
  assert.equal(ev.type, "u32");
  assert.equal(ev.bytes, 4);
  /* CHECK 2 — model EVENTS_LAYOUT row. */
  assert.equal(EVENTS_LAYOUT.type5DoorForcedRerun.offset, 992, "model layout @992");
  /* CHECK 3 — cpp struct field + offset/sizeof static_asserts. */
  const header = readFileSync(join(root, "native", "decomp", "game_update_slice.h"), "utf8");
  const source = readFileSync(join(root, "native", "decomp", "game_update_slice.cpp"), "utf8");
  assert.ok(header.includes("uint32_t type5_door_forced_rerun;"), "header field");
  assert.ok(source.includes("events->type5_door_forced_rerun += 1"), "cpp fire site");
  assert.match(source, /offsetof\(IsaacGameUpdateSliceEvents, type5_door_forced_rerun\) == 992/);
  assert.match(source, /sizeof\(IsaacGameUpdateSliceEvents\) == 1260/);
  /* CHECK 4 — ABI_SIZES events 996 (state/runtime frozen). */
  assert.deepEqual(ABI_SIZES, { state: 524, constants: 32, runtimeInputs: 23696, events: 1260 });
  /* CHECK 5 — the coarse counters @164/@196 STAY in the events ABI (never
     fire post-retirement). */
  const evMap = new Map(spec.events.map((e) => [e.offset, e.name]));
  assert.equal(evMap.get(164), "opaqueRoomUpdateClearDoorSlots", "coarse slot @164 STAYS");
  assert.equal(evMap.get(196), "opaqueRoomUpdateClearDoors", "coarse slot @196 STAYS");
  assert.equal(EVENTS_LAYOUT.opaqueRoomUpdateClearDoorSlots.offset, 164, "layout coarse @164");
  assert.equal(EVENTS_LAYOUT.opaqueRoomUpdateClearDoors.offset, 196, "layout coarse @196");
});

test("ABI v119: idx-24 coarse retirement equivalence — failing door fires the mask carrier only; gate-closed fires byte-for-byte silence", () => {
  const st = { roomDescFlags44: 9, roomDescClearCount4a: 0, flags2654c: 0,
    roomAlive12c0: 0, roomAlive12c4: 0, roomGreedWave723c: 0, roomClearDelay11ec: 0,
    roomType8: 0, roomDescSubtype: 0, difficulty269c8: 0, roomBossCount12c8: 0,
    roomBossCount12cc: 0, roomBossSnapshot7224: 0, roomTimer722c: 0,
    roomCollectibleTimer7764: 0, roomTimer7214: 0, roomTimer706c: 0,
    roomTimer7230: 0, roomWaterAmount7240: 0, roomLavaIntensity7740: 0,
    roomFlag7894: 0, roomFlag7769: 0, roomByte7220: 0, mode26584: 0 };
  const rt = { globalClearSkip997a: 0, alive12c0: 0, alive12c4: 0,
    roomGreedWave723c: 0, roomClearDelay11ec: 0, roomType8: 0,
    roomDescSubtype: 0, roomDescFlags44: 9, doorSlots: [] };
  const run = (doorSlots) => resumeGameUpdateRoomUpdatePrefix(
    { ...st },
    { ...rt, doorSlots },
    { continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX },
  );
  /* (a) gate open (one failing slot): the mask carrier fires, the coarse
     NEVER fires; the forced-arm idx-33 carrier rides the same tick. */
  const open = run([{ present: 1, field3a0: 0, field8: 1, fieldC: 0 }]);
  const openEv = open.events ?? open;
  assert.equal(openEv.opaqueRoomUpdateClearDoorSlotsMask >>> 0, 1, "mask carrier fires on gate open");
  assert.equal(openEv.opaqueRoomUpdateClearDoorSlots | 0, 0,
    "idx-24 coarse edge RETIRED — never fires under any input");
  assert.equal(openEv.type5DoorForcedRerun | 0, 1,
    "idx-33 forced-arm carrier fires on the same tick (merge law)");
  assert.equal(openEv.opaqueRoomUpdateClearDoors | 0, 0, "idx-33 coarse stays retired");
  /* (b) gate closed (all slots early-out / absent): byte-for-byte silence. */
  for (const [slots, label] of [
    [[{ present: 1, field3a0: 0x10, field8: 1, fieldC: 0 }], "early-out clause 1"],
    [[{ present: 1, field3a0: 0, field8: 7, fieldC: 0 }], "early-out f8==7"],
    [[{ present: 0, field3a0: 0, field8: 1, fieldC: 0 }], "absent slot"],
    [[], "no slots"],
  ]) {
    const r = run(slots);
    const ev2 = r.events ?? r;
    assert.equal(ev2.opaqueRoomUpdateClearDoorSlotsMask | 0, 0, `${label}: no carrier`);
    assert.equal(ev2.opaqueRoomUpdateClearDoorSlots | 0, 0, `${label}: no coarse`);
    assert.equal(ev2.type5DoorForcedRerun | 0, 0, `${label}: no idx-33 carrier`);
  }
  /* (c) WIDE present 0x100 qualifies (FULL-DWORD law) — the carrier fires
     where a byte-narrowed mutant would stay silent. */
  const wide = run([{ present: 0x100, field3a0: 0, field8: 1, fieldC: 0 }]);
  const wideEv = wide.events ?? wide;
  assert.equal(wideEv.opaqueRoomUpdateClearDoorSlotsMask >>> 0, 1,
    "WIDE present 0x100 -> carrier (low-byte mutant dies)");
});

test("ABI v119: idx-33 coarse retirement equivalence — gated arm fires the plan only; forced arm fires type5DoorForcedRerun; nested site gated", () => {
  const base = step({});
  const shaped = {
    ...base.state,
    timedTransitionCleanupMode: 0,
    roomClearDelay11ec: 0, roomAlive12c0: 0, roomAlive12c4: 0, roomGreedWave723c: 0,
    roomType8: 1, roomDescSubtype: 0, roomDescFlags44: 0,
  };
  const ev = { ...base.events, continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_UPDATE_PREFIX };
  /* (a) GATED arm (0x10/2 skip keeps the snapshot valid): the plan carrier
     fires exactly where the coarse armed; the forced carrier stays 0. */
  const gated = resumeGameUpdateRoomUpdatePrefix(
    { ...shaped, roomType8: 0x10, roomDescSubtype: 2 },
    { doorSlots: [{ present: 1, field3a0: 0, field8: 1, fieldC: 5 }] },
    { ...ev },
  );
  assert.equal(gated.events.type5DoorOpenCalls | 0, 1, "gated arm: plan carrier fires");
  assert.equal(gated.events.type5DoorForcedRerun | 0, 0, "gated arm: forced carrier silent");
  assert.equal(gated.events.opaqueRoomUpdateClearDoors | 0, 0,
    "idx-33 coarse edge RETIRED — never fires under any input");
  /* (b) FORCED arm (clear-path residual ran): exactly the forced carrier. */
  const forced = resumeGameUpdateRoomUpdatePrefix(
    { ...shaped },
    { doorSlots: [
      { present: 1, field3a0: 0, field8: 1, fieldC: 1 },
      { present: 1, field3a0: 0, field8: 1, fieldC: 5 },
    ] },
    { ...ev },
  );
  assert.equal(forced.events.type5DoorForcedRerun | 0, 1, "forced arm: carrier fires");
  assert.equal(forced.events.type5DoorOpenCalls | 0, 0,
    "forced arm publishes NO plan (post-clear states are host-time)");
  assert.equal(forced.events.opaqueRoomUpdateClearDoors | 0, 0, "coarse stays retired");
  /* (c) All type-5 doors early-out: byte-for-byte silence on both arms. */
  const none = resumeGameUpdateRoomUpdatePrefix(
    { ...shaped, roomType8: 0x10, roomDescSubtype: 2 },
    { doorSlots: [{ present: 1, field3a0: 0x10, field8: 1, fieldC: 5 }] },
    { ...ev },
  );
  assert.equal(none.events.type5DoorOpenCalls | 0, 0, "no plan");
  assert.equal(none.events.type5DoorForcedRerun | 0, 0, "no forced carrier");
  assert.equal(none.events.opaqueRoomUpdateClearDoors | 0, 0, "no coarse");
  /* (d) Nested site (0x10/3): always gated — the plan carrier fires. */
  const nested = resumeGameUpdateRoomClearNested(
    { ...base.state, roomType8: 0x10, roomDescSubtype: 3 },
    { doorSlots: [{ present: 1, field3a0: 0, field8: 1, fieldC: 5 }] },
    { ...base.events, continuationKind: UPDATE_CONTINUATION.RESUME_AFTER_ROOM_CLEAR_NESTED },
  );
  assert.equal(nested.events.type5DoorOpenCalls | 0, 1, "nested: plan carrier fires");
  assert.equal(nested.events.type5DoorForcedRerun | 0, 0, "nested: forced carrier silent");
  assert.equal(nested.events.opaqueRoomUpdateClearDoors | 0, 0, "nested: coarse stays retired");
});

/* ================= ABI v123 (record idx 38 opaqueRoomUpdateTailMid706cExpire):
   shop-restock body 0x008158a0 LAW PACK — exports-only landing
   (update-v123-706c-restock-laws; ADDENDUM 3 F1-F4 in
   section-notes/update-84c170-tail/NOTES.md; abiV118 idx-4 template).
   Transcribed from cpu-dump/008158a0.txt branch-by-branch. Boundary STAYS
   counted (F4 blockers); layouts frozen, ABI 99. ==== */
import {
  SHOP_RESTOCK_XORSHIFT_S1,
  SHOP_RESTOCK_XORSHIFT_S2,
  SHOP_RESTOCK_XORSHIFT_S3,
  SHOP_RESTOCK_ITEM_ID_MAX,
  gameUpdateSlice706cRestockFrame,
  gameUpdateSliceSfxUpdFrame,
  SHOP_RESTOCK_MAX,
  gameUpdateSlice706cShopGate,
  gameUpdateSlice706cBucketParity,
  gameUpdateSlice706cBucketIndex,
  gameUpdateSlice706cCounterIncCap255,
  gameUpdateSlice706cIdivQuot,
  gameUpdateSlice706cIdivRem,
  gameUpdateSlice706cPosX,
  gameUpdateSlice706cPosY,
  gameUpdateSlice706cVcallArm,
  gameUpdateSlice706cHashZero,
  gameUpdateSlice706cXorshiftStep,
} from "../scripts/decomp/game-update-model.mjs";

test("ABI v123: 706c shop gate is FULL-DWORD [Room+8]==2 (byte-narrow mutant dies)", () => {
  assert.equal(gameUpdateSlice706cShopGate(2), 1);
  assert.equal(gameUpdateSlice706cShopGate(0x102), 0, "0x102 low byte 2 but dword != 2");
  assert.equal(gameUpdateSlice706cShopGate(0xffffffff), 0);
  assert.equal(gameUpdateSlice706cShopGate(0), 0);
});

test("ABI v123: 706c bucket select is UNSIGNED shr/and with parity low bit", () => {
  assert.equal(gameUpdateSlice706cBucketParity(5), 1);
  assert.equal(gameUpdateSlice706cBucketParity(0x100), 0, "high bits are not parity");
  assert.equal(gameUpdateSlice706cBucketIndex(5, 8), 2, "(5>>1)&7");
  assert.equal(gameUpdateSlice706cBucketIndex(0xffffffff, 8), 7, "u32 wrap");
  assert.equal(gameUpdateSlice706cBucketIndex(0x80000000, 8), 0, "signed-read mutant dies");
});

test("ABI v123: 706c counter inc keeps a 0xff byte capped (jae-skip mutant dies)", () => {
  assert.equal(gameUpdateSlice706cCounterIncCap255(0), 1);
  assert.equal(gameUpdateSlice706cCounterIncCap255(0xfe), 0xff);
  assert.equal(gameUpdateSlice706cCounterIncCap255(0xff), 0xff, "cap holds");
  assert.equal(gameUpdateSlice706cCounterIncCap255(0x1ff), 0xff, "byte-narrow input");
});

test("ABI v123: 706c grid pos idiv TRUNCATES toward zero and f32 rounds per op", () => {
  /* x86 cdq/idiv semantics: remainder has the dividend's sign. */
  assert.equal(gameUpdateSlice706cIdivQuot(-7, 2), -3, "trunc toward zero");
  assert.equal(gameUpdateSlice706cIdivRem(-7, 2), -1, "remainder sign = dividend");
  assert.equal(gameUpdateSlice706cIdivQuot(7, -2), -3);
  assert.equal(gameUpdateSlice706cIdivRem(7, -2), 1);
  assert.equal(gameUpdateSlice706cIdivRem(0x105, 13), 1, "261 % 13 = 1");
  /* f32: cvtdq2ps -> mulss 40 -> addss 40/120, each op rounded. */
  assert.equal(gameUpdateSlice706cPosX(3), 160);
  assert.equal(gameUpdateSlice706cPosY(1), 160);
  const big = 0x20000001; /* f32 conversion rounds; double-math mutant dies */
  assert.ok(Object.is(Math.fround(gameUpdateSlice706cPosX(big % 7)), gameUpdateSlice706cPosX(big % 7)));
});

test("ABI v123: 706c xorshift{2,7,7} chain + hash-zero fatal predicate", () => {
  assert.equal(SHOP_RESTOCK_XORSHIFT_S1, 2);
  assert.equal(SHOP_RESTOCK_XORSHIFT_S2, 7);
  assert.equal(SHOP_RESTOCK_XORSHIFT_S3, 7);
  let x = 0x12345678 >>> 0;
  x = gameUpdateSlice706cXorshiftStep(x);
  assert.equal(x, ((0x12345678 ^ (0x12345678 >>> 2)) >>> 0) === x ? x : x);
  /* exact single-step value */
  const s1 = 0x12345678 >>> 0;
  const a = (s1 ^ (s1 >>> 2)) >>> 0;
  const b = (a ^ ((a << 7) >>> 0)) >>> 0;
  const c = (b ^ (b >>> 7)) >>> 0;
  assert.equal(x, c, "single step matches x^=x>>2; x^=x<<7; x^=x>>7");
  assert.notEqual(gameUpdateSlice706cXorshiftStep(1), 1, "identity mutant dies");
  assert.equal(gameUpdateSlice706cHashZero(0), 1, "zero hash fires the fatal twin");
  assert.equal(gameUpdateSlice706cHashZero(0x100), 0, "0x100 must NOT fatal");
});

test("ABI v123: 706c vcall arm UNSIGNED 0x1bf bound + slot gate", () => {
  assert.equal(gameUpdateSlice706cVcallArm(0x1000, 0x1bf), 1);
  assert.equal(gameUpdateSlice706cVcallArm(0x1000, 0x1c0), 0, "UNSIGNED ja skip");
  assert.equal(gameUpdateSlice706cVcallArm(0, 5), 0, "null slot skips");
  assert.equal(gameUpdateSlice706cVcallArm(0x1000, 0x100001bf & 0xffffffff), 0);
  assert.equal(SHOP_RESTOCK_ITEM_ID_MAX, 0x1bf);
});

